// Hyperreal Mechanical Watch Movement — E-Ink Stipple & Ordered Dither Study
// Rendered exclusively with p5.brush in a narrow ladder of warm paper greys

const PAL = {
  BG:       "#DFDDD2", // Level 0: Pale, slightly yellowed unlit e-ink display ground
  GHOST_HI: "#E8E6DC", // Level 1: Faint bright ghost persistence
  GHOST_LO: "#CCC9BE", // Level 2: Faint dark ghost persistence
  GHOST_MD: "#D5D2C7", // Intermediate ghost persistence
  STEP1:    "#C2BEB2", // Level 3: Light warm paper grey
  STEP2:    "#9A968A", // Level 4: Mid-light mechanical grey
  STEP3:    "#706C62", // Level 5: Mid-dark mechanical grey
  STEP4:    "#47443D", // Level 6: Deep shadow grey
  INK:      "#211F1B"  // Level 7: Crisp e-ink carbon dark
};

// Movement primary center and scale
const MCX = 565;
const MCY = 620;
const MR  = 450;

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(89104);
  noiseSeed(89104);

  // Scale built-in brushes first per constraints
  brush.scaleBrushes(3);

  // Register custom pixel-crisp technical pens, ordered dither matrices, and stipple brushes
  // Added after scaleBrushes(3) so weights remain in exact 1:1 canvas units
  brush.add("tech_pen", {
    type: "default",
    weight: 1.05,
    scatter: 0,
    sharpness: 0.98,
    grain: 1,
    opacity: 250,
    spacing: 0.14,
    pressure: [1, 1, 1],
    noise: 0
  });

  brush.add("hairline", {
    type: "default",
    weight: 0.62,
    scatter: 0,
    sharpness: 0.99,
    grain: 1,
    opacity: 245,
    spacing: 0.14,
    pressure: [1, 1, 1],
    noise: 0
  });

  brush.add("bold_pen", {
    type: "default",
    weight: 1.75,
    scatter: 0,
    sharpness: 0.98,
    grain: 1,
    opacity: 255,
    spacing: 0.14,
    pressure: [1, 1, 1],
    noise: 0
  });

  // Ordered Dither Level 1: Sparse 8px Bayer dot grid (12.5%)
  brush.add("dither_1", {
    type: "custom",
    weight: 4.0,
    scatter: 0,
    opacity: 240,
    spacing: 2.0,
    pressure: [1, 1, 1],
    tip: (_m) => {
      _m.rect(-0.55, -0.55, 1.1, 1.1);
    },
    rotate: "none",
    markerTip: false,
    noise: 0
  });

  // Ordered Dither Level 2: Checkerboard 6px ordered dither (25%)
  brush.add("dither_2", {
    type: "custom",
    weight: 4.0,
    scatter: 0,
    opacity: 245,
    spacing: 1.5,
    pressure: [1, 1, 1],
    tip: (_m) => {
      _m.rect(-1.5, -1.5, 1.2, 1.2);
      _m.rect(1.5, 1.5, 1.2, 1.2);
    },
    rotate: "none",
    markerTip: false,
    noise: 0
  });

  // Ordered Dither Level 3: Dense 50% Bayer pattern
  brush.add("dither_3", {
    type: "custom",
    weight: 4.0,
    scatter: 0,
    opacity: 250,
    spacing: 1.5,
    pressure: [1, 1, 1],
    tip: (_m) => {
      _m.rect(-1.6, -1.6, 1.55, 1.55);
      _m.rect(1.4, 1.4, 1.55, 1.55);
      _m.rect(-1.6, 1.4, 1.05, 1.05);
    },
    rotate: "none",
    markerTip: false,
    noise: 0
  });

  // Ordered Dither Level 4: Heavy 75% ordered dither matrix
  brush.add("dither_4", {
    type: "custom",
    weight: 4.0,
    scatter: 0,
    opacity: 255,
    spacing: 1.25,
    pressure: [1, 1, 1],
    tip: (_m) => {
      _m.rect(-1.6, -1.6, 1.9, 1.9);
      _m.rect(0.9, 0.9, 1.9, 1.9);
      _m.rect(-1.6, 0.9, 1.45, 1.45);
      _m.rect(0.9, -1.6, 1.45, 1.45);
    },
    rotate: "none",
    markerTip: false,
    noise: 0
  });

  // Fine Pen Stipple: Multi-point stochastic pen stippling
  brush.add("stipple_fine", {
    type: "custom",
    weight: 3.6,
    scatter: 0.75,
    opacity: 235,
    spacing: 1.45,
    pressure: [0.95, 1.05, 0.95],
    tip: (_m) => {
      _m.circle(-1.3, -0.9, 0.85);
      _m.circle(1.4, 0.6, 0.7);
      _m.circle(-0.1, 1.5, 0.75);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.15
  });

  // Micro Stipple: Delicate grain for frosted plates and ghosting
  brush.add("stipple_micro", {
    type: "custom",
    weight: 3.2,
    scatter: 1.0,
    opacity: 215,
    spacing: 1.8,
    pressure: [1, 1, 1],
    tip: (_m) => {
      _m.circle(-1.0, 0, 0.65);
      _m.circle(1.1, 0.9, 0.55);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.1
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.BG);
  brush.noField();

  // 1. E-INK SCREEN MATRIX & GHOSTED PREVIOUS IMAGE (OFFSET GEAR)
  drawDisplayGround();
  drawGhostedGearSystem(false);

  // 2. MAINPLATE (PLATINE) & MILLED RECESSES
  drawMainplateAndRecesses();

  // 3. LOWER GEAR TRAIN & OPEN MAINSPRING BARREL
  drawMainspringBarrel(405, 435, 160);
  drawThirdWheel(420, 755, 96);
  drawCenterWheel(MCX, MCY, 136);
  drawFourthWheel(585, 835, 102);
  drawEscapementAndPallet(755, 760, 68, 710, 665);

  // 4. SCULPTED BRIDGES, CÔTES DE GENÈVE & WINDING WHEELS
  drawBarrelBridgeAndWinding();
  drawTrainWheelBridge();
  drawCenterWheelCock();

  // 5. BALANCE ASSEMBLY, BREGUET HAIRSPRING & BALANCE COCK
  drawBalanceAssemblyAndHairspring(755, 515, 148);
  drawBalanceCockAndRegulator(755, 515);

  // 6. HYPERREAL JEWELS, SCREWS & PERSISTENT GHOSTING TRACE
  drawAllJewelsAndScrews();
  drawGhostedGearSystem(true); // Subtle bistable e-ink persistence across light surfaces

  // 7. TECHNICAL PAGE FRAMING & E-INK CALIBRATION LADDER
  drawTechnicalPageOverlay();

  noLoop();
}

// =============================================================================
// GEOMETRY & DITHER RENDERING UTILITIES
// =============================================================================

function resetBrushState() {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set("hairline", PAL.INK, 1);
}

function makeCirclePts(cx, cy, r, steps = 64) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  return pts;
}

function makeArcSectorPts(cx, cy, rIn, rOut, aStart, aEnd, steps = 32) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rOut, cy + sin(a) * rOut]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = lerp(aStart, aEnd, i / steps);
    pts.push([cx + cos(a) * rIn, cy + sin(a) * rIn]);
  }
  return pts;
}

function renderPoly(pts, washCol, hatches, strokeBrush, strokeCol, strokeW = 1) {
  resetBrushState();
  let p = new brush.Polygon(pts);
  if (washCol) {
    p.wash(washCol, 255);
  }
  if (hatches && hatches.length > 0) {
    for (let h of hatches) {
      brush.hatchStyle(h.brush, h.col, h.weight || 1);
      // Slight 0.37 deg offset avoids horizontal vertex grazing in polygon intersection
      p.hatch(h.dist, h.angle + 0.37, { rand: h.rand || 0 });
    }
    brush.noHatch();
  }
  if (strokeBrush && strokeCol) {
    brush.set(strokeBrush, strokeCol, strokeW);
    p.draw(strokeBrush, strokeCol, strokeW);
  }
}

function drawAnnulus(cx, cy, rIn, rOut, washCol, hatches, strokeBrush, strokeCol, strokeW = 1) {
  // Split into two clean half-rings so polygon topology has zero holes or seams
  let wash1 = makeArcSectorPts(cx, cy, rIn, rOut, -1.5, 181.5, 40);
  let wash2 = makeArcSectorPts(cx, cy, rIn, rOut, 178.5, 361.5, 40);
  let hatch1 = makeArcSectorPts(cx, cy, rIn, rOut, 0, 180, 40);
  let hatch2 = makeArcSectorPts(cx, cy, rIn, rOut, 180, 360, 40);

  resetBrushState();
  if (washCol) {
    new brush.Polygon(wash1).wash(washCol, 255);
    new brush.Polygon(wash2).wash(washCol, 255);
  }
  if (hatches && hatches.length > 0) {
    let p1 = new brush.Polygon(hatch1);
    let p2 = new brush.Polygon(hatch2);
    for (let h of hatches) {
      brush.hatchStyle(h.brush, h.col, h.weight || 1);
      p1.hatch(h.dist, h.angle + 0.37, { rand: h.rand || 0 });
      p2.hatch(h.dist, h.angle + 0.37, { rand: h.rand || 0 });
    }
    brush.noHatch();
  }
  if (strokeBrush && strokeCol) {
    brush.set(strokeBrush, strokeCol, strokeW);
    brush.noFill();
    brush.noWash();
    brush.circle(cx, cy, rOut, 0);
    brush.circle(cx, cy, rIn, 0);
  }
}

function drawGearTeethRing(cx, cy, rIn, rRoot, rPitch, rTip, numTeeth, washCol, ditherSpec, lineCol, isGhost = false) {
  // Split toothed ring into 4 quadrant sectors for fast, watertight simple polygons
  let teethPerQuad = Math.floor(numTeeth / 4);
  let stepA = 360 / numTeeth;

  for (let q = 0; q < 4; q++) {
    let startIdx = q * teethPerQuad;
    let endIdx = (q === 3) ? numTeeth : (q + 1) * teethPerQuad;
    let pts = [];

    for (let i = startIdx; i < endIdx; i++) {
      let a0 = i * stepA;
      let aRoot1  = a0 + stepA * 0.12;
      let aPitch1 = a0 + stepA * 0.24;
      let aTip1   = a0 + stepA * 0.34;
      let aTip2   = a0 + stepA * 0.60;
      let aPitch2 = a0 + stepA * 0.70;
      let aRoot2  = a0 + stepA * 0.82;
      let aNext   = (i + 1) * stepA;

      pts.push([cx + cos(a0) * rRoot, cy + sin(a0) * rRoot]);
      pts.push([cx + cos(aRoot1) * rRoot, cy + sin(aRoot1) * rRoot]);
      pts.push([cx + cos(aPitch1) * rPitch, cy + sin(aPitch1) * rPitch]);
      pts.push([cx + cos(aTip1) * rTip, cy + sin(aTip1) * rTip]);
      pts.push([cx + cos(aTip2) * rTip, cy + sin(aTip2) * rTip]);
      pts.push([cx + cos(aPitch2) * rPitch, cy + sin(aPitch2) * rPitch]);
      pts.push([cx + cos(aRoot2) * rRoot, cy + sin(aRoot2) * rRoot]);
      if (i === endIdx - 1) {
        pts.push([cx + cos(aNext) * rRoot, cy + sin(aNext) * rRoot]);
      }
    }

    let aStart = startIdx * stepA;
    let aEnd   = endIdx * stepA;
    let innerSteps = 18;
    for (let s = innerSteps; s >= 0; s--) {
      let a = lerp(aStart, aEnd, s / innerSteps);
      pts.push([cx + cos(a) * rIn, cy + sin(a) * rIn]);
    }

    resetBrushState();
    let p = new brush.Polygon(pts);
    if (washCol) p.wash(washCol, 255);
    if (ditherSpec) {
      for (let h of ditherSpec) {
        brush.hatchStyle(h.brush, h.col, h.weight || 1);
        p.hatch(h.dist, h.angle + 0.37, { rand: 0 });
      }
      brush.noHatch();
    }
  }

  // Crisp outline of the gear teeth
  resetBrushState();
  brush.set(isGhost ? "hairline" : "tech_pen", lineCol, isGhost ? 0.75 : 0.85);
  for (let i = 0; i < numTeeth; i++) {
    let a0      = i * stepA;
    let aRoot1  = a0 + stepA * 0.12;
    let aPitch1 = a0 + stepA * 0.24;
    let aTip1   = a0 + stepA * 0.34;
    let aTip2   = a0 + stepA * 0.60;
    let aPitch2 = a0 + stepA * 0.70;
    let aRoot2  = a0 + stepA * 0.82;
    let aNext   = (i + 1) * stepA;

    let tPts = [
      [cx + cos(a0) * rRoot, cy + sin(a0) * rRoot],
      [cx + cos(aRoot1) * rRoot, cy + sin(aRoot1) * rRoot],
      [cx + cos(aPitch1) * rPitch, cy + sin(aPitch1) * rPitch],
      [cx + cos(aTip1) * rTip, cy + sin(aTip1) * rTip],
      [cx + cos(aTip2) * rTip, cy + sin(aTip2) * rTip],
      [cx + cos(aPitch2) * rPitch, cy + sin(aPitch2) * rPitch],
      [cx + cos(aRoot2) * rRoot, cy + sin(aRoot2) * rRoot],
      [cx + cos(aNext) * rRoot, cy + sin(aNext) * rRoot]
    ];
    for (let k = 0; k < tPts.length - 1; k++) {
      brush.line(tPts[k][0], tPts[k][1], tPts[k + 1][0], tPts[k + 1][1]);
    }
  }
  brush.circle(cx, cy, rIn, 0);
}

function drawSpokes(cx, cy, rHub, rRimIn, numSpokes, wHub, wRim, rotOffset, washCol, ditherSpec, lineCol, bevelCol) {
  for (let i = 0; i < numSpokes; i++) {
    let a = rotOffset + (i / numSpokes) * 360;
    let perp = a + 90;
    let p1 = [cx + cos(a) * rHub + cos(perp) * wHub, cy + sin(a) * rHub + sin(perp) * wHub];
    let p2 = [cx + cos(a) * rRimIn + cos(perp) * wRim, cy + sin(a) * rRimIn + sin(perp) * wRim];
    let p3 = [cx + cos(a) * rRimIn - cos(perp) * wRim, cy + sin(a) * rRimIn - sin(perp) * wRim];
    let p4 = [cx + cos(a) * rHub - cos(perp) * wHub, cy + sin(a) * rHub - sin(perp) * wHub];

    renderPoly([p1, p2, p3, p4], washCol, ditherSpec, "tech_pen", lineCol, 0.85);

    // Chamfered anglage edge along spoke
    if (bevelCol) {
      let b1 = [cx + cos(a) * (rHub + 3) + cos(perp) * (wHub * 0.58), cy + sin(a) * (rHub + 3) + sin(perp) * (wHub * 0.58)];
      let b2 = [cx + cos(a) * (rRimIn - 3) + cos(perp) * (wRim * 0.58), cy + sin(a) * (rRimIn - 3) + sin(perp) * (wRim * 0.58)];
      let b3 = [cx + cos(a) * (rRimIn - 3) - cos(perp) * (wRim * 0.58), cy + sin(a) * (rRimIn - 3) - sin(perp) * (wRim * 0.58)];
      let b4 = [cx + cos(a) * (rHub + 3) - cos(perp) * (wHub * 0.58), cy + sin(a) * (rHub + 3) - sin(perp) * (wHub * 0.58)];
      resetBrushState();
      brush.set("hairline", bevelCol, 0.8);
      brush.line(b1[0], b1[1], b2[0], b2[1]);
      brush.line(b4[0], b4[1], b3[0], b3[1]);
    }
  }
}

function drawDashedCircle(cx, cy, r, dashCount, duty, brushName, col, w = 1) {
  resetBrushState();
  brush.set(brushName, col, w);
  let step = 360 / dashCount;
  for (let i = 0; i < dashCount; i++) {
    let a1 = i * step;
    let a2 = a1 + step * duty;
    brush.arc(cx, cy, r, a1, a2);
  }
}

function drawDashedLine(x1, y1, x2, y2, dashLen, gapLen, brushName, col, w = 1) {
  resetBrushState();
  brush.set(brushName, col, w);
  let d = dist(x1, y1, x2, y2);
  let steps = Math.floor(d / (dashLen + gapLen));
  for (let i = 0; i <= steps; i++) {
    let t1 = (i * (dashLen + gapLen)) / d;
    let t2 = min(1, (i * (dashLen + gapLen) + dashLen) / d);
    if (t1 < 1) {
      brush.line(lerp(x1, x2, t1), lerp(y1, y2, t1), lerp(x1, x2, t2), lerp(y1, y2, t2));
    }
  }
}

function drawConcentricStipple(cx, cy, rIn, rOut, stepR, brushName, col, w = 1) {
  resetBrushState();
  brush.set(brushName, col, w);
  for (let r = rIn; r <= rOut; r += stepR) {
    brush.circle(cx, cy, r, 0);
  }
}

// =============================================================================
// 1. E-INK SCREEN GROUND & GHOSTED PREVIOUS IMAGE (SECOND OFFSET GEAR)
// =============================================================================

function drawDisplayGround() {
  // Subtle e-ink micro-capsule grain across the unlit display
  resetBrushState();
  brush.set("dither_1", PAL.GHOST_HI, 0.85);
  for (let y = 24; y < 1180; y += 16) {
    brush.line(24, y, 1176, y);
  }
  brush.set("stipple_micro", PAL.GHOST_MD, 0.7);
  for (let y = 32; y < 1176; y += 28) {
    brush.line(28, y, 1172, y);
  }
}

function drawGhostedGearSystem(isOverlayPass) {
  // Previous e-ink frame: A large offset technical gear at (775, 370) + secondary pinion at (330, 250)
  const gx = 775;
  const gy = 370;
  const gr = 345;

  if (!isOverlayPass) {
    // Full low-contrast ghosted rendering on the unlit display ground
    // Outer toothed ring of the ghost gear
    drawGearTeethRing(
      gx, gy,
      gr - 46, gr - 16, gr - 7, gr + 6,
      64,
      null,
      [{ brush: "dither_2", col: PAL.GHOST_LO, dist: 6, angle: 0 }],
      PAL.GHOST_LO,
      true
    );

    // Bright ghost halo on the inner rim (classic e-ink waveform inverse artifact)
    drawAnnulus(
      gx, gy, gr - 62, gr - 46,
      PAL.GHOST_HI,
      [{ brush: "dither_1", col: PAL.GHOST_LO, dist: 8, angle: 45 }],
      "hairline", PAL.GHOST_LO, 0.7
    );

    // 6 wide technical spokes on the ghost gear
    drawSpokes(
      gx, gy,
      95, gr - 62,
      6, 20, 14, 18,
      null,
      [{ brush: "dither_1", col: PAL.GHOST_LO, dist: 7, angle: -30 }],
      PAL.GHOST_LO,
      PAL.GHOST_HI
    );

    // Ghosted central hub with keyway notch
    drawAnnulus(
      gx, gy, 44, 95,
      null,
      [{ brush: "dither_2", col: PAL.GHOST_LO, dist: 6, angle: 0 }],
      "hairline", PAL.GHOST_LO, 0.8
    );

    // Pitch circle and ghosted technical callouts from previous page
    drawDashedCircle(gx, gy, gr - 7, 72, 0.55, "hairline", PAL.GHOST_LO, 0.75);
    drawDashedCircle(gx, gy, gr + 28, 90, 0.35, "hairline", PAL.GHOST_LO, 0.65);
    drawDashedLine(gx - 390, gy, gx + 380, gy, 14, 8, "hairline", PAL.GHOST_LO, 0.75);
    drawDashedLine(gx, gy - 340, gx, gy + 390, 14, 8, "hairline", PAL.GHOST_LO, 0.75);

    // Secondary meshed ghost gear at upper-left (315, 235)
    const g2x = 315;
    const g2y = 235;
    const g2r = 165;
    drawGearTeethRing(
      g2x, g2y,
      g2r - 30, g2r - 12, g2r - 5, g2r + 4,
      36,
      null,
      [{ brush: "dither_1", col: PAL.GHOST_LO, dist: 6, angle: 0 }],
      PAL.GHOST_LO,
      true
    );
    drawSpokes(
      g2x, g2y,
      46, g2r - 30,
      5, 11, 8, 12,
      null,
      [{ brush: "dither_1", col: PAL.GHOST_LO, dist: 7, angle: 45 }],
      PAL.GHOST_LO,
      null
    );
    drawAnnulus(
      g2x, g2y, 20, 46,
      null,
      [{ brush: "dither_2", col: PAL.GHOST_LO, dist: 6, angle: 0 }],
      "hairline", PAL.GHOST_LO, 0.7
    );
    drawDashedLine(g2x - 195, g2y, g2x + 195, g2y, 10, 6, "hairline", PAL.GHOST_LO, 0.65);
    drawDashedLine(g2x, g2y - 195, g2x, g2y + 195, 10, 6, "hairline", PAL.GHOST_LO, 0.65);

    // Ghosted previous page table/diagram box in top-right corner
    resetBrushState();
    brush.set("hairline", PAL.GHOST_LO, 0.7);
    brush.rect(860, 72, 265, 110, "corner");
    brush.line(860, 102, 1125, 102);
    brush.line(965, 72, 965, 182);
    for (let y = 118; y < 175; y += 16) {
      drawDashedLine(872, y, 952, y, 6, 4, "hairline", PAL.GHOST_LO, 0.65);
      drawDashedLine(978, y, 1110, y, 10, 5, "hairline", PAL.GHOST_LO, 0.65);
    }
  } else {
    // Subtle bistable persistence overlay across the foreground movement
    drawDashedCircle(gx, gy, gr - 7, 90, 0.4, "hairline", PAL.GHOST_LO, 0.65);
    drawDashedCircle(gx, gy, gr - 46, 72, 0.45, "hairline", PAL.GHOST_LO, 0.65);
    drawDashedCircle(gx, gy, 95, 36, 0.45, "hairline", PAL.GHOST_LO, 0.65);

    // Ghosted gear teeth silhouettes faintly lingering across bridges
    let stepA = 360 / 64;
    resetBrushState();
    brush.set("hairline", PAL.GHOST_LO, 0.6);
    for (let i = 0; i < 64; i += 2) {
      let a1 = i * stepA + stepA * 0.28;
      let a2 = i * stepA + stepA * 0.62;
      brush.arc(gx, gy, gr + 5, a1, a2);
      brush.line(
        gx + cos(a1) * (gr - 14), gy + sin(a1) * (gr - 14),
        gx + cos(a1) * (gr + 5), gy + sin(a1) * (gr + 5)
      );
    }
  }
}

// =============================================================================
// 2. MAINPLATE (PLATINE) & MILLED RECESSES
// =============================================================================

function drawMainplateAndRecesses() {
  // Outer stepped casing flange with mounting lugs/ears
  drawAnnulus(
    MCX, MCY, MR - 24, MR + 14,
    PAL.BG,
    [
      { brush: "dither_2", col: PAL.STEP2, dist: 6, angle: 0 },
      { brush: "dither_1", col: PAL.STEP3, dist: 8, angle: 90 }
    ],
    "bold_pen", PAL.INK, 1.0
  );

  // Outer bevel ticks (degree/machining graduations around casing flange)
  resetBrushState();
  brush.set("hairline", PAL.STEP4, 0.8);
  for (let a = 0; a < 360; a += 3) {
    let r1 = (a % 15 === 0) ? MR - 22 : MR - 10;
    brush.line(
      MCX + cos(a) * r1, MCY + sin(a) * r1,
      MCX + cos(a) * (MR + 13), MCY + sin(a) * (MR + 13)
    );
  }

  // Mainplate frosted surface (maillechort / German silver rendered with fine stippling)
  let mainplatePts = makeCirclePts(MCX, MCY, MR - 24, 96);
  renderPoly(
    mainplatePts,
    PAL.BG,
    [
