  );

  // Concentric engine-turned stipple rings on mainplate perimeter
  drawConcentricStipple(MCX, MCY, MR - 65, MR - 28, 7, "stipple_micro", PAL.STEP3, 0.85);

  // Deep milled recesses in the mainplate for the gear train and barrel
  const recesses = [
