    { x: 585, y: 835, r: 116, depth: "mid" },   // Fourth wheel recess
    { x: 755, y: 760, r: 84,  depth: "deep" },  // Escape wheel recess
    { x: 755, y: 515, r: 162, depth: "deep" }   // Balance assembly recess
