          { brush: "dither_2", col: PAL.STEP3, dist: 6, angle: 0 },
          { brush: "dither_2", col: PAL.STEP2, dist: 6, angle: 90 },
          { brush: "stipple_micro", col: PAL.STEP4, dist: 8, angle: -45 }
        ];
    renderPoly(pts, PAL.BG, floorHatches, "tech_pen", PAL.INK, 1.0);

    // Perlage (overlapping stippled circles) on recess floor
    resetBrushState();
    brush.set("stipple_micro", PAL.STEP4, 0.85);
    let ringR = rec.r * 0.62;
    for (let a = 0; a < 360; a += 30) {
      brush.circle(rec.x + cos(a) * ringR, rec.y + sin(a) * ringR, rec.r * 0.32, 0);
    }

    // Stepped vertical wall / chamfer around recess rim
    drawAnnulus(
      rec.x, rec.y, rec.r - 8, rec.r,
      null,
      [{ brush: "dither_4", col: PAL.STEP4, dist: 5, angle: 45 }],
      "hairline", PAL.INK, 0.9
    );
  }
}

