function drawMainspringBarrel(cx, cy, r) {
  // Outer toothed barrel drum
  drawGearTeethRing(
    cx, cy,
    r - 22, r - 6, r - 2, r + 4,
    80,
    PAL.BG,
    [{ brush: "dither_2", col: PAL.STEP3, dist: 6, angle: 0 }],
    PAL.INK
  );

  // Dark interior cavity of the open barrel showing the coiled mainspring
  let cavityPts = makeCirclePts(cx, cy, r - 22, 64);
  renderPoly(
    cavityPts,
    PAL.BG,
    [
      { brush: "dither_4", col: PAL.STEP4, dist: 5, angle: 0 },
      { brush: "dither_3", col: PAL.INK, dist: 6, angle: 90 }
    ],
    "tech_pen", PAL.INK, 1.1
  );

  // Coiled Mainspring inside the barrel drum (Archimedean spiral bands)
  resetBrushState();
  const coils = 10.5;
  const maxTheta = coils * 360;
  const rStart = 42;
  const rEnd = r - 25;

  // Draw light paper-grey top edge of mainspring blade + crisp ink separation
  for (let pass = 0; pass < 2; pass++) {
    brush.set(pass === 0 ? "bold_pen" : "hairline", pass === 0 ? PAL.STEP1 : PAL.INK, pass === 0 ? 1.15 : 0.9);
    let rOffset = (pass === 0) ? 1.6 : 0;
    let prevX = cx + rStart + rOffset;
    let prevY = cy;
    for (let t = 12; t <= maxTheta; t += 12) {
      let rad = lerp(rStart, rEnd, pow(t / maxTheta, 0.82)) + rOffset;
      let x = cx + cos(t) * rad;
      let y = cy + sin(t) * rad;
      brush.line(prevX, prevY, x, y);
      prevX = x;
      prevY = y;
    }
  }

  // Partial cutaway drum cover (3-arm skeletonized barrel cover)
  drawAnnulus(
    cx, cy, r - 36, r - 22,
    PAL.BG,
    [{ brush: "dither_1", col: PAL.STEP3, dist: 6, angle: -45 }],
    "tech_pen", PAL.INK, 0.95
  );

  // Central barrel arbor & mainspring hook
  let arborPts = makeCirclePts(cx, cy, 42, 48);
  renderPoly(
    arborPts,
    PAL.BG,
    [
      { brush: "dither_2", col: PAL.STEP3, dist: 6, angle: 0 },
      { brush: "stipple_fine", col: PAL.STEP4, dist: 7, angle: 60 }
    ],
    "tech_pen", PAL.INK, 1.0
  );
}

