function drawBridgeWithGenevaAndAnglage(outerPts, innerPts, stripAngle = -28) {
  // 1. Wash entire bridge footprint with opaque e-ink paper ground to occlude lower gears
  renderPoly(outerPts, PAL.BG, [
    { brush: "dither_2", col: PAL.STEP3, dist: 5, angle: stripAngle + 90 }
  ], "bold_pen", PAL.INK, 1.15);

  // 2. Anglage facet differentiation along outer bevel segments
  resetBrushState();
  for (let i = 0; i < outerPts.length; i++) {
    let ni = (i + 1) % outerPts.length;
    let quad = [outerPts[i], outerPts[ni], innerPts[ni], innerPts[i]];
    let dx = outerPts[ni][0] - outerPts[i][0];
    let dy = outerPts[ni][1] - outerPts[i][1];
    let ang = atan2(dy, dx);
    // Flat technical bevel lighting: discrete e-ink step based on edge orientation
    let bevelHatches = [];
    if (sin(ang - 45) > 0.35) {
      // Bright paper bevel highlight
      bevelHatches = [];
    } else if (sin(ang - 45) > -0.25) {
      bevelHatches = [{ brush: "dither_2", col: PAL.STEP2, dist: 5, angle: 0 }];
    } else {
      bevelHatches = [
        { brush: "dither_3", col: PAL.STEP4, dist: 5, angle: 0 },
        { brush: "dither_2", col: PAL.INK, dist: 6, angle: 90 }
      ];
    }
    renderPoly(quad, PAL.BG, bevelHatches, "hairline", PAL.STEP4, 0.65);
  }

  // 3. Inner bridge plateau with ordered-dither Côtes de Genève + fine stippling
  renderPoly(
    innerPts,
    PAL.BG,
    [
      { brush: "dither_1", col: PAL.STEP2, dist: 6, angle: stripAngle },
      { brush: "stipple_micro", col: PAL.STEP3, dist: 8, angle: stripAngle + 90 },
      // Geneva stripe rib pattern via wide-spaced dense dither passes
      { brush: "dither_3", col: PAL.STEP3, dist: 26, angle: stripAngle },
      { brush: "hairline", col: PAL.STEP4, dist: 26, angle: stripAngle }
    ],
    "tech_pen", PAL.INK, 0.95
  );

  // Re-stroke crisp outer boundary
  resetBrushState();
  brush.set("bold_pen", PAL.INK, 1.1);
  new brush.Polygon(outerPts).draw("bold_pen", PAL.INK, 1.1);
}

function computeInsetPts(pts, insetDist) {
  let n = pts.length;
  let res = [];
  // Compute centroid for inward direction check
  let cx = 0, cy = 0;
  for (let p of pts) { cx += p[0]; cy += p[1]; }
  cx /= n; cy /= n;

  for (let i = 0; i < n; i++) {
    let pPrev = pts[(i - 1 + n) % n];
    let pCurr = pts[i];
    let pNext = pts[(i + 1) % n];

    let v1x = pCurr[0] - pPrev[0], v1y = pCurr[1] - pPrev[1];
    let l1 = Math.hypot(v1x, v1y) || 1;
    v1x /= l1; v1y /= l1;

    let v2x = pNext[0] - pCurr[0], v2y = pNext[1] - pCurr[1];
    let l2 = Math.hypot(v2x, v2y) || 1;
    v2x /= l2; v2y /= l2;

    let n1x = -v1y, n1y = v1x;
    let n2x = -v2y, n2y = v2x;

    let bx = n1x + n2x, by = n1y + n2y;
    let bl = Math.hypot(bx, by) || 1;
    bx /= bl; by /= bl;

    // Ensure normal points inward toward centroid
    let toCx = cx - pCurr[0], toCy = cy - pCurr[1];
    if (bx * toCx + by * toCy < 0) {
      bx = -bx; by = -by;
    }

    res.push([pCurr[0] + bx * insetDist, pCurr[1] + by * insetDist]);
  }
  return res;
}

