  // 2. Balance Wheel Rim (Glucydur rim with 16 poising/timing weights & screws)
  drawAnnulus(
    bx, by, br - 18, br,
    PAL.BG,
    [
      { brush: "dither_1", col: PAL.STEP2, dist: 5, angle: 0 },
      { brush: "dither_2", col: PAL.STEP3, dist: 6, angle: 90 }
    ],
    "bold_pen", PAL.INK, 1.05
  );

  // Inner and outer chamfer rings on the Balance Wheel rim
  drawAnnulus(
    bx, by, br - 22, br - 18,
    PAL.BG,
    [{ brush: "dither_3", col: PAL.STEP4, dist: 4, angle: 45 }],
    "hairline", PAL.INK, 0.8
