  // 16 Timing / Poising Screws around the Balance Wheel rim
  resetBrushState();
  for (let i = 0; i < 16; i++) {
    let a = i * 22.5 + 11.25;
    let perp = a + 90;
    // Outer screw head projecting from rim
    let rInS = br;
    let rOutS = br + 7.5;
    let wS = 3.8;
    let sPts = [
      [bx + cos(a) * rInS + cos(perp) * wS, by + sin(a) * rInS + sin(perp) * wS],
      [bx + cos(a) * rOutS + cos(perp) * wS, by + sin(a) * rOutS + sin(perp) * wS],
      [bx + cos(a) * rOutS - cos(perp) * wS, by + sin(a) * rOutS - sin(perp) * wS],
      [bx + cos(a) * rInS - cos(perp) * wS, by + sin(a) * rInS - sin(perp) * wS]
    ];
    renderPoly(sPts, PAL.BG, [{ brush: "dither_3", col: PAL.STEP4, dist: 4, angle: 0 }], "hairline", PAL.INK, 0.85);
    // Screw slot
    brush.set("hairline", PAL.INK, 0.9);
    brush.line(
      bx + cos(a) * (rOutS - 2), by + sin(a) * (rOutS - 2),
      bx + cos(a) * rOutS, by + sin(a) * rOutS
    );

    // Inner poising nut on even indices
    if (i % 2 === 0) {
      let nPts = [
        [bx + cos(a) * (br - 22) + cos(perp) * 3.2, by + sin(a) * (br - 22) + sin(perp) * 3.2],
        [bx + cos(a) * (br - 27) + cos(perp) * 3.2, by + sin(a) * (br - 27) + sin(perp) * 3.2],
        [bx + cos(a) * (br - 27) - cos(perp) * 3.2, by + sin(a) * (br - 27) - sin(perp) * 3.2],
        [bx + cos(a) * (br - 22) - cos(perp) * 3.2, by + sin(a) * (br - 22) - sin(perp) * 3.2]
      ];
      renderPoly(nPts, PAL.BG, [{ brush: "dither_2", col: PAL.STEP4, dist: 4, angle: 0 }], "hairline", PAL.INK, 0.8);
    }
  }

  // 3. 4 Sculpted Balance Wheel Spokes (positioned at 35, 125, 215, 305 deg)
  drawSpokes(
    bx, by, 28, br - 22,
    4, 9.0, 6.5, 35,
    PAL.BG,
    [{ brush: "dither_1", col: PAL.STEP2, dist: 5, angle: 35 }],
    PAL.INK, PAL.STEP3
  );

  // 4. THE HAIRSPRING (13.5 Archimedean Spiral Coils + Breguet Overcoil)
  // Central brass/steel collet holding inner end of hairspring
  let colletPts = makeCirclePts(bx, by, 19, 32);
  renderPoly(
    colletPts,
    PAL.BG,
    [{ brush: "dither_3", col: PAL.STEP4, dist: 4, angle: 0 }],
    "tech_pen", PAL.INK, 0.95
  );

  resetBrushState();
  const numCoils = 13.5;
  const totalDeg = numCoils * 360;
  const rInnerSpring = 20;
  const rOuterSpring = 96;
  const stepDeg = 6;

  // Pass 1: Ribbon depth edge (mid mechanical grey offset by 1.3px)
  brush.set("hairline", PAL.STEP3, 0.85);
  let px1 = bx + rInnerSpring + 1.3;
  let py1 = by;
  for (let deg = stepDeg; deg <= totalDeg; deg += stepDeg) {
    let r = lerp(rInnerSpring, rOuterSpring, deg / totalDeg) + 1.3;
    let x = bx + cos(deg) * r;
    let y = by + sin(deg) * r;
    brush.line(px1, py1, x, y);
    px1 = x;
    py1 = y;
  }

  // Pass 2: Razor-sharp e-ink dark primary hairspring blade
  brush.set("tech_pen", PAL.INK, 0.82);
  let px2 = bx + rInnerSpring;
  let py2 = by;
  for (let deg = stepDeg; deg <= totalDeg; deg += stepDeg) {
    let r = lerp(rInnerSpring, rOuterSpring, deg / totalDeg);
    let x = bx + cos(deg) * r;
    let y = by + sin(deg) * r;
    brush.line(px2, py2, x, y);
    px2 = x;
    py2 = y;
  }

  // Pass 3: Breguet Overcoil rising across the upper coils to the regulator pins & stud
  // Draw a crisp paper-white separation halo first so the elevated overcoil crosses cleanly over the flat coils
  let overcoilPts = [
    [px2, py2],
    [bx - 75, by - 58],
    [bx - 38, by - 78],
    [bx + 12, by - 74],
    [bx + 48, by - 88], // Regulator curb pins location
    [bx + 88, by - 68]  // Hairspring stud location
  ];
  brush.set("bold_pen", PAL.BG, 1.8);
  brush.spline(overcoilPts, 0.5);
  brush.set("tech_pen", PAL.INK, 1.05);
  brush.spline(overcoilPts, 0.5);
}

