function drawRubyJewel(cx, cy, rRuby, hasChaton = true, isShockSpring = false) {
  // 1. Countersunk concave dish in bridge
  let rSink = rRuby * (hasChaton ? 1.85 : 1.45);
  let rMid  = rRuby * (hasChaton ? 1.38 : 1.0);
  drawAnnulus(
    cx, cy, rMid, rSink,
    PAL.BG,
    [
      { brush: "dither_2", col: PAL.STEP3, dist: 5, angle: 45 },
      { brush: "stipple_micro", col: PAL.STEP4, dist: 6, angle: -45 }
    ],
    "tech_pen", PAL.INK, 0.95
  );
  // Radial light/dark bevel facets on countersink
  for (let f = 0; f < 2; f++) {
    let a = f * 180 - 45;
    let fPts = makeArcSectorPts(cx, cy, rMid, rSink, a, a + 55, 12);
    renderPoly(
      fPts,
      f === 0 ? PAL.BG : null,
      f === 0 ? [] : [{ brush: "dither_4", col: PAL.STEP4, dist: 4, angle: 0 }],
      "hairline", PAL.STEP3, 0.65
    );
  }

  // 2. Gold/Metal Chaton Ring (in warm greyscale)
  if (hasChaton) {
    drawAnnulus(
      cx, cy, rRuby, rMid,
      PAL.BG,
      [
        { brush: "dither_1", col: PAL.STEP2, dist: 5, angle: 0 },
        { brush: "stipple_fine", col: PAL.STEP3, dist: 6, angle: 90 }
      ],
      "tech_pen", PAL.INK, 1.0
    );
  }

  // 3. Translucent Synthetic Ruby Body (Deep dark cross-dither + crisp crystalline facets)
  let rubyPts = makeCirclePts(cx, cy, rRuby, 40);
  renderPoly(
    rubyPts,
    PAL.BG,
    [
      { brush: "dither_4", col: PAL.STEP4, dist: 4.5, angle: 0 },
      { brush: "dither_4", col: PAL.INK, dist: 5.0, angle: 90 },
      { brush: "stipple_fine", col: PAL.INK, dist: 6.0, angle: 45 }
    ],
    "bold_pen", PAL.INK, 1.05
  );

  // Crisp geometric specular reflection windows inside the ruby (no soft blending!)
  let spec1 = makeArcSectorPts(cx, cy, rRuby * 0.45, rRuby * 0.88, -68, -18, 10);
  renderPoly(spec1, PAL.BG, [], "hairline", PAL.INK, 0.75);

  let spec2 = makeArcSectorPts(cx, cy, rRuby * 0.48, rRuby * 0.85, 110, 158, 10);
  renderPoly(spec2, PAL.BG, [{ brush: "dither_2", col: PAL.STEP2, dist: 4, angle: 0 }], "hairline", PAL.INK, 0.75);

  // Crystalline crown facet lines
  resetBrushState();
  brush.set("hairline", PAL.STEP1, 0.75);
  for (let a = 0; a < 360; a += 45) {
    brush.line(
      cx + cos(a) * (rRuby * 0.44), cy + sin(a) * (rRuby * 0.44),
      cx + cos(a) * (rRuby * 0.94), cy + sin(a) * (rRuby * 0.94)
    );
  }

  // 4. Central Oil Sink & Polished Steel Pivot Tip
  let oilPts = makeCirclePts(cx, cy, rRuby * 0.44, 28);
  renderPoly(
    oilPts,
    PAL.BG,
    [{ brush: "dither_3", col: PAL.STEP3, dist: 4, angle: 45 }],
    "hairline", PAL.INK, 0.9
  );

  let pivotPts = makeCirclePts(cx, cy, rRuby * 0.24, 24);
  renderPoly(
    pivotPts,
    PAL.BG,
    [{ brush: "dither_2", col: PAL.STEP4, dist: 4, angle: 0 }],
    "tech_pen", PAL.INK, 0.95
  );
  // Crisp white highlight dot on steel pivot
  let hiPts = makeCirclePts(cx - rRuby * 0.07, cy - rRuby * 0.07, rRuby * 0.09, 12);
  renderPoly(hiPts, PAL.BG, [], "hairline", PAL.STEP2, 0.6);

  // 5. Incabloc Lyre Shock-Protection Spring (for Balance Wheel Jewel)
  if (isShockSpring) {
    resetBrushState();
    brush.set("tech_pen", PAL.INK, 1.0);
    for (let side of [-1, 1]) {
      let lyrePts = [
        [cx + side * 6, cy + rRuby * 1.25],
        [cx + side * (rRuby * 1.42), cy + rRuby * 0.4],
        [cx + side * (rRuby * 0.95), cy - rRuby * 0.55],
        [cx + side * (rRuby * 1.25), cy - rRuby * 1.15],
        [cx + side * 5, cy - rRuby * 1.45]
      ];
      brush.set("bold_pen", PAL.BG, 1.4);
      brush.spline(lyrePts, 0.5);
      brush.set("tech_pen", PAL.INK, 1.05);
      brush.spline(lyrePts, 0.5);
    }
  }
}

function drawScrew(cx, cy, r, slotAngle = 35, isDarkBlued = false) {
  // Countersink bevel
  drawAnnulus(
    cx, cy, r, r + 3.5,
    PAL.BG,
    [{ brush: "dither_3", col: PAL.STEP4, dist: 4, angle: 45 }],
    "hairline", PAL.INK, 0.85
  );

  // Screw head
  let headPts = makeCirclePts(cx, cy, r, 32);
  let hatches = isDarkBlued
    ? [
        { brush: "dither_3", col: PAL.STEP4, dist: 4.5, angle: 0 },
        { brush: "dither_2", col: PAL.INK, dist: 5.0, angle: 90 }
      ]
    : [
        { brush: "dither_1", col: PAL.STEP2, dist: 5.0, angle: slotAngle + 90 }
      ];
  renderPoly(headPts, PAL.BG, hatches, "tech_pen", PAL.INK, 0.95);

  // Specular half-crescent on dark blued screws
  if (isDarkBlued) {
    let hiArc = makeArcSectorPts(cx, cy, r * 0.35, r * 0.82, -70, 10, 10);
    renderPoly(hiArc, PAL.BG, [{ brush: "dither_1", col: PAL.STEP2, dist: 4, angle: 0 }], null, null);
  }

  // Prominent angled screw slot with chamfered edges
  let perp = slotAngle + 90;
  let sw = max(1.6, r * 0.18);
  let sPts = [
    [cx + cos(slotAngle) * (r - 0.5) + cos(perp) * sw, cy + sin(slotAngle) * (r - 0.5) + sin(perp) * sw],
    [cx - cos(slotAngle) * (r - 0.5) + cos(perp) * sw, cy - sin(slotAngle) * (r - 0.5) + sin(perp) * sw],
    [cx - cos(slotAngle) * (r - 0.5) - cos(perp) * sw, cy - sin(slotAngle) * (r - 0.5) - sin(perp) * sw],
    [cx + cos(slotAngle) * (r - 0.5) - cos(perp) * sw, cy + sin(slotAngle) * (r - 0.5) - sin(perp) * sw]
  ];
  renderPoly(sPts, PAL.INK, [], "hairline", PAL.INK, 0.85);

  // White paper highlight line along one edge of the slot
  resetBrushState();
  brush.set("hairline", PAL.BG, 0.9);
  brush.line(
    cx + cos(slotAngle) * (r - 1.5) + cos(perp) * (sw + 1.1),
    cy + sin(slotAngle) * (r - 1.5) + sin(perp) * (sw + 1.1),
    cx - cos(slotAngle) * (r - 1.5) + cos(perp) * (sw + 1.1),
    cy - sin(slotAngle) * (r - 1.5) + sin(perp) * (sw + 1.1)
  );
}

