const CW = 1200;
const CH = 1200;

// Cold clinical light direction in 3D world space (normalized)
// X: left-to-right, Y: vertical up from slate, Z: toward viewer
const LIGHT_DIR = (() => {
  let lx = -0.48, ly = 0.72, lz = 0.50;
  let len = Math.hypot(lx, ly, lz);
  return { x: lx / len, y: ly / len, z: lz / len };
})();

// Camera elevation pitch (looking down at the horizontal black slate at 28 degrees)
const CAM_PITCH = 28 * Math.PI / 180;
const SIN_P = Math.sin(CAM_PITCH);
const COS_P = Math.cos(CAM_PITCH);
// Camera view vector (from scene toward eye)
const VIEW_DIR = { x: 0, y: SIN_P, z: COS_P };

// Half-vector between light and view for metallic specular calculation
const HALF_VEC = (() => {
  let hx = LIGHT_DIR.x + VIEW_DIR.x;
  let hy = LIGHT_DIR.y + VIEW_DIR.y;
  let hz = LIGHT_DIR.z + VIEW_DIR.z;
  let len = Math.hypot(hx, hy, hz);
  return { x: hx / len, y: hy / len, z: hz / len };
})();

