function draw() {
  translate(-width / 2, -height / 2);

  // 1. Warm grey archival ground & faint clinical measured grid
  drawPaperGroundAndGrid();

  // 2. Top scientific plate headers & inclination geometry diagrams
  const stripX = 48;
  const stripY = 316;
  const stripW = 1104;
  const stripH = 508;
  const gutter = 11;
  const frameW = (stripW - gutter * 4) / 5; // 212 px per frame
  const frameH = stripH;

  drawTopTechnicalHeader(stripX, stripY, stripW, frameW, gutter);

  // 3. Outer Muybridge plate border backing
  brush.noStroke();
  brush.wash("#b5b3ad", 90);
  brush.rect(stripX - 10, stripY - 10, stripW + 20, stripH + 20, "corner");
  brush.noWash();

  // 4. Render each of the 5 frames in the horizontal strip
  for (let i = 0; i < 5; i++) {
    let fx = stripX + i * (frameW + gutter);
    let fy = stripY;
    drawSequenceFrame(i, fx, fy, frameW, frameH, FRAMES[i]);
  }

  // 5. Ruled frame borders, registration crosshairs & handwritten index marks
  drawStripBordersAndIndexMarks(stripX, stripY, stripW, stripH, frameW, frameH, gutter);

  // 6. Lower Marey/Muybridge chronographic precession trace & tonal calibration scale
  drawBottomChronographAndScale(stripX, stripY + stripH, stripW, frameW, gutter);

  noLoop();
}

// =============================================================================
// 1. PAPER GROUND & FAINT MEASURED GRID
// =============================================================================
function drawPaperGroundAndGrid() {
  // Subtle warm-grey paper mottling washes
  brush.noStroke();
  brush.wash("#cbc9c3", 75);
  brush.rect(40, 40, CW - 80, CH - 80, "corner");
  brush.wash("#bab8b2", 45);
  brush.rect(0, 0, CW, 190, "corner");
  brush.rect(0, CH - 180, CW, 180, "corner");
  brush.noWash();

  // Faint archival grain across paper
  brush.set("spray", "#9a9994", 0.6);
  for (let i = 0; i < 48; i++) {
    let y = map(i, 0, 47, 30, CH - 30);
    brush.line(30, y + random(-4, 4), CW - 30, y + random(-4, 4));
  }

  // Faint measured millimeter/centimeter grid
  const gx0 = 36, gy0 = 36, gx1 = CW - 36, gy1 = CH - 36;
  const minorStep = 16; // 2mm subdivisions
  const majorStep = 80; // 1cm blocks

  // Minor grid lines
  brush.set("2H", "#b0b2b4", 0.22);
  for (let x = gx0; x <= gx1; x += minorStep) {
    if ((x - gx0) % majorStep !== 0) {
      brush.line(x, gy0, x, gy1);
    }
  }
  for (let y = gy0; y <= gy1; y += minorStep) {
    if ((y - gy0) % majorStep !== 0) {
      brush.line(gx0, y, gx1, y);
    }
  }

  // Major grid lines (cool clinical grey)
  brush.set("2H", "#999ea4", 0.36);
  for (let x = gx0; x <= gx1; x += majorStep) {
    brush.line(x, gy0, x, gy1);
    // Ruler ticks on top and bottom datum
    brush.set("HB", "#697078", 0.42);
    brush.line(x, gy0 - 5, x, gy0 + 5);
    brush.line(x, gy1 - 5, x, gy1 + 5);
    brush.set("2H", "#999ea4", 0.36);
  }
  for (let y = gy0; y <= gy1; y += majorStep) {
    brush.line(gx0, y, gx1, y);
    brush.set("HB", "#697078", 0.42);
    brush.line(gx0 - 5, y, gx0 + 5, y);
    brush.line(gx1 - 5, y, gx1 + 5, y);
    brush.set("2H", "#999ea4", 0.36);
  }

  // Outer measured datum border
  brush.set("HB", "#5e646c", 0.55);
  brush.line(gx0, gy0, gx1, gy0);
  brush.line(gx1, gy0, gx1, gy1);
  brush.line(gx1, gy1, gx0, gy1);
  brush.line(gx0, gy1, gx0, gy0);

  // Corner fiducial crosshairs
  const corners = [[gx0, gy0], [gx1, gy0], [gx1, gy1], [gx0, gy1]];
  for (let [cx, cy] of corners) {
    brush.set("rotring", "#2b3038", 0.5);
    brush.line(cx - 12, cy, cx + 12, cy);
    brush.line(cx, cy - 12, cx, cy + 12);
    brush.circle(cx, cy, 5, 0.05);
  }
}

// =============================================================================
// 2. TOP TECHNICAL HEADER & INCLINATION GEOMETRY DIAGRAMS
// =============================================================================
function drawTopTechnicalHeader(stripX, stripY, stripW, frameW, gutter) {
  // Top title & plate metadata
  drawGlyphText("PLATE IV. — PRECESSION & COLLAPSE OF AN OBLATE SILVER DISK ON CLEAVED SLATE", stripX, 66, 9.5, "#363c44", 0.48);
  drawGlyphText("CHRONOPHOTOGRAPHIC GRAPHITE STUDY  |  INTERVAL dt = 0.145 s  |  SCALE 1 : 1", stripX, 86, 7.5, "#555c66", 0.38);
  drawGlyphText("SPECIMEN: AR .900 CROWN (38.1 mm, 26.73 g)", stripX + stripW - 335, 66, 7.5, "#424952", 0.40);
  drawGlyphText("ILLUMINATION: COLLIMATED COLD ARC, 54 DEG", stripX + stripW - 335, 86, 7.5, "#555c66", 0.36);

  // Horizontal ruled divider line
  brush.set("HB", "#4b525b", 0.5);
  brush.line(stripX, 102, stripX + stripW, 102);
  brush.set("2H", "#7a828c", 0.3);
  brush.line(stripX, 106, stripX + stripW, 106);

  // Analytical inclination schematics centered over each of the 5 frames
  const diagY = 204;
  const rad = 46;

  // Connecting horizontal datum across all 5 diagrams
  brush.set("2H", "#858c94", 0.32);
  brush.line(stripX, diagY, stripX + stripW, diagY);

  for (let i = 0; i < 5; i++) {
    let f = FRAMES[i];
    let cx = stripX + i * (frameW + gutter) + frameW * 0.5;

    // Vertical drop-line into frame
    brush.set("2H", "#808790", 0.32);
    for (let y = 122; y < stripY - 10; y += 10) {
      brush.line(cx, y, cx, Math.min(y + 5, stripY - 10));
    }

    // Protractor reference circle
    brush.set("2H", "#7c838c", 0.35);
    brush.circle(cx, diagY, rad, 0.08);

    // Slate surface baseline in diagram
    brush.set("HB", "#383f47", 0.55);
    brush.line(cx - rad - 10, diagY, cx + rad + 10, diagY);

    // Hatching under the slate datum
    brush.set("2H", "#636b75", 0.3);
    for (let hx = cx - rad - 6; hx <= cx + rad + 6; hx += 6) {
      brush.line(hx, diagY, hx - 5, diagY + 7);
    }

    // Tilted coin chord at angle tiltDeg
    let ang = f.tiltDeg * Math.PI / 180;
    let dirSign = (i % 2 === 0) ? 1 : -1;
    let xTip = cx + dirSign * Math.cos(ang) * (rad * 1.35);
    let yTip = diagY - Math.sin(ang) * (rad * 1.35);

    // Normal vector arrow
    let nx = -dirSign * Math.sin(ang) * (rad * 0.72);
    let ny = -Math.cos(ang) * (rad * 0.72);
    let mx = (cx + xTip) * 0.5;
    let my = (diagY + yTip) * 0.5;
    brush.set("2H", "#535b65", 0.38);
    brush.line(mx, my, mx + nx, my + ny);
    brush.circle(mx + nx, my + ny, 2.2, 0.05);

    // Angle arc if tilted
    if (f.tiltDeg > 1) {
      brush.set("HB", "#454c56", 0.4);
      let startA = dirSign > 0 ? -f.tiltDeg : 180;
      let endA = dirSign > 0 ? 0 : 180 + f.tiltDeg;
      brush.arc(cx, diagY, rad * 0.55, startA, endA);
    }

    // Bold coin chord in diagram
    brush.set("rotring", "#1d2228", 0.75);
    brush.line(cx, diagY, xTip, yTip);
    brush.circle(cx, diagY, 2.5, 0.02);

    // Labels around diagram
    drawGlyphText(f.roman, cx - 6, 128, 9.5, "#262b32", 0.52);
    drawGlyphText("a = " + f.tiltDeg.toFixed(1) + " DEG", cx - 38, diagY + rad + 18, 7.2, "#394048", 0.42);
    drawGlyphText("h = " + (Math.sin(ang) * 19.05).toFixed(1) + " mm", cx - 38, diagY + rad + 33, 6.8, "#565e68", 0.36);
  }
}

// =============================================================================
// 3. SEQUENCE FRAME: STUDIO VOID, BLACK SLATE, REFLECTION & SILVER COIN
// =============================================================================
function drawSequenceFrame(idx, fx, fy, fw, fh, frameCfg) {
  const xmin = fx + 1;
  const ymin = fy + 1;
  const xmax = fx + fw - 1;
  const ymax = fy + fh - 1;

  const slateHorizonY = fy + 258; // Top horizon of the black slate table
  const slateLedgeY = fy + 448;   // Front cleaved edge of the black slate slab
  const coinContactY = fy + 318;  // Where the lowest point of the coin touches the slate
  const cx = fx + fw * 0.5;

  // --- A. STUDIO DARK GRAPHITE-CHARCOAL BACKGROUND (y: fy .. slateHorizonY) ---
  brush.noStroke();
  brush.wash("#2c3138", 215);
  brush.rect(fx, fy, fw, slateHorizonY - fy, "corner");
  brush.wash("#1e2329", 160);
  brush.rect(fx, fy + 110, fw, slateHorizonY - (fy + 110), "corner");
  // Subtle cold clinical light beam falloff from upper-left
  brush.wash("#464f5a", 65);
  brush.rect(fx, fy, fw * 0.62, (slateHorizonY - fy) * 0.65, "corner");
  brush.noWash();

  // Fine cross-hatched graphite/charcoal atmosphere in upper background
  brush.hatchStyle("2B", "#1a1f25", 0.48);
  brush.hatch(5.5, 32 + idx * 3, { rand: 0.08 });
  brush.noStroke();
  brush.rect(fx + 2, fy + 2, fw - 4, slateHorizonY - fy - 2, "corner");
  brush.noHatch();

  brush.hatchStyle("HB", "#373f49", 0.35);
  brush.hatch(7.5, -58, { rand: 0.06 });
  brush.noStroke();
  brush.rect(fx + 2, fy + 2, fw - 4, (slateHorizonY - fy) * 0.7, "corner");
  brush.noHatch();

  // Faint background collimation grid lines visible through the dark tone
  brush.set("2H", "#464f59", 0.25);
  for (let gx = fx + 26; gx < xmax; gx += 53) {
    drawClippedLine(gx, fy + 4, gx, slateHorizonY - 2, xmin, ymin, xmax, ymax);
  }
  for (let gy = fy + 42; gy < slateHorizonY; gy += 53) {
    drawClippedLine(fx + 4, gy, xmax - 4, gy, xmin, ymin, xmax, ymax);
  }

  // --- B. BLACK SLATE SLAB (y: slateHorizonY .. ymax) ---
  brush.noStroke();
  // Top polished dark slate plane
  brush.wash("#14181e", 242);
  brush.rect(fx, slateHorizonY, fw, slateLedgeY - slateHorizonY, "corner");
  // Deeper shadow gradient toward the back and bottom of slate
  brush.wash("#0b0d11", 190);
  brush.rect(fx, slateHorizonY, fw, 38, "corner");
  // Front cleaved rock face of the slate slab
  brush.wash("#080a0d", 250);
  brush.rect(fx, slateLedgeY, fw, ymax - slateLedgeY, "corner");
  brush.noWash();

  // Horizontal laminar slate grain & cold specular sheen on the black slate surface
  for (let i = 0; i < 68; i++) {
    let sy = map(i, 0, 67, slateHorizonY + 2, slateLedgeY - 2);
    let n = noise(idx * 17 + i * 0.15);
    let col = n > 0.62 ? "#38414c" : (n > 0.35 ? "#21272f" : "#0d1015");
    let w = map(sy, slateHorizonY, slateLedgeY, 0.28, 0.55);
    brush.set(n > 0.5 ? "HB" : "charcoal", col, w);
    let xStart = fx + random(0, 18);
    let xEnd = xmax - random(0, 18);
    drawClippedLine(xStart, sy, xEnd, sy + random(-0.8, 0.8), xmin, ymin, xmax, ymax);
  }

  // Subtle natural cleavage fractures on the black slate surface
  for (let c = 0; c < 4; c++) {
    let cy0 = random(slateHorizonY + 12, slateLedgeY - 16);
    let cx0 = fx + random(10, fw - 50);
    let pts = [];
    for (let s = 0; s <= 5; s++) {
      pts.push([
        constrain(cx0 + s * random(14, 24), xmin + 2, xmax - 2),
        constrain(cy0 + random(-2.5, 2.5), slateHorizonY + 2, slateLedgeY - 2),
        0.5
      ]);
    }
    brush.set("2H", "#45505e", 0.26);
    brush.spline(pts, 0.3);
    brush.set("rotring", "#080a0e", 0.32);
    let ptsShadow = pts.map(p => [p[0], p[1] + 1.1, 0.5]);
    brush.spline(ptsShadow, 0.3);
  }

  // Front bevel & foliated rock strata on the slate ledge (y: slateLedgeY .. ymax)
  brush.set("silverGlint", "#6d7887", 0.45);
  drawClippedLine(fx + 2, slateLedgeY, xmax - 2, slateLedgeY, xmin, ymin, xmax, ymax);
  brush.set("HB", "#454e59", 0.35);
  drawClippedLine(fx + 2, slateLedgeY + 1.5, xmax - 2, slateLedgeY + 1.5, xmin, ymin, xmax, ymax);

  for (let s = 0; s < 26; s++) {
    let ly = map(s, 0, 25, slateLedgeY + 4, ymax - 3);
    let col = s % 4 === 0 ? "#3b434d" : (s % 2 === 0 ? "#1f242c" : "#0b0d12");
    brush.set("charcoal", col, 0.48);
    drawClippedLine(fx + 2, ly, xmax - 2, ly + random(-1.2, 1.2), xmin, ymin, xmax, ymax);
  }

  // White chalk scale ticks along the front slate ledge
  const scaleY = ymax - 12;
  brush.set("2H", "#8c96a4", 0.32);
  drawClippedLine(fx + 18, scaleY, xmax - 18, scaleY, xmin, ymin, xmax, ymax);
  for (let tx = fx + 18; tx <= xmax - 18; tx += 14) {
    let isMaj = ((tx - (fx + 18)) % 70 === 0);
    brush.set("2H", isMaj ? "#c4ced9" : "#7c8694", isMaj ? 0.42 : 0.28);
    drawClippedLine(tx, scaleY - (isMaj ? 5 : 2.5), tx, scaleY + (isMaj ? 3 : 1.5), xmin, ymin, xmax, ymax);
  }

  // --- C. BUILD 3D COIN BASIS FOR THIS FRAME ---
  const coinR = 82;   // Coin radius in px (diameter 164 px)
  const coinT = 13.5; // Coin thickness in px (sculptural milled edge)
  const basis = buildCoinBasis(cx, coinContactY, coinR, coinT, frameCfg);

  // --- D. SPECULAR REFLECTION OF THE COIN IN THE BLACK SLATE ---
  drawCoinSlateReflection(basis, xmin, slateHorizonY + 2, xmax, slateLedgeY - 2, frameCfg);

  // --- E. CAST SHADOW & CONTACT OCCLUSION ON THE BLACK SLATE ---
  drawCoinCastShadow(basis, xmin, slateHorizonY + 2, xmax, slateLedgeY - 2, frameCfg);

  // --- F. HIGH-SPEED SPINNING GHOST ARCS & CHATTER MARKS ---
  if (frameCfg.blurArcs > 0) {
    drawSpinMotionGhosts(basis, xmin, ymin, xmax, slateLedgeY - 2, frameCfg);
  }
  drawSlateSkitterMarks(basis, cx, coinContactY, xmin, slateHorizonY + 2, xmax, slateLedgeY - 2, frameCfg);

  // --- G. HYPERREAL 3D SILVER COIN (MILLED EDGE, WORN PORTRAIT, SPECULAR STREAKS) ---
  drawHyperrealCoin(basis, xmin, ymin, xmax, ymax, frameCfg, idx);
}

// =============================================================================
// 3D COIN GEOMETRY & PROJECTION ENGINE
// =============================================================================
function buildCoinBasis(cx, contactY, R, T, frameCfg) {
  let alpha = frameCfg.tiltDeg * Math.PI / 180;
  let az = frameCfg.azDeg * Math.PI / 180;
  let spin = frameCfg.spinDeg * Math.PI / 180;

  // Coin face normal N (points out of obverse portrait face)
  // At alpha = 0 (flat), N = (0, 1, 0) pointing straight up from the slate
  let nx = Math.sin(alpha) * Math.cos(az);
  let ny = Math.cos(alpha);
  let nz = Math.sin(alpha) * Math.sin(az);
  let N = { x: nx, y: ny, z: nz };

  // Construct orthonormal basis (U0, V0) in the coin plane before in-plane spin:
  // V0 is horizontal tangent in the slate plane: (-sin(az), 0, cos(az))
  let v0x = -Math.sin(az);
  let v0y = 0;
  let v0z = Math.cos(az);

  // U0 = V0 x N (points along the steepest ascent of the tilted coin plane)
  let u0x = v0y * nz - v0z * ny; // -cos(az)*cos(alpha)
  let u0y = v0z * nx - v0x * nz; // sin(alpha)
  let u0z = v0x * ny - v0y * nx; // -sin(az)*cos(alpha)

  // Make U0 point generally Left (-X) when flat so portrait faces left in standard orientation
  // Let's align local portrait axes (U, V) smoothly across frames:
  // Use Gram-Schmidt from world (-1, 0, 0) and (0, 0, -1) projected onto plane perpendicular to N
  let refUx = -1, refUy = 0, refUz = 0;
  let dotUN = refUx * nx + refUy * ny + refUz * nz;
  let ux = refUx - dotUN * nx;
  let uy = refUy - dotUN * ny;
  let uz = refUz - dotUN * nz;
  let uLen = Math.hypot(ux, uy, uz);
  ux /= uLen; uy /= uLen; uz /= uLen;

  // V = N x U (so U, V, N is right-handed; when N=(0,1,0) and U=(-1,0,0), V=(0,0,1) or flip so +V is up on screen)
  // On screen, +Y_up or -Z_depth is up on screen. Let's set V = U x N so +V is toward the back/top of the coin
  let vx = uy * nz - uz * ny;
  let vy = uz * nx - ux * nz;
  let vz = ux * ny - uy * nx;

  // Apply in-plane spin rotation `spin` so U = right (+u), V = up (+v) on portrait face
  // Note: ux currently points left (-X), so let's negate ux,uy,uz so +u is right (+X) and -u is left (-X)
  ux = -ux; uy = -uy; uz = -uz;

  let cosS = Math.cos(spin), sinS = Math.sin(spin);
  let U = {
    x: ux * cosS - vx * sinS,
    y: uy * cosS - vy * sinS,
    z: uz * cosS - vz * sinS
  };
  let V = {
    x: ux * sinS + vx * cosS,
    y: uy * sinS + vy * cosS,
    z: uz * sinS + vz * cosS
  };

  // Height of coin center above the slate (Y_up = 0) so lowest rim point touches Y_up = 0
  let centerH = R * Math.sin(alpha) + (T * 0.5) * Math.cos(alpha);

  // 3D position of coin point (u, v, z) where u,v in [-1, 1] (normalized by R) and z in [-T/2, T/2]
  function point3D(u, v, zOffset) {
    let px = R * (u * U.x + v * V.x) + zOffset * N.x;
    let py = centerH + R * (u * U.y + v * V.y) + zOffset * N.y;
    let pz = R * (u * U.z + v * V.z) + zOffset * N.z;
    return { x: px, y: py, z: pz };
  }

  // Project 3D world point to 2D canvas coordinates
  function project3D(p) {
    return {
      x: cx + p.x,
      y: contactY - p.y * COS_P + p.z * SIN_P
    };
  }

  // Project local (u, v, zOffset) directly to 2D screen coordinates
  function project(u, v, zOffset = T * 0.5) {
    return project3D(point3D(u, v, zOffset));
  }

  // Project reflection in the black slate (Y_up -> -Y_up)
  function projectReflected(u, v, zOffset = T * 0.5) {
    let p = point3D(u, v, zOffset);
    return {
      x: cx + p.x,
      y: contactY + p.y * COS_P + p.z * SIN_P
    };
  }

  // Project cast shadow onto the slate (Y_up = 0) along LIGHT_DIR
  function projectShadow(u, v, zOffset = 0) {
    let p = point3D(u, v, zOffset);
    let t = p.y / LIGHT_DIR.y;
    let sx = p.x - t * LIGHT_DIR.x;
    let sz = p.z - t * LIGHT_DIR.z;
    return {
      x: cx + sx,
      y: contactY + sz * SIN_P
    };
  }

  return {
    cx, contactY, R, T, alpha, az, spin,
    N, U, V, centerH,
    point3D, project3D, project, projectReflected, projectShadow
  };
}

// =============================================================================
// SLATE REFLECTION, CAST SHADOW & MOTION EFFECTS
// =============================================================================
function drawCoinSlateReflection(basis, xmin, ymin, xmax, ymax, frameCfg) {
  const { R, T, projectReflected } = basis;

  // Soft dark-silver reflection wash in the polished black slate
  let polyPts = [];
  for (let a = 0; a < 360; a += 10) {
    let rad = a * Math.PI / 180;
    let p = projectReflected(Math.cos(rad), Math.sin(rad), -T * 0.5);
    polyPts.push([
      constrain(p.x, xmin + 2, xmax - 2),
      constrain(p.y, ymin + 2, ymax - 2)
    ]);
  }
  let reflPoly = new brush.Polygon(polyPts);
  reflPoly.wash("#3c4654", 42);

  // Horizontal broken specular reflection streaks across the reflected coin disk
  let steps = 42;
  for (let i = 0; i < steps; i++) {
    let v = map(i, 0, steps - 1, -0.95, 0.95);
    let maxU = Math.sqrt(Math.max(0, 1 - v * v));
    let pL = projectReflected(-maxU, v, T * 0.5);
    let pR = projectReflected(maxU, v, T * 0.5);

    // Break reflection into horizontal slate-cleavage segments
    let segs = 4;
    for (let s = 0; s < segs; s++) {
      let t0 = s / segs + random(0, 0.05);
      let t1 = (s + 0.75) / segs;
      let x0 = lerp(pL.x, pR.x, t0);
      let y0 = lerp(pL.y, pR.y, t0);
      let x1 = lerp(pL.x, pR.x, t1);
      let y1 = lerp(pL.y, pR.y, t1);

      // Reflection intensity fades with distance below contact point
      let distFade = constrain(map((y0 + y1) * 0.5 - basis.contactY, 0, 130, 1.0, 0.15), 0.1, 1.0);
      if (random() < 0.78 * distFade) {
        let isGlint = Math.abs(v + 0.15) < 0.25 && s === 1;
        let col = isGlint ? "#8c9baa" : (distFade > 0.55 ? "#5a6675" : "#303842");
        brush.set(isGlint ? "silverGlint" : "HB", col, isGlint ? 0.45 : 0.35);
        // Horizontal shear from slate cleavage
        drawClippedLine(x0, y0, x1, y0 + (y1 - y0) * 0.35, xmin, ymin, xmax, ymax);
      }
    }
  }

  // Reflected milled edge glints right below the contact zone
  for (let a = 0; a < 360; a += 8) {
    let rad = a * Math.PI / 180;
    let pTop = projectReflected(Math.cos(rad), Math.sin(rad), T * 0.5);
    let pBot = projectReflected(Math.cos(rad), Math.sin(rad), -T * 0.5);
    if (pTop.y > basis.contactY - 4 && pTop.y < basis.contactY + 75) {
      let col = (a % 24 === 0) ? "#7d8b99" : "#3b4450";
      brush.set("2H", col, 0.3);
      drawClippedLine(pTop.x, pTop.y, pBot.x, pBot.y, xmin, ymin, xmax, ymax);
    }
  }
}

function drawCoinCastShadow(basis, xmin, ymin, xmax, ymax, frameCfg) {
  const { T, projectShadow, point3D, project3D } = basis;

  // Cast shadow polygon on the slate surface
  let shadPts = [];
  for (let a = 0; a < 360; a += 10) {
    let rad = a * Math.PI / 180;
    let p = projectShadow(Math.cos(rad), Math.sin(rad), 0);
    shadPts.push([
      constrain(p.x, xmin + 2, xmax - 2),
      constrain(p.y, ymin + 2, ymax - 2)
    ]);
  }
  let shadPoly = new brush.Polygon(shadPts);
  shadPoly.wash("#050709", 185);

  // Dense charcoal cross-hatching inside the cast shadow umbra
  for (let i = 0; i < 38; i++) {
    let v = map(i, 0, 37, -0.96, 0.96);
    let uSpan = Math.sqrt(Math.max(0, 1 - v * v));
    let p0 = projectShadow(-uSpan, v, -T * 0.3);
    let p1 = projectShadow(uSpan, v, -T * 0.3);
    brush.set("charcoal", "#050608", 0.55);
    drawClippedLine(p0.x, p0.y, p1.x, p1.y, xmin, ymin, xmax, ymax);
  }

  // Razor-sharp contact occlusion directly where the lowest coin rim meets or hovers over the slate
  for (let a = 0; a < 360; a += 4) {
    let rad = a * Math.PI / 180;
    let p3 = point3D(Math.cos(rad), Math.sin(rad), -T * 0.5);
    if (p3.y < 28) {
      let pScreen = project3D(p3);
      let pSlate = project3D({ x: p3.x, y: 0, z: p3.z });
      brush.set("rotring", "#030406", map(p3.y, 0, 28, 0.85, 0.3));
      drawClippedLine(pSlate.x - 3, pSlate.y, pSlate.x + 3, pSlate.y, xmin, ymin, xmax, ymax);
      if (p3.y > 1.5 && p3.y < 16) {
        // Dark gap under hovering edge (especially prominent in Frame 4!)
        brush.set("charcoal", "#040507", 0.65);
        drawClippedLine(pScreen.x, pScreen.y + 1, pSlate.x, pSlate.y, xmin, ymin, xmax, ymax);
      }
    }
  }
}

function drawSpinMotionGhosts(basis, xmin, ymin, xmax, ymax, frameCfg) {
  // Ghostly high-speed silver rim arcs showing precession trajectory during shutter interval
  for (let g = 1; g <= frameCfg.blurArcs; g++) {
    let dTilt = g * 3.2;
    let dAz = g * 14 * (frameCfg.azDeg > 90 ? -1 : 1);
    let ghostCfg = {
      tiltDeg: frameCfg.tiltDeg + dTilt,
      azDeg: frameCfg.azDeg + dAz,
      spinDeg: frameCfg.spinDeg - g * 12
    };
    let gBasis = buildCoinBasis(basis.cx, basis.contactY, basis.R, basis.T, ghostCfg);

    let pts = [];
    for (let a = -70; a <= 160; a += 8) {
      let rad = a * Math.PI / 180;
      let p = gBasis.project(Math.cos(rad), Math.sin(rad), basis.T * 0.5);
      if (p.x > xmin + 3 && p.x < xmax - 3 && p.y > ymin + 3 && p.y < ymax - 3) {
        pts.push([p.x, p.y, 0.4]);
      }
    }
    if (pts.length > 3) {
      let col = g === 1 ? "#9aa6b4" : (g === 2 ? "#687380" : "#454e59");
      brush.set("2H", col, map(g, 1, frameCfg.blurArcs, 0.38, 0.18));
      brush.spline(pts, 0.4);
    }
  }
}

function drawSlateSkitterMarks(basis, cx, contactY, xmin, ymin, xmax, ymax, frameCfg) {
  // Fine spiral scratch trails and tiny slate dust particles on the black slate
  let numArcs = 5 + Math.floor(frameCfg.chatter * 6);
  for (let i = 0; i < numArcs; i++) {
    let rx = random(18, 68);
    let ry = rx * SIN_P * random(0.75, 1.15);
    let aStart = random(0, 360);
    let aSpan = random(35, 110);
    let pts = [];
    for (let a = aStart; a <= aStart + aSpan; a += 12) {
      let rad = a * Math.PI / 180;
      let px = cx + Math.cos(rad) * rx + random(-2, 2);
      let py = contactY + Math.sin(rad) * ry + random(-1, 1);
      if (px > xmin + 3 && px < xmax - 3 && py > ymin + 3 && py < ymax - 3) {
        pts.push([px, py, 0.35]);
      }
    }
    if (pts.length > 2) {
      brush.set("fineEngrave", i % 2 === 0 ? "#6e7b8a" : "#495360", 0.24);
      brush.spline(pts, 0.35);
    }
  }

  // Microscopic slate dust & silver abrasion flecks
  for (let d = 0; d < frameCfg.dustCount; d++) {
    let ang = random(0, TWO_PI);
    let dist = random(10, 82);
    let dx = cx + Math.cos(ang) * dist;
    let dy = contactY + Math.sin(ang) * dist * SIN_P + random(-8, 14);
    if (dx > xmin + 4 && dx < xmax - 4 && dy > ymin + 4 && dy < ymax - 4) {
      let col = random() < 0.35 ? "#b8c4d0" : "#5e6977";
      brush.set("rotring", col, random(0.2, 0.38));
      brush.line(dx, dy, dx + random(0.6, 1.8), dy + random(-0.4, 0.4));
    }
  }
}

// =============================================================================
// 4. HYPERREAL 3D COIN: MILLED EDGE, WORN PORTRAIT & SPECULAR STREAKS
// =============================================================================
function drawHyperrealCoin(basis, xmin, ymin, xmax, ymax, frameCfg, frameIdx) {
  const { R, T, N, U, V, project, point3D, project3D } = basis;

  // --- STEP 1: OPAQUE UNDERPAINTING OF THE COIN CYLINDER & OBVERSE FACE ---
  // Back/bottom rim polygon
  let botPts = [];
  let topPts = [];
  for (let a = 0; a < 360; a += 6) {
    let rad = a * Math.PI / 180;
    let cu = Math.cos(rad), cv = Math.sin(rad);
    let pb = project(cu, cv, -T * 0.5);
    let pt = project(cu, cv, T * 0.5);
    botPts.push([constrain(pb.x, xmin, xmax), constrain(pb.y, ymin, ymax)]);
    topPts.push([constrain(pt.x, xmin, xmax), constrain(pt.y, ymin, ymax)]);
  }
  let botPoly = new brush.Polygon(botPts);
  botPoly.wash("#2a3038", 235);

  let topPoly = new brush.Polygon(topPts);
  topPoly.wash("#7a838e", 240);

  // --- STEP 2: THE MILLED (REEDED) CYLINDRICAL EDGE ---
  // Draw 160 axial reeds around the visible front/side perimeter of the coin cylinder
  const numReeds = 160;
  for (let i = 0; i < numReeds; i++) {
    let theta = (i / numReeds) * TWO_PI;
    let cu = Math.cos(theta);
    let cv = Math.sin(theta);

    // Outward radial normal of cylinder at theta
    let rx = cu * U.x + cv * V.x;
    let ry = cu * U.y + cv * V.y;
    let rz = cu * U.z + cv * V.z;

    // Check if this reed on the cylinder wall faces the camera
    let camDot = rx * VIEW_DIR.x + ry * VIEW_DIR.y + rz * VIEW_DIR.z;
    if (camDot > -0.08) {
      let pt = project(cu, cv, T * 0.5);
      let pb = project(cu, cv, -T * 0.5);

      // Illumination of the cylinder reed
      let lightDot = rx * LIGHT_DIR.x + ry * LIGHT_DIR.y + rz * LIGHT_DIR.z;
      let specDot = Math.max(0, rx * HALF_VEC.x + ry * HALF_VEC.y + rz * HALF_VEC.z);
      let spec = Math.pow(specDot, 16);

      // Alternating convex ridge vs concave groove of the milled reeding
      let isRidge = (i % 2 === 0);
      let reedMod = isRidge ? 0.22 : -0.25;
      let lum = constrain(0.42 + 0.45 * lightDot + reedMod + 0.85 * spec, 0.05, 1.0);

      let col, brName, w;
      if (lum > 0.86) {
        col = "#f5faff";
        brName = "silverGlint";
        w = 0.52;
      } else if (lum > 0.68) {
        col = "#cdd8e4";
        brName = "fineEngrave";
        w = 0.45;
      } else if (lum > 0.46) {
        col = "#8c96a3";
        brName = "HB";
        w = 0.42;
      } else if (lum > 0.25) {
        col = "#464e58";
        brName = "2B";
        w = 0.45;
      } else {
        col = "#171b21";
        brName = "rotring";
        w = 0.48;
      }

      brush.set(brName, col, w);
      drawClippedLine(pt.x, pt.y, pb.x, pb.y, xmin, ymin, xmax, ymax);

      // Extra bright specular bead along the middle of the milled cylinder in the glare zone
      if (isRidge && spec > 0.35) {
        let pm1 = project(cu, cv, T * 0.22);
        let pm2 = project(cu, cv, -T * 0.22);
        brush.set("silverGlint", "#ffffff", 0.6);
        drawClippedLine(pm1.x, pm1.y, pm2.x, pm2.y, xmin, ymin, xmax, ymax);
      }
    }
  }

  // Bottom cylinder lip contour along the visible arc
  for (let i = 0; i < 120; i++) {
    let t0 = (i / 120) * TWO_PI;
    let t1 = ((i + 1) / 120) * TWO_PI;
    let rx = Math.cos(t0) * U.x + Math.sin(t0) * V.x;
    let ry = Math.cos(t0) * U.y + Math.sin(t0) * V.y;
    let rz = Math.cos(t0) * U.z + Math.sin(t0) * V.z;
    let camDot = rx * VIEW_DIR.x + ry * VIEW_DIR.y + rz * VIEW_DIR.z;
    if (camDot > 0.0) {
      let p0 = project(Math.cos(t0), Math.sin(t0), -T * 0.5);
      let p1 = project(Math.cos(t1), Math.sin(t1), -T * 0.5);
      brush.set("rotring", "#101419", 0.55);
      drawClippedLine(p0.x, p0.y, p1.x, p1.y, xmin, ymin, xmax, ymax);
    }
  }

  // --- STEP 3: 3D NORMAL-MAPPED TONAL SHADING OF THE OBVERSE FACE & WORN RELIEF ---
  // Scan densely across the coin disk in (u, v) to render the metallic field,
  // dark circulation patina halo around the relief, and raking relief bevels
  const gridN = 66;
  const stepUV = 2.0 / gridN;
  const eps = 0.018;

  // Anisotropic brushed metal direction on the coin face
  const brushAng = 0.42;
  const bDirU = Math.cos(brushAng);
  const bDirV = Math.sin(brushAng);

  for (let iu = 0; iu < gridN; iu++) {
    let u = -0.97 + (iu + 0.5) * stepUV;
    for (let iv = 0; iv < gridN; iv++) {
      let v = -0.97 + (iv + 0.5) * stepUV;
      let r2 = u * u + v * v;
      if (r2 > 0.95) continue;

      let hObj = getCoinRelief(u, v);
      let hU = getCoinRelief(u + eps, v);
      let hV = getCoinRelief(u, v + eps);

      // Surface gradient on coin face
      let dhu = (hU.h - hObj.h) / eps;
      let dhv = (hV.h - hObj.h) / eps;

      // Perturbed 3D normal of the relief surface
      let reliefScale = 0.26;
      let nx = N.x - reliefScale * (dhu * U.x + dhv * V.x);
      let ny = N.y - reliefScale * (dhu * U.y + dhv * V.y);
      let nz = N.z - reliefScale * (dhu * U.z + dhv * V.z);
      let nLen = Math.hypot(nx, ny, nz);
      nx /= nLen; ny /= nLen; nz /= nLen;

      // Diffuse + metallic cartwheel luster + raking relief highlights
      let ndotl = Math.max(0, nx * LIGHT_DIR.x + ny * LIGHT_DIR.y + nz * LIGHT_DIR.z);
      let ndoth = Math.max(0, nx * HALF_VEC.x + ny * HALF_VEC.y + nz * HALF_VEC.z);

      // Cartwheel luster (two opposite radial flares across the coin center)
      let radAngle = Math.atan2(v, u);
      let lusterAxis = -0.65 + frameIdx * 0.22;
      let cartwheel = Math.pow(Math.abs(Math.cos(radAngle - lusterAxis)), 7) * 0.35;

      // Linear specular band across the tilted disk
      let linearBand = Math.exp(-Math.pow((u * 0.65 + v * 0.75 - 0.12 + frameIdx * 0.04) * 3.8, 2)) * 0.42;

      // Dark circulation patina nestled into the recessed boundary around the portrait & letters
      let patina = hObj.patina * 0.32;

      let lum = 0.18 + 0.52 * ndotl + 0.55 * Math.pow(ndoth, 10) + cartwheel + linearBand - patina;
      // Worn high points catch extra cold specular sheen
      if (hObj.isWornFlat) lum += 0.12;
      lum = constrain(lum, 0.04, 1.0);

      // Elevate 3D point slightly by relief height
      let zSurf = T * 0.5 + hObj.h * 2.2;
      let sLen = 0.032;
      // Stroke direction follows brushed metal grain on field, or contours on steep slopes
      let gradMag = Math.hypot(dhu, dhv);
      let su = gradMag > 0.8 ? -dhv / gradMag : bDirU;
      let sv = gradMag > 0.8 ? dhu / gradMag : bDirV;

      let p0 = project(u - su * sLen, v - sv * sLen, zSurf);
      let p1 = project(u + su * sLen, v + sv * sLen, zSurf);

      let col, brName, w;
      if (lum > 0.88) {
        col = "#f4f9ff";
        brName = "silverGlint";
        w = 0.52;
      } else if (lum > 0.72) {
        col = "#d2dde8";
        brName = "fineEngrave";
        w = 0.46;
      } else if (lum > 0.56) {
        col = "#a3aebc";
        brName = "2H";
        w = 0.44;
      } else if (lum > 0.40) {
        col = "#707985";
        brName = "HB";
        w = 0.45;
      } else if (lum > 0.24) {
        col = "#3f4650";
        brName = "2B";
        w = 0.48;
      } else {
        col = "#1b2027";
        brName = "charcoal";
        w = 0.50;
      }

      brush.set(brName, col, w);
      drawClippedLine(p0.x, p0.y, p1.x, p1.y, xmin, ymin, xmax, ymax);
    }
  }

  // --- STEP 4: EXPLICIT WORN PROFILE PORTRAIT CONTOURS, HAIR, LAUREL & DRAPERY ---
  drawPortraitReliefDetails(basis, xmin, ymin, xmax, ymax);

  // --- STEP 5: PERIPHERAL WORN INSCRIPTION LETTERS & DENTICLES ---
  drawRimBeadingAndInscription(basis, xmin, ymin, xmax, ymax);

  // --- STEP 6: COLD CLINICAL SPECULAR STREAKS & CIRCULATION SCRATCHES ---
  drawSpecularStreaksOnCoin(basis, xmin, ymin, xmax, ymax, frameIdx);
}

// =============================================================================
// PROCEDURAL NUMISMATIC RELIEF HEIGHTMAP & EXPLICIT PORTRAIT CONTOURS
// =============================================================================
function getCoinRelief(u, v) {
  let r = Math.hypot(u, v);
  if (r > 1.0) return { h: 0, patina: 0, isWornFlat: false };

  let h = 0;
  let patina = 0;

  // 1. Raised outer rim collar (r in 0.90 .. 1.00)
  if (r > 0.89) {
    let rimT = constrain((r - 0.89) / 0.04, 0, 1);
    h = Math.max(h, 0.52 * rimT);
  }
  // Recessed crease just inside the rim (collects dark patina)
  if (r > 0.83 && r <= 0.90) {
    patina += 0.55 * Math.exp(-Math.pow((r - 0.875) / 0.018, 2));
  }

  // 2. Classical Profile Silhouette (facing left, -u)
  // Valid vertical span of portrait: v in [-0.64, 0.58]
  if (v >= -0.64 && v <= 0.58) {
    let uFront = getProfileFrontU(v);
    let uBack = getProfileBackU(v);

    if (u >= uFront && u <= uBack) {
      let width = Math.max(0.05, uBack - uFront);
      let t = (u - uFront) / width; // 0 at facial profile edge, 1 at back of hair/neck

      // Steep bevel at the front profile edge, broad plateau across cheek & cranium
      let frontBevel = constrain(t / 0.14, 0, 1);
      let backBevel = constrain((1 - t) / 0.16, 0, 1);
      let arch = Math.sin(constrain(t, 0, 1) * Math.PI);

      let baseH = 0.46 * Math.pow(frontBevel * backBevel, 0.45) + 0.18 * arch;

      // Internal anatomical sculptural modulations:
      // Eye socket depression behind nasal bridge
      let dEye = Math.hypot((u - (-0.23)) / 0.09, (v - 0.17) / 0.07);
      if (dEye < 1.0) baseH -= 0.16 * (1 - dEye * dEye);

      // Zygomatic cheekbone & jaw ridge
      let dCheek = Math.hypot((u - (-0.14)) / 0.16, (v - 0.02) / 0.15);
      if (dCheek < 1.0) baseH += 0.14 * (1 - dCheek * dCheek);

      // Laurel wreath / diadem band slanting across cranium
      let bandDist = Math.abs((u * 0.65 + v * 0.76) - 0.12);
      if (v > -0.05 && v < 0.48 && u > -0.26 && u < 0.34 && bandDist < 0.075) {
        let leafMod = 0.06 * Math.cos((u - v) * 28);
        baseH += 0.18 * (1 - bandDist / 0.075) + leafMod;
      }

      // Worn hair locks & chignon waves on back of head
      if (t > 0.48 && v > -0.18) {
        baseH += 0.08 * Math.sin((u * 18 + v * 14));
      }

      // Sternocleidomastoid neck tendon & classical bust drapery folds
      if (v < -0.20) {
        let neckTendon = Math.exp(-Math.pow((u - (-0.08 + (v + 0.25) * 0.45)) / 0.06, 2));
        baseH += 0.09 * neckTendon;
      }
      if (v < -0.44) {
        baseH += 0.08 * Math.cos((u * 22 + v * 10));
      }

      h = Math.max(h, baseH);
    } else {
      // Dark circulation patina halo immediately outside the portrait contour
      let distOut = u < uFront ? (uFront - u) : (u - uBack);
      if (distOut > 0 && distOut < 0.075) {
        patina += 0.85 * (1 - distOut / 0.075);
      }
    }
  }

  // Circulation wear: clamp & flatten the highest relief plateaus
  let isWornFlat = false;
  if (h > 0.54) {
    h = 0.54 + (h - 0.54) * 0.15;
    isWornFlat = true;
  }

  return { h, patina, isWornFlat };
}

// Piecewise smooth anatomical anterior profile curve (forehead, nose, lips, chin, throat, bust)
function getProfileFrontU(v) {
  if (v > 0.48) {
    // Upper crown rounding back
    let t = (v - 0.48) / 0.10;
    return -0.24 + 0.28 * t * t;
  } else if (v > 0.23) {
    // Forehead & brow ridge
    let t = (v - 0.23) / 0.25;
    return -0.34 + 0.10 * t - 0.02 * Math.sin(t * Math.PI);
  } else if (v > 0.18) {
    // Nasal root (nasion) indentation
    let t = (v - 0.18) / 0.05;
    return -0.31 - 0.03 * Math.cos(t * Math.PI);
  } else if (v > 0.03) {
    // Nose bridge projecting out to nose tip at v = 0.04
    let t = (0.18 - v) / 0.15;
    return -0.31 - 0.17 * Math.sin(t * Math.PI * 0.62);
  } else if (v > -0.01) {
    // Underside of nose returning to philtrum
    let t = (0.03 - v) / 0.04;
    return -0.46 + 0.10 * t;
  } else if (v > -0.13) {
    // Upper lip, mouth cleft, and lower lip
    let t = (-0.01 - v) / 0.12;
    let lipWave = 0.035 * Math.sin(t * Math.PI * 2.0);
    return -0.37 - lipWave + 0.02 * t;
  } else if (v > -0.23) {
    // Chin prominence rounding into submental line
    let t = (-0.13 - v) / 0.10;
    return -0.34 - 0.045 * Math.sin(t * Math.PI) + 0.14 * Math.pow(t, 2.4);
  } else if (v > -0.52) {
    // Anterior neck slanting down to bust point
    let t = (-0.23 - v) / 0.29;
    return -0.20 - 0.16 * t + 0.02 * Math.sin(t * Math.PI);
  } else {
    // Lower bust truncation sweeping down and right
    let t = (-0.52 - v) / 0.12;
    return -0.36 + 0.34 * t * t;
  }
}

// Posterior profile curve (occiput, chignon bun, nape of neck, posterior shoulder drapery)
function getProfileBackU(v) {
  if (v > 0.20) {
    // Crown to back of cranium
    let t = (0.58 - v) / 0.38;
    return 0.04 + 0.37 * Math.sin(t * Math.PI * 0.55);
  } else if (v > -0.10) {
    // Classical hair chignon / knot at back of head
    let t = (0.20 - v) / 0.30;
    return 0.40 + 0.11 * Math.sin(t * Math.PI) - 0.16 * t;
  } else if (v > -0.32) {
    // Nape of neck indentation
    let t = (-0.10 - v) / 0.22;
    return 0.24 - 0.04 * Math.sin(t * Math.PI) + 0.05 * t;
  } else {
    // Posterior shoulder & drapery truncation
    let t = (-0.32 - v) / 0.32;
    return 0.29 + 0.07 * Math.sin(t * Math.PI * 0.7) - 0.38 * Math.pow(t, 2.2);
  }
}

function drawPortraitReliefDetails(basis, xmin, ymin, xmax, ymax) {
  const { T, project } = basis;
  const zTop = T * 0.5 + 1.1;

  // Helper to project and draw a 2D curve in (u, v) coin space
  function strokeCoinCurve(uvPoints, brName, col, weight, curv = 0.35) {
    let pts = [];
    for (let [u, v] of uvPoints) {
      let p = project(u, v, zTop);
      if (p.x >= xmin + 2 && p.x <= xmax - 2 && p.y >= ymin + 2 && p.y <= ymax - 2) {
        pts.push([p.x, p.y, 0.6]);
      }
    }
    if (pts.length >= 2) {
      brush.set(brName, col, weight);
      if (pts.length === 2) {
        brush.line(pts[0][0], pts[0][1], pts[1][0], pts[1][1]);
      } else {
        brush.spline(pts, curv);
      }
    }
  }

  // 1. Bright cold silver highlight along the anterior facial profile (facing the upper-left light)
  let frontHighlightPts = [];
  let frontShadowCrevicePts = [];
  for (let v = 0.55; v >= -0.58; v -= 0.025) {
    let uf = getProfileFrontU(v);
    frontHighlightPts.push([uf + 0.012, v]);
    frontShadowCrevicePts.push([uf - 0.012, v]);
  }
  strokeCoinCurve(frontShadowCrevicePts, "rotring", "#1a2027", 0.46, 0.3);
  strokeCoinCurve(frontHighlightPts, "silverGlint", "#eef6ff", 0.52, 0.3);

  // 2. Posterior head/hair/neck shadow edge (facing away from light)
  let backShadowPts = [];
  let backRimPts = [];
  for (let v = 0.55; v >= -0.58; v -= 0.03) {
    let ub = getProfileBackU(v);
    backShadowPts.push([ub + 0.012, v]);
    backRimPts.push([ub - 0.015, v]);
  }
  strokeCoinCurve(backShadowPts, "charcoal", "#161b22", 0.55, 0.35);
  strokeCoinCurve(backRimPts, "HB", "#65707d", 0.40, 0.35);

  // 3. Facial anatomy: Brow, Eye, Nostril wing, Mouth cleft, Jawline, Ear, Neck muscle
  // Brow & upper eyelid
  strokeCoinCurve([[-0.32, 0.22], [-0.25, 0.23], [-0.18, 0.20]], "rotring", "#242a32", 0.42);
  // Eye almond & pupil shadow
  strokeCoinCurve([[-0.28, 0.17], [-0.23, 0.185], [-0.18, 0.165]], "rotring", "#1d2229", 0.44);
  strokeCoinCurve([[-0.27, 0.16], [-0.23, 0.155], [-0.19, 0.165]], "silverGlint", "#d8e3ee", 0.36);
  // Nostril wing & nasolabial crease
  strokeCoinCurve([[-0.43, 0.03], [-0.36, 0.025], [-0.33, 0.05]], "rotring", "#20262e", 0.42);
  // Mouth parting line
  strokeCoinCurve([[-0.39, -0.065], [-0.33, -0.06], [-0.29, -0.07]], "rotring", "#1b2028", 0.44);
  // Chin & Mandible jawline sweeping up toward ear
  strokeCoinCurve([[-0.37, -0.19], [-0.26, -0.21], [-0.11, -0.15], [0.02, -0.04]], "HB", "#2d343d", 0.44);
  strokeCoinCurve([[-0.36, -0.17], [-0.25, -0.19], [-0.11, -0.13]], "silverGlint", "#d0dce8", 0.40);

  // 4. Laurel wreath double fillet & leaves
  strokeCoinCurve([[-0.22, 0.44], [-0.05, 0.30], [0.12, 0.16], [0.28, 0.03]], "rotring", "#232931", 0.45);
  strokeCoinCurve([[-0.19, 0.46], [-0.02, 0.32], [0.15, 0.18], [0.31, 0.05]], "silverGlint", "#e6f0fa", 0.48);

  // Laurel leaves along the diadem
  for (let l = 0; l < 5; l++) {
    let t = l / 4;
    let lu = lerp(-0.16, 0.20, t);
    let lv = lerp(0.41, 0.11, t);
    strokeCoinCurve([[lu, lv], [lu - 0.04, lv + 0.07], [lu - 0.09, lv + 0.09]], "silverGlint", "#dce7f3", 0.42);
    strokeCoinCurve([[lu, lv], [lu + 0.06, lv + 0.04], [lu + 0.08, lv + 0.08]], "HB", "#343b45", 0.38);
  }

  // 5. Worn hair waves over temple, cranium, and chignon
  const hairStrands = [
    [[-0.24, 0.34], [-0.14, 0.37], [-0.04, 0.32]],
    [[-0.18, 0.25], [-0.06, 0.27], [0.05, 0.21]],
    [[-0.08, 0.16], [0.04, 0.17], [0.16, 0.10]],
    [[0.02, 0.48], [0.16, 0.44], [0.28, 0.32], [0.36, 0.18]],
    [[0.08, 0.38], [0.22, 0.33], [0.33, 0.20], [0.39, 0.06]],
    [[0.22, 0.14], [0.36, 0.12], [0.47, 0.05], [0.43, -0.05]],
    [[0.24, 0.04], [0.38, 0.02], [0.48, -0.02], [0.38, -0.09]]
  ];
  for (let strand of hairStrands) {
    strokeCoinCurve(strand, "HB", "#2d343e", 0.40);
    let hiStrand = strand.map(([u, v]) => [u - 0.01, v + 0.012]);
    strokeCoinCurve(hiStrand, "fineEngrave", "#c8d4e0", 0.36);
  }

  // 6. Neck sternocleidomastoid & classical bust drapery folds
  strokeCoinCurve([[-0.02, -0.08], [-0.12, -0.26], [-0.24, -0.48]], "HB", "#353d47", 0.40);
  strokeCoinCurve([[-0.04, -0.08], [-0.14, -0.26], [-0.26, -0.48]], "silverGlint", "#cedae6", 0.38);

  // Truncated bust base & drapery folds
  strokeCoinCurve([[-0.35, -0.52], [-0.16, -0.59], [0.06, -0.60], [0.28, -0.54]], "rotring", "#191e25", 0.52);
  strokeCoinCurve([[-0.34, -0.50], [-0.15, -0.57], [0.06, -0.58], [0.27, -0.52]], "silverGlint", "#e4eef8", 0.46);
}

function drawRimBeadingAndInscription(basis, xmin, ymin, xmax, ymax) {
  const { T, project } = basis;
  const zRim = T * 0.5 + 0.9;

  // 1. Raised outer rim inner bevel circle (r = 0.91) and outer edge (r = 0.99)
  for (let ringR of [0.91, 0.985]) {
    for (let a = 0; a < 360; a += 6) {
      let r0 = a * Math.PI / 180;
      let r1 = (a + 6) * Math.PI / 180;
      let p0 = project(Math.cos(r0) * ringR, Math.sin(r0) * ringR, zRim);
      let p1 = project(Math.cos(r1) * ringR, Math.sin(r1) * ringR, zRim);

      // Upper-left vs lower-right bevel lighting
      let bevelLight = Math.cos(r0 - 2.35);
      if (ringR < 0.95) bevelLight = -bevelLight;

      let col = bevelLight > 0.35 ? "#e6f0fa" : (bevelLight > -0.2 ? "#7d8794" : "#222830");
      let br = bevelLight > 0.35 ? "silverGlint" : "HB";
      brush.set(br, col, 0.42);
      drawClippedLine(p0.x, p0.y, p1.x, p1.y, xmin, ymin, xmax, ymax);
    }
  }

  // 2. Worn denticles (beading ring at r = 0.875)
  for (let a = 0; a < 360; a += 5) {
    let rad = a * Math.PI / 180;
    let pIn = project(Math.cos(rad) * 0.86, Math.sin(rad) * 0.86, zRim);
    let pOut = project(Math.cos(rad) * 0.895, Math.sin(rad) * 0.895, zRim);
    let col = (a % 10 === 0) ? "#ccd7e3" : "#373f49";
    brush.set("fineEngrave", col, 0.34);
    drawClippedLine(pIn.x, pIn.y, pOut.x, pOut.y, xmin, ymin, xmax, ymax);
  }

  // 3. Worn peripheral Latin inscription & date arcs (r = 0.77 .. 0.83)
  // Left arc: "LIBERTAS" (angles 125° to 225°), Right arc: "ARGENTUM" (-45° to 55°), Bottom: "1878" (-112° to -68°)
  const legendArcs = [
    { start: 128, end: 222, count: 9 },
    { start: -42, end: 52, count: 9 },
    { start: -110, end: -70, count: 4 }
  ];

  for (let arcDef of legendArcs) {
    let step = (arcDef.end - arcDef.start) / arcDef.count;
    for (let k = 0; k < arcDef.count; k++) {
      let deg = arcDef.start + (k + 0.5) * step;
      let rad = deg * Math.PI / 180;
      let rIn = 0.755, rOut = 0.825;
      let dRad = 0.025;

      // Wear factor: some letters are worn almost flat into the field
      let wear = 0.4 + 0.6 * noise(k * 3.1 + arcDef.start);
      if (wear < 0.52) continue;

      let pB1 = project(Math.cos(rad - dRad) * rIn, Math.sin(rad - dRad) * rIn, zRim);
      let pT1 = project(Math.cos(rad - dRad) * rOut, Math.sin(rad - dRad) * rOut, zRim);
      let pB2 = project(Math.cos(rad + dRad) * rIn, Math.sin(rad + dRad) * rIn, zRim);
      let pT2 = project(Math.cos(rad + dRad) * rOut, Math.sin(rad + dRad) * rOut, zRim);

      // Dark shadow side of micro-relief letter
      brush.set("rotring", "#222830", 0.36);
      drawClippedLine(pB2.x, pB2.y, pT2.x, pT2.y, xmin, ymin, xmax, ymax);
      drawClippedLine(pB1.x, pB1.y, pB2.x, pB2.y, xmin, ymin, xmax, ymax);

      // Bright silver highlight on light-facing stem/crossbar of letter
      brush.set("silverGlint", "#dce7f2", 0.38);
      drawClippedLine(pB1.x, pB1.y, pT1.x, pT1.y, xmin, ymin, xmax, ymax);
      if (k % 2 === 0) {
        drawClippedLine(pT1.x, pT1.y, pT2.x, pT2.y, xmin, ymin, xmax, ymax);
      } else {
        drawClippedLine(pB1.x, pB1.y, pT2.x, pT2.y, xmin, ymin, xmax, ymax);
      }
    }
  }
}

function drawSpecularStreaksOnCoin(basis, xmin, ymin, xmax, ymax, frameIdx) {
  const { T, project } = basis;
  const zGlint = T * 0.5 + 1.4;

  // Cold clinical specular streaks cutting across the worn silver surface
  const streakAngle = -0.58 + frameIdx * 0.08;
  const dirU = Math.cos(streakAngle);
  const dirV = Math.sin(streakAngle);
  const perpU = -dirV;
  const perpV = dirU;

  // Primary & secondary specular bands across the coin face
  const streakOffsets = [-0.28, -0.22, -0.17, -0.12, -0.07, 0.14, 0.19, 0.24, 0.42];
  for (let s = 0; s < streakOffsets.length; s++) {
    let off = streakOffsets[s];
    let isPrimary = Math.abs(off + 0.17) < 0.08;
    let maxChord = Math.sqrt(Math.max(0, 0.88 - off * off));

    let segCount = isPrimary ? 5 : 3;
    for (let k = 0; k < segCount; k++) {
      let t0 = map(k, 0, segCount, -maxChord, maxChord) + random(-0.04, 0.04);
      let t1 = t0 + random(0.16, 0.36);
      t1 = Math.min(t1, maxChord);
      if (t1 <= t0) continue;

      let u0 = off * perpU + t0 * dirU;
      let v0 = off * perpV + t0 * dirV;
      let u1 = off * perpU + t1 * dirU;
      let v1 = off * perpV + t1 * dirV;

      let p0 = project(u0, v0, zGlint);
      let p1 = project(u1, v1, zGlint);

      brush.set("silverGlint", isPrimary ? "#ffffff" : "#e3edf7", isPrimary ? 0.62 : 0.42);
      drawClippedLine(p0.x, p0.y, p1.x, p1.y, xmin, ymin, xmax, ymax);
    }
  }

  // Fine circulation hairlines & micro-scratches catching raking cold light
  for (let m = 0; m < 18; m++) {
    let uc = random(-0.65, 0.65);
    let vc = random(-0.65, 0.65);
    if (uc * uc + vc * vc > 0.72) continue;
    let ang = random(-PI, PI);
    let len = random(0.08, 0.24);
    let p0 = project(uc - Math.cos(ang) * len, vc - Math.sin(ang) * len, zGlint);
    let p1 = project(uc + Math.cos(ang) * len, vc + Math.sin(ang) * len, zGlint);
    brush.set("fineEngrave", m % 3 === 0 ? "#f0f7ff" : "#b8c5d4", 0.28);
    drawClippedLine(p0.x, p0.y, p1.x, p1.y, xmin, ymin, xmax, ymax);
  }
}

// =============================================================================
// 5. RULED FRAME BORDERS & HANDWRITTEN-LOOKING INDEX MARKS
// =============================================================================
function drawStripBordersAndIndexMarks(stripX, stripY, stripW, stripH, frameW, frameH, gutter) {
  // Outer double-ruled architectural plate border around the entire strip
  brush.set("rotring", "#1a1f26", 0.8);
  brush.line(stripX - 6, stripY - 6, stripX + stripW + 6, stripY - 6);
  brush.line(stripX + stripW + 6, stripY - 6, stripX + stripW + 6, stripY + stripH + 6);
  brush.line(stripX + stripW + 6, stripY + stripH + 6, stripX - 6, stripY + stripH + 6);
  brush.line(stripX - 6, stripY + stripH + 6, stripX - 6, stripY - 6);

  brush.set("HB", "#454d57", 0.45);
  brush.line(stripX - 10, stripY - 10, stripX + stripW + 10, stripY - 10);
  brush.line(stripX + stripW + 10, stripY - 10, stripX + stripW + 10, stripY + stripH + 10);
  brush.line(stripX + stripW + 10, stripY + stripH + 10, stripX - 10, stripY + stripH + 10);
  brush.line(stripX - 10, stripY + stripH + 10, stripX - 10, stripY - 10);

  // Individual ruled frame borders & index marks
  for (let i = 0; i < 5; i++) {
    let fx = stripX + i * (frameW + gutter);
    let fy = stripY;
    let f = FRAMES[i];

    // Crisp ruled graphite/ink border around each frame
    brush.set("rotring", "#161a20", 0.72);
    brush.line(fx, fy, fx + frameW, fy);
    brush.line(fx + frameW, fy, fx + frameW, fy + frameH);
    brush.line(fx + frameW, fy + frameH, fx, fy + frameH);
    brush.line(fx, fy + frameH, fx, fy);

    // Inner fine silver-grey hairline border inside each frame
    brush.set("2H", "#6c7682", 0.28);
    brush.line(fx + 3, fy + 3, fx + frameW - 3, fy + 3);
    brush.line(fx + frameW - 3, fy + 3, fx + frameW - 3, fy + frameH - 3);
    brush.line(fx + frameW - 3, fy + frameH - 3, fx + 3, fy + frameH - 3);
    brush.line(fx + 3, fy + frameH - 3, fx + 3, fy + 3);

    // Small registration ticks at midpoints of frame edges
    let mx = fx + frameW * 0.5;
    let my = fy + frameH * 0.5;
    brush.set("2H", "#98a3b0", 0.35);
    brush.line(mx, fy, mx, fy + 7);
    brush.line(mx, fy + frameH - 7, mx, fy + frameH);
    brush.line(fx, my, fx + 7, my);
    brush.line(fx + frameW - 7, my, fx + frameW, my);

    // Small handwritten-looking index mark in upper-left corner inside the frame
    drawGlyphText(String(i + 1), fx + 10, fy + 14, 8.5, "#c5d0dc", 0.42);
    brush.set("2H", "#8c96a3", 0.32);
    brush.line(fx + 8, fy + 27, fx + 24, fy + 27);

    // Handwritten-looking index annotations below each frame on the warm-grey ground
    let labelY = fy + frameH + 20;
    drawGlyphText(f.id, fx + 4, labelY, 8.5, "#252b33", 0.48, true);
    drawGlyphText(f.time, fx + frameW - 88, labelY, 7.5, "#3e454f", 0.40, true);
    drawGlyphText(f.vel, fx + 4, labelY + 18, 7.0, "#505862", 0.36, true);

    // Small index tick below frame center
    brush.set("HB", "#383f48", 0.48);
    brush.line(mx, fy + frameH + 6, mx, fy + frameH + 16);
  }
}

// =============================================================================
// 6. LOWER MAREY CHRONOGRAPH TRACE & TONAL CALIBRATION WEDGE
// =============================================================================
function drawBottomChronographAndScale(stripX, bottomY, stripW, frameW, gutter) {
  const graphTop = bottomY + 66;
  const graphH = 128;
  const graphMid = graphTop + graphH * 0.5;
  const graphBot = graphTop + graphH;

  // Graph box wash
  brush.noStroke();
  brush.wash("#bcbab3", 85);
  brush.rect(stripX, graphTop, stripW, graphH, "corner");
  brush.noWash();

  // Graph borders & zero-datum axis
  brush.set("HB", "#454d56", 0.48);
  brush.line(stripX, graphTop, stripX + stripW, graphTop);
  brush.line(stripX, graphBot, stripX + stripW, graphBot);
  brush.line(stripX, graphTop, stripX, graphBot);
  brush.line(stripX + stripW, graphTop, stripX + stripW, graphBot);

  brush.set("2H", "#6f7782", 0.35);
  brush.line(stripX, graphMid, stripX + stripW, graphMid);

  // Vertical drop-lines from the 5 frame centers through the chronograph
  const restX = stripX + 4 * (frameW + gutter) + frameW * 0.5;
  const startX = stripX + frameW * 0.5;

  for (let i = 0; i < 5; i++) {
    let cx = stripX + i * (frameW + gutter) + frameW * 0.5;
    brush.set("2H", "#79818c", 0.32);
    for (let y = bottomY + 44; y <= graphBot; y += 8) {
      brush.line(cx, y, cx, Math.min(y + 4, graphBot));
    }
  }

  // Plot the Euler's Disk damped high-frequency precession wave:
  // As time approaches restX, amplitude decays to 0 while frequency chirps upward!
  let wavePts = [];
  let envTopPts = [];
  let envBotPts = [];
  const totalSamples = 260;

  for (let s = 0; s <= totalSamples; s++) {
    let x = map(s, 0, totalSamples, stripX + 16, stripX + stripW - 16);
    let u = constrain((restX - x) / (restX - startX), 0, 1.12);

    let amp = Math.pow(u, 0.72) * (graphH * 0.42);
    // Chirping phase: frequency accelerates as coin approaches flat collapse
    let phase = (1.15 - u) * 58 + Math.pow(1.15 - u, 3.2) * 42;
    let yWave = graphMid - amp * Math.cos(phase);

    wavePts.push([x, yWave, 0.55]);
    envTopPts.push([x, graphMid - amp, 0.4]);
    envBotPts.push([x, graphMid + amp, 0.4]);
  }

  // Envelope curves in fine 2H pencil
  brush.set("2H", "#747c87", 0.34);
  brush.spline(envTopPts, 0.3);
  brush.spline(envBotPts, 0.3);

  // Primary oscillation trace in crisp HB graphite + cold white highlight offset
  brush.set("silverGlint", "#e6eef7", 0.38);
  let hiWavePts = wavePts.map(p => [p[0], p[1] - 1.0, 0.4]);
  brush.spline(hiWavePts, 0.35);

  brush.set("HB", "#262c34", 0.52);
  brush.spline(wavePts, 0.35);

  // Circle markers on the envelope at each of the 5 sampled frames
  for (let i = 0; i < 5; i++) {
    let cx = stripX + i * (frameW + gutter) + frameW * 0.5;
    let u = constrain((restX - cx) / (restX - startX), 0, 1.12);
    let amp = Math.pow(u, 0.72) * (graphH * 0.42);
    brush.set("rotring", "#1b2028", 0.55);
    brush.circle(cx, graphMid - amp, 3.5, 0.05);
    brush.set("silverGlint", "#f0f7ff", 0.45);
    brush.circle(cx, graphMid - amp, 1.5, 0.02);
  }

  // Graph annotations
  drawGlyphText("FIG. 2 — VERTICAL RIM DISPLACEMENT & PRECESSION CHIRP ENVELOPE z(t)", stripX + 10, graphTop + 12, 7.0, "#383f48", 0.38);
  drawGlyphText("COLLAPSE SINGULARITY [t = 0.620 s]", restX - 82, graphBot - 18, 6.8, "#454d57", 0.36);

  // Bottom sensitometric 9-step tonal calibration wedge (charcoal to cold white chalk) & millimeter bar
  const footerY = graphBot + 28;
  drawGlyphText("MILLIMETER REFERENCE SCALE (1 DIV = 2.0 mm)", stripX, footerY, 7.0, "#464e58", 0.36);

  const barY = footerY + 18;
  const barW = 320;
  brush.set("rotring", "#242a32", 0.55);
  brush.line(stripX, barY, stripX + barW, barY);
  brush.line(stripX, barY + 6, stripX + barW, barY + 6);
  for (let x = stripX; x <= stripX + barW; x += 16) {
    let isMaj = ((x - stripX) % 80 === 0);
    brush.set("rotring", "#242a32", isMaj ? 0.55 : 0.35);
    brush.line(x, barY - (isMaj ? 4 : 0), x, barY + (isMaj ? 10 : 6));
  }

  // 9-step sensitometric greyscale strip on the bottom right
  const wedgeTones = [
    "#0c0f14", "#1d222a", "#323943", "#4c5561",
    "#6c7683", "#8e99a6", "#b2bcc8", "#d4dee8", "#f2f8ff"
  ];
  const stepW = 36, stepH = 18;
  const wedgeX = stripX + stripW - wedgeTones.length * stepW;
  const wedgeY = footerY + 6;

  drawGlyphText("TONAL STEP WEDGE (CHARCOAL / GRAPHITE / WHITE CHALK)", wedgeX - 10, footerY - 12, 6.8, "#464e58", 0.35);

  for (let s = 0; s < wedgeTones.length; s++) {
    let sx = wedgeX + s * stepW;
    brush.noStroke();
    brush.wash(wedgeTones[s], 235);
    brush.rect(sx, wedgeY, stepW, stepH, "corner");
    brush.noWash();

    brush.hatchStyle("HB", wedgeTones[s], 0.42);
    brush.hatch(3.5, 45, { rand: 0.04 });
    brush.noStroke();
    brush.rect(sx, wedgeY, stepW, stepH, "corner");
    brush.noHatch();

    brush.set("rotring", "#282e37", 0.42);
    brush.line(sx, wedgeY, sx + stepW, wedgeY);
    brush.line(sx + stepW, wedgeY, sx + stepW, wedgeY + stepH);
    brush.line(sx + stepW, wedgeY + stepH, sx, wedgeY + stepH);
    brush.line(sx, wedgeY + stepH, sx, wedgeY);
  }
}

// =============================================================================
// UTILITIES: LIANG-BARSKY LINE CLIPPING & VECTOR STROKE GLYPH RENDERER
// =============================================================================
function drawClippedLine(x1, y1, x2, y2, xmin, ymin, xmax, ymax) {
  let t0 = 0.0, t1 = 1.0;
  let dx = x2 - x1, dy = y2 - y1;

  let p = [-dx, dx, -dy, dy];
  let q = [x1 - xmin, xmax - x1, y1 - ymin, ymax - y1];

  for (let i = 0; i < 4; i++) {
    if (p[i] === 0) {
      if (q[i] < 0) return;
    } else {
      let t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return;
        if (t < t1) t1 = t;
      }
    }
  }

  if (t0 < t1) {
    let cx1 = x1 + t0 * dx;
    let cy1 = y1 + t0 * dy;
    let cx2 = x1 + t1 * dx;
    let cy2 = y1 + t1 * dy;
    if (Math.hypot(cx2 - cx1, cy2 - cy1) > 0.4) {
      brush.line(cx1, cy1, cx2, cy2);
    }
  }
}

// Vector stroke font for authentic handwritten/draughtsman technical notations via p5.brush
