function drawGlyphText(str, x, y, size, color, weight, italic = false) {
  brush.set("HB", color, weight);
  let cursorX = x;
  let charW = size * 0.62;
  let charH = size;
  let spacing = size * 0.82;
  let slant = italic ? 0.18 : 0.04;

  for (let idx = 0; idx < str.length; idx++) {
    let ch = str[idx];
    if (ch === " ") {
      cursorX += spacing * 0.75;
      continue;
    }
    let strokes = GLYPHS[ch] || GLYPHS[ch.toUpperCase()];
    if (strokes) {
      let jx = random(-0.25, 0.25);
      let jy = random(-0.25, 0.25);
      for (let poly of strokes) {
        for (let k = 0; k < poly.length - 1; k++) {
          let [u0, v0] = poly[k];
          let [u1, v1] = poly[k + 1];
          let x0 = cursorX + u0 * charW + (1 - v0) * charH * slant + jx;
          let y0 = y + v0 * charH + jy;
          let x1 = cursorX + u1 * charW + (1 - v1) * charH * slant + jx;
          let y1 = y + v1 * charH + jy;
          brush.line(x0, y0, x1, y1);
        }
      }
    }
    cursorX += spacing;
  }
}

