  brush.noField();

  // 1. Build the 3D-layered pile of hyperreal dried chillies
  const chillies = buildChilliPile();

  // 2. Build echoing reverse-appliqué contour rings + slit-shaped gaps from the pile silhouette
  const clothData = buildReverseAppliqueBands(chillies);

  // 3. Render the concentric watercolor reverse-appliqué cloth bands & slits
  renderReverseAppliqueCloth(clothData);

  // 4. Cast deep ambient shadow around the base of the chilli pile onto the cloth
  renderPileBaseShadow(clothData.rings[0]);

  // 5. Render the hyperreal chillies (layered back-to-front)
  for (let i = 0; i < chillies.length; i++) {
    renderChilliCastShadow(chillies[i]);
    renderHyperrealChilli(chillies[i]);
  }

  // 6. Scatter a few loose pale seeds in the crevices and inner cloth rim
  renderLooseSeeds(chillies, clothData.rings[0]);

  noLoop();
}

// ============================================================================
// STEP 1: GENERATE HYPERREAL CHILLI PILE GEOMETRY
// ============================================================================

function buildChilliPile() {
  const chillies = [];
  const cx = 600;
  const cy = 600;

  // Layer 0: Outer radiating base chillies (15 pods defining the dramatic lobed silhouette)
  const baseCount = 15;
  for (let i = 0; i < baseCount; i++) {
    const baseAngle = i * (360 / baseCount) + random(-9, 9);
    const dist = random(145, 205);
    const x = cx + cos(baseAngle) * dist;
    const y = cy + sin(baseAngle) * dist;
    // Orient mostly outward or at a sweeping diagonal so tips/stems poke into the contour
    const flip = random() < 0.72 ? 0 : 180;
    const angle = baseAngle + flip + random(-32, 32);
    const variantPool = ["crimson", "scarlet", "tangerine", "crimson", "scarlet", "pasilla"];
    const variant = variantPool[i % variantPool.length];
    const isPlump = variant === "tangerine" || variant === "pasilla";

    chillies.push(createChilliObject({
      x, y,
      angle,
      length: isPlump ? random(195, 245) : random(235, 295),
      maxWidth: isPlump ? random(64, 82) : random(46, 62),
      bend: random(-34, 34),
      sBend: random(-14, 14),
      variant,
      layer: 0,
      hasSplit: random() < 0.28,
      stemFirst: flip === 180
    }));
  }

  // Layer 1: Middle tangled heap (12 pods interlocking across the pile)
  const midCount = 12;
  for (let i = 0; i < midCount; i++) {
    const a = i * (360 / midCount) + 15 + random(-14, 14);
    const dist = random(65, 145);
    const x = cx + cos(a) * dist;
    const y = cy + sin(a) * dist;
    const angle = a + random(40, 150) * (i % 2 === 0 ? 1 : -1);
    const variantPool = ["scarlet", "tangerine", "crimson", "tangerine", "scarlet", "pasilla"];
    const variant = variantPool[i % variantPool.length];
    const isPlump = variant === "tangerine" && i % 2 === 0;

    chillies.push(createChilliObject({
      x, y,
      angle,
      length: isPlump ? random(185, 235) : random(220, 285),
      maxWidth: isPlump ? random(62, 78) : random(48, 66),
      bend: random(-38, 38),
      sBend: random(-16, 16),
      variant,
      layer: 1,
      hasSplit: i % 2 === 0 || random() < 0.45
    }));
  }

  // Layer 2: Top focal crown (9 hyper-detailed pods under direct frontal festive light)
  const topConfigs = [
    { dx: -55, dy: -48, angle: -28, len: 270, w: 64, bend: 26, var: "crimson", split: true },
    { dx: 58, dy: -35, angle: 42, len: 245, w: 72, bend: -24, var: "tangerine", split: true },
    { dx: -15, dy: 58, angle: 155, len: 265, w: 58, bend: 30, var: "scarlet", split: true },
    { dx: 72, dy: 62, angle: -65, len: 230, w: 54, bend: -28, var: "crimson", split: false },
    { dx: -85, dy: 28, angle: 112, len: 225, w: 70, bend: 22, var: "tangerine", split: true },
    { dx: 12, dy: -88, angle: 8, len: 255, w: 56, bend: -32, var: "scarlet", split: true },
    { dx: -32, dy: -5, angle: -118, len: 215, w: 62, bend: 18, var: "pasilla", split: true },
    { dx: 28, dy: 14, angle: 24, len: 260, w: 60, bend: -26, var: "scarlet", split: true },
    { dx: -5, dy: -22, angle: -52, len: 235, w: 68, bend: 28, var: "tangerine", split: true }
  ];

  for (let i = 0; i < topConfigs.length; i++) {
    const cfg = topConfigs[i];
    chillies.push(createChilliObject({
      x: cx + cfg.dx + random(-8, 8),
      y: cy + cfg.dy + random(-8, 8),
      angle: cfg.angle + random(-6, 6),
      length: cfg.len,
      maxWidth: cfg.w,
      bend: cfg.bend,
      sBend: random(-12, 12),
      variant: cfg.var,
      layer: 2,
      hasSplit: cfg.split
    }));
  }

  return chillies;
}

function createChilliObject(params) {
  const { x, y, angle, length, maxWidth, bend, sBend, variant, layer, hasSplit } = params;
  const seed = floor(random(10000));
  const wrinkleFreq = random(3.5, 5.5);
  const wrinklePhase = random(360);
  const numRidges = floor(random(5, 8));

  // Precompute spine and cross-axes along t in [0, 1]
  const steps = 36;
  const spine = [];
  const ca = cos(angle);
  const sa = sin(angle);

  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const lx = (t - 0.44) * length;
    const ly = bend * sin(t * 180) + sBend * sin(t * 360);

    // Derivative for tangent / normal
    const dlx = length;
    const dly = bend * PI * cos(t * 180) + sBend * TWO_PI * cos(t * 360);
    const mag = sqrt(dlx * dlx + dly * dly) || 1;
    const tx = dlx / mag;
    const ty = dly / mag;
    const nx = -ty;
    const ny = tx;

    // World coordinates
    const wx = x + lx * ca - ly * sa;
    const wy = y + lx * sa + ly * ca;
    const wnx = nx * ca - ny * sa;
    const wny = nx * sa + ny * ca;
    const wtx = tx * ca - ty * sa;
    const wty = tx * sa + ty * ca;

    // Width profile of dried pod with wrinkled pinching
    const shoulder = 1 - pow(1 - min(1, t / 0.13), 2.3);
    const taper = pow(max(0, 1 - t), 0.68);
    const pinch = 1 + 0.09 * sin(t * 180 * wrinkleFreq + wrinklePhase)
                    + 0.06 * cos(t * 180 * (wrinkleFreq * 1.7) - wrinklePhase * 0.6);
    const w = (maxWidth * 0.5) * shoulder * taper * pinch;

    spine.push({ t, wx, wy, wnx, wny, wtx, wty, w });
  }

  // Stem points for t < 0
  const stemLen = random(46, 74);
  const stemCurve = random(-28, 28);
  const stemPts = [];
  const s0 = spine[0];
  for (let i = 0; i <= 10; i++) {
    const st = i / 10;
    const dist = st * stemLen;
    const side = stemCurve * st * st;
    const sx = s0.wx - s0.wtx * dist + s0.wnx * side;
    const sy = s0.wy - s0.wty * dist + s0.wny * side;
    const sw = lerp(maxWidth * 0.15, maxWidth * 0.065, sin(st * 140)) + (st > 0.85 ? 2.5 : 0);
    stemPts.push({ st, sx, sy, wnx: s0.wnx, wny: s0.wny, wtx: s0.wtx, wty: s0.wty, sw });
  }

  return {
    ...params,
    seed,
    wrinkleFreq,
    wrinklePhase,
    numRidges,
    spine,
    stemPts,
    splitT1: random(0.18, 0.28),
    splitT2: random(0.68, 0.82),
    splitBias: random(-0.18, 0.18),
    splitWidth: random(0.36, 0.48)
  };
}

// ============================================================================
// STEP 2: GENERATE REVERSE-APPLIQUÉ CONTOUR BANDS & SLIT-SHAPED GAPS
// ============================================================================

function buildReverseAppliqueBands(chillies) {
  const cx = 600;
  const cy = 600;
  const numAngles = 360;

  // Collect all chilli sample disks (pods + stems) to compute exact envelope
  const disks = [];
  for (let c of chillies) {
    for (let i = 0; i < c.spine.length; i += 2) {
      const sp = c.spine[i];
      const dx = sp.wx - cx;
      const dy = sp.wy - cy;
      disks.push({
        r: sqrt(dx * dx + dy * dy),
        a: atan2(dy, dx),
        w: sp.w + 11
      });
    }
    for (let i = 0; i < c.stemPts.length; i += 2) {
      const st = c.stemPts[i];
      const dx = st.sx - cx;
      const dy = st.sy - cy;
      disks.push({
        r: sqrt(dx * dx + dy * dy),
        a: atan2(dy, dx),
        w: st.sw + 9
      });
    }
  }

  // Ray-cast from center for each degree to find outermost chilli silhouette R0(theta)
  let rawR0 = new Array(numAngles).fill(260);
  for (let m = 0; m < numAngles; m++) {
    const theta = m;
    let maxR = 240;
    for (let d of disks) {
      const diff = theta - d.a;
      const perp = abs(d.r * sin(diff));
      if (perp <= d.w) {
        const proj = d.r * cos(diff);
        if (proj > 0) {
          const hit = proj + sqrt(max(0, d.w * d.w - perp * perp));
          if (hit > maxR) maxR = hit;
        }
      }
    }
    rawR0[m] = maxR;
  }

  // Morphological closing / smooth bridging so cloth contour hugs lobes like cut fabric
  let rCurr = smoothCircularArray(rawR0, 6, 0.65);
  rCurr = smoothCircularArray(rCurr, 4, 0.35);

  // Build 17 concentric contour boundaries (16 bands stepping outward to cover 1200x1200)
  // Color rhythm: Black, Turquoise, Scarlet, Tangerine, Black, Scarlet, Tangerine, Turquoise...
  const bandColors = [
    "clothBlack",     // Band 0: frames the red/orange chillies in stark high contrast
    "clothTurquoise", // Band 1: immediate electric jolt of turquoise
    "clothScarlet",   // Band 2: festive scarlet
    "clothTangerine", // Band 3: bright tangerine
    "clothBlack",     // Band 4: graphic black separator
    "clothScarlet",   // Band 5: scarlet
    "clothTangerine", // Band 6: tangerine
    "clothTurquoise", // Band 7: jolt of turquoise
    "clothBlack",     // Band 8: black
    "clothTangerine", // Band 9: tangerine
    "clothScarlet",   // Band 10: scarlet
    "clothBlack",     // Band 11: black
    "clothTurquoise", // Band 12: jolt of turquoise
    "clothScarlet",   // Band 13: scarlet
    "clothTangerine", // Band 14: tangerine
    "clothBlack",     // Band 15: black
    "clothTurquoise"  // Band 16: corner fill
  ];

  // What color shows through the slit-shaped gaps of each band ("revealing the colour beneath")
  const slitRevealSequence = [
    ["clothTurquoise", "clothScarlet", "clothTangerine"], // inside Band 0 (Black)
    ["clothBlack", "clothScarlet", "clothTangerine"],     // inside Band 1 (Turquoise)
    ["clothBlack", "clothTurquoise", "clothTangerine"],   // inside Band 2 (Scarlet)
    ["clothBlack", "clothTurquoise", "clothScarlet"],     // inside Band 3 (Tangerine)
  ];

  const rings = [];
  const numRings = bandColors.length + 1;

  for (let k = 0; k < numRings; k++) {
    const pts = [];
    for (let m = 0; m < numAngles; m++) {
      const theta = m;
      // Ragged cut-fabric jitter + occasional scissor-snip notches
      const nVal = noise(k * 7.3 + 10, cos(theta) * 1.8 + 5, sin(theta) * 1.8 + 5);
      const fineJagged = (noise(k * 19.1, m * 0.45) - 0.5) * 4.6;
      const snip = (m + k * 7) % 19 === 0 ? -3.2 : ((m + k * 11) % 23 === 0 ? 2.6 : 0);
      const r = rCurr[m] + (nVal - 0.5) * 5.0 + fineJagged + snip;

      pts.push({
        theta,
        r,
        x: cx + cos(theta) * r,
        y: cy + sin(theta) * r
      });
    }
    rings.push(pts);

    // Step outward for next contour ring
    const stepWidth = k === 0 ? 31 : (k < 6 ? 33 : 36);
    const nextR = new Array(numAngles);
    for (let m = 0; m < numAngles; m++) {
      const wave = 2.4 * sin(m * 6 + k * 42) + 1.8 * cos(m * 9 - k * 31);
      nextR[m] = rCurr[m] + stepWidth + wave;
    }
    rCurr = smoothCircularArray(nextR, 3, 0.45);
  }

  // Generate small slit-shaped gaps along the middle of each band
  const slits = [];
  for (let k = 0; k < bandColors.length; k++) {
    const innerRing = rings[k];
    const outerRing = rings[k + 1];
    const avgR = (innerRing[0].r + outerRing[0].r) * 0.5;
    // Angular step so arc spacing is ~54px around the ring
    const dTheta = max(4, round((54 / avgR) * (180 / PI)));
    const revealPool = slitRevealSequence[k % slitRevealSequence.length];

    let slitIdx = 0;
    for (let m = floor(k * 3.7) % dTheta; m < numAngles - dTheta * 0.6; m += dTheta) {
      const mMid = (m + numAngles) % numAngles;
      const pIn = innerRing[mMid];
      const pOut = outerRing[mMid];
      const mx = (pIn.x + pOut.x) * 0.5;
      const my = (pIn.y + pOut.y) * 0.5;

      // Skip slits completely off-canvas
      if (mx < -25 || mx > 1225 || my < -25 || my > 1225) continue;

      const bandThick = dist(pIn.x, pIn.y, pOut.x, pOut.y);
      // Tangent vector along the contour ring
      const mPrev = (mMid - 3 + numAngles) % numAngles;
      const mNext = (mMid + 3) % numAngles;
      const tx = ((innerRing[mNext].x + outerRing[mNext].x) - (innerRing[mPrev].x + outerRing[mPrev].x)) * 0.5;
      const ty = ((innerRing[mNext].y + outerRing[mNext].y) - (innerRing[mPrev].y + outerRing[mPrev].y)) * 0.5;
      const tMag = sqrt(tx * tx + ty * ty) || 1;
      const ux = tx / tMag;
      const uy = ty / tMag;
      // Normal vector pointing outward
      const nx = -uy;
      const ny = ux;

      // Slit dimensions (pointed fabric slit or double-notched slot)
      const halfLen = random(11, 18.5);
      const halfWid = clampVal(bandThick * random(0.18, 0.25), 4.2, 8.2);
      const revealColorKey = revealPool[slitIdx % revealPool.length];
      slitIdx++;

      // Build 10-vertex ragged slit polygon
      const slitPts = [];
      const stepsSlit = 10;
      for (let s = 0; s < stepsSlit; s++) {
        const ang = (s / stepsSlit) * 360;
        const c = cos(ang);
        const sn = sin(ang);
        // Pinched lens/spindle profile like a slit cut in cloth
        const pinchEnv = pow(abs(sn), 0.75) * (sn >= 0 ? 1 : -1);
        const ragL = (noise(k * 13, mMid, s) - 0.5) * 1.8;
        const sx = mx + ux * (c * halfLen + ragL) + nx * (pinchEnv * halfWid + ragL * 0.5);
        const sy = my + uy * (c * halfLen + ragL) + ny * (pinchEnv * halfWid + ragL * 0.5);
        slitPts.push({ x: sx, y: sy });
      }

      slits.push({
        bandIdx: k,
        mx, my, ux, uy, nx, ny,
        halfLen, halfWid,
        pts: slitPts,
        revealColorKey,
        parentColorKey: bandColors[k]
      });
    }
  }

  return { rings, bandColors, slits };
}

function smoothCircularArray(arr, radius, maxPullWeight) {
  const n = arr.length;
  const out = new Array(n);
  for (let i = 0; i < n; i++) {
    let sum = 0;
    let wSum = 0;
    let localMax = arr[i];
    for (let j = -radius; j <= radius; j++) {
      const idx = (i + j + n) % n;
      const w = exp(-(j * j) / (2 * (radius * 0.55) * (radius * 0.55)));
      sum += arr[idx] * w;
      wSum += w;
      if (arr[idx] > localMax) localMax = arr[idx];
    }
    const avg = sum / wSum;
    out[i] = lerp(avg, localMax, maxPullWeight * 0.28);
  }
  return out;
}

function clampVal(v, lo, hi) {
  return max(lo, min(hi, v));
}

// ============================================================================
// STEP 3: RENDER REVERSE-APPLIQUÉ WATERCOLOUR BANDS, RAGGED EDGES & SLITS
// ============================================================================

function renderReverseAppliqueCloth(clothData) {
  const { rings, bandColors, slits } = clothData;
  const numAngles = 360;
  const numSectors = 6; // 6 sectors of 60 degrees per ring for clean non-overlapping polygons
  const sectorSpan = numAngles / numSectors;

  // Group band sectors by color key for fast, pure watercolor batching
  const colorKeys = ["clothBlack", "clothScarlet", "clothTangerine", "clothTurquoise"];

  for (let cKey of colorKeys) {
    const hexCol = PALETTE[cKey];
    const isBlack = cKey === "clothBlack";

    brush.noStroke();
    brush.wash(hexCol, isBlack ? 245 : 215);
    brush.fill(hexCol, isBlack ? 165 : 145);
    brush.fillBleed(0.05, "out");
    brush.fillTexture(0.52, 0.38);

    for (let k = 0; k < bandColors.length; k++) {
      if (bandColors[k] !== cKey) continue;

      const innerRing = rings[k];
      const outerRing = rings[k + 1];

      for (let sec = 0; sec < numSectors; sec++) {
        const aStart = sec * sectorSpan;
        const aEnd = (sec + 1) * sectorSpan;

        // Check if sector is within canvas bounds
        let visible = false;
        for (let a = aStart; a <= aEnd; a += 15) {
          const p1 = innerRing[a % numAngles];
          const p2 = outerRing[a % numAngles];
          if ((p1.x >= -80 && p1.x <= 1280 && p1.y >= -80 && p1.y <= 1280) ||
              (p2.x >= -80 && p2.x <= 1280 && p2.y >= -80 && p2.y <= 1280)) {
            visible = true;
            break;
          }
        }
        if (!visible) continue;

        brush.beginShape(0);
        // Walk along inner boundary
        for (let a = aStart; a <= aEnd + 1; a += 2) {
          const p = innerRing[a % numAngles];
          // Slightly tuck inner edge inward by 2px so bands overlap seamlessly
          const dx = p.x - 600;
          const dy = p.y - 600;
          const d = sqrt(dx * dx + dy * dy) || 1;
          brush.vertex(p.x - (dx / d) * 2.2, p.y - (dy / d) * 2.2);
        }
        // Walk back along outer boundary
        for (let a = aEnd + 1; a >= aStart; a -= 2) {
          const p = outerRing[a % numAngles];
          const dx = p.x - 600;
          const dy = p.y - 600;
          const d = sqrt(dx * dx + dy * dy) || 1;
          brush.vertex(p.x + (dx / d) * 1.8, p.y + (dy / d) * 1.8);
        }
        brush.endShape(true);
      }
    }
  }

  // Batch-render the slit-shaped gaps by reveal color
  for (let cKey of colorKeys) {
    const hexCol = PALETTE[cKey];
    brush.noStroke();
    brush.wash(hexCol, 245);
    brush.fill(hexCol, 150);
    brush.fillBleed(0.03, "in");
    brush.fillTexture(0.45, 0.35);

    for (let slit of slits) {
      if (slit.revealColorKey !== cKey) continue;
      brush.beginShape(0.15);
      for (let pt of slit.pts) {
        brush.vertex(pt.x, pt.y);
      }
      brush.endShape(true);
    }
  }

  brush.noFill();
  brush.noWash();

  // Render subtle woven cloth texture & watercolor granulations along bands
  for (let k = 0; k < bandColors.length; k++) {
    const cKey = bandColors[k];
    const innerRing = rings[k];
    const outerRing = rings[k + 1];
    const frayCol = cKey === "clothBlack" ? PALETTE.frayBlack :
                    cKey === "clothScarlet" ? PALETTE.frayScarlet :
                    cKey === "clothTangerine" ? PALETTE.frayTangerine : PALETTE.frayTurquoise;

    // Fine contour-following weave lines in cpencil
    brush.set("cpencil", frayCol, 0.42);
    for (let m = 0; m < numAngles; m += 9) {
      const m2 = (m + 7) % numAngles;
      const tBias = random(0.25, 0.75);
      const x1 = lerp(innerRing[m].x, outerRing[m].x, tBias);
      const y1 = lerp(innerRing[m].y, outerRing[m].y, tBias);
      if (x1 < -10 || x1 > 1210 || y1 < -10 || y1 > 1210) continue;
      const x2 = lerp(innerRing[m2].x, outerRing[m2].x, tBias);
      const y2 = lerp(innerRing[m2].y, outerRing[m2].y, tBias);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Render ragged cut-fabric edges, drop-shadows, and frayed threads along every contour boundary
  for (let k = 1; k < rings.length - 1; k++) {
    const ring = rings[k];
    const innerColorKey = bandColors[k - 1];
    const frayCol = innerColorKey === "clothBlack" ? PALETTE.frayBlack :
                    innerColorKey === "clothScarlet" ? PALETTE.frayScarlet :
                    innerColorKey === "clothTangerine" ? PALETTE.frayTangerine : PALETTE.frayTurquoise;

    // 1. Cut-cloth cast shadow just outside the ragged step edge
    brush.set("charcoal", PALETTE.clothShadow, 0.85);
    const chunkStep = 18;
    for (let m = 0; m < numAngles; m += chunkStep) {
      const pts = [];
      let onScreen = false;
      for (let j = 0; j <= chunkStep; j += 2) {
        const p = ring[(m + j) % numAngles];
        if (p.x >= -20 && p.x <= 1220 && p.y >= -20 && p.y <= 1220) onScreen = true;
        const dx = p.x - 600;
        const dy = p.y - 600;
        const d = sqrt(dx * dx + dy * dy) || 1;
        pts.push([p.x + (dx / d) * 2.2 + 0.8, p.y + (dy / d) * 2.2 + 1.0, 0.8]);
      }
      if (onScreen && pts.length >= 2) {
        brush.spline(pts, 0.2);
      }
    }

    // 2. Ragged cut fabric rim + frayed little fibers & reverse-appliqué hem stitches
    brush.set("cpencil", frayCol, 0.65);
    for (let m = 0; m < numAngles; m += chunkStep) {
      const pts = [];
      let onScreen = false;
      for (let j = 0; j <= chunkStep; j += 1) {
        const p = ring[(m + j) % numAngles];
        if (p.x >= -20 && p.x <= 1220 && p.y >= -20 && p.y <= 1220) onScreen = true;
        pts.push([p.x, p.y, 0.7 + 0.4 * ((j % 3) === 0 ? 1 : 0)]);
      }
      if (onScreen && pts.length >= 2) {
        brush.spline(pts, 0.15);
      }
    }

    // 3. Tiny frayed threads & blind-hem ticks perpendicular to the cut edge
    brush.set("2H", frayCol, 0.55);
    for (let m = 0; m < numAngles; m += 3) {
      const p = ring[m];
      if (p.x < 0 || p.x > 1200 || p.y < 0 || p.y > 1200) continue;
      const dx = p.x - 600;
      const dy = p.y - 600;
      const d = sqrt(dx * dx + dy * dy) || 1;
      const nx = dx / d;
      const ny = dy / d;
      const frayLen = random(2.5, 5.5);
      const jitterA = random(-0.35, 0.35);
      const fx = nx * cos(jitterA * 57) - ny * sin(jitterA * 57);
      const fy = nx * sin(jitterA * 57) + ny * cos(jitterA * 57);
      brush.line(p.x - fx * 1.2, p.y - fy * 1.2, p.x + fx * frayLen, p.y + fy * frayLen);
    }
  }

  // Render ragged rims, recessed shadows, and corner tack-stitches around every slit-shaped gap
  for (let slit of slits) {
    const pts = slit.pts;
    // Inner recessed shadow along top lip of slit
    brush.set("rotring", PALETTE.clothShadow, 0.85);
    const topLip = [];
    for (let i = 0; i <= 5; i++) {
      topLip.push([pts[i].x + 0.8, pts[i].y + 1.1, 0.9]);
    }
    brush.spline(topLip, 0.25);

    // Cut fabric rim highlight along bottom lip of slit
    const frayCol = slit.parentColorKey === "clothBlack" ? PALETTE.frayBlack :
                    slit.parentColorKey === "clothScarlet" ? PALETTE.frayScarlet :
                    slit.parentColorKey === "clothTangerine" ? PALETTE.frayTangerine : PALETTE.frayTurquoise;
    brush.set("cpencil", frayCol, 0.65);
    const botLip = [];
    for (let i = 5; i <= 10; i++) {
      const p = pts[i % pts.length];
      botLip.push([p.x, p.y, 0.85]);
    }
    brush.spline(botLip, 0.25);

    // Tiny tack stitches at both pointed ends of the slit
    brush.set("rotring", PALETTE.clothShadow, 0.6);
    const pRight = pts[0];
    const pLeft = pts[5];
    brush.line(
      pRight.x - slit.nx * 2.5, pRight.y - slit.ny * 2.5,
      pRight.x + slit.nx * 2.5, pRight.y + slit.ny * 2.5
    );
    brush.line(
      pLeft.x - slit.nx * 2.5, pLeft.y - slit.ny * 2.5,
      pLeft.x + slit.nx * 2.5, pLeft.y + slit.ny * 2.5
    );
  }
}

function renderPileBaseShadow(innerRing) {
  // Deep shadow halo where the chilli pile meets the innermost reverse-appliqué cloth ring
  brush.set("charcoal", "#050103", 1.8);
  const n = innerRing.length;
  for (let m = 0; m < n; m += 2) {
    const p = innerRing[m];
    const dx = p.x - 600;
    const dy = p.y - 600;
    const d = sqrt(dx * dx + dy * dy) || 1;
    const nx = dx / d;
    const ny = dy / d;
    brush.line(p.x - nx * 16, p.y - ny * 16, p.x + nx * 5, p.y + ny * 5);
  }
}

// ============================================================================
// STEP 4: RENDER HYPERREAL DRIED CHILLIES (GLOSSY MARKER + COLOURED PENCIL)
// ============================================================================

function renderChilliCastShadow(ch) {
  const sp = ch.spine;
  const shOffX = 5.5;
  const shOffY = 7.5;

  // Opaque dark shadow wash beneath the pod so overlapping chillies separate cleanly
  brush.noStroke();
  brush.wash("#080102", 185);
  brush.beginShape(0.2);
  for (let i = 0; i < sp.length; i += 2) {
    const p = sp[i];
    brush.vertex(p.wx + p.wnx * (p.w * 0.96) + shOffX, p.wy + p.wny * (p.w * 0.96) + shOffY);
  }
  for (let i = sp.length - 1; i >= 0; i -= 2) {
    const p = sp[i];
    brush.vertex(p.wx - p.wnx * (p.w * 0.96) + shOffX, p.wy - p.wny * (p.w * 0.96) + shOffY);
  }
  brush.endShape(true);
  brush.noWash();

  // Soft charcoal penumbra along shadow rim
  brush.set("2B", "#0a0204", 1.15);
  const shadowRim = [];
  for (let i = 2; i < sp.length - 2; i += 3) {
    const p = sp[i];
    shadowRim.push([
      p.wx + p.wnx * (p.w * 0.95) + shOffX * 1.1,
      p.wy + p.wny * (p.w * 0.95) + shOffY * 1.1,
      0.8
    ]);
  }
  if (shadowRim.length >= 2) brush.spline(shadowRim, 0.35);
}

function renderHyperrealChilli(ch) {
  const pal = PALETTE[ch.variant];
  const sp = ch.spine;

  // --------------------------------------------------------------------------
  // A. Base Pod Silhouette in Deep Crevice Tone (Wash)
  // --------------------------------------------------------------------------
  brush.noStroke();
  brush.wash(pal.base, 250);
  brush.beginShape(0.15);
  for (let i = 0; i < sp.length; i++) {
    const p = sp[i];
    brush.vertex(p.wx + p.wnx * p.w, p.wy + p.wny * p.w);
  }
  for (let i = sp.length - 1; i >= 0; i--) {
    const p = sp[i];
    brush.vertex(p.wx - p.wnx * p.w, p.wy - p.wny * p.w);
  }
  brush.endShape(true);
  brush.noWash();

  // --------------------------------------------------------------------------
  // B. Glossy Marker Longitudinal Lobes & Buckled Skin Planes
  // --------------------------------------------------------------------------
  const numRidges = ch.numRidges;
  for (let r = 0; r < numRidges; r++) {
    // sNorm in [-0.82, +0.82] across the width of the chilli
    const sNorm = map(r, 0, numRidges - 1, -0.80, 0.80);
    const centerProximity = 1 - abs(sNorm); // frontal light strongest near crown (sNorm ~ -0.15..0.35)
    const lightBias = 1 - abs(sNorm + 0.12) * 0.95;

    // Choose marker color for this longitudinal lobe
    const lobeColor = lightBias > 0.68 ? pal.bright :
                      lightBias > 0.38 ? pal.mid : pal.dark;
    const markerW = map(ch.maxWidth, 45, 82, 0.85, 1.45) * (0.7 + 0.5 * centerProximity);

    brush.set("gloss_marker", lobeColor, markerW);

    const lobePts = [];
    for (let i = 1; i < sp.length - 1; i += 2) {
      const p = sp[i];
      // Wrinkled lateral undulation along the ridge
      const buckle = 0.11 * sin(p.t * 360 * ch.wrinkleFreq + r * 55 + ch.wrinklePhase)
                   + 0.06 * cos(p.t * 540 * ch.wrinkleFreq - r * 80);
      const s = clampVal(sNorm + buckle, -0.92, 0.92);
      const px = p.wx + p.wnx * (p.w * s);
      const py = p.wy + p.wny * (p.w * s);
      const press = 0.55 + 0.65 * sin(p.t * 180) * (0.7 + 0.3 * sin(p.t * 720 + r * 45));
      lobePts.push([px, py, press]);
    }
    if (lobePts.length >= 2) {
      brush.spline(lobePts, 0.35);
    }

    // Second hot glossy marker pass on the sun-facing central ridges
    if (lightBias > 0.55) {
      brush.set("marker", pal.hot, markerW * 0.68);
      for (let seg = 3; seg < sp.length - 5; seg += 6) {
        const segPts = [];
        for (let k = 0; k <= 4; k++) {
          const idx = min(sp.length - 2, seg + k);
          const p = sp[idx];
          const buckle = 0.10 * sin(p.t * 360 * ch.wrinkleFreq + r * 55 + ch.wrinklePhase);
          const s = clampVal(sNorm + buckle, -0.85, 0.85);
          segPts.push([
            p.wx + p.wnx * (p.w * s),
            p.wy + p.wny * (p.w * s),
            0.9 * sin((k / 4) * 180)
          ]);
        }
        if (segPts.length >= 2) brush.spline(segPts, 0.3);
      }
    }
  }

  // --------------------------------------------------------------------------
  // C. Transverse Buckled Facets (Glossy Marker Cross-Knuckles)
  // --------------------------------------------------------------------------
  const numBuckles = floor(random(7, 12));
  for (let b = 0; b < numBuckles; b++) {
    const idx = floor(map(b, 0, numBuckles - 1, 4, sp.length - 5));
    const p = sp[idx];
    const pNext = sp[min(sp.length - 1, idx + 2)];
    const s1 = random(-0.65, 0.15);
    const s2 = s1 + random(0.28, 0.58);

    // Lit facet side
    brush.set("marker", b % 2 === 0 ? pal.hot : pal.bright, 0.72);
    brush.line(
      p.wx + p.wnx * (p.w * s1),
      p.wy + p.wny * (p.w * s1),
      pNext.wx + pNext.wnx * (pNext.w * s2),
      pNext.wy + pNext.wny * (pNext.w * s2)
    );
  }

  // --------------------------------------------------------------------------
  // D. Dense Coloured Pencil Shading, Wrinkle Valleys & Reflected Rim Glow
  // --------------------------------------------------------------------------

  // 1. Cross-contour coloured pencil modeling across the ridges
  for (let i = 2; i < sp.length - 2; i += 1) {
    const p = sp[i];
    if (p.w < 4) continue;

    // Bright hot pencil hatching over the crown
    brush.set("cpencil", i % 2 === 0 ? pal.hot : pal.bright, 0.62);
    const sA = random(-0.55, 0.05);
    const sB = sA + random(0.25, 0.48);
    const arcPts = [
      [p.wx + p.wnx * (p.w * sA), p.wy + p.wny * (p.w * sA), 0.5],
      [p.wx + p.wnx * (p.w * ((sA + sB) * 0.5)) + p.wtx * 3.2,
       p.wy + p.wny * (p.w * ((sA + sB) * 0.5)) + p.wty * 3.2, 0.95],
      [p.wx + p.wnx * (p.w * sB), p.wy + p.wny * (p.w * sB), 0.5]
    ];
    brush.spline(arcPts, 0.4);

    // Dark coloured pencil shading along the lower/outer flank
    brush.set("cpencil", pal.dark, 0.68);
    brush.line(
      p.wx + p.wnx * (p.w * 0.48),
      p.wy + p.wny * (p.w * 0.48),
      p.wx + p.wnx * (p.w * 0.92) + p.wtx * 2.5,
      p.wy + p.wny * (p.w * 0.92) + p.wty * 2.5
    );
  }

  // 2. Deep longitudinal & forked wrinkle trenches in 2B & cpencil
  const numValleys = numRidges + 2;
  for (let v = 0; v < numValleys; v++) {
    const vNorm = map(v, 0, numValleys - 1, -0.86, 0.86);
    brush.set(v % 2 === 0 ? "2B" : "cpencil", pal.crevice, 0.72);

    const valleyPts = [];
    for (let i = 1; i < sp.length - 1; i += 2) {
      const p = sp[i];
      const jag = 0.13 * sin(p.t * 360 * ch.wrinkleFreq + v * 67 + ch.wrinklePhase)
                + 0.07 * sin(p.t * 900 + v * 110);
      const s = clampVal(vNorm + jag, -0.95, 0.95);
      valleyPts.push([
        p.wx + p.wnx * (p.w * s),
        p.wy + p.wny * (p.w * s),
        0.45 + 0.65 * abs(sin(p.t * 540 + v * 40))
      ]);
    }
    if (valleyPts.length >= 2) {
      brush.spline(valleyPts, 0.25);
    }

    // Y-shaped wrinkle forks branching off the main longitudinal trench
    brush.set("rotring", pal.crevice, 0.52);
    for (let i = 4; i < sp.length - 5; i += 5) {
      if ((i + v) % 2 !== 0) continue;
      const p1 = sp[i];
      const p2 = sp[i + 2];
      const s1 = clampVal(vNorm + 0.08 * sin(i * 45), -0.85, 0.85);
      const s2 = clampVal(s1 + (v % 2 === 0 ? 0.24 : -0.24), -0.92, 0.92);
      brush.line(
        p1.wx + p1.wnx * (p1.w * s1),
        p1.wy + p1.wny * (p1.w * s1),
        p2.wx + p2.wnx * (p2.w * s2),
        p2.wy + p2.wny * (p2.w * s2)
      );
    }
  }

  // 3. Warm reflected bounce-light along the shadowed edge of the pod
  brush.set("cpencil", pal.reflect, 0.75);
  const rimPts = [];
  for (let i = 3; i < sp.length - 3; i += 2) {
    const p = sp[i];
    rimPts.push([
      p.wx + p.wnx * (p.w * 0.90),
      p.wy + p.wny * (p.w * 0.90),
      0.75 * sin(p.t * 180)
    ]);
  }
  if (rimPts.length >= 2) brush.spline(rimPts, 0.3);

  // Crisp outer contour definition
  brush.set("2B", pal.crevice, 0.7);
  const topEdge = [];
  const botEdge = [];
  for (let i = 0; i < sp.length; i += 2) {
    const p = sp[i];
    topEdge.push([p.wx - p.wnx * p.w, p.wy - p.wny * p.w, 0.7]);
    botEdge.push([p.wx + p.wnx * p.w, p.wy + p.wny * p.w, 0.85]);
  }
  brush.spline(topEdge, 0.25);
  brush.spline(botEdge, 0.25);

  // --------------------------------------------------------------------------
  // E. High-Contrast Frontal Glossy Specular Highlights
  // --------------------------------------------------------------------------
  for (let r = 1; r < numRidges - 1; r++) {
    const sNorm = map(r, 0, numRidges - 1, -0.78, 0.78);
    if (sNorm < -0.58 || sNorm > 0.45) continue;

    // Avoid placing skin highlights inside the split seam opening
    for (let i = 3; i < sp.length - 4; i += 3) {
      const p = sp[i];
      const pNext = sp[i + 2];

      if (ch.hasSplit && p.t >= ch.splitT1 - 0.03 && p.t <= ch.splitT2 + 0.03 &&
          abs(sNorm - ch.splitBias) < ch.splitWidth * 1.15) {
        continue;
      }

      const buckle1 = 0.09 * sin(p.t * 360 * ch.wrinkleFreq + r * 55 + ch.wrinklePhase);
      const buckle2 = 0.09 * sin(pNext.t * 360 * ch.wrinkleFreq + r * 55 + ch.wrinklePhase);
      const s1 = sNorm + buckle1;
      const s2 = sNorm + buckle2;

      const x1 = p.wx + p.wnx * (p.w * s1);
      const y1 = p.wy + p.wny * (p.w * s1);
      const x2 = pNext.wx + pNext.wnx * (pNext.w * s2);
      const y2 = pNext.wy + pNext.wny * (pNext.w * s2);

      // Warm gloss halo
      brush.set("cpencil", pal.glossWarm, 0.9);
      brush.line(x1, y1, x2, y2);

      // Stark white specular gleam on the knuckle peak
      if ((i + r) % 2 === 0) {
        brush.set("specular_nib", pal.glossWhite, 0.78);
        const xm = (x1 + x2) * 0.5;
        const ym = (y1 + y2) * 0.5;
        brush.line(x1, y1, xm + p.wtx * 2, ym + p.wty * 2);
      }
    }
  }

  // --------------------------------------------------------------------------
  // F. Split Seam & Clusters of Pale Seeds (when hasSplit is true)
  // --------------------------------------------------------------------------
  if (ch.hasSplit) {
    renderSplitSeamAndSeeds(ch, pal);
  }

  // --------------------------------------------------------------------------
  // G. Woody Dried Calyx Cap & Striated Pedicel (Stem)
  // --------------------------------------------------------------------------
  renderChilliStem(ch);
}

function renderSplitSeamAndSeeds(ch, pal) {
  const sp = ch.spine;
  const iStart = max(2, floor(ch.splitT1 * (sp.length - 1)));
  const iEnd = min(sp.length - 3, ceil(ch.splitT2 * (sp.length - 1)));
  if (iEnd - iStart < 4) return;

  const upperLip = [];
  const lowerLip = [];
  const centerLine = [];

  for (let i = iStart; i <= iEnd; i++) {
    const p = sp[i];
    const u = (i - iStart) / (iEnd - iStart);
    // Spindle opening profile with jagged torn skin edges
    const env = sin(u * 180) * pow(sin(u * 180), 0.25);
    const jagU = (noise(ch.seed, i * 0.6, 1) - 0.5) * 0.14;
    const jagL = (noise(ch.seed, i * 0.6, 2) - 0.5) * 0.14;

    const sMid = ch.splitBias + 0.06 * sin(u * 360);
    const halfOpen = ch.splitWidth * env;

    const sUp = clampVal(sMid - halfOpen + jagU * env, -0.88, 0.88);
    const sLo = clampVal(sMid + halfOpen + jagL * env, -0.88, 0.88);

    const ux = p.wx + p.wnx * (p.w * sUp);
    const uy = p.wy + p.wny * (p.w * sUp);
    const lx = p.wx + p.wnx * (p.w * sLo);
    const ly = p.wy + p.wny * (p.w * sLo);

    upperLip.push({ x: ux, y: uy, p, env });
    lowerLip.push({ x: lx, y: ly, p, env });
    centerLine.push({
      x: (ux + lx) * 0.5,
      y: (uy + ly) * 0.5,
      rad: dist(ux, uy, lx, ly) * 0.5,
      p, u, env
    });
  }

  // 1. Dark cavernous interior of split pod
  brush.noStroke();
  brush.wash("#120202", 250);
  brush.beginShape(0.1);
  for (let pt of upperLip) brush.vertex(pt.x, pt.y);
  for (let i = lowerLip.length - 1; i >= 0; i--) brush.vertex(lowerLip[i].x, lowerLip[i].y);
  brush.endShape(true);
  brush.noWash();

  // Deep interior cross-hatching
  brush.set("2B", "#080001", 0.75);
  for (let i = 1; i < upperLip.length - 1; i++) {
    brush.line(upperLip[i].x, upperLip[i].y, lowerLip[i].x, lowerLip[i].y);
  }

  // 2. Spongy pale-orange placenta / pith ribs running inside the cavity
  brush.set("cpencil", "#d97832", 0.7);
  const pithPts1 = [];
  const pithPts2 = [];
  for (let i = 1; i < centerLine.length - 1; i++) {
    const c = centerLine[i];
    pithPts1.push([
      c.x - c.p.wnx * (c.rad * 0.25),
      c.y - c.p.wny * (c.rad * 0.25),
      0.8 * c.env
    ]);
    pithPts2.push([
      c.x + c.p.wnx * (c.rad * 0.22),
      c.y + c.p.wny * (c.rad * 0.22),
      0.7 * c.env
    ]);
  }
  if (pithPts1.length >= 2) brush.spline(pithPts1, 0.35);
  brush.set("cpencil", "#f5ac67", 0.5);
  if (pithPts2.length >= 2) brush.spline(pithPts2, 0.35);

  // 3. Packed clusters of hyperreal Pale Seeds inside the split seam
  for (let i = 1; i < centerLine.length - 1; i++) {
    const c = centerLine[i];
    if (c.rad < 2.8) continue;

    const seedsInRow = c.rad > 9 ? 3 : (c.rad > 5 ? 2 : 1);
    for (let s = 0; s < seedsInRow; s++) {
      const lateral = seedsInRow === 1 ? random(-0.2, 0.2) :
                      map(s, 0, seedsInRow - 1, -0.58, 0.58) + random(-0.12, 0.12);
      const sx = c.x + c.p.wnx * (c.rad * lateral) + random(-1.5, 1.5);
      const sy = c.y + c.p.wny * (c.rad * lateral) + random(-1.5, 1.5);
      const seedRadius = clampVal(c.rad * random(0.36, 0.48), 3.6, 6.2);
      const seedAng = atan2(c.p.wty, c.p.wtx) + random(-55, 55);
      renderSinglePaleSeed(sx, sy, seedRadius, seedAng);
    }
  }

  // A couple of seeds spilling just over the lower split lip
  if (centerLine.length >= 5) {
    const midIdx = floor(centerLine.length * 0.5);
    const lipPt = lowerLip[midIdx];
    renderSinglePaleSeed(
      lipPt.x + lipPt.p.wnx * 3.5,
      lipPt.y + lipPt.p.wny * 3.5,
      4.8,
      random(360)
    );
  }

  // 4. Crisp torn brittle skin rim around the split seam
  const upSpline = upperLip.map(pt => [pt.x, pt.y, 0.85]);
  const loSpline = lowerLip.map(pt => [pt.x, pt.y, 0.85]);

  // Dark inner thickness lip
  brush.set("rotring", "#1a0203", 0.75);
  brush.spline(upSpline, 0.2);
  brush.spline(loSpline, 0.2);

  // Brittle curled orange/cream edge highlight catching the frontal light
  brush.set("cpencil", pal.glossWarm, 0.72);
  const upHighlight = upperLip.map(pt => [
    pt.x - pt.p.wnx * 1.4,
    pt.y - pt.p.wny * 1.4,
    0.8 * pt.env
  ]);
  const loHighlight = lowerLip.map(pt => [
    pt.x + pt.p.wnx * 1.4,
    pt.y + pt.p.wny * 1.4,
    0.9 * pt.env
  ]);
  brush.spline(upHighlight, 0.2);
  brush.spline(loHighlight, 0.2);
}

function renderSinglePaleSeed(x, y, r, angleDeg) {
  const ca = cos(angleDeg);
  const sa = sin(angleDeg);

  // Teardrop/kidney seed contour (8 points)
  const seedPts = [];
  const steps = 8;
  for (let i = 0; i < steps; i++) {
    const a = i * (360 / steps);
    // Pointed hilum beak at a = 0, flat kidney indentation at a = 90
    const rx = r * (1.15 + (i === 0 ? 0.28 : 0));
    const ry = r * 0.82 * (i === 2 ? 0.75 : 1.0);
    const lx = cos(a) * rx;
    const ly = sin(a) * ry;
    seedPts.push({
      x: x + lx * ca - ly * sa,
      y: y + lx * sa + ly * ca
    });
  }

  // 1. Seed cast shadow
  brush.set("rotring", "#120202", 0.85);
  brush.circle(x + 1.2, y + 1.4, r * 0.9, 0.2);

  // 2. Opaque pale straw-ivory seed body wash
  brush.noStroke();
  brush.wash("#f7e39c", 252);
  brush.beginShape(0.2);
  for (let pt of seedPts) brush.vertex(pt.x, pt.y);
  brush.endShape(true);
  brush.noWash();

  // 3. Golden-ochre central embryonic depression & cream rim highlight
  brush.set("cpencil", "#b87924", 0.65);
  brush.circle(x, y, r * 0.42, 0.25);

  brush.set("specular_nib", "#fffbe6", 0.68);
  brush.line(
    seedPts[0].x, seedPts[0].y,
    seedPts[7].x, seedPts[7].y
  );
  brush.line(
    seedPts[7].x, seedPts[7].y,
    seedPts[6].x, seedPts[6].y
  );

  // 4. Crisp dark seed outline
  brush.set("rotring", "#421e06", 0.45);
  const rim = seedPts.map(pt => [pt.x, pt.y, 0.7]);
  rim.push([seedPts[0].x, seedPts[0].y, 0.7]);
  brush.spline(rim, 0.25);
}

function renderChilliStem(ch) {
  const s0 = ch.spine[0];
  const s1 = ch.spine[2];
  const st = ch.stemPts;

  // 1. 5-pointed woody calyx cap grasping the pod shoulder
  const calyxTeeth = 5;
  brush.noStroke();
  brush.wash("#3d311d", 248);
  brush.beginShape(0.1);
  for (let i = 0; i < calyxTeeth; i++) {
    const f = map(i, 0, calyxTeeth - 1, -0.78, 0.78);
    // Base on shoulder
    const bx = s0.wx + s0.wnx * (s1.w * f * 0.8);
    const by = s0.wy + s0.wny * (s1.w * f * 0.8);
    brush.vertex(bx, by);
    // Pointed calyx tooth reaching onto the pod
    const tx = s1.wx + s1.wnx * (s1.w * f * 0.92) + s1.wtx * random(4, 9);
    const ty = s1.wy + s1.wny * (s1.w * f * 0.92) + s1.wty * random(4, 9);
    brush.vertex(tx, ty);
  }
  for (let i = calyxTeeth - 1; i >= 0; i--) {
    const f = map(i, 0, calyxTeeth - 1, -0.65, 0.65);
    brush.vertex(
      s0.wx - s0.wtx * 6 + s0.wnx * (s1.w * f * 0.55),
      s0.wy - s0.wty * 6 + s0.wny * (s1.w * f * 0.55)
    );
  }
  brush.endShape(true);

  // 2. Woody stem (pedicel) base wash
  brush.wash("#4a3c24", 248);
  brush.beginShape(0.15);
  for (let i = 0; i < st.length; i++) {
    const p = st[i];
    brush.vertex(p.sx + p.wnx * p.sw, p.sy + p.wny * p.sw);
  }
  for (let i = st.length - 1; i >= 0; i--) {
    const p = st[i];
    brush.vertex(p.sx - p.wnx * p.sw, p.sy - p.wny * p.sw);
  }
  brush.endShape(true);
  brush.noWash();

  // 3. Fibrous woody striations in coloured pencil & rotring
  const stemTones = ["#241c0e", "#78643e", "#a89165", "#d9c59a"];
  for (let f = -3; f <= 3; f++) {
    const sNorm = f / 3.2;
    const col = sNorm < -0.2 ? stemTones[3] :
                sNorm < 0.2 ? stemTones[2] :
                sNorm < 0.55 ? stemTones[1] : stemTones[0];
    brush.set("cpencil", col, 0.58);
    const fiberPts = [];
    for (let i = 0; i < st.length; i += 2) {
      const p = st[i];
      fiberPts.push([
        p.sx + p.wnx * (p.sw * sNorm),
        p.sy + p.wny * (p.sw * sNorm),
        0.75
      ]);
    }
    if (fiberPts.length >= 2) brush.spline(fiberPts, 0.25);
  }

  // Calyx tooth shadow outlines
  brush.set("rotring", "#1a1308", 0.55);
  for (let i = 0; i < calyxTeeth; i++) {
    const f = map(i, 0, calyxTeeth - 1, -0.75, 0.75);
    brush.line(
      s0.wx + s0.wnx * (s1.w * f * 0.55),
      s0.wy + s0.wny * (s1.w * f * 0.55),
      s1.wx + s1.wnx * (s1.w * f * 0.88) + s1.wtx * 6,
      s1.wy + s1.wny * (s1.w * f * 0.88) + s1.wty * 6
    );
  }

  // Cut woody end of stem
  const tip = st[st.length - 1];
  brush.set("cpencil", "#c7b183", 0.75);
  brush.circle(tip.sx, tip.sy, tip.sw * 0.85, 0.3);
  brush.set("rotring", "#241c0e", 0.5);
  brush.circle(tip.sx, tip.sy, tip.sw * 0.95, 0.3);
}

// ============================================================================
// STEP 5: LOOSE SPILLED SEEDS FOR EXTRA HYPERREAL INCIDENT
// ============================================================================

function renderLooseSeeds(chillies, innerRing) {
  // Scatter loose pale seeds in pockets among the top chillies
  for (let i = 0; i < 24; i++) {
    const a = i * 15 + random(-5, 5);
    const r = random(35, 225);
    const sx = 600 + cos(a) * r;
    const sy = 600 + sin(a) * r;
    renderSinglePaleSeed(sx, sy, random(4.0, 5.6), random(360));
  }

  // A few seeds spilled onto the innermost black reverse-appliqué cloth band
  for (let i = 0; i < 14; i++) {
    const idx = floor(random(innerRing.length));
    const p = innerRing[idx];
    const dx = p.x - 600;
    const dy = p.y - 600;
    const d = sqrt(dx * dx + dy * dy) || 1;
    const offset = random(4, 18);
    renderSinglePaleSeed(
      p.x + (dx / d) * offset,
      p.y + (dy / d) * offset,
      random(4.2, 5.5),
      random(360)
    );
  }
}

