// =========================================================================
// GEOMETRY & PERSPECTIVE HELPERS
// =========================================================================

// Outer rim radius including 12-lobed scallop and the two rim chips
function getOuterRadius(deg) {
  let a = ((deg % 360) + 360) % 360;
  // 12-lobed Regency/Victorian scallop
  let scallop = 5.2 * cos(12 * a) + 1.1 * cos(24 * a);
  let r = R_RIM + scallop;

  // Main chip at ~207 degrees (top-left rim, 10 o'clock)
  let d1 = abs(a - 207.5);
  if (d1 < 8.2) {
    let t = d1 / 8.2;
    let profile = pow(1 - t * t, 1.45);
    let jag =
      2.2 * sin((a - 200) * 52) +
      1.4 * cos((a - 200) * 115) +
      0.8 * sin((a - 200) * 210);
    r -= 19.5 * profile + jag * profile;
  }

  // Secondary small nick at ~27 degrees (lower-right rim, 4 o'clock)
  let d2 = abs(a - 27.0);
  if (d2 < 3.8) {
    let t = d2 / 3.8;
    let profile = pow(1 - t * t, 1.3);
    let jag = 1.1 * sin((a - 24) * 90);
    r -= 8.5 * profile + jag * profile;
  }

  return r;
}

// 3D elevation z(r) of the plate cross-section
function getPlateZ(r) {
  if (r <= R_WELL) return 0;
  if (r <= R_CAV) {
    let t = (r - R_WELL) / (R_CAV - R_WELL);
    return 15 * (t * t * (3 - 2 * t));
  }
  let t = constrain((r - R_CAV) / (R_RIM - R_CAV), 0, 1.1);
  return 15 + 19 * pow(t, 0.86);
}

// Convert polar plate coords (r, deg) -> canvas [x, y]
function polarPt(r, deg, extraZ = 0) {
  let z = getPlateZ(r) + extraZ;
  let x = CX + r * cos(deg);
  let y = CY + r * sin(deg) * ASP - z;
  return [x, y];
}

// Convert flat well coords (wx, wy) -> canvas [x, y]
function wellPt(wx, wy, extraZ = 0) {
  let r = sqrt(wx * wx + wy * wy);
  let z = getPlateZ(r) + extraZ;
  return [CX + wx, CY + wy * ASP - z];
}

// Draw a spline in well coordinates
function wellSpline(pts, curv = 0.5) {
  if (pts.length < 2) return;
  let sPts = pts.map((p) => {
    let sp = wellPt(p[0], p[1]);
    return p.length > 2 ? [sp[0], sp[1], p[2]] : sp;
  });
  brush.spline(sPts, curv);
}

// Draw a line in well coordinates
function wellLine(x1, y1, x2, y2) {
  let p1 = wellPt(x1, y1);
  let p2 = wellPt(x2, y2);
  brush.line(p1[0], p1[1], p2[0], p2[1]);
}

// Draw a filled shape in well coordinates
function wellShape(pts, curv = 0.3) {
  if (pts.length < 3) return;
  brush.beginShape(curv);
  for (let p of pts) {
    let sp = wellPt(p[0], p[1]);
    brush.vertex(sp[0], sp[1]);
  }
  brush.endShape(true);
}

// =========================================================================
// MAIN DRAW
// =========================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background(COL_PINE_BASE);

  // 1. Scrubbed Pine Table Background
  drawScrubbedPineTable();

  // 2. Cool & Soft Morning Cast Shadow under Plate
  drawPlateCastShadow();

  // 3. Porcelain Plate Body & 3D Shading
  drawPorcelainBody();

  // 4. Blue Willow Transferware Pattern (Watercolors + Copperplate Line)
  drawTransferwareBorders();
  drawWillowCentralScene();

  // 5. Glaze Crazing Network & Stained Hairline Crack
  drawGlazeCrazing();
  drawHairlineCrack();

  // 6. Rim Chips (Exposed Biscuit Clay) & Worn Rim Gilt
  drawRimChips();
  drawWornRimGilt();

  // 7. Morning Window Light Glints across Glaze
  drawMorningGlazeReflections();

  noLoop();
}

// =========================================================================
// 1. SCRUBBED PINE TABLE
// =========================================================================

function drawScrubbedPineTable() {
  // Subtle board tilt (-3.5 degrees)
  let slope = tan(-3.5);
  let seamY1 = 235;
  let seamY2 = 975;

  // Base warm raw umber and bleached driftwood watercolor washes
  brush.noStroke();
  brush.fillBleed(0.32, "out");
  brush.fillTexture(0.58, 0.32);

  // Warm raw umber wash bands following plank direction
  const washBands = [
    { y: 70, h: 110, col: COL_PINE_WARM, op: 48 },
    { y: 185, h: 85, col: COL_PINE_UMBER, op: 36 },
    { y: 310, h: 160, col: COL_PINE_WARM, op: 42 },
    { y: 520, h: 210, col: COL_PINE_GREY, op: 38 },
    { y: 790, h: 160, col: COL_PINE_WARM, op: 46 },
    { y: 945, h: 90, col: COL_PINE_UMBER, op: 42 },
    { y: 1080, h: 140, col: COL_PINE_WARM, op: 52 }
  ];

  for (let b of washBands) {
    brush.fill(b.col, b.op);
    let dy = 1200 * slope;
    brush.beginShape(0.2);
    brush.vertex(-40, b.y - b.h / 2);
    brush.vertex(1240, b.y - b.h / 2 + dy);
    brush.vertex(1240, b.y + b.h / 2 + dy);
    brush.vertex(-40, b.y + b.h / 2);
    brush.endShape(true);
  }

  // Morning sunlight warm glow top-left, cool ambient shadow bottom-right
  brush.fill("#fff9eb", 45);
  brush.beginShape(0.3);
  brush.vertex(-20, -20);
  brush.vertex(920, -20);
  brush.vertex(420, 960);
  brush.vertex(-20, 740);
  brush.endShape(true);

  brush.fill("#8f969c", 32);
  brush.beginShape(0.3);
  brush.vertex(580, 350);
  brush.vertex(1220, 120);
  brush.vertex(1220, 1220);
  brush.vertex(150, 1220);
  brush.endShape(true);
  brush.noFill();

  // Pine knots (one on top plank at x=210, y=125; one on bottom plank at x=980, y=1075; one peeking out left at x=85, y=680)
  const knots = [
    { x: 215, y: 118, rx: 46, ry: 22 },
    { x: 985, y: 1082, rx: 54, ry: 25 },
    { x: 78, y: 695, rx: 38, ry: 19 }
  ];

  // Wood grain flow lines across the three planks
  const planks = [
    { yMin: -40, yMax: seamY1, seed: 10 },
    { yMin: seamY1, yMax: seamY2, seed: 20 },
    { yMin: seamY2, yMax: 1250, seed: 30 }
  ];

  for (let pl of planks) {
    let numLines = floor((pl.yMax - pl.yMin) * 0.52);
    for (let i = 0; i < numLines; i++) {
      let baseY = map(i, 0, numLines, pl.yMin, pl.yMax);

      // Skip hidden middle of plate to save render budget
      let midY = baseY + 600 * slope;
      if (
        abs(midY - CY) < 280 &&
        i % 3 !== 0 // still draw some full lines, clip others around plate
      ) {
        drawGrainStrand(baseY, slope, knots, pl, -30, 190);
        drawGrainStrand(baseY, slope, knots, pl, 990, 1230);
      } else {
        drawGrainStrand(baseY, slope, knots, pl, -30, 1230);
      }
    }
  }

  // Draw the pine knots in detail
  for (let k of knots) {
    brush.noStroke();
    brush.fill(COL_PINE_UMBER, 95);
    brush.fillBleed(0.2, "out");
    brush.circle(k.x, k.y, k.ry * 0.9, 0.35);
    brush.fill(COL_PINE_DARK, 130);
    brush.circle(k.x, k.y, k.ry * 0.45, 0.25);
    brush.noFill();

    brush.set("2B", COL_PINE_DARK, 0.35);
    for (let ring = 1; ring <= 5; ring++) {
      let pts = [];
      for (let a = 0; a <= 360; a += 30) {
        let radX = k.rx * (ring / 4.2) + random(-2, 2);
        let radY = k.ry * (ring / 4.2) + random(-1, 1);
        pts.push([
          k.x + radX * cos(a),
          k.y + radY * sin(a) + radX * cos(a) * slope
        ]);
      }
      brush.spline(pts, 0.5);
    }
    // Tiny check cracks inside knot center
    brush.set("rotring", "#3a291a", 0.28);
    brush.line(k.x - 8, k.y - 2, k.x + 9, k.y + 3);
    brush.line(k.x - 3, k.y - 6, k.x + 2, k.y + 6);
  }

  // Plank seams (recessed shadow + scrubbed bevel highlight)
  for (let sy of [seamY1, seamY2]) {
    let dy = 1200 * slope;
    // Soft umber stain along seam
    brush.set("transfer_blur", COL_PINE_UMBER, 1.8);
    brush.line(-20, sy + 2, 1220, sy + dy + 2);

    // Dark gap
    brush.set("charcoal", "#3d2e1e", 0.55);
    let pts = [];
    for (let x = -20; x <= 1220; x += 60) {
      pts.push([x, sy + x * slope + random(-0.8, 0.8), random(0.6, 1.2)]);
    }
    brush.spline(pts, 0.3);

    // Crisp dark core line
    brush.set("rotring", "#291d12", 0.35);
    brush.line(-20, sy, 1220, sy + dy);

    // Sunlit lower edge of seam
    brush.set("2H", "#fcf8f0", 0.45);
    brush.line(-20, sy + 3.2, 1220, sy + dy + 3.2);
  }

  // Subtle cross-grain scrub marks and bleached mineral flecks
  brush.set("2H", "#f5efe2", 0.25);
  for (let i = 0; i < 140; i++) {
    let sx = random(20, 1180);
    let sy = random(20, 1180);
    if (dist(sx, sy, CX, CY) < 430) continue;
    let len = random(18, 65);
    let ang = random(-18, 12);
    brush.line(sx, sy, sx + len * cos(ang), sy + len * sin(ang));
  }
}

function drawGrainStrand(baseY, slope, knots, pl, xStart, xEnd) {
  let pts = [];
  let nOff = baseY * 0.015 + pl.seed;
  let step = 42;
  for (let x = xStart; x <= xEnd; x += step) {
    let y = baseY + x * slope;
    // Cathedral wave undulation
    let wave =
      sin(x * 0.22 + pl.seed * 17) * 12 * noise(x * 0.003, nOff) +
      (noise(x * 0.006, baseY * 0.02) - 0.5) * 18;
    y += wave;

    // Deflect around knots
    for (let k of knots) {
      let dx = x - k.x;
      let dy = y - k.y;
      let d = sqrt((dx * dx) / (k.rx * k.rx * 3.5) + (dy * dy) / (k.ry * k.ry * 4.5));
      if (d < 2.2) {
        let push = pow(1 - d / 2.2, 2) * k.ry * 1.35;
        y += dy >= 0 ? push : -push;
      }
    }

    y = constrain(y, pl.yMin + x * slope + 2, pl.yMax + x * slope - 2);
    pts.push([x, y, random(0.4, 1.15)]);
  }

  if (pts.length >= 2) {
    let r = random();
    if (r < 0.45) {
      brush.set("pine_grain", COL_PINE_UMBER, random(0.55, 1.15));
    } else if (r < 0.78) {
      brush.set("2H", COL_PINE_WARM, random(0.3, 0.55));
    } else if (r < 0.92) {
      brush.set("HB", COL_PINE_DARK, random(0.2, 0.35));
    } else {
      brush.set("2H", "#f4eee1", random(0.25, 0.45));
    }
    brush.spline(pts, 0.45);
  }
}

// =========================================================================
// 2. PLATE CAST SHADOW (COOL & SOFT)
// =========================================================================

function drawPlateCastShadow() {
  brush.noStroke();

  // Layered cool slate-umber watercolor washes shifted down-right (light from top-left)
  const shadowLayers = [
    { dx: 52, dy: 58, rx: 486, ry: 445, col: "#7d8287", op: 28, bleed: 0.45 },
    { dx: 40, dy: 46, rx: 476, ry: 436, col: "#5b646e", op: 36, bleed: 0.38 },
    { dx: 28, dy: 34, rx: 468, ry: 428, col: "#414b57", op: 45, bleed: 0.28 },
    { dx: 16, dy: 20, rx: 462, ry: 422, col: "#2c3540", op: 58, bleed: 0.18 },
    { dx: 7, dy: 9, rx: 456, ry: 416, col: "#1d242e", op: 72, bleed: 0.08 }
  ];

  for (let sl of shadowLayers) {
    brush.fill(sl.col, sl.op);
    brush.fillBleed(sl.bleed, "out");
    brush.fillTexture(0.45, 0.22);
    brush.beginShape(0.35);
    for (let a = 0; a < 360; a += 10) {
      let rMod = getOuterRadius(a) / R_RIM;
      let sx = CX + sl.dx + sl.rx * rMod * cos(a);
      let sy = CY + sl.dy + sl.ry * rMod * sin(a);
      brush.vertex(sx, sy);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // Soft charcoal ambient occlusion hatching in the deepest shadow crescent (bottom-right)
  brush.set("charcoal", "#1c222b", 0.45);
  for (let a = -35; a <= 125; a += 1.6) {
    let rOut = getOuterRadius(a);
    let p1 = polarPt(rOut - 4, a);
    let spread = map(cos(a - 45), -1, 1, 8, 42);
    let p2 = [p1[0] + spread * cos(42), p1[1] + spread * sin(42)];
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

// =========================================================================
// 3. PORCELAIN PLATE BODY & 3D SHADING
// =========================================================================

function drawPorcelainBody() {
  brush.noStroke();

  // Opaque porcelain base wash so table wood grain never shows through the plate
  for (let pass = 0; pass < 2; pass++) {
    brush.wash( pass === 0 ? "#ebe5d8" : COL_PORC_LIGHT, pass === 0 ? 255 : 235);
    brush.beginShape(0.3);
    for (let a = 0; a < 360; a += 5) {
      let pt = polarPt(getOuterRadius(a), a);
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // Subtle warm antique cream tone on the well and lower-right flange
  brush.fill(COL_PORC_CREAM, 65);
  brush.fillBleed(0.18, "in");
  brush.fillTexture(0.3, 0.15);
  brush.beginShape(0.35);
  for (let a = 0; a < 360; a += 10) {
    let pt = polarPt(R_WELL + 8, a);
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);

  // Lower-right rim flange subtle halftone shadow (slopes away from top-left light)
  brush.fill(COL_PORC_SHAD, 52);
  brush.fillBleed(0.25, "in");
  brush.beginShape(0.35);
  for (let a = -35; a <= 135; a += 8) {
    let pt = polarPt(getOuterRadius(a) - 2, a);
    brush.vertex(pt[0], pt[1]);
  }
  for (let a = 135; a >= -35; a -= 8) {
    let pt = polarPt(R_CAV + 6, a);
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);

  // Top-left inner cavetto crescent shadow (sloping down into the well away from light)
  brush.fill(COL_PORC_SHAD, 78);
  brush.fillBleed(0.22, "out");
  brush.beginShape(0.35);
  for (let a = 130; a <= 315; a += 8) {
    let pt = polarPt(R_CAV + 4, a);
    brush.vertex(pt[0], pt[1]);
  }
  for (let a = 315; a >= 130; a -= 8) {
    let pt = polarPt(R_WELL - 16, a);
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);

  // Deeper core of the cavetto shadow at ~225 deg
  brush.fill(COL_PORC_DEEP, 52);
  brush.fillBleed(0.2, "out");
  brush.beginShape(0.35);
  for (let a = 165; a <= 280; a += 8) {
    let pt = polarPt(R_CAV - 2, a);
    brush.vertex(pt[0], pt[1]);
  }
  for (let a = 280; a >= 165; a -= 8) {
    let pt = polarPt(R_WELL - 6, a);
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);
  brush.noFill();

  // Molded radial ribs on the rim flange (subtle Regency 12-lobe fluting)
  for (let lobe = 0; lobe < 12; lobe++) {
    letvalleyDeg = lobe * 30 + 15;
    let pIn = polarPt(R_CAV + 10, valleyDeg);
    let pOut = polarPt(getOuterRadius(valleyDeg) - 10, valleyDeg);
    brush.set("2H", COL_PORC_SHAD, 0.32);
    brush.line(pIn[0], pIn[1], pOut[0], pOut[1]);
    let pInH = polarPt(R_CAV + 10, valleyDeg + 1.2);
    let pOutH = polarPt(getOuterRadius(valleyDeg + 1.2) - 10, valleyDeg + 1.2);
    brush.set("2H", "#ffffff", 0.35);
    brush.line(pInH[0], pInH[1], pOutH[0], pOutH[1]);
  }
}

// =========================================================================
// 4A. BLUE WILLOW TRANSFERWARE BORDERS (RIM & CAVETTO)
// =========================================================================

function drawTransferwareBorders() {
  // 1. Pale blurred underglaze cobalt watercolor wash under the rim & cavetto bands
  brush.noStroke();
  brush.fill(B_BLUR_WASH, 68);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.3);

  // Rim border wash in 4 quadrant arcs for clean fill geometry
  for (let q = 0; q < 4; q++) {
    let aStart = q * 90;
    let aEnd = (q + 1) * 90;
    brush.beginShape(0.25);
    for (let a = aStart; a <= aEnd; a += 5) {
      let rOut = min(452, getOuterRadius(a) - 5);
      let pt = polarPt(rOut, a);
      brush.vertex(pt[0], pt[1]);
    }
    for (let a = aEnd; a >= aStart; a -= 5) {
      let rIn = 358 + 7 * sin(12 * a);
      let pt = polarPt(rIn, a);
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);
  }

  // Darker cobalt wash on outer rim diaper band
  brush.fill(B_PALE_COBALT, 62);
  brush.fillBleed(0.14, "out");
  for (let q = 0; q < 4; q++) {
    let aStart = q * 90;
    let aEnd = (q + 1) * 90;
    brush.beginShape(0.25);
    for (let a = aStart; a <= aEnd; a += 5) {
      let rOut = min(448, getOuterRadius(a) - 6);
      let pt = polarPt(rOut, a);
      brush.vertex(pt[0], pt[1]);
    }
    for (let a = aEnd; a >= aStart; a -= 5) {
      let pt = polarPt(392, a);
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);
  }

  // Cavetto border wash (r = 283 to 321)
  brush.fill(B_BLUR_WASH, 72);
  brush.fillBleed(0.15, "out");
  for (let q = 0; q < 4; q++) {
    let aStart = q * 90;
    let aEnd = (q + 1) * 90;
    brush.beginShape(0.25);
    for (let a = aStart; a <= aEnd; a += 6) {
      let pt = polarPt(320, a);
      brush.vertex(pt[0], pt[1]);
    }
    for (let a = aEnd; a >= aStart; a -= 6) {
      let pt = polarPt(283, a);
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);
  }
  brush.noFill();

  // 2. Soft transfer ink bleed along the border edges
  brush.set("transfer_blur", B_MID_COBALT, 1.1);
  drawPolarRing(448, 3, true);
  drawPolarRing(388, 3, false);
  drawPolarRing(320, 3, false);
  drawPolarRing(284, 3, false);

  // 3. Crisp Copperplate Linework for the Outer Rim Border
  // Outer scalloped double framing lines
  brush.set("engraving_needle", B_PRUSSIAN, 0.95);
  drawScallopedRing(453, 2);
  brush.set("engraving_needle", B_DARK_COBALT, 0.75);
  drawScallopedRing(447, 2);

  // Main Rim Diaper Trellis & Alternating Scroll/Blossom Panels (r = 390..446)
  for (let a = 0; a < 360; a += 1.5) {
    let rMax = getOuterRadius(a) - 7;
    if (rMax < 400) continue; // Clipped by big chip

    let rTop = min(446, rMax);
    let rBot = 390;

    // Alternating 30-degree panels: diamond diaper trellis vs. floral scroll cartouche
    let sectorPhase = a % 30;
    if (sectorPhase < 18) {
      // Crisscross diamond diaper lattice
      let p1 = polarPt(rBot, a);
      let p2 = polarPt(rTop, a + 2.6);
      let p3 = polarPt(rTop, a - 2.6);
      brush.set("engraving_needle", B_DARK_COBALT, 0.65);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.line(p1[0], p1[1], p3[0], p3[1]);

      // Small cobalt dot inside each diamond cell
      if (abs((a % 3) - 1.5) < 0.8 && rTop > 425) {
        let pm = polarPt(418, a);
        brush.set("rotring", B_PRUSSIAN, 0.45);
        brush.circle(pm[0], pm[1], 1.6, 0.2);
      }
    } else if (abs(sectorPhase - 24) < 0.8) {
      // Stylized Willow chrysanthemum / butterfly motif at center of cartouche
      drawRimBlossomCartouche(a, (rBot + rTop) * 0.5, rTop - rBot);
    }
  }

  // Rim inner ring at r = 388
  brush.set("engraving_needle", B_PRUSSIAN, 0.85);
  drawPolarRing(389, 2, true);
  brush.set("engraving_needle", B_COBALT, 0.65);
  drawPolarRing(384, 2, true);

  // Inner Apron of Rim: Scalloped Swags, Spearheads & Tassels (r = 350..384)
  for (let a = 0; a < 360; a += 7.5) {
    let nextA = a + 7.5;
    // Half-oval swag
    let swagPts = [];
    for (let t = 0; t <= 1; t += 0.25) {
      let ang = lerp(a, nextA, t);
      let rad = 384 - 22 * sin(t * 180);
      swagPts.push(polarPt(rad, ang));
    }
    brush.set("engraving_needle", B_DARK_COBALT, 0.72);
    brush.spline(swagPts, 0.5);

    // Inner hatch lines inside swag
    for (let t = 0.2; t <= 0.8; t += 0.2) {
      let ang = lerp(a, nextA, t);
      let rad = 383 - 19 * sin(t * 180);
      let pA = polarPt(383, ang);
      let pB = polarPt(rad, ang);
      brush.set("engraving_needle", B_COBALT, 0.5);
      brush.line(pA[0], pA[1], pB[0], pB[1]);
    }

    // Dangling spearhead / trefoil pointing inward between swags
    let pTip = polarPt(348, a);
    let pBaseL = polarPt(368, a - 1.2);
    let pBaseR = polarPt(368, a + 1.2);
    let pMid = polarPt(383, a);
    brush.set("engraving_needle", B_PRUSSIAN, 0.75);
    brush.line(pMid[0], pMid[1], pTip[0], pTip[1]);
    brush.line(pBaseL[0], pBaseL[1], pTip[0], pTip[1]);
    brush.line(pBaseR[0], pBaseR[1], pTip[0], pTip[1]);
  }

  // 4. Cavetto Band (r = 282..322): Classic Lattice & 4 Floral Cartouches
  brush.set("engraving_needle", B_PRUSSIAN, 0.9);
  drawPolarRing(322, 2, false);
  drawPolarRing(318, 2, false);
  drawPolarRing(285, 2, false);
  drawPolarRing(281, 2, false);

  for (let a = 0; a < 360; a += 2) {
    // Check if inside one of 4 diagonal cartouches (45, 135, 225, 315 deg)
    let inCartouche = false;
    for (let cAng of [45, 135, 225, 315]) {
      if (abs(a - cAng) < 10) inCartouche = true;
    }

    if (!inCartouche) {
      let p1 = polarPt(285, a);
      let p2 = polarPt(318, a + 2.8);
      let p3 = polarPt(318, a - 2.8);
      brush.set("engraving_needle", B_COBALT, 0.58);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      brush.line(p1[0], p1[1], p3[0], p3[1]);
    }
  }

  // Draw the 4 Cavetto Cartouches
  for (let cAng of [45, 135, 225, 315]) {
    // Cartouche oval frame
    let framePts = [];
    for (let t = 0; t <= 360; t += 30) {
      let ang = cAng + 9.2 * cos(t);
      let rad = 301.5 + 15 * sin(t);
      framePts.push(polarPt(rad, ang));
    }
    brush.set("engraving_needle", B_PRUSSIAN, 0.85);
    brush.spline(framePts, 0.5);

    // Scroll floret inside cartouche
    let pc = polarPt(301.5, cAng);
    brush.set("engraving_needle", B_DARK_COBALT, 0.75);
    brush.circle(pc[0], pc[1], 5.5, 0.2);
    for (let k = -6; k <= 6; k += 3) {
      if (k === 0) continue;
      let pf = polarPt(301.5 + (k % 2 === 0 ? 5 : -5), cAng + k);
      brush.line(pc[0], pc[1], pf[0], pf[1]);
    }
  }
}

function drawPolarRing(r, stepDeg = 2, clipToOuter = true) {
  let pts = [];
  for (let a = 0; a <= 360; a += stepDeg) {
    let maxR = getOuterRadius(a) - 4;
    if (clipToOuter && r > maxR) {
      if (pts.length >= 2) brush.spline(pts, 0.4);
      pts = [];
    } else {
      pts.push(polarPt(r, a));
    }
  }
  if (pts.length >= 2) brush.spline(pts, 0.4);
}

function drawScallopedRing(baseR, stepDeg = 2) {
  let pts = [];
  for (let a = 0; a <= 360; a += stepDeg) {
    let r = baseR + 4.8 * cos(12 * a);
    let maxR = getOuterRadius(a) - 3.5;
    if (r > maxR) {
      if (pts.length >= 2) brush.spline(pts, 0.4);
      pts = [];
    } else {
      pts.push(polarPt(r, a));
    }
  }
  if (pts.length >= 2) brush.spline(pts, 0.4);
}

function drawRimBlossomCartouche(deg, rMid, bandH) {
  let pc = polarPt(rMid, deg);
  // Central blossom
  brush.set("engraving_needle", B_PRUSSIAN, 0.85);
  brush.circle(pc[0], pc[1], 5, 0.25);
  for (let p = 0; p < 8; p++) {
    let pa = p * 45;
    let rad = rMid + sin(pa) * (bandH * 0.36);
    let ang = deg + cos(pa) * 3.8;
    if (rad < getOuterRadius(ang) - 6) {
      let pp = polarPt(rad, ang);
      brush.set("engraving_needle", B_DARK_COBALT, 0.65);
      brush.line(pc[0], pc[1], pp[0], pp[1]);
      brush.circle(pp[0], pp[1], 3.2, 0.3);
    }
  }
  // Flanking scroll tendrils
  for (let side of [-1, 1]) {
    let sPts = [
      polarPt(rMid - 12, deg + side * 1.5),
      polarPt(rMid, deg + side * 4.2),
      polarPt(rMid + 12, deg + side * 5.2),
      polarPt(rMid + 4, deg + side * 3.5)
    ];
    brush.set("engraving_needle", B_COBALT, 0.6);
    brush.spline(sPts, 0.6);
  }
}

