  // --- PASS 3: Sampan Boat on the River ---
  drawSampanBoat();

  // --- PASS 4: Right Estate Island, Fruit Tree, Pines & Rocks ---
  drawRightEstateLandAndTrees();

  // --- PASS 5: The Main Two-Story Pagoda / Palace ---
  drawMainPagoda();

  // --- PASS 6: The Weeping Willow Tree (Trunk, Boughs & Drooping Catkins) ---
  drawWeepingWillowTree();

