function drawWeepingWillowTree() {
  // Rooted on the right bank near the bridgehead (wx = 8, wy = 72), arching left over the water
  brush.set("engraving_needle", B_PRUSSIAN, 1.05);
  // Gnarled trunk contours
  wellSpline([[14, 74], [8, 42], [-2, 10], [-18, -22], [-38, -48]], 0.45);
  wellSpline([[2, 75], [-2, 44], [-12, 12], [-28, -20], [-48, -44]], 0.45);

  // Bark texture & knot holes on willow trunk
  brush.set("engraving_needle", B_DARK_COBALT, 0.65);
  wellSpline([[8, 68], [3, 42], [-7, 14], [-23, -18]], 0.45);
  wellSpline([[5, 58], [0, 32], [-10, 4]], 0.45);

  // Upper arching boughs
  brush.set("engraving_needle", B_PRUSSIAN, 0.88);
  // Left bough arching over bridge
  wellSpline([[-35, -38], [-58, -62], [-82, -68], [-102, -55]], 0.45);
  // Center-left bough
  wellSpline([[-28, -32], [-42, -74], [-62, -88], [-78, -82]], 0.45);
  // Center-top bough
  wellSpline([[-18, -20], [-18, -68], [-25, -96], [-38, -102]], 0.45);
  // Right bough
  wellSpline([[-8, -6], [6, -48], [22, -72], [36, -68]], 0.45);

  // Cascading Weeping Willow Fronds & Drooping Catkins!
  // 28 hanging curtains of fine dotted/feathered cobalt strands
  const frondOrigins = [
    [-102, -54, 48], [-94, -62, 54], [-86, -68, 58], [-78, -80, 65],
    [-70, -86, 68], [-62, -88, 66], [-54, -84, 62], [-46, -92, 68],
    [-38, -100, 72], [-30, -96, 68], [-22, -88, 64], [-14, -78, 58],
    [-6, -72, 55], [2, -68, 54], [10, -72, 56], [18, -74, 58],
    [26, -70, 52], [34, -64, 46], [-88, -42, 36], [-72, -48, 42],
    [-55, -52, 44], [-38, -54, 42], [-18, -45, 38], [4, -42, 38],
    [20, -40, 36], [30, -35, 32]
  ];

  for (let idx = 0; idx < frondOrigins.length; idx++) {
    let [ox, oy, len] = frondOrigins[idx];
    let col = idx % 3 === 0 ? B_PRUSSIAN : idx % 3 === 1 ? B_DARK_COBALT : B_COBALT;
    brush.set("engraving_needle", col, 0.62);

    // Gently swaying vertical curve for the hanging willow strand
    let sway = sin(idx * 37) * 5;
    wellSpline([
      [ox, oy],
      [ox + sway * 0.5, oy + len * 0.45],
      [ox + sway, oy + len]
    ], 0.4);

    // Opposite-paired tiny willow leaves / catkin ticks along the hanging strand
    for (let d = 5; d <= len; d += 4.8) {
      let lx = ox + sway * (d / len);
      let ly = oy + d;
      wellLine(lx, ly, lx - 3.6, ly + 2.8);
      wellLine(lx, ly + 1.5, lx + 3.6, ly + 4.2);
    }
  }
}

