  // Far railing (behind the 3 figures, slightly raised)
  brush.set("engraving_needle", B_DARK_COBALT, 0.68);
  wellSpline([[-156, 51], [-118, 39], [-84, 35], [-48, 39], [-10, 53]], 0.4);
  // Near railing posts & latticework
  for (let x = -152; x <= -14; x += 11.5) {
    let t = (x + 158) / 150;
    let yDeck = 64 - 18 * sin(t * 180);
    brush.set("engraving_needle", B_PRUSSIAN, 0.78);
    wellLine(x, yDeck + 4, x, yDeck - 11);
    if (x < -20) {
      let tNext = (x + 11.5 + 158) / 150;
      let yNext = 64 - 18 * sin(tNext * 180);
      brush.set("engraving_needle", B_COBALT, 0.52);
      wellLine(x, yDeck - 9, x + 11.5, yNext);
      wellLine(x, yDeck, x + 11.5, yNext - 9);
    }
  }

  // Three Semicircular Masonry Arches & Stone Piers
  const arches = [
    { cx: -128, w: 34, h: 20, yBase: 82 },
    { cx: -84, w: 42, h: 26, yBase: 84 },
    { cx: -40, w: 34, h: 20, yBase: 82 }
  ];

  for (let ar of arches) {
    // Arch vault curve
    let aPts = [];
    let vPts = [];
    for (let deg = 180; deg >= 0; deg -= 20) {
      let ax = ar.cx + (ar.w * 0.5) * cos(deg);
      let ay = ar.yBase - ar.h * sin(deg);
      aPts.push([ax, ay]);
      vPts.push([ax, ay - 5]);
    }
    brush.set("engraving_needle", B_PRUSSIAN, 0.95);
    wellSpline(aPts, 0.45);
    brush.set("engraving_needle", B_DARK_COBALT, 0.68);
    wellSpline(vPts, 0.45);

    // Voussoir arch stones
    for (let deg = 165; deg >= 15; deg -= 25) {
      let x1 = ar.cx + (ar.w * 0.5) * cos(deg);
      let y1 = ar.yBase - ar.h * sin(deg);
      let x2 = ar.cx + (ar.w * 0.5 + 4) * cos(deg);
      let y2 = ar.yBase - (ar.h + 5) * sin(deg);
      wellLine(x1, y1, x2, y2);
    }

    // Dark shadow inside upper vault of each arch
    brush.set("engraving_needle", B_PRUSSIAN, 0.72);
    for (let s = -ar.w * 0.38; s <= ar.w * 0.38; s += 3.5) {
      let hTop = ar.yBase - ar.h * sqrt(max(0, 1 - pow(s / (ar.w * 0.5), 2)));
      wellLine(ar.cx + s, hTop, ar.cx + s, hTop + 8);
    }
  }

  // Stone piers between the arches
  for (let px of [-152, -108, -60, -18]) {
    brush.set("engraving_needle", B_PRUSSIAN, 0.88);
    wellLine(px - 4, 62, px - 5, 85);
    wellLine(px + 4, 62, px + 5, 85);
    wellLine(px - 7, 85, px + 7, 85);
    // Horizontal ashlar courses on piers
    brush.set("engraving_needle", B_COBALT, 0.55);
    for (let py = 66; py <= 82; py += 4) {
      wellLine(px - 5, py, px + 5, py);
    }
  }
}

