function drawForegroundFenceAndGarden() {
  // --- THE ZIGZAG FRETWORK FENCE (wx = -162 to +176, wy = 148..195) ---
  // 6 vertices forming 5 angled zigzag panels across the foreground bank
  const fencePosts = [
    [-158, 174],
    [-96, 152],
    [-34, 178],
    [32, 150],
    [98, 176],
    [164, 152]
  ];
  const fenceH = 26;

  for (let i = 0; i < fencePosts.length - 1; i++) {
    let [x1, y1] = fencePosts[i];
    let [x2, y2] = fencePosts[i + 1];

    // Top & bottom rails (double lines)
    brush.set("engraving_needle", B_PRUSSIAN, 0.92);
    wellLine(x1, y1 - fenceH, x2, y2 - fenceH);
    wellLine(x1, y1 - fenceH + 3.5, x2, y2 - fenceH + 3.5);
    wellLine(x1, y1, x2, y2);
    wellLine(x1, y1 - 3.5, x2, y2 - 3.5);

    // Classic Chinese fretwork / swastika-lattice infill inside each panel
    brush.set("engraving_needle", B_DARK_COBALT, 0.62);
    let steps = 8;
    for (let s = 1; s < steps; s++) {
      let tA = s / steps;
      let tB = constrain((s + 1.4) / steps, 0, 1);
      let tC = constrain((s - 1.4) / steps, 0, 1);

      let pxTop = lerp(x1, x2, tA);
      let pyTop = lerp(y1, y2, tA) - fenceH + 3.5;

      let pxBotR = lerp(x1, x2, tB);
      let pyBotR = lerp(y1, y2, tB) - 3.5;

      let pxBotL = lerp(x1, x2, tC);
      let pyBotL = lerp(y1, y2, tC) - 3.5;

      wellLine(pxTop, pyTop, pxBotR, pyBotR);
      wellLine(pxTop, pyTop, pxBotL, pyBotL);
    }

    // Center horizontal bar inside lattice
    let midY1 = y1 - fenceH * 0.5;
    let midY2 = y2 - fenceH * 0.5;
    wellLine(x1, midY1, x2, midY2);
  }

  // Heavy Fence Posts with Finial Caps at each corner
  for (let [px, py] of fencePosts) {
    brush.set("engraving_needle", B_PRUSSIAN, 1.0);
    wellLine(px - 2, py + 4, px - 2, py - fenceH - 5);
    wellLine(px + 2, py + 4, px + 2, py - fenceH - 5);
    let pCap = wellPt(px, py - fenceH - 7);
    brush.circle(pCap[0], pCap[1], 3.8, 0.2);
  }

  // --- Foreground Rocks, Peony Shrubs & Small Garden Trees (wy = 175..265) ---
  // Shoreline above fence
  brush.set("engraving_needle", B_PRUSSIAN, 0.85);
  wellSpline([[-185, 162], [-115, 142], [-35, 152], [45, 138], [135, 145], [212, 132]], 0.4);

  // Foreground scalloped boulders and peony foliage below fence
  const rockMounds = [
    { x: -105, y: 212, w: 48, h: 24 },
    { x: -38, y: 228, w: 62, h: 32 },
    { x: 35, y: 222, w: 68, h: 34 },
    { x: 105, y: 215, w: 52, h: 26 },
    { x: -8, y: 252, w: 75, h: 22 }
  ];

  for (let rm of rockMounds) {
    brush.set("engraving_needle", B_PRUSSIAN, 0.88);
    let rPts = [];
    for (let a = 180; a <= 360; a += 22) {
      let rx = rm.x + (rm.w * 0.5) * cos(a);
      let ry = rm.y + rm.h * sin(a) + 4 * sin(a * 5);
      if (rx * rx + ry * ry < 272 * 272) {
        rPts.push([rx, ry]);
      }
    }
    wellSpline(rPts, 0.4);

    // Dense cobalt engraving shading inside foreground rocks
    brush.set("engraving_needle", B_DARK_COBALT, 0.62);
    for (let dx = -rm.w * 0.42; dx <= rm.w * 0.42; dx += 4.5) {
      let rx = rm.x + dx;
      let ryTop = rm.y - rm.h * sqrt(max(0, 1 - pow(dx / (rm.w * 0.5), 2))) + 4;
      let ryBot = min(rm.y + 4, sqrt(max(0, 270 * 270 - rx * rx)) - 4);
      if (ryBot > ryTop) {
        wellLine(rx, ryTop, rx + 2, ryBot);
      }
    }
  }

  // Small leafy shrub at far right of fence (wx = 178, wy = 165)
  for (let a = 0; a < 360; a += 36) {
    let pLeaf = wellPt(178 + 18 * cos(a), 168 + 14 * sin(a));
    brush.set("engraving_needle", B_COBALT, 0.65);
    brush.circle(pLeaf[0], pLeaf[1], 7, 0.35);
  }
}

