// =========================================================================
// 5. GLAZE CRAZING NETWORK & STAINED HAIRLINE CRACK
// =========================================================================

function drawGlazeCrazing() {
  // Generate a semi-regular cellular network of glaze crackle across the plate
  // Crazing is most visible in creamy porcelain zones and stained slightly darker near the center & hairline crack
  const rings = [0, 34, 68, 104, 142, 180, 218, 254, 286, 322, 362, 404, 444];
  let grid = [];

  for (let ri = 0; ri < rings.length; ri++) {
    let r = rings[ri];
    if (r === 0) {
      grid.push([{ r: 0, a: 0, x: CX, y: CY, wx: 0, wy: 0 }]);
      continue;
    }
    let numPts = max(7, floor((TWO_PI * r) / 42));
    let row = [];
    for (let j = 0; j < numPts; j++) {
      let a = (j * 360) / numPts + random(-6, 6);
      let rr = constrain(r + random(-9, 9), 8, getOuterRadius(a) - 6);
      let pt = polarPt(rr, a);
      row.push({
        r: rr,
        a: a,
        x: pt[0],
        y: pt[1],
        wx: rr * cos(a),
        wy: rr * sin(a)
      });
    }
    grid.push(row);
  }

  // Draw circumferential and radial craze connections with organic micro-bends
  for (let ri = 1; ri < grid.length; ri++) {
    let row = grid[ri];
    let prevRow = grid[ri - 1];

    for (let j = 0; j < row.length; j++) {
      let p1 = row[j];
      let p2 = row[(j + 1) % row.length];

      // Circumferential craze segment (skip ~18% for realistic T-junctions)
      if (random() < 0.82) {
        drawCrazeSegment(p1, p2);
      }

      // Radial craze connection to inner ring
      let bestK = 0;
      let bestDist = 99999;
      for (let k = 0; k < prevRow.length; k++) {
        let d = dist(p1.x, p1.y, prevRow[k].x, prevRow[k].y);
        if (d < bestDist) {
          bestDist = d;
          bestK = k;
        }
      }
      if (random() < 0.86) {
        drawCrazeSegment(p1, prevRow[bestK]);
      }
    }
  }
}

function drawCrazeSegment(p1, p2) {
  // Determine tea-stain intensity based on proximity to center well or the top-left hairline crack
  let mx = (p1.wx + p2.wx) * 0.5;
  let my = (p1.wy + p2.wy) * 0.5;
  let distToCrack = distToSegment(mx, my, -408, -212, -55, -22);
  let distToCenter = sqrt(mx * mx + my * my);

  let col = COL_CRAZE_LIGHT;
  let w = 0.58;
  if (distToCrack < 75 || (distToCenter < 130 && random() < 0.45)) {
    col = COL_CRAZE_MID;
    w = 0.72;
  } else if (random() < 0.25) {
    col = "#d4c8b4";
    w = 0.48;
  }

  let midX = (p1.x + p2.x) * 0.5 + random(-3.2, 3.2);
  let midY = (p1.y + p2.y) * 0.5 + random(-3.2, 3.2);

  brush.set("craze_hair", col, w);
  brush.spline([
    [p1.x, p1.y, random(0.4, 0.9)],
    [midX, midY, random(0.6, 1.1)],
    [p2.x, p2.y, random(0.4, 0.9)]
  ], 0.35);
}

function distToSegment(px, py, x1, y1, x2, y2) {
  let l2 = (x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1);
  if (l2 === 0) return dist(px, py, x1, y1);
  let t = constrain(((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2, 0, 1);
  return dist(px, py, x1 + t * (x2 - x1), y1 + t * (y2 - y1));
}

function drawHairlineCrack() {
  // Propagates from the big rim chip at 207.5 deg inward into the central well
  let c0 = polarPt(getOuterRadius(207.5) + 1, 207.5);
  const crackNodes = [
    [c0[0], c0[1], 1.2],
    polarPt(422, 206.2).concat([1.15]),
    polarPt(390, 208.0).concat([1.1]),
    polarPt(355, 205.8).concat([1.05]),
    polarPt(322, 204.2).concat([1.0]),
    polarPt(288, 205.5).concat([0.92]),
    wellPt(-222, -98).concat([0.85]),
    wellPt(-182, -76).concat([0.78]),
    wellPt(-142, -62).concat([0.68]),
    wellPt(-102, -42).concat([0.52]),
    wellPt(-68, -28).concat([0.32]),
    wellPt(-42, -19).concat([0.12])
  ];

  // Secondary branch splitting off at the cavetto
  const forkNodes = [
    polarPt(322, 204.2).concat([0.75]),
    polarPt(292, 198.5).concat([0.62]),
    wellPt(-238, -68).concat([0.48]),
    wellPt(-202, -45).concat([0.28]),
    wellPt(-176, -34).concat([0.1])
  ];

  // 1. Warm amber-tea stain halo bled into the glaze along the crack
  brush.set("transfer_blur", "#b89c74", 1.85);
  brush.spline(crackNodes, 0.25);
  brush.set("transfer_blur", "#9e7d52", 1.1);
  brush.spline(crackNodes, 0.25);
  brush.spline(forkNodes, 0.25);

  // 2. Crisp dark oxidized hairline core
  brush.set("rotring", COL_CRAZE_DARK, 0.52);
  brush.spline(crackNodes, 0.22);
  brush.set("rotring", "#332214", 0.35);
  brush.spline(crackNodes.slice(0, 8), 0.22);

  brush.set("rotring", COL_CRAZE_DARK, 0.36);
  brush.spline(forkNodes, 0.22);

  // 3. Microscopic light-catching glaze step along the lower-right lip of the crack
  let hiNodes = crackNodes.slice(0, 10).map((p) => [p[0] + 1.4, p[1] + 1.4, p[2] * 0.7]);
  brush.set("engraving_needle", "#ffffff", 0.55);
  brush.spline(hiNodes, 0.22);
}

// =========================================================================
// 6. RIM CHIPS (EXPOSED BISCUIT CLAY) & WORN RIM GILT
// =========================================================================

function drawRimChips() {
  // --- CHIP 1: Main Conchoidal Rim Fracture at 199..216 degrees (Top-Left, 10 o'clock) ---
  let outerPts = [];
  let innerPts = [];
  for (let a = 198.5; a <= 216.5; a += 1.0) {
    outerPts.push(polarPt(getOuterRadius(a), a));
  }
  for (let a = 216.5; a >= 198.5; a -= 1.0) {
    let t = (a - 207.5) / 9.0;
    let depth = 16.5 * pow(max(0, 1 - t * t), 1.2) + 2.2 * sin(a * 45);
    innerPts.push(polarPt(getOuterRadius(a) - depth, a));
  }

  // Matte unglazed biscuit clay fill
  brush.noStroke();
  brush.wash(COL_BISCUIT_LIGHT, 245);
  brush.beginShape(0.15);
  for (let p of outerPts) brush.vertex(p[0], p[1]);
  for (let p of innerPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  // Warm clay shading wash inside fracture concavity
  brush.fill(COL_BISCUIT_MID, 130);
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.75, 0.5);
  brush.beginShape(0.2);
  for (let p of outerPts) brush.vertex(p[0], p[1]);
  for (let p of innerPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // Rough granular ceramic body texture & stepped conchoidal fracture ridges
  brush.set("charcoal", COL_BISCUIT_DARK, 0.38);
  for (let i = 1; i < outerPts.length - 1; i++) {
    let pO = outerPts[i];
    let pI = innerPts[innerPts.length - 1 - i];
    brush.line(pO[0], pO[1], pI[0], pI[1]);
  }
  // Stepped ridge lines along the chip
  let midChipPts = outerPts.map((p, idx) => {
    let pi = innerPts[innerPts.length - 1 - idx];
    return [lerp(p[0], pi[0], 0.5), lerp(p[1], pi[1], 0.5)];
  });
  brush.set("2B", COL_BISCUIT_DARK, 0.42);
  brush.spline(midChipPts, 0.3);

  // Sharp broken white glaze edge & dark shadow under upper lip
  brush.set("rotring", "#423321", 0.42);
  brush.spline(outerPts, 0.25);
  brush.set("rotring", "#ffffff", 0.55);
  brush.spline(innerPts, 0.25);
  brush.set("engraving_needle", B_PRUSSIAN, 0.65);
  // Broken cobalt transfer edge along inner fracture line
  brush.spline(innerPts.slice(2, innerPts.length - 2), 0.25);

  // --- CHIP 2: Smaller Flake Nick at 23.5..30.5 degrees (Lower-Right, 4 o'clock) ---
  let out2 = [];
  let in2 = [];
  for (let a = 23.0; a <= 31.0; a += 1.0) {
    out2.push(polarPt(getOuterRadius(a), a));
  }
  for (let a = 31.0; a >= 23.0; a -= 1.0) {
    let t = (a - 27.0) / 4.0;
    let depth = 9.5 * pow(max(0, 1 - t * t), 1.2);
    in2.push(polarPt(getOuterRadius(a) - depth, a));
  }

  brush.noStroke();
  brush.wash(COL_BISCUIT_MID, 240);
  brush.beginShape(0.15);
  for (let p of out2) brush.vertex(p[0], p[1]);
  for (let p of in2) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noWash();

  brush.set("charcoal", COL_BISCUIT_DARK, 0.35);
  brush.spline(out2, 0.25);
  brush.set("rotring", "#ffffff", 0.45);
  brush.spline(in2, 0.25);
}

function drawWornRimGilt() {
  // Discontinuous, rubbed antique gold leaf around the scalloped outer rim edge
  for (let a = 0; a < 360; a += 1.2) {
    // Skip the two chipped zones
    if (abs(a - 207.5) < 9.2 || abs(a - 27.0) < 4.5) continue;

    // Wear pattern: rubbed away on some scallop crests, preserved in others
    let wearNoise = noise(cos(a) * 2.5 + 10, sin(a) * 2.5 + 10);
    if (wearNoise < 0.34) continue;

    let rEdge = getOuterRadius(a) - 1.8;
    let p1 = polarPt(rEdge, a);
    let p2 = polarPt(getOuterRadius(a + 1.1) - 1.8, a + 1.1);

    // Base rubbed ochre-gold bole
    brush.set("2B", COL_GILT_DARK, 0.48);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    if (wearNoise > 0.46) {
      brush.set("cpencil", COL_GILT_MID, 0.55);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }

    // Bright specular metallic gold glints catching morning light (top-left & bottom-right)
    let lightCatch = cos(a - 218) * 0.6 + cos(a - 38) * 0.5;
    if (wearNoise > 0.54 && lightCatch > 0.15) {
      brush.set("rotring", COL_GILT_BRIGHT, 0.48);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
      if (lightCatch > 0.42 && random() < 0.4) {
        brush.set("rotring", "#ffffff", 0.38);
        brush.circle(p1[0], p1[1], 1.4, 0.1);
      }
    }
  }

  // Crisp outer porcelain contour shadow where plate rim meets table shadow
  brush.set("rotring", "#3a4047", 0.32);
  for (let a = -50; a <= 130; a += 3) {
    let p1 = polarPt(getOuterRadius(a), a);
    let p2 = polarPt(getOuterRadius(a + 3), a + 3);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }
}

