function drawMorningGlazeReflections() {
  // 1. Soft translucent morning window pane reflection across the upper-left well & rim
  // Divided into 2 panes by a subtle window sash bar!
  brush.noStroke();

  // Pane 1 (Upper-left rim & upper well)
  brush.wash("#ffffff", 26);
  wellShape([
    [-255, -185], [-65, -245], [-25, -142], [-218, -75]
  ], 0.18);

  // Pane 2 (Below window mullion bar, crossing willow & water)
  brush.wash("#ffffff", 22);
  wellShape([
    [-210, -52], [-18, -118], [18, -15], [-175, 48]
  ], 0.18);

  // Brighter core inside top-left rim flange (facing the morning window)
  brush.wash("#ffffff", 38);
  brush.beginShape(0.3);
  for (let a = 192; a <= 258; a += 5) {
    if (abs(a - 207.5) < 9) continue;
    let pt = polarPt(getOuterRadius(a) - 8, a);
    brush.vertex(pt[0], pt[1]);
  }
  for (let a = 258; a >= 192; a -= 5) {
    let pt = polarPt(R_CAV + 8, a);
    brush.vertex(pt[0], pt[1]);
  }
  brush.endShape(true);

  // 2. Curved Cavetto Specular Reflection (Bottom-Right inner curve r ≈ 296..314)
  // The concave cavetto on the bottom-right directly reflects the top-left morning window!
  // Split into two curved panes by the window mullion at ~32 degrees
  const cavettoArcs = [
    { a1: -18, a2: 28, op: 64 },
    { a1: 35, a2: 86, op: 58 }
  ];

  for (let arcDef of cavettoArcs) {
    brush.wash("#ffffff", arcDef.op);
    brush.beginShape(0.3);
    for (let a = arcDef.a1; a <= arcDef.a2; a += 4) {
      let pt = polarPt(313, a);
      brush.vertex(pt[0], pt[1]);
    }
    for (let a = arcDef.a2; a >= arcDef.a1; a -= 4) {
      let pt = polarPt(294, a);
      brush.vertex(pt[0], pt[1]);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 3. Glossy glaze sheen strokes & crisp pure-white specular glints
  brush.set("glaze_sheen", "#ffffff", 1.1);
  for (let arcDef of cavettoArcs) {
    let pts = [];
    for (let a = arcDef.a1 + 3; a <= arcDef.a2 - 3; a += 4) {
      pts.push(polarPt(304, a));
    }
    brush.spline(pts, 0.45);
  }

  // Sharp specular ridge along the cavetto lip & top-left rim scallops
  brush.set("rotring", "#ffffff", 0.65);
  for (let arcDef of cavettoArcs) {
    let pts = [];
    for (let a = arcDef.a1 + 5; a <= arcDef.a2 - 5; a += 3) {
      pts.push(polarPt(303, a));
    }
    brush.spline(pts, 0.45);
  }

  // Top-left rim flange wet-glaze highlights following the 12-lobed ripples
  for (let a = 185; a <= 268; a += 2.5) {
    if (abs(a - 207.5) < 9.5) continue;
    let rHi = 335 + 14 * sin(a * 6);
    let p1 = polarPt(rHi, a);
    let p2 = polarPt(rHi + 18, a + 1.8);
    brush.set("2H", "#ffffff", 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);
  }

  // Tiny pinprick glaze micro-highlights catching morning light on the transferware relief
  brush.set("rotring", "#ffffff", 0.45);
  for (let i = 0; i < 45; i++) {
    let a = random(185, 265);
    if (abs(a - 207.5) < 10) continue;
    let r = random(330, 442);
    let pt = polarPt(r, a);
    brush.circle(pt[0], pt[1], random(0.8, 2.0), 0.15);
  }
}

// Hyperreal Screenprint of a Crushed Aluminium Soda Can on Asphalt
// Built as multi-plate serigraph layers with misregistration, coarse spray halftones,
// torn enamel, pooled reflections, and squeegee drag marks.

const PAL = {
  PAPER: "#F6ECD9",       // Warm sunlit vintage screenprint stock
  PAPER_HI: "#FFFDF6",    // Blinding noon specular white / raw paper knockout
  ASPHALT_TAN: "#EAD8B8", // Warm sun-baked tarmac undertone
  YELLOW: "#FFD400",      // Process Yellow plate
  AMBER: "#FF9A00",       // Warm golden-amber halftone overprint
  PINK: "#FF1268",        // Fluorescent Pink plate
  VERMILION: "#FF3D14",   // Fiery Pop Vermilion (Pink over Yellow overprint)
  CYAN: "#00C8FF",        // Electric Cyan plate (misregistered)
  PLUM: "#390A2E",        // Deep Violet-Plum overprint (Pink + Cyan + Black)
  BLACK: "#120E15"        // Dense Carbon Black key plate
};

// Screenprint plate registration offsets (in canvas pixels)
// Cyan plate sits noticeably out of registration, leaving raw paper slivers & neon fringes
const REG = {
  YELLOW: { x: 0, y: 0 },
  CYAN:   { x: 13, y: -9 },
  PINK:   { x: -5, y: 4 },
  VERM:   { x: -2, y: 2 },
  PLUM:   { x: 4, y: -3 },
  BLACK:  { x: 0, y: 0 },
  WHITE:  { x: -3, y: -2 }
};

// Can central axis: from Front-Left Lid (u=0) to Back-Right Base (u=1)
const CAN_A = { x: 300, y: 652 };
const CAN_B = { x: 900, y: 442 };
const AXIS_DX = CAN_B.x - CAN_A.x; // +600
const AXIS_DY = CAN_B.y - CAN_A.y; // -210
const AXIS_LEN = Math.hypot(AXIS_DX, AXIS_DY); // ~635.6
const UX = AXIS_DX / AXIS_LEN;     // +0.944
const UY = AXIS_DY / AXIS_LEN;     // -0.330
const VX = -UY;                    // +0.330 (points down-right)
const VY = UX;                     // +0.944

// Maps axial parameter u (0..1) and perpendicular offset v (px) to canvas (x, y)
function canPt(u, v, ox = 0, oy = 0) {
  return [
    CAN_A.x + u * AXIS_DX + v * VX + ox,
    CAN_A.y + u * AXIS_DY + v * VY + oy
  ];
}

// Helper for elliptical lid/base points
function lidPt(uCenter, vCenter, rx, ry, tiltDeg, angDeg, ox = 0, oy = 0) {
  let c = canPt(uCenter, vCenter);
  let rad = (angDeg * Math.PI) / 180;
  let tilt = (tiltDeg * Math.PI) / 180;
  let lx = Math.cos(rad) * rx;
  let ly = Math.sin(rad) * ry;
  let rxRot = lx * Math.cos(tilt) - ly * Math.sin(tilt);
  let ryRot = lx * Math.sin(tilt) + ly * Math.cos(tilt);
  return [c[0] + rxRot + ox, c[1] + ryRot + oy];
}

