// Draws a batch of polygons as a flat opaque screenprint layer
function drawScreenPlate(polyList, col, washAlpha = 238, reg = { x: 0, y: 0 }, hatchDist = 4.6, hatchAng = 25, strokeW = 0.65) {
  if (!polyList || polyList.length === 0) return;

  // 1. Flat screenprint wash pass (batched by color)
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.wash(col, washAlpha);
  for (let p of polyList) {
    let pts = p.pts || p;
    let curv = p.curv !== undefined ? p.curv : 0.06;
    if (pts.length < 3) continue;
    brush.beginShape(curv);
    for (let v of pts) {
      brush.vertex(v[0] + reg.x, v[1] + reg.y);
    }
    brush.endShape(true);
  }
  brush.noWash();

  // 2. Opaque silkscreen ink deposit (dense marker hatch + crisp edge contour)
  if (hatchDist > 0) {
    brush.hatchStyle("screen_ink", col, 0.95);
    brush.hatch(hatchDist, hatchAng, { rand: 0.015 });
  } else {
    brush.noHatch();
  }

  if (strokeW > 0) {
    brush.set("screen_ink", col, strokeW);
  } else {
    brush.noStroke();
  }

  for (let p of polyList) {
    let pts = p.pts || p;
    let curv = p.curv !== undefined ? p.curv : 0.06;
    if (pts.length < 3) continue;
    brush.beginShape(curv);
    for (let v of pts) {
      brush.vertex(v[0] + reg.x, v[1] + reg.y);
    }
    brush.endShape(true);
  }

  brush.noHatch();
  brush.noStroke();
}

// Draws coarse spray halftone bands between two curves or along a path
function sprayBand(ptA, ptB, brushName, col, weight, passes = 2, reg = { x: 0, y: 0 }) {
  brush.set(brushName, col, weight);
  for (let i = 0; i < passes; i++) {
    let jx = random(-4, 4);
    let jy = random(-4, 4);
    brush.line(
      ptA[0] + reg.x + jx,
      ptA[1] + reg.y + jy,
      ptB[0] + reg.x - jx,
      ptB[1] + reg.y - jy
    );
  }
}

// Draws structured silkscreen halftone dot rows inside a rectangular/quadrilateral zone
function drawHalftoneGrid(p00, p10, p11, p01, rows, cols, col, reg = { x: 0, y: 0 }, maxW = 1.25, minW = 0.35) {
  brush.set("halftone_dot", col, maxW);
  for (let r = 0; r <= rows; r++) {
    let ty = r / Math.max(1, rows);
    let w = lerp(maxW, minW, ty);
    brush.strokeWeight(w);
    let sx = lerp(p00[0], p01[0], ty) + reg.x;
    let sy = lerp(p00[1], p01[1], ty) + reg.y;
    let ex = lerp(p10[0], p11[0], ty) + reg.x;
    let ey = lerp(p10[1], p11[1], ty) + reg.y;
    brush.line(sx, sy, ex, ey);
  }
}

function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();

  // Initialize default brush immediately
  brush.set("screen_ink", PAL.BLACK, 1);

  // =========================================================================
  // 0. WARM PAPER STOCK & SCREENPRINT FRAME UNDERBASE
  // =========================================================================
  background(PAL.PAPER);

  // Warm sunlit tarmac paper wash within the silkscreen frame (78..1122)
  let framePolys = [
    {
      pts: [[82, 84], [1118, 78], [1124, 1116], [76, 1122]],
      curv: 0.01
    }
  ];
  drawScreenPlate(framePolys, PAL.ASPHALT_TAN, 145, { x: 0, y: 0 }, 0, 0, 0);

  // Warm sunlit pavement zones (lighter upper-left noon hotspot, warmer lower-right)
  let warmGroundPolys = [
    {
      pts: [[78, 82], [860, 80], [640, 440], [80, 620]],
      curv: 0.08
    },
    {
      pts: [[140, 740], [1120, 490], [1122, 1118], [78, 1120]],
      curv: 0.05
    }
  ];
  drawScreenPlate([warmGroundPolys[0]], PAL.PAPER_HI, 165, { x: 0, y: 0 }, 0, 0, 0);

  // =========================================================================
  // 1. ASPHALT TARMAC TEXTURE, HALFTONE GRADIENTS & AGGREGATE GRIT
  // =========================================================================
  drawAsphaltBackground();

  // =========================================================================
  // 2. HARD NOON CAST SHADOW & SPILLED SODA REFLECTION POOL (MULTI-PLATE)
  // =========================================================================
  drawShadowAndSodaPool();

  // =========================================================================
  // 3. THE CRUSHED ALUMINIUM CAN — SEPARATED SCREENPRINT PLATES
  // =========================================================================
  drawCrushedCanPlates();

  // =========================================================================
  // 4. FRONT LID, COUNTERSINK RIM, DRINK HOLE, PULL-TAB & REAR BASE
  // =========================================================================
  drawCanEndsHyperreal();

  // =========================================================================
  // 5. TORN INK SHARDS, COARSE SPRAY HALFTONES & SPECULAR NOON POOLS
  // =========================================================================
  drawTornInkAndReflections();

  // =========================================================================
  // 6. SQUEEGEE DRAG STREAKS, REGISTRATION MARKS & PRINT MARGIN INCIDENTS
  // =========================================================================
  drawSqueegeeAndRegistration();

  noLoop();
}

// ===========================================================================
// SECTION 1: ASPHALT BACKGROUND & GRITTY PAVEMENT PLATES
// ===========================================================================
function drawAsphaltBackground() {
  // Large warm yellow screenprint undertones across the sun-baked asphalt
  let yellowAsphalt = [
    { pts: [[84, 540], [420, 460], [620, 560], [280, 820], [82, 790]], curv: 0.1 },
    { pts: [[680, 260], [1118, 210], [1120, 580], [790, 540]], curv: 0.1 },
    { pts: [[480, 820], [1080, 680], [1118, 980], [560, 1080]], curv: 0.08 }
  ];
  drawScreenPlate(yellowAsphalt, PAL.YELLOW, 150, REG.YELLOW, 12, -18, 0);

  // Coarse halftone spray bands in Yellow, Cyan (shifted), and Pink on the asphalt
  for (let i = 0; i < 18; i++) {
    let y = map(i, 0, 17, 130, 1090);
    let x1 = random(85, 320);
    let x2 = random(880, 1115);
    sprayBand([x1, y], [x2, y - random(-35, 35)], "halftone_coarse", PAL.YELLOW, random(1.1, 2.2), 1, REG.YELLOW);
    if (i % 2 === 0) {
      sprayBand([x1 + 60, y + 15], [x2 - 40, y - 20], "halftone_coarse", PAL.PINK, random(0.7, 1.4), 1, REG.PINK);
    }
    if (i % 3 === 0) {
      sprayBand([x1 + 30, y - 10], [x2 - 80, y + 25], "halftone_coarse", PAL.CYAN, random(0.65, 1.3), 1, REG.CYAN);
    }
  }

  // Structured silkscreen halftone dot matrices in shadow-transition zones on tarmac
  drawHalftoneGrid([110, 760], [520, 690], [560, 1060], [110, 1080], 24, 24, PAL.PINK, REG.PINK, 1.05, 0.3);
  drawHalftoneGrid([620, 580], [1095, 470], [1105, 920], [670, 990], 26, 26, PAL.CYAN, REG.CYAN, 1.1, 0.25);
  drawHalftoneGrid([580, 640], [1080, 540], [1090, 880], [640, 950], 22, 22, PAL.BLACK, REG.BLACK, 1.15, 0.25);
  drawHalftoneGrid([120, 210], [540, 140], [490, 420], [110, 480], 16, 16, PAL.YELLOW, REG.YELLOW, 1.2, 0.35);

  // Diagonal sun-softened tar crack across the asphalt (Cyan fringe + Pink fringe + Black core)
  let crackPts = [
    [92, 338], [168, 355], [245, 344], [335, 378], [412, 392],
    [485, 430], [785, 695], [875, 735], [945, 792], [1035, 815], [1118, 862]
  ];
  let crackPoly = [];
  for (let p of crackPts) crackPoly.push([p[0], p[1] - 4]);
  for (let i = crackPts.length - 1; i >= 0; i--) {
    crackPoly.push([crackPts[i][0] + 3, crackPts[i][1] + 6]);
  }
  drawScreenPlate([{ pts: crackPoly, curv: 0.1 }], PAL.CYAN, 210, REG.CYAN, 0, 0, 0.6);
  drawScreenPlate([{ pts: crackPoly, curv: 0.1 }], PAL.PINK, 210, REG.PINK, 0, 0, 0.6);
  drawScreenPlate([{ pts: crackPoly, curv: 0.1 }], PAL.BLACK, 245, REG.BLACK, 4, 15, 0.8);

  // Secondary branching tarmac fissure in upper-right
  let crack2 = [
    [760, 84], [790, 155], [775, 225], [820, 295], [805, 365], [845, 420]
  ];
  brush.set("screen_fine", PAL.CYAN, 1.6);
  for (let i = 0; i < crack2.length - 1; i++) {
    brush.line(
      crack2[i][0] + REG.CYAN.x, crack2[i][1] + REG.CYAN.y,
      crack2[i + 1][0] + REG.CYAN.x, crack2[i + 1][1] + REG.CYAN.y
    );
  }
  brush.set("screen_fine", PAL.BLACK, 2.1);
  for (let i = 0; i < crack2.length - 1; i++) {
    brush.line(crack2[i][0], crack2[i][1], crack2[i + 1][0], crack2[i + 1][1]);
  }

  // Generate 320 hyperreal angular asphalt aggregate stones batched by plate!
  let aggYellow = [];
  let aggCyan = [];
  let aggPink = [];
  let aggBlack = [];
  let aggWhite = [];

  for (let i = 0; i < 320; i++) {
    // Cluster stones more densely around the can & foreground shadow (y: 350..1060)
    let u = random();
    let gx = random(92, 1108);
    let gy = u < 0.68 ? random(380, 1040) : random(95, 1095);
    let distToCan = Math.abs((gy - 580) * 0.8 + (gx - 600) * 0.28);
    let sz = map(constrain(distToCan, 0, 500), 0, 500, random(5, 16), random(3, 9));
    // Perspective compression on ground plane
    let rx = sz * random(0.9, 1.45);
    let ry = sz * random(0.5, 0.85);
    let sides = int(random(4, 7));
    let stonePts = [];
    for (let s = 0; s < sides; s++) {
      let a = (s / sides) * 360 + random(-18, 18);
      stonePts.push([
        gx + cos(a) * rx,
        gy + sin(a) * ry
      ]);
    }
    // Sharp noon shadow facet for each aggregate pebble (offset down-right)
    let shadowPts = stonePts.map(pt => [pt[0] + sz * 0.45, pt[1] + sz * 0.55]);
    aggBlack.push({ pts: shadowPts, curv: 0 });

    let rPick = random();
    if (rPick < 0.34) {
      aggYellow.push({ pts: stonePts, curv: 0 });
    } else if (rPick < 0.62) {
      aggCyan.push({ pts: stonePts, curv: 0 });
    } else if (rPick < 0.85) {
      aggPink.push({ pts: stonePts, curv: 0 });
    } else {
      aggWhite.push({ pts: stonePts, curv: 0 });
    }
  }

  drawScreenPlate(aggYellow, PAL.YELLOW, 235, REG.YELLOW, 0, 0, 0.4);
  drawScreenPlate(aggCyan, PAL.CYAN, 225, REG.CYAN, 0, 0, 0.4);
  drawScreenPlate(aggPink, PAL.PINK, 225, REG.PINK, 0, 0, 0.4);
  drawScreenPlate(aggBlack, PAL.BLACK, 245, REG.BLACK, 0, 0, 0.45);
  drawScreenPlate(aggWhite, PAL.PAPER_HI, 250, REG.WHITE, 0, 0, 0.5);

  // Coarse black screenprint stipple across lower-right & mid-ground tarmac
  for (let i = 0; i < 24; i++) {
    let sx = random(120, 1080);
    let sy = random(420, 1080);
    sprayBand([sx, sy], [sx + random(-140, 140), sy + random(-50, 50)], "halftone_tight", PAL.BLACK, random(0.8, 1.65), 1, REG.BLACK);
  }
}

// ===========================================================================
