  let lidV = -2;
  let tilt = -19;

  // Build elliptical ring polygons for the double-seamed aluminium lid
  let outerRimPts = [];
  let countersinkOuter = [];
  let countersinkInner = [];
  let innerPlatePts = [];

  for (let a = 0; a < 360; a += 12) {
    // Slight flattening at bottom-right (a ~ 20..110) where can was stomped
    let crushMod = (a > 15 && a < 115) ? 0.88 : 1.0;
    let dentMod  = (a > 240 && a < 320) ? 0.93 : 1.0;
    let rScale = crushMod * dentMod;

    outerRimPts.push(lidPt(lidU, lidV, 88 * rScale, 150 * rScale, tilt, a));
    countersinkOuter.push(lidPt(lidU, lidV, 76 * rScale, 134 * rScale, tilt, a));
    countersinkInner.push(lidPt(lidU, lidV, 67 * rScale, 120 * rScale, tilt, a));
    innerPlatePts.push(lidPt(lidU, lidV, 62 * rScale, 112 * rScale, tilt, a));
  }

  // 1. Misregistered Electric Cyan lid plate (creates vibrant cyan chrome fringe on left/top rim)
  drawScreenPlate([{ pts: outerRimPts, curv: 0.15 }], PAL.CYAN, 242, REG.CYAN, 4.2, -25, 0.8);

  // 2. Process Yellow metallic reflection sectors on the lid
  drawScreenPlate([{ pts: countersinkOuter, curv: 0.15 }], PAL.YELLOW, 238, REG.YELLOW, 4.4, 20, 0.7);

  // 3. Fluorescent Pink reflected body glow inside the recessed countersink wall
  let pinkLidCrescent = [];
  for (let a = -60; a <= 130; a += 12) {
    pinkLidCrescent.push(lidPt(lidU, lidV, 76, 134, tilt, a));
  }
  for (let a = 130; a >= -60; a -= 12) {
    pinkLidCrescent.push(lidPt(lidU, lidV, 64, 115, tilt, a));
  }
  drawScreenPlate([{ pts: pinkLidCrescent, curv: 0.12 }], PAL.PINK, 238, REG.PINK, 4.0, 45, 0.65);

  // 4. Inner Aluminium Lid Plate — Divided into buckled metallic reflection facets
  let lidSectorCyan = [];
  for (let a = 140; a <= 310; a += 15) lidSectorCyan.push(lidPt(lidU, lidV, 62, 112, tilt, a));
  lidSectorCyan.push(lidPt(lidU, lidV, 4, 4, tilt, 0));

  let lidSectorWhite = [];
  for (let a = 200; a <= 285; a += 12) lidSectorWhite.push(lidPt(lidU, lidV, 62, 112, tilt, a));
  lidSectorWhite.push(lidPt(lidU, lidV, 0, 0, tilt, 0));

  let lidSectorYellow = [];
  for (let a = 285; a <= 395; a += 15) lidSectorYellow.push(lidPt(lidU, lidV, 60, 108, tilt, a));
  lidSectorYellow.push(lidPt(lidU, lidV, 0, 0, tilt, 0));

  drawScreenPlate([{ pts: lidSectorCyan, curv: 0.08 }], PAL.CYAN, 238, { x: 4, y: -3 }, 4.2, 15, 0.65);
  drawScreenPlate([{ pts: lidSectorYellow, curv: 0.08 }], PAL.YELLOW, 240, REG.YELLOW, 4.2, -20, 0.65);
  drawScreenPlate([{ pts: lidSectorWhite, curv: 0.08 }], PAL.PAPER_HI, 252, REG.WHITE, 3.6, 30, 0.75);

  // 5. Deep Black Countersink Groove & Rim Shadow Arcs
  let blackGroove1 = [];
  for (let a = 110; a <= 290; a += 12) blackGroove1.push(lidPt(lidU, lidV, 77, 135, tilt, a));
  for (let a = 290; a >= 110; a -= 12) blackGroove1.push(lidPt(lidU, lidV, 68, 120, tilt, a));

  let blackGroove2 = [];
  for (let a = -50; a <= 95; a += 12) blackGroove2.push(lidPt(lidU, lidV, 88, 150, tilt, a));
  for (let a = 95; a >= -50; a -= 12) blackGroove2.push(lidPt(lidU, lidV, 78, 136, tilt, a));

  drawScreenPlate(
    [{ pts: blackGroove1, curv: 0.12 }, { pts: blackGroove2, curv: 0.12 }],
    PAL.BLACK, 250, REG.BLACK, 3.6, -35, 0.85
  );

  // Blinding Noon Highlight Arc along the outer double-seamed chime rim (upper-left arc)
  let rimHighlightArc = [];
  for (let a = 155; a <= 285; a += 10) rimHighlightArc.push(lidPt(lidU, lidV, 88, 150, tilt, a));
  for (let a = 285; a >= 155; a -= 10) rimHighlightArc.push(lidPt(lidU, lidV, 78, 135, tilt, a));
  drawScreenPlate([{ pts: rimHighlightArc, curv: 0.12 }], PAL.PAPER_HI, 255, REG.WHITE, 3.2, 25, 0.9);

  // -------------------------------------------------------------------------
  // B. PUNCHED-IN DRINK OPENING (DARK MOUTH) & SUBMERGED SCORED FLAP
  // -------------------------------------------------------------------------
  // Located in the lower half of the lid (ang ~ 25..155 deg)
  let mouthPts = [
    lidPt(lidU, lidV, 16, 26, tilt, 35),
    lidPt(lidU, lidV, 48, 84, tilt, 42),
    lidPt(lidU, lidV, 55, 96, tilt, 78),
    lidPt(lidU, lidV, 52, 92, tilt, 118),
    lidPt(lidU, lidV, 42, 74, tilt, 148),
    lidPt(lidU, lidV, 14, 24, tilt, 135)
  ];

  // Cyan & Pink misregistered rim around the punched-in drink opening
  drawScreenPlate([{ pts: mouthPts, curv: 0.18 }], PAL.CYAN, 240, { x: 6, y: -5 }, 3.8, 0, 0.7);
  drawScreenPlate([{ pts: mouthPts, curv: 0.18 }], PAL.PINK, 235, REG.PINK, 3.8, 0, 0.7);

  // Pitch-black interior of the open soda can mouth
  drawScreenPlate([{ pts: mouthPts, curv: 0.18 }], PAL.BLACK, 255, REG.BLACK, 3.2, 45, 0.95);

  // Folded-down scored aluminium tear panel glinting inside the dark mouth
  let submergedFlap = [
    lidPt(lidU, lidV, 18, 30, tilt, 55),
    lidPt(lidU, lidV, 38, 66, tilt, 65),
    lidPt(lidU, lidV, 34, 60, tilt, 108),
    lidPt(lidU, lidV, 16, 28, tilt, 115)
  ];
  drawScreenPlate([{ pts: submergedFlap, curv: 0.12 }], PAL.PLUM, 240, REG.BLACK, 3.8, 15, 0.6);
  let flapGlint = [
    lidPt(lidU, lidV, 22, 38, tilt, 62),
    lidPt(lidU, lidV, 35, 62, tilt, 72),
    lidPt(lidU, lidV, 31, 55, tilt, 88)
  ];
  drawScreenPlate([{ pts: flapGlint, curv: 0.1 }], PAL.CYAN, 245, { x: 2, y: -2 }, 3.5, 15, 0.7);

  // Crisp raw-paper metallic lip highlight around the upper rim of the drink hole
  let mouthRimHi = [
    lidPt(lidU, lidV, 49, 86, tilt, 45),
    lidPt(lidU, lidV, 57, 99, tilt, 80),
    lidPt(lidU, lidV, 53, 94, tilt, 118),
    lidPt(lidU, lidV, 50, 88, tilt, 80)
  ];
  drawScreenPlate([{ pts: mouthRimHi, curv: 0.15 }], PAL.PAPER_HI, 255, REG.WHITE, 3.0, 0, 0.85);

  // -------------------------------------------------------------------------
  // C. STAY-ON ALUMINIUM PULL-TAB (RIVETED AT CENTER, POINTING UPPER-RIGHT)
  // -------------------------------------------------------------------------
  let tabOuter = [
    lidPt(lidU, lidV, 14, 22, tilt, 75),
    lidPt(lidU, lidV, 16, 25, tilt, 165),
    lidPt(lidU, lidV, 44, 76, tilt, 228),
    lidPt(lidU, lidV, 50, 86, tilt, 255),
    lidPt(lidU, lidV, 44, 76, tilt, 285),
    lidPt(lidU, lidV, 16, 25, tilt, 345)
  ];
  let tabHole = [
    lidPt(lidU, lidV, 20, 34, tilt, 232),
    lidPt(lidU, lidV, 38, 65, tilt, 242),
    lidPt(lidU, lidV, 42, 72, tilt, 256),
    lidPt(lidU, lidV, 38, 65, tilt, 272),
    lidPt(lidU, lidV, 20, 34, tilt, 280)
  ];

  // Cast shadow of the pull-tab onto the lid plate
  drawScreenPlate([{ pts: tabOuter, curv: 0.18 }], PAL.BLACK, 250, { x: 6, y: 8 }, 3.6, 30, 0.8);
  // Misregistered Cyan pull-tab bevel
  drawScreenPlate([{ pts: tabOuter, curv: 0.18 }], PAL.CYAN, 245, { x: 6, y: -5 }, 3.6, -20, 0.75);
  // Bright Raw Paper White pull-tab body
  drawScreenPlate([{ pts: tabOuter, curv: 0.18 }], PAL.PAPER_HI, 255, REG.WHITE, 3.2, 15, 0.9);
  // Finger hole cutout inside the pull-tab (shows dark/cyan lid underneath)
  drawScreenPlate([{ pts: tabHole, curv: 0.2 }], PAL.BLACK, 248, { x: 2, y: 3 }, 3.5, 45, 0.75);
  drawScreenPlate([{ pts: tabHole, curv: 0.2 }], PAL.CYAN, 235, { x: -2, y: -2 }, 3.8, -15, 0.65);

  // Central Rivet Button of the pull-tab
  let rivetCenter = lidPt(lidU, lidV, 2, 2, tilt, 0);
  let rivetPts = [];
  for (let a = 0; a < 360; a += 30) {
    rivetPts.push([rivetCenter[0] + cos(a) * 8, rivetCenter[1] + sin(a) * 10]);
  }
  drawScreenPlate([{ pts: rivetPts, curv: 0.25 }], PAL.BLACK, 250, { x: 3, y: 3 }, 3.2, 0, 0.8);
  drawScreenPlate([{ pts: rivetPts, curv: 0.25 }], PAL.PAPER_HI, 255, REG.WHITE, 3.0, 0, 0.85);

  // -------------------------------------------------------------------------
  // D. REAR-RIGHT BASE RIM & CONCAVE SILVER DOME (Near u=0.95)
  // -------------------------------------------------------------------------
  let baseU = 0.945;
  let baseV = -4;
  let baseTilt = -15;

  let baseBevelPts = [];
  let baseRimPts = [];
  let baseDomeShadow = [];

  for (let a = -105; a <= 105; a += 12) {
    baseBevelPts.push(lidPt(baseU - 0.025, baseV, 68, 134, baseTilt, a));
  }
  for (let a = 105; a >= -105; a -= 12) {
    baseBevelPts.push(lidPt(baseU, baseV, 58, 120, baseTilt, a));
  }

  for (let a = -105; a <= 105; a += 12) {
    baseRimPts.push(lidPt(baseU, baseV, 58, 120, baseTilt, a));
  }
  for (let a = 105; a >= -105; a -= 12) {
    baseRimPts.push(lidPt(baseU + 0.022, baseV, 50, 108, baseTilt, a));
  }

  for (let a = -88; a <= 88; a += 15) {
    baseDomeShadow.push(lidPt(baseU + 0.015, baseV, 48, 104, baseTilt, a));
  }
  for (let a = 88; a >= -88; a -= 15) {
    baseDomeShadow.push(lidPt(baseU - 0.005, baseV, 26, 78, baseTilt, a));
  }

  drawScreenPlate([{ pts: baseBevelPts, curv: 0.12 }], PAL.CYAN, 240, REG.CYAN, 4.0, 25, 0.75);
  drawScreenPlate([{ pts: baseBevelPts, curv: 0.12 }], PAL.YELLOW, 235, REG.YELLOW, 4.2, -15, 0.65);
  drawScreenPlate([{ pts: baseDomeShadow, curv: 0.15 }], PAL.BLACK, 250, REG.BLACK, 3.6, 40, 0.85);
  drawScreenPlate([{ pts: baseRimPts, curv: 0.12 }], PAL.PAPER_HI, 255, REG.WHITE, 3.2, -20, 0.9);
}

// ===========================================================================
// SECTION 5: TORN INK SHARDS, POOLED METAL REFLECTIONS & HALFTONE GRADIENTS
// ===========================================================================
function drawTornInkAndReflections() {
  // 1. COARSE SPRAY HALFTONE GRADIENTS across the curved facets of the can
  // Halftones turn flat screenprint shapes into hyperreal 3D metallic form
  sprayBand(canPt(0.08, -115), canPt(0.38, -95), "halftone_tight", PAL.YELLOW, 1.4, 2, REG.YELLOW);
  sprayBand(canPt(0.62, -108), canPt(0.90, -112), "halftone_tight", PAL.YELLOW, 1.4, 2, REG.YELLOW);

  sprayBand(canPt(0.12, -35), canPt(0.32, -55), "halftone_tight", PAL.PINK, 1.35, 2, REG.PINK);
  sprayBand(canPt(0.45, 28), canPt(0.72, -18), "halftone_tight", PAL.PINK, 1.4, 2, REG.PINK);
  sprayBand(canPt(0.62, -48), canPt(0.88, -42), "halftone_tight", PAL.VERMILION, 1.3, 2, REG.VERM);

  sprayBand(canPt(0.34, -45), canPt(0.58, -22), "halftone_tight", PAL.CYAN, 1.5, 2, REG.CYAN);
  sprayBand(canPt(0.14, 118), canPt(0.84, 118), "halftone_tight", PAL.BLACK, 1.55, 2, REG.BLACK);
  sprayBand(canPt(0.34, -28), canPt(0.56, 8), "halftone_tight", PAL.BLACK, 1.4, 2, REG.BLACK);

  // Structured halftone dot rows inside the central concave dent & right cylinder curve
  drawHalftoneGrid(
    canPt(0.33, -58), canPt(0.58, -48), canPt(0.56, 14), canPt(0.35, -4),
    12, 12, PAL.BLACK, REG.BLACK, 1.0, 0.3
  );
  drawHalftoneGrid(
    canPt(0.64, -96), canPt(0.90, -100), canPt(0.91, -52), canPt(0.65, -48),
    10, 12, PAL.YELLOW, REG.YELLOW, 1.05, 0.3
  );
  drawHalftoneGrid(
    canPt(0.10, 88), canPt(0.36, 48), canPt(0.42, 112), canPt(0.14, 132),
    11, 11, PAL.BLACK, REG.BLACK, 1.05, 0.35
  );

  // 2. POOLED METALLIC REFLECTIONS inside the concave dents of the can!
  // Concentric liquid-like specular rings in Cyan, Yellow, Pink, and Blinding White
  let dentPool1_Cyan = [
    canPt(0.38, -44), canPt(0.49, -54), canPt(0.54, -32), canPt(0.47, -14), canPt(0.39, -22)
  ];
  let dentPool1_White = [
    canPt(0.41, -40), canPt(0.48, -46), canPt(0.51, -32), canPt(0.45, -22)
  ];

  let dentPool2_Cyan = [
    canPt(0.65, -34), canPt(0.76, -52), canPt(0.81, -26), canPt(0.70, -8)
  ];
  let dentPool2_White = [
    canPt(0.68, -32), canPt(0.75, -44), canPt(0.78, -26), canPt(0.71, -16)
  ];

  let dentPool3_Yellow = [
    canPt(0.20, -48), canPt(0.29, -64), canPt(0.32, -32), canPt(0.22, -16)
  ];
  let dentPool3_White = [
    canPt(0.23, -46), canPt(0.28, -56), canPt(0.30, -34), canPt(0.24, -24)
  ];

  drawScreenPlate([{ pts: dentPool1_Cyan, curv: 0.25 }, { pts: dentPool2_Cyan, curv: 0.25 }], PAL.CYAN, 248, REG.CYAN, 3.6, 15, 0.75);
  drawScreenPlate([{ pts: dentPool3_Yellow, curv: 0.25 }], PAL.YELLOW, 248, REG.YELLOW, 3.6, -15, 0.75);
  drawScreenPlate(
    [
      { pts: dentPool1_White, curv: 0.25 },
      { pts: dentPool2_White, curv: 0.25 },
      { pts: dentPool3_White, curv: 0.25 }
    ],
    PAL.PAPER_HI, 255, REG.WHITE, 3.0, 20, 0.85
  );

  // 3. TORN INK & ABRADED ENAMEL ALONG THE SHARP BUCKLE RIDGES!
  // Where extreme metal folding cracked the pink/red screenprint ink, exposing raw silver/cyan aluminium
  let tornInkShards = [
    // Jagged torn-ink strip along Primary Ridge 1 (u ~ 0.24..0.35)
    { pts: [canPt(0.23, -138), canPt(0.26, -134), canPt(0.32, -84), canPt(0.35, -44), canPt(0.32, -40), canPt(0.28, -88)], curv: 0.01 },
    // Jagged torn-ink lightning ridge across the central stomp buckle (u ~ 0.41..0.59)
    { pts: [canPt(0.40, -116), canPt(0.43, -110), canPt(0.48, -62), canPt(0.60, -46), canPt(0.58, -36), canPt(0.45, -56)], curv: 0.01 },
    // Transverse pinch tear cutting right through the middle of the "O" and wave ribbon
    { pts: [canPt(0.34, -14), canPt(0.45, 18), canPt(0.59, 42), canPt(0.57, 50), canPt(0.43, 26), canPt(0.32, -6)], curv: 0.01 },
    // Right shoulder buckle ridge abrasion
    { pts: [canPt(0.61, -98), canPt(0.64, -92), canPt(0.63, -44), canPt(0.76, -18), canPt(0.73, -10), canPt(0.60, -40)], curv: 0.01 },
    // Upper crest noon specular sliver (raw paper knockout along top edge of can)
    { pts: [canPt(0.06, -140), canPt(0.25, -144), canPt(0.40, -118), canPt(0.24, -134), canPt(0.06, -130)], curv: 0.02 },
    { pts: [canPt(0.68, -130), canPt(0.92, -136), canPt(0.92, -124), canPt(0.69, -120)], curv: 0.02 },
    // Scraped lower belly crease ridges where asphalt abraded the paint
    { pts: [canPt(0.16, 118), canPt(0.36, 102), canPt(0.44, 122), canPt(0.35, 110), canPt(0.17, 126)], curv: 0.01 },
    { pts: [canPt(0.54, 114), canPt(0.74, 92), canPt(0.85, 112), canPt(0.73, 100), canPt(0.55, 122)], curv: 0.01 }
  ];

  // Print the torn-ink shards first in misregistered Electric Cyan, then in razor-sharp Raw Paper White
  drawScreenPlate(tornInkShards, PAL.CYAN, 245, { x: 8, y: -6 }, 3.4, 30, 0.7);
  drawScreenPlate(tornInkShards, PAL.PAPER_HI, 255, REG.WHITE, 3.0, -15, 0.9);

  // Fine black serigraph scratch lines & flaking ink contours along the torn ridges
  brush.set("screen_fine", PAL.BLACK, 1.35);
  for (let shard of tornInkShards) {
    let pts = shard.pts;
    for (let i = 0; i < pts.length - 1; i++) {
      brush.line(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1]);
    }
  }

  // Tiny scattered paint flakes / chipped enamel specks around the sharpest folds
  let flakesPink = [];
  let flakesCyan = [];
  let flakesBlack = [];
  let foldCenters = [
    canPt(0.29, -78), canPt(0.46, -58), canPt(0.45, 22),
    canPt(0.63, -44), canPt(0.35, 108), canPt(0.68, 98)
  ];
  for (let fc of foldCenters) {
    for (let k = 0; k < 10; k++) {
      let fx = fc[0] + random(-32, 32);
      let fy = fc[1] + random(-24, 24);
      let s = random(2.5, 6.5);
      let tri = [[fx, fy], [fx + s, fy - s * 0.4], [fx + s * 0.3, fy + s * 0.8]];
      if (k % 3 === 0) flakesPink.push({ pts: tri, curv: 0 });
      else if (k % 3 === 1) flakesCyan.push({ pts: tri, curv: 0 });
      else flakesBlack.push({ pts: tri, curv: 0 });
    }
  }
  drawScreenPlate(flakesPink, PAL.PINK, 245, REG.PINK, 0, 0, 0.5);
  drawScreenPlate(flakesCyan, PAL.CYAN, 245, REG.CYAN, 0, 0, 0.5);
  drawScreenPlate(flakesBlack, PAL.BLACK, 250, REG.BLACK, 0, 0, 0.55);
}

// ===========================================================================
// SECTION 6: SQUEEGEE DRAG STREAKS, REGISTRATION TARGETS & COLOR BARS
// ===========================================================================
function drawSqueegeeAndRegistration() {
  // 1. SQUEEGEE DRAG MARKS (Where the silkscreen squeegee pulled dry/streaky ink past edges)
  // Pulled right from the rear base of the can & shadow onto the sunlit asphalt
  let dragLinesBlack = [
    [canPt(0.95, 120), [1142, canPt(0.95, 120)[1] - 4]],
    [canPt(0.98, 165), [1146, canPt(0.98, 165)[1] - 6]],
    [canPt(0.88, 218), [1138, canPt(0.88, 218)[1] - 3]],
    [[665, 888], [910, 882]],
    [[78, 285], [245, 282]],
    [[82, 965], [260, 960]]
  ];
  brush.set("squeegee", PAL.BLACK, 1.25);
  for (let dl of dragLinesBlack) {
    brush.line(dl[0][0], dl[0][1], dl[1][0], dl[1][1]);
  }

  // Fluorescent Pink squeegee drag smears from the upper-left and lower-right can edges
  let dragLinesPink = [
    [canPt(0.24, -142), [canPt(0.24, -142)[0] - 135, canPt(0.24, -142)[1] + 5]],
    [canPt(0.75, -132), [1138, canPt(0.75, -132)[1] - 4]],
    [[410, 955], [685, 948]],
    [[76, 612], [205, 608]]
  ];
  brush.set("squeegee", PAL.PINK, 1.15);
  for (let dl of dragLinesPink) {
    brush.line(dl[0][0] + REG.PINK.x, dl[0][1] + REG.PINK.y, dl[1][0] + REG.PINK.x, dl[1][1] + REG.PINK.y);
  }

  // Electric Cyan squeegee drag streaks (with misregistration offset!)
  let dragLinesCyan = [
    [canPt(0.04, -146), [72, canPt(0.04, -146)[1] + 4]],
    [canPt(0.92, -98), [1144, canPt(0.92, -98)[1] - 3]],
    [[545, 922], [845, 916]]
  ];
  brush.set("squeegee", PAL.CYAN, 1.15);
  for (let dl of dragLinesCyan) {
    brush.line(dl[0][0] + REG.CYAN.x, dl[0][1] + REG.CYAN.y, dl[1][0] + REG.CYAN.x, dl[1][1] + REG.CYAN.y);
  }

  // Process Yellow squeegee drag across top and bottom screen boundaries
  brush.set("squeegee", PAL.YELLOW, 1.35);
  brush.line(120, 82, 540, 78);
  brush.line(680, 1118, 1080, 1114);

  // 2. SCREENPRINT BORDER FRAME LINES (Slightly misregistered per plate!)
  let borderPlates = [
    { col: PAL.YELLOW, reg: REG.YELLOW, w: 0.9 },
    { col: PAL.CYAN,   reg: REG.CYAN,   w: 0.85 },
    { col: PAL.PINK,   reg: REG.PINK,   w: 0.85 },
    { col: PAL.BLACK,  reg: REG.BLACK,  w: 1.15 }
  ];
  for (let bp of borderPlates) {
    brush.set("screen_fine", bp.col, bp.w);
    let x0 = 78 + bp.reg.x;
    let y0 = 78 + bp.reg.y;
    let x1 = 1122 + bp.reg.x;
    let y1 = 1122 + bp.reg.y;
    brush.line(x0, y0, x1, y0);
    brush.line(x1, y0, x1, y1);
    brush.line(x1, y1, x0, y1);
    brush.line(x0, y1, x0, y0);
  }

  // 3. AUTHENTIC SILKSCREEN REGISTRATION CROSSHAIRS IN THE 4 CORNERS
  // Each plate prints its crosshair at its own registration offset, visibly showing the Cyan shift!
  let regTargets = [
    [44, 44],
    [1156, 44],
    [44, 1156],
    [1156, 1156]
  ];
  for (let rt of regTargets) {
    for (let bp of borderPlates) {
      let cx = rt[0] + bp.reg.x * 0.65;
      let cy = rt[1] + bp.reg.y * 0.65;
      brush.set("screen_fine", bp.col, 0.85);
      brush.line(cx - 16, cy, cx + 16, cy);
      brush.line(cx, cy - 16, cx, cy + 16);
      brush.circle(cx, cy, 9, 0.02);
    }
  }

  // 4. PRINTER'S COLOR SEPARATION REGISTRATION SWATCH BARS (Bottom-Right Margin)
  let swatchColors = [
    { col: PAL.YELLOW, reg: REG.YELLOW },
    { col: PAL.PINK,   reg: REG.PINK },
    { col: PAL.VERMILION, reg: REG.VERM },
    { col: PAL.CYAN,   reg: REG.CYAN },
    { col: PAL.PLUM,   reg: REG.PLUM },
    { col: PAL.BLACK,  reg: REG.BLACK }
  ];
  for (let i = 0; i < swatchColors.length; i++) {
    let sx = 820 + i * 46;
    let sy = 1138;
    let swPoly = [
      [sx, sy], [sx + 36, sy], [sx + 36, sy + 22], [sx, sy + 22]
    ];
    drawScreenPlate(
      [{ pts: swPoly, curv: 0 }],
      swatchColors[i].col,
      245,
      { x: swatchColors[i].reg.x * 0.4, y: swatchColors[i].reg.y * 0.4 },
      3.6,
      0,
      0.6
    );
  }
}

// Hyperreal Heap of Silver River Fish on a Banana Leaf (Madhubani / Mithila Document Style)
// p5.js 2.x + p5.brush (WEBGL, 1200x1200)

const W_CANVAS = 1200;
const H_CANVAS = 1200;

// Occlusion & spatial masks (1200 x 1200)
let bodyMask;       // -1 = banana leaf/ground, 0..N-1 = topmost fish index
let pectoralMask;   // fish index whose pectoral fin covers pixel
let eyeSpecMask;    // 1 = protected wet white specular reflection on fish eye

// Palette: Dusky Twilight Tones + Silver River Fish + Vermilion, Marigold, Parrot Green
const PAL = {
  ink: "#0b0e14",
  inkSoft: "#1a202c",
  twilightBg: "#161c28",
  twilightSlate: "#252f42",
  twilightPlum: "#2c283b",
  twilightPewter: "#3b485e",

  leafDark: "#182e28",
  leafMid: "#213d34",
  leafOlive: "#2a4a3e",
  leafSage: "#385c4c",
  leafRib: "#4c6e59",
  leafPale: "#698a70",

  vermilion: "#d43824",
  vermilionDark: "#9c2214",
  marigold: "#e88c1f",
  marigoldDark: "#bd6812",
  parrot: "#62ab30",
  parrotDark: "#45801e",

  dorsalDark: "#2b364a",
  dorsalSlate: "#43536b",
  flankSteel: "#677994",
  flankSilver: "#92a4bc",
  flankBright: "#b8c7d9",
  bellyPearl: "#dae3ee",
  bellyLight: "#edf3f9",
  pureWhite: "#f7fbff",
  gillRed: "#c92918",
  finAmber: "#7b8899"
};

let fishes = [];
let washBatches = {};

function addWashPoly(colorHex, opacity, pts) {
  if (!pts || pts.length < 3) return;
  const key = colorHex + "_" + opacity;
  if (!washBatches[key]) {
    washBatches[key] = { color: colorHex, opacity: opacity, polys: [] };
  }
  washBatches[key].polys.push(pts);
}

function flushWashBatches(orderKeys) {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.noFill();
  const keys = orderKeys || Object.keys(washBatches);
  for (let k of keys) {
    const batch = washBatches[k];
    if (!batch) continue;
    brush.wash(batch.color, batch.opacity);
    for (let pts of batch.polys) {
      brush.beginShape(0);
      for (let i = 0; i < pts.length; i++) {
        brush.vertex(pts[i][0], pts[i][1]);
      }
      brush.endShape(true);
    }
  }
  brush.noWash();
}

async function setup() {
  createCanvas(W_CANVAS, H_CANVAS, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(42719);

  // Register custom hyperreal pen & highlight brushes
  brush.add("finePen", {
