function draw() {
  translate(-width / 2, -height / 2);
  brush.noField();
  background(PAL.twilightBg);

  bodyMask = new Int8Array(W_CANVAS * H_CANVAS);
  bodyMask.fill(-1);
  pectoralMask = new Int8Array(W_CANVAS * H_CANVAS);
  pectoralMask.fill(-1);
  eyeSpecMask = new Uint8Array(W_CANVAS * H_CANVAS);

  // 1. Build fish geometry & populate pixel occlusion masks
  initFishHeap();

  // 2. Stage & flush background + banana leaf + border washes
  washBatches = {};
  stageBorderAndLeafWashes();
  flushWashBatches();

  // 3. Stage & flush fish washes in strict back-to-front heap order
  for (let f = 0; f < fishes.length; f++) {
    washBatches = {};
    stageSingleFishWashes(fishes[f], f);
    flushWashBatches();
  }

  // 4. Subtle watercolor glazing pass for twilight depth & wet sheen
  renderWatercolorGlazes();

  // 5. Render obsessive Madhubani double-line borders & compartments
  renderBordersPenWork();

  // 6. Render banana leaf midrib, double-line veins & kachni lamina hatching
  renderBananaLeafPenWork();

  // 7. Render loose fallen scales & water droplets on the leaf
  renderLooseScalesAndDroplets();

  // 8. Render all 12 hyperreal silver river fish (scales, gill slits, fins, wet eyes)
  for (let f = 0; f < fishes.length; f++) {
    renderSingleFishPenWork(fishes[f], f);
  }

  // 9. Final wet specular highlights & glistening mucilage streaks
  renderFinalWetHighlights();

  noLoop();
}

// ============================================================================
// GEOMETRY & MASK UTILITIES
// ============================================================================

function rasterizePoly(pts, maskArr, val) {
  if (!pts || pts.length < 3) return;
  let minY = H_CANVAS - 1, maxY = 0;
  for (let i = 0; i < pts.length; i++) {
    const y = pts[i][1];
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  minY = max(0, floor(minY));
  maxY = min(H_CANVAS - 1, ceil(maxY));

  const n = pts.length;
  let nodes = [];
  for (let y = minY; y <= maxY; y++) {
    nodes.length = 0;
    const py = y + 0.5;
    let j = n - 1;
    for (let i = 0; i < n; i++) {
      const yi = pts[i][1], yj = pts[j][1];
      if ((yi < py && yj >= py) || (yj < py && yi >= py)) {
        const xi = pts[i][0], xj = pts[j][0];
        nodes.push(xi + ((py - yi) / (yj - yi)) * (xj - xi));
      }
      j = i;
    }
    nodes.sort((a, b) => a - b);
    const rowOffset = y * W_CANVAS;
    for (let k = 0; k < nodes.length - 1; k += 2) {
      let xStart = max(0, floor(nodes[k]));
      let xEnd = min(W_CANVAS - 1, ceil(nodes[k + 1]));
      for (let x = xStart; x <= xEnd; x++) {
        maskArr[rowOffset + x] = val;
      }
    }
  }
}

function rasterizeCircle(cx, cy, r, maskArr, val) {
  const minY = max(0, floor(cy - r));
  const maxY = min(H_CANVAS - 1, ceil(cy + r));
  const r2 = r * r;
  for (let y = minY; y <= maxY; y++) {
    const dy = y - cy;
    const dxMax = sqrt(max(0, r2 - dy * dy));
    const minX = max(0, floor(cx - dxMax));
    const maxX = min(W_CANVAS - 1, ceil(cx + dxMax));
    const row = y * W_CANVAS;
    for (let x = minX; x <= maxX; x++) {
      maskArr[row + x] = val;
    }
  }
}

function isLeafVisible(x, y) {
  const ix = floor(x), iy = floor(y);
  if (ix < 116 || ix > 1084 || iy < 116 || iy > 1084) return false;
  return bodyMask[iy * W_CANVAS + ix] === -1;
}

function isFishVisible(x, y, fIdx, checkPectoral = false) {
  const ix = floor(x), iy = floor(y);
  if (ix < 24 || ix >= W_CANVAS - 24 || iy < 24 || iy >= H_CANVAS - 24) return false;
  const idx = iy * W_CANVAS + ix;
  if (eyeSpecMask[idx] === 1) return false;
  if (bodyMask[idx] !== fIdx) return false;
  if (checkPectoral && pectoralMask[idx] === fIdx) return false;
  return true;
}

function clippedLineLeaf(x1, y1, x2, y2) {
  const distXY = dist(x1, y1, x2, y2);
  if (distXY < 1) return;
  const steps = max(2, ceil(distXY / 3));
  let inSeg = false;
  let sx = 0, sy = 0;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = lerp(x1, x2, t);
    const y = lerp(y1, y2, t);
    const vis = isLeafVisible(x, y);
    if (vis && !inSeg) {
      inSeg = true;
      sx = x;
      sy = y;
    } else if (!vis && inSeg) {
      inSeg = false;
      const px = lerp(x1, x2, (i - 1) / steps);
      const py = lerp(y1, y2, (i - 1) / steps);
      if (dist(sx, sy, px, py) >= 1.2) brush.line(sx, sy, px, py);
    }
  }
  if (inSeg && dist(sx, sy, x2, y2) >= 1.2) {
    brush.line(sx, sy, x2, y2);
  }
}

function clippedLineFish(x1, y1, x2, y2, fIdx, checkPectoral = false) {
  const v1 = isFishVisible(x1, y1, fIdx, checkPectoral);
  const v2 = isFishVisible(x2, y2, fIdx, checkPectoral);
  const xm = (x1 + x2) * 0.5, ym = (y1 + y2) * 0.5;
  const vm = isFishVisible(xm, ym, fIdx, checkPectoral);
  if (v1 && v2 && vm) {
    brush.line(x1, y1, x2, y2);
    return;
  }
  if (!v1 && !v2 && !vm) return;

  const distXY = dist(x1, y1, x2, y2);
  if (distXY < 1.2) return;
  const steps = max(3, ceil(distXY / 2.5));
  let inSeg = false;
  let sx = 0, sy = 0;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = lerp(x1, x2, t);
    const y = lerp(y1, y2, t);
    const vis = isFishVisible(x, y, fIdx, checkPectoral);
    if (vis && !inSeg) {
      inSeg = true;
      sx = x;
      sy = y;
    } else if (!vis && inSeg) {
      inSeg = false;
      const px = lerp(x1, x2, (i - 1) / steps);
      const py = lerp(y1, y2, (i - 1) / steps);
      if (dist(sx, sy, px, py) >= 1.0) brush.line(sx, sy, px, py);
    }
  }
  if (inSeg && dist(sx, sy, x2, y2) >= 1.0) {
    brush.line(sx, sy, x2, y2);
  }
}

function drawPolylineFish(pts, fIdx, checkPectoral = false) {
  for (let i = 0; i < pts.length - 1; i++) {
    clippedLineFish(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], fIdx, checkPectoral);
  }
}

// ============================================================================
// FISH ANATOMY & HEAP INITIALIZATION
// ============================================================================

function dorsalProfile(u) {
  if (u <= 0) return 0;
  if (u < 0.08) return pow(u / 0.08, 0.62) * 0.44;
  if (u < 0.36) {
    const t = (u - 0.08) / 0.28;
    return 0.44 + 0.56 * sin(t * 90);
  }
  if (u <= 0.87) {
    const t = (u - 0.36) / 0.51;
    return 0.26 + 0.74 * pow(cos(t * 90), 1.35);
  }
  const t = constrain((u - 0.87) / 0.05, 0, 1);
  return 0.26 + 0.06 * t;
}

function ventralProfile(u) {
  if (u <= 0) return 0;
  if (u < 0.08) return pow(u / 0.08, 0.65) * 0.38;
  if (u < 0.38) {
    const t = (u - 0.08) / 0.30;
    return 0.38 + 0.68 * sin(t * 90);
  }
  if (u <= 0.87) {
    const t = (u - 0.38) / 0.49;
    return 0.25 + 0.81 * pow(cos(t * 90), 1.45);
  }
  const t = constrain((u - 0.87) / 0.05, 0, 1);
  return 0.25 + 0.06 * t;
}

function buildFishObject(spec, idx) {
  const { cx, cy, L, W, angle, bend1, bend2, flip, cols, rows, accent } = spec;
  const spine = [];
  const N_SAMPLES = 130; // u from 0.0 to 1.29
  const cosA = cos(angle), sinA = sin(angle);

  for (let i = 0; i <= N_SAMPLES; i++) {
    const u = i / 100; // 0.00 to 1.30
    const lx = (u - 0.45) * L;
    const ly = (bend1 * L * sin(u * 180) + bend2 * L * sin(u * 360)) * flip;
    const wx = cx + lx * cosA - ly * sinA;
    const wy = cy + lx * sinA + ly * cosA;
    spine.push({ u, x: wx, y: wy, tx: 0, ty: 0, nx: 0, ny: 0 });
  }

  for (let i = 0; i <= N_SAMPLES; i++) {
    const i0 = max(0, i - 1);
    const i1 = min(N_SAMPLES, i + 1);
    let dx = spine[i1].x - spine[i0].x;
    let dy = spine[i1].y - spine[i0].y;
    const mag = sqrt(dx * dx + dy * dy) || 1;
    dx /= mag;
    dy /= mag;
    spine[i].tx = dx;
    spine[i].ty = dy;
    // Normal points toward v = +1 (ventral when flip = 1)
    spine[i].nx = -dy * flip;
    spine[i].ny = dx * flip;
  }

  function pt(u, v) {
    const uc = constrain(u, 0, 1.28);
    const idxF = uc * 100;
    const i0 = floor(idxF);
    const i1 = min(N_SAMPLES, i0 + 1);
    const frac = idxF - i0;
    const s0 = spine[i0], s1 = spine[i1];
    const sx = lerp(s0.x, s1.x, frac);
    const sy = lerp(s0.y, s1.y, frac);
    const nx = lerp(s0.nx, s1.nx, frac);
    const ny = lerp(s0.ny, s1.ny, frac);
    const tx = lerp(s0.tx, s1.tx, frac);
    const ty = lerp(s0.ty, s1.ty, frac);

    const dW = dorsalProfile(min(uc, 0.90)) * W;
    const vW = ventralProfile(min(uc, 0.90)) * W;
    const off = v < 0 ? v * dW : v * vW;
    return {
      x: sx + nx * off,
      y: sy + ny * off,
      tx, ty, nx, ny
    };
  }

  // Construct polygons
  const bodyPoly = [];
  for (let i = 0; i <= 45; i++) {
    const u = (i / 45) * 0.90;
    const p = pt(u, -1.0);
    bodyPoly.push([p.x, p.y]);
  }
  for (let i = 45; i >= 0; i--) {
    const u = (i / 45) * 0.90;
    const p = pt(u, 1.0);
    bodyPoly.push([p.x, p.y]);
  }

  // Caudal (Tail) Fin Polygon
  const caudalPoly = [];
  const tailUpper = [
    [0.88, -0.92], [0.94, -1.35], [1.02, -1.75], [1.11, -1.95],
    [1.17, -1.85], [1.13, -1.30], [1.06, -0.55], [1.01, 0.0]
  ];
  const tailLower = [
    [1.05, 0.55], [1.12, 1.25], [1.16, 1.78], [1.10, 1.90],
    [1.01, 1.70], [0.94, 1.32], [0.88, 0.92]
  ];
  for (let uv of tailUpper) {
    const p = pt(uv[0], uv[1]);
    caudalPoly.push([p.x, p.y]);
  }
  for (let uv of tailLower) {
    const p = pt(uv[0], uv[1]);
    caudalPoly.push([p.x, p.y]);
  }

  // Dorsal Fin Polygon
  const dorsalFinPoly = [];
  const dFinCoords = [
    [0.37, -0.95], [0.40, -1.78], [0.44, -1.82], [0.49, -1.62],
    [0.54, -1.42], [0.59, -1.25], [0.58, -0.95]
  ];
  for (let uv of dFinCoords) {
    const p = pt(uv[0], uv[1]);
    dorsalFinPoly.push([p.x, p.y]);
  }

  // Pelvic Fin Polygon
  const pelvicFinPoly = [];
  const pFinCoords = [
    [0.47, 0.92], [0.51, 1.54], [0.55, 1.58], [0.59, 1.35], [0.56, 0.92]
  ];
  for (let uv of pFinCoords) {
    const p = pt(uv[0], uv[1]);
    pelvicFinPoly.push([p.x, p.y]);
  }

  // Anal Fin Polygon
  const analFinPoly = [];
  const aFinCoords = [
    [0.67, 0.92], [0.71, 1.52], [0.76, 1.48], [0.82, 1.28], [0.81, 0.92]
  ];
  for (let uv of aFinCoords) {
    const p = pt(uv[0], uv[1]);
    analFinPoly.push([p.x, p.y]);
  }

  // Pectoral Fin Polygon (lies over the fish's own flank/belly)
  const pectoralFinPoly = [];
  const pecCoords = [
    [0.245, 0.35], [0.29, 0.42], [0.37, 0.72], [0.42, 1.04],
    [0.39, 1.15], [0.31, 0.98], [0.25, 0.62]
  ];
  for (let uv of pecCoords) {
    const p = pt(uv[0], uv[1]);
    pectoralFinPoly.push([p.x, p.y]);
  }

  const eyeCenter = pt(0.105, -0.18);
  const eyeRadius = W * 0.24;

  return {
    idx, spec, pt, L, W, flip, cols, rows, accent,
    bodyPoly, caudalPoly, dorsalFinPoly, pelvicFinPoly, analFinPoly, pectoralFinPoly,
    eyeCenter, eyeRadius
  };
}

function initFishHeap() {
