    { cx: 410, cy: 335, L: 470, W: 92, angle: 24, bend1: -0.05, bend2: 0.02, flip: 1, cols: 26, rows: 12, accent: PAL.vermilion },
    { cx: 785, cy: 855, L: 475, W: 92, angle: -156, bend1: 0.05, bend2: -0.02, flip: -1, cols: 26, rows: 12, accent: PAL.marigold },
    { cx: 800, cy: 350, L: 455, W: 88, angle: 144, bend1: 0.045, bend2: 0.02, flip: 1, cols: 25, rows: 12, accent: PAL.parrot },
    { cx: 395, cy: 845, L: 465, W: 90, angle: -36, bend1: -0.045, bend2: 0.02, flip: -1, cols: 25, rows: 12, accent: PAL.vermilion },

    // Mid-perimeter river fish tucked into the heap sides
    { cx: 265, cy: 595, L: 385, W: 74, angle: -76, bend1: 0.055, bend2: 0.015, flip: 1, cols: 22, rows: 11, accent: PAL.marigold },
    { cx: 935, cy: 585, L: 385, W: 74, angle: 104, bend1: -0.055, bend2: -0.015, flip: -1, cols: 22, rows: 11, accent: PAL.vermilion },
    { cx: 605, cy: 235, L: 375, W: 70, angle: 7, bend1: 0.05, bend2: -0.02, flip: 1, cols: 22, rows: 11, accent: PAL.parrot },
    { cx: 595, cy: 960, L: 375, W: 70, angle: -173, bend1: -0.05, bend2: 0.02, flip: -1, cols: 22, rows: 11, accent: PAL.marigold },

    // Upper central heap (grand Hilsa & Rohu specimens piled across the center)
    { cx: 555, cy: 700, L: 515, W: 105, angle: -15, bend1: 0.04, bend2: -0.02, flip: 1, cols: 28, rows: 13, accent: PAL.vermilion },
    { cx: 640, cy: 485, L: 520, W: 106, angle: 165, bend1: -0.04, bend2: 0.02, flip: -1, cols: 28, rows: 13, accent: PAL.marigold },
    { cx: 590, cy: 590, L: 565, W: 114, angle: 33, bend1: -0.045, bend2: 0.025, flip: 1, cols: 30, rows: 14, accent: PAL.vermilion },
    { cx: 475, cy: 470, L: 390, W: 74, angle: -44, bend1: 0.055, bend2: 0.015, flip: -1, cols: 23, rows: 11, accent: PAL.parrot }
  ];

  fishes = [];
  for (let i = 0; i < specs.length; i++) {
    const fObj = buildFishObject(specs[i], i);
    fishes.push(fObj);

    // Rasterize fins & body into bodyMask so higher fish cleanly occlude lower fish
    rasterizePoly(fObj.dorsalFinPoly, bodyMask, i);
    rasterizePoly(fObj.pelvicFinPoly, bodyMask, i);
    rasterizePoly(fObj.analFinPoly, bodyMask, i);
    rasterizePoly(fObj.caudalPoly, bodyMask, i);
    rasterizePoly(fObj.bodyPoly, bodyMask, i);
    rasterizePoly(fObj.pectoralFinPoly, bodyMask, i);

    // Pectoral mask for self-occlusion of belly scales
    rasterizePoly(fObj.pectoralFinPoly, pectoralMask, i);
  }

  // Populate protected eye specular mask for the topmost visible eyes
  for (let i = 0; i < fishes.length; i++) {
    const f = fishes[i];
    const ec = f.eyeCenter;
    const er = f.eyeRadius;
    const sx = ec.x - er * 0.26;
    const sy = ec.y - er * 0.26;
    if (bodyMask[floor(sy) * W_CANVAS + floor(sx)] === i) {
      rasterizeCircle(sx, sy, er * 0.25, eyeSpecMask, 1);
    }
  }
}

// ============================================================================
// STAGE BORDER & BANANA LEAF WASHES
// ============================================================================

function rectPoly(x, y, w, h) {
  return [[x, y], [x + w, y], [x + w, y + h], [x, y + h]];
}

function stageBorderAndLeafWashes() {
  // Outer twilight slab base
  addWashPoly(PAL.twilightSlate, 230, rectPoly(24, 24, 1152, 1152));

  // Inner banana leaf slab base
  addWashPoly(PAL.leafDark, 250, rectPoly(116, 116, 968, 968));

  // Banana leaf lateral vein strips & flat accents of vermilion, marigold, parrot green
  // Central midrib runs from (116, 920) to (1084, 280)
  const mx0 = 116, my0 = 920, mx1 = 1084, my1 = 280;
  const mdx = mx1 - mx0, mdy = my1 - my0;
  const mLen = sqrt(mdx * mdx + mdy * mdy);
  const tx = mdx / mLen, ty = mdy / mLen;
  const nx = -ty, ny = tx;

  const nStrips = 44;
  const stripColors = [PAL.leafDark, PAL.leafMid, PAL.leafOlive, PAL.leafSage];
  const accentColors = [PAL.vermilion, PAL.marigold, PAL.parrot];

  for (let side of [-1, 1]) {
    const vAngle = side === -1 ? -112 : 68;
    const vx = cos(vAngle), vy = sin(vAngle);

    for (let s = -12; s < nStrips; s++) {
      const t0 = s / 34;
      const t1 = (s + 1) / 34;
      const bx0 = mx0 + mdx * t0, by0 = my0 + mdy * t0;
      const bx1 = mx0 + mdx * t1, by1 = my0 + mdy * t1;

      const reach = 950;
      const p0 = [constrain(bx0, 116, 1084), constrain(by0, 116, 1084)];
      const p1 = [constrain(bx1, 116, 1084), constrain(by1, 116, 1084)];
      const p2 = [constrain(bx1 + vx * reach, 116, 1084), constrain(by1 + vy * reach, 116, 1084)];
      const p3 = [constrain(bx0 + vx * reach, 116, 1084), constrain(by0 + vy * reach, 116, 1084)];

      const baseCol = stripColors[(s + 100) % stripColors.length];
      addWashPoly(baseCol, 210, [p0, p1, p2, p3]);

      // Flat accent vein bands in vermilion, marigold orange, and parrot green
      const accCol = accentColors[(s + 100) % 3];
      const bx1a = lerp(bx0, bx1, 0.28), by1a = lerp(by0, by1, 0.28);
      const q0 = [constrain(bx0, 116, 1084), constrain(by0, 116, 1084)];
      const q1 = [constrain(bx1a, 116, 1084), constrain(by1a, 116, 1084)];
      const q2 = [constrain(bx1a + vx * reach, 116, 1084), constrain(by1a + vy * reach, 116, 1084)];
      const q3 = [constrain(bx0 + vx * reach, 116, 1084), constrain(by0 + vy * reach, 116, 1084)];
      addWashPoly(accCol, (s % 2 === 0) ? 215 : 155, [q0, q1, q2, q3]);
    }
  }

  // Central Banana Leaf Midrib flat compartments
  const nMidSegs = 28;
  for (let i = 0; i < nMidSegs; i++) {
    const t0 = i / nMidSegs, t1 = (i + 1) / nMidSegs;
    const x0 = lerp(mx0, mx1, t0), y0 = lerp(my0, my1, t0);
    const x1 = lerp(mx0, mx1, t1), y1 = lerp(my0, my1, t1);
    const w0 = lerp(22, 9, t0), w1 = lerp(22, 9, t1);

    const midPoly = [
      [x0 - nx * w0, y0 - ny * w0],
      [x1 - nx * w1, y1 - ny * w1],
      [x1 + nx * w1, y1 + ny * w1],
      [x0 + nx * w0, y0 + ny * w0]
    ];
    addWashPoly(PAL.leafRib, 240, midPoly);

    // Core accent stripe down the midrib
    const acc = accentColors[i % 3];
    const corePoly = [
      [x0 - nx * w0 * 0.42, y0 - ny * w0 * 0.42],
      [x1 - nx * w1 * 0.42, y1 - ny * w1 * 0.42],
      [x1 + nx * w1 * 0.42, y1 + ny * w1 * 0.42],
      [x0 + nx * w0 * 0.42, y0 + ny * w0 * 0.42]
    ];
    addWashPoly(acc, 235, corePoly);
  }

  // Border Bands (28..86 primary band, 86..116 secondary wave band)
  // Mask out the 4 border margins cleanly over the leaf edges
  addWashPoly(PAL.twilightBg, 255, rectPoly(0, 0, 1200, 116));
  addWashPoly(PAL.twilightBg, 255, rectPoly(0, 1084, 1200, 116));
  addWashPoly(PAL.twilightBg, 255, rectPoly(0, 116, 116, 968));
  addWashPoly(PAL.twilightBg, 255, rectPoly(1084, 116, 116, 968));

  // Populate triangular compartments in the 4 primary border bands (32..84)
  const step = 44;
  const bAccents = [PAL.vermilion, PAL.marigold, PAL.parrot, PAL.twilightPewter];
  for (let side = 0; side < 4; side++) {
    for (let p = 116; p < 1084; p += step) {
      const pNext = min(1084, p + step);
      const pMid = (p + pNext) * 0.5;
      const c1 = bAccents[floor(p / step) % 4];
      const c2 = bAccents[(floor(p / step) + 1) % 4];
      const c3 = bAccents[(floor(p / step) + 2) % 4];

      if (side === 0) { // Top (y: 32..84)
        addWashPoly(c1, 235, [[p, 84], [pMid, 32], [pNext, 84]]);
        addWashPoly(c2, 225, [[p, 32], [pMid, 32], [p, 84]]);
        addWashPoly(c3, 225, [[pMid, 32], [pNext, 32], [pNext, 84]]);
      } else if (side === 1) { // Bottom (y: 1116..1168)
        addWashPoly(c1, 235, [[p, 1116], [pMid, 1168], [pNext, 1116]]);
        addWashPoly(c2, 225, [[p, 1168], [pMid, 1168], [p, 1116]]);
        addWashPoly(c3, 225, [[pMid, 1168], [pNext, 1168], [pNext, 1116]]);
      } else if (side === 2) { // Left (x: 32..84)
        addWashPoly(c1, 235, [[84, p], [32, pMid], [84, pNext]]);
        addWashPoly(c2, 225, [[32, p], [32, pMid], [84, p]]);
        addWashPoly(c3, 225, [[32, pMid], [32, pNext], [84, pNext]]);
      } else { // Right (x: 1116..1168)
        addWashPoly(c1, 235, [[1116, p], [1168, pMid], [1116, pNext]]);
        addWashPoly(c2, 225, [[1168, p], [1168, pMid], [1116, p]]);
        addWashPoly(c3, 225, [[1168, pMid], [1168, pNext], [1116, pNext]]);
      }
    }
  }

  // Secondary inner border band compartments (88..112)
  const sStep = 28;
  for (let p = 116; p < 1084; p += sStep) {
    const pNext = min(1084, p + sStep);
    const col = accentColors[floor(p / sStep) % 3];
    addWashPoly(col, 215, rectPoly(p + 3, 90, pNext - p - 6, 20));
    addWashPoly(col, 215, rectPoly(p + 3, 1090, pNext - p - 6, 20));
    addWashPoly(col, 215, rectPoly(90, p + 3, 20, pNext - p - 6));
    addWashPoly(col, 215, rectPoly(1090, p + 3, 20, pNext - p - 6));
  }

  // Four Corner Medallions (32..112)
  const corners = [[32, 32], [1088, 32], [32, 1088], [1088, 1088]];
  for (let i = 0; i < 4; i++) {
    const [cx, cy] = corners[i];
    addWashPoly(PAL.twilightSlate, 250, rectPoly(cx, cy, 80, 80));
    addWashPoly(accentColors[i % 3], 240, [
      [cx + 40, cy + 6], [cx + 74, cy + 40], [cx + 40, cy + 74], [cx + 6, cy + 40]
    ]);
    addWashPoly(accentColors[(i + 1) % 3], 245, rectPoly(cx + 24, cy + 24, 32, 32));
  }
}

// ============================================================================
// STAGE SINGLE FISH WASHES (HYPERREAL SILVER + GILL SLITS + WET EYES)
// ============================================================================

function buildStripPoly(f, u0, u1, v0, v1, steps = 16) {
  const poly = [];
  for (let i = 0; i <= steps; i++) {
    const u = lerp(u0, u1, i / steps);
    const p = f.pt(u, v0);
    poly.push([p.x, p.y]);
  }
  for (let i = steps; i >= 0; i--) {
    const u = lerp(u0, u1, i / steps);
    const p = f.pt(u, v1);
    poly.push([p.x, p.y]);
  }
  return poly;
}

function circlePoly(cx, cy, r, n = 18) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = (i / n) * 360;
    pts.push([cx + cos(a) * r, cy + sin(a) * r]);
  }
  return pts;
}

function stageSingleFishWashes(f) {
  // Subtle contact shadow onto underlying leaf/fish
  const shadowPoly = f.bodyPoly.map(p => [p[0] + 5, p[1] + 6]);
  addWashPoly(PAL.ink, 145, shadowPoly);

  // Fins base washes
  addWashPoly(PAL.finAmber, 225, f.dorsalFinPoly);
  addWashPoly(PAL.finAmber, 225, f.pelvicFinPoly);
  addWashPoly(PAL.finAmber, 225, f.analFinPoly);
  addWashPoly(PAL.finAmber, 235, f.caudalPoly);

  // Flat accent bands on fins (vermilion, marigold, parrot green)
  const dTipPoly = [
    f.dorsalFinPoly[0], f.dorsalFinPoly[1], f.dorsalFinPoly[2], f.dorsalFinPoly[3],
    [lerp(f.dorsalFinPoly[3][0], f.dorsalFinPoly[6][0], 0.35),
     lerp(f.dorsalFinPoly[3][1], f.dorsalFinPoly[6][1], 0.35)]
  ];
  addWashPoly(f.accent, 215, dTipPoly);

  // Caudal fin fork accent band
  const cBase0 = f.pt(0.88, -0.75);
  const cBase1 = f.pt(0.88, 0.75);
  const cMid0 = f.pt(1.03, -1.25);
  const cMid1 = f.pt(1.00, 0.0);
  const cMid2 = f.pt(1.03, 1.25);
  addWashPoly(PAL.marigold, 195, [
    [cBase0.x, cBase0.y], [cMid0.x, cMid0.y], [cMid1.x, cMid1.y],
    [cMid2.x, cMid2.y], [cBase1.x, cBase1.y]
  ]);

  // Longitudinal metallic silver body bands (from dorsal gunmetal to belly pearl)
  addWashPoly(PAL.dorsalDark, 250, buildStripPoly(f, 0.0, 0.90, -1.0, -0.56, 22));
  addWashPoly(PAL.dorsalSlate, 250, buildStripPoly(f, 0.0, 0.90, -0.58, -0.22, 22));
  addWashPoly(PAL.flankSteel, 250, buildStripPoly(f, 0.04, 0.90, -0.24, 0.08, 22));
  addWashPoly(PAL.flankSilver, 250, buildStripPoly(f, 0.08, 0.90, 0.06, 0.42, 22));
  addWashPoly(PAL.flankBright, 250, buildStripPoly(f, 0.12, 0.90, 0.40, 0.72, 22));
  addWashPoly(PAL.bellyPearl, 250, buildStripPoly(f, 0.14, 0.90, 0.70, 1.0, 22));

  // Luminous mid-flank specular metallic ribbon
  addWashPoly(PAL.bellyLight, 235, buildStripPoly(f, 0.25, 0.78, -0.06, 0.16, 16));

  // Scattered iridescent twilight scales (vermilion, marigold, parrot green, pure pearl)
  const du = (0.88 - 0.25) / f.cols;
  const dv = 1.84 / f.rows;
  const accList = [PAL.vermilion, PAL.marigold, PAL.parrot, PAL.pureWhite];
  for (let c = 1; c < f.cols - 1; c += 2) {
    for (let r = 2; r < f.rows - 2; r++) {
      const hash = (c * 37 + r * 19 + f.idx * 13) % 17;
      if (hash < 3) {
        const u = 0.25 + (c + 0.5) * du;
        const v = -0.92 + (r + (c % 2) * 0.5) * dv;
        const p0 = f.pt(u - du * 0.35, v - dv * 0.42);
        const p1 = f.pt(u + du * 0.45, v);
        const p2 = f.pt(u - du * 0.35, v + dv * 0.42);
        const p3 = f.pt(u - du * 0.65, v);
        addWashPoly(accList[(c + r + f.idx) % 4], 215, [
          [p0.x, p0.y], [p1.x, p1.y], [p2.x, p2.y], [p3.x, p3.y]
        ]);
      }
    }
  }

  // Gill Slit crescent (deep vermilion & crimson filaments peeking behind operculum)
  const gillPoly = [];
  for (let i = 0; i <= 10; i++) {
    const v = lerp(-0.82, 0.88, i / 10);
    const uOp = 0.242 - 0.036 * v * v;
    const p = f.pt(uOp - 0.005, v);
    gillPoly.push([p.x, p.y]);
  }
  for (let i = 10; i >= 0; i--) {
    const v = lerp(-0.82, 0.88, i / 10);
    const uOp = 0.242 - 0.036 * v * v + 0.022 * (1 - 0.4 * v * v);
    const p = f.pt(uOp, v);
    gillPoly.push([p.x, p.y]);
  }
  addWashPoly(PAL.gillRed, 250, gillPoly);

  // Operculum mother-of-pearl & marigold cheek plates
  const opercPoly = [];
  for (let i = 0; i <= 10; i++) {
    const v = lerp(-0.78, 0.82, i / 10);
    const uPre = 0.175 - 0.028 * v * v;
    const p = f.pt(uPre, v);
    opercPoly.push([p.x, p.y]);
  }
  for (let i = 10; i >= 0; i--) {
    const v = lerp(-0.78, 0.82, i / 10);
    const uOp = 0.240 - 0.036 * v * v;
    const p = f.pt(uOp, v);
    opercPoly.push([p.x, p.y]);
  }
  addWashPoly(PAL.flankBright, 240, opercPoly);

  // Warm marigold & vermilion nacreous flush on cheek
  addWashPoly(PAL.marigold, 195, buildStripPoly(f, 0.14, 0.21, 0.05, 0.48, 6));
  addWashPoly(PAL.vermilion, 185, buildStripPoly(f, 0.18, 0.235, -0.35, 0.08, 6));

  // Pectoral fin wash on top of flank
  addWashPoly(PAL.finAmber, 235, f.pectoralFinPoly);
  const pecSpinePoly = [
    f.pectoralFinPoly[0], f.pectoralFinPoly[1],
    f.pectoralFinPoly[2], f.pectoralFinPoly[3],
    [lerp(f.pectoralFinPoly[3][0], f.pectoralFinPoly[5][0], 0.4),
     lerp(f.pectoralFinPoly[3][1], f.pectoralFinPoly[5][1], 0.4)]
  ];
  addWashPoly(PAL.vermilion, 220, pecSpinePoly);

  // Hyperreal Wet Eye washes
  const ec = f.eyeCenter;
  const er = f.eyeRadius;
  addWashPoly(PAL.ink, 250, circlePoly(ec.x, ec.y, er * 1.12, 20));
  addWashPoly(PAL.marigold, 250, circlePoly(ec.x, ec.y, er * 0.94, 20));
  addWashPoly(PAL.vermilion, 235, circlePoly(ec.x + er * 0.12, ec.y + er * 0.10, er * 0.76, 16));
  addWashPoly(PAL.bellyLight, 245, circlePoly(ec.x - er * 0.06, ec.y - er * 0.06, er * 0.72, 18));
  addWashPoly(PAL.ink, 255, circlePoly(ec.x, ec.y, er * 0.48, 18));
  // Pure white wet corneal specular reflection
  addWashPoly(PAL.pureWhite, 255, circlePoly(ec.x - er * 0.26, ec.y - er * 0.26, er * 0.22, 14));
  addWashPoly(PAL.pureWhite, 250, circlePoly(ec.x + er * 0.24, ec.y + er * 0.22, er * 0.09, 10));
}

// ============================================================================
// WATERCOLOR GLAZES
// ============================================================================

function renderWatercolorGlazes() {
  brush.noStroke();
  brush.noHatch();
  brush.noMass();
  brush.noWash();
  brush.fillBleed(0.12, "in");
  brush.fillTexture(0.45, 0.3);

  // Subtle twilight atmosphere glazes over selected fish flanks
  for (let i = 0; i < fishes.length; i++) {
    const f = fishes[i];
    brush.fill(i % 2 === 0 ? PAL.twilightPlum : PAL.leafSage, 42);
    const poly = buildStripPoly(f, 0.18, 0.82, -0.75, 0.15, 12);
    brush.beginShape(0);
    for (let pt of poly) brush.vertex(pt[0], pt[1]);
    brush.endShape(true);
  }
  brush.noFill();
}

// ============================================================================
// DOUBLE-LINE MADHUBANI BORDERS & KACHNI HATCHING
// ============================================================================

function drawDoubleFrame(x, y, w, h, gap, tickStep = 0) {
  brush.set("boldPen", PAL.ink, 1.0);
  brush.line(x, y, x + w, y);
  brush.line(x + w, y, x + w, y + h);
  brush.line(x + w, y + h, x, y + h);
  brush.line(x, y + h, x, y);

  brush.line(x + gap, y + gap, x + w - gap, y + gap);
  brush.line(x + w - gap, y + gap, x + w - gap, y + h - gap);
  brush.line(x + w - gap, y + h - gap, x + gap, y + h - gap);
  brush.line(x + gap, y + h - gap, x + gap, y + gap);

  if (tickStep > 0) {
    brush.set("microPen", PAL.ink, 0.9);
    for (let tx = x + gap; tx <= x + w - gap; tx += tickStep) {
      brush.line(tx, y, tx, y + gap);
      brush.line(tx, y + h - gap, tx, y + h);
    }
    for (let ty = y + gap; ty <= y + h - gap; ty += tickStep) {
      brush.line(x, ty, x + gap, ty);
      brush.line(x + w - gap, ty, x + w, ty);
    }
  }
}

function hatchTriangle(p0, p1, p2, spacing = 3.2) {
  const d12 = dist(p1[0], p1[1], p2[0], p2[1]);
  const steps = max(3, floor(d12 / spacing));
  for (let i = 1; i < steps; i++) {
    const t = i / steps;
    const x = lerp(p1[0], p2[0], t);
    const y = lerp(p1[1], p2[1], t);
    brush.line(p0[0], p0[1], x, y);
  }
}

function renderBordersPenWork() {
  // Structural concentric double-line frames
  drawDoubleFrame(24, 24, 1152, 1152, 6, 6);
  drawDoubleFrame(84, 84, 1032, 1032, 5, 5);
  drawDoubleFrame(112, 112, 976, 976, 5, 5);

  // Primary border zigzag double lines & dense triangle kachni hatching
  const step = 44;
  for (let side = 0; side < 4; side++) {
    for (let p = 116; p < 1084; p += step) {
      const pNext = min(1084, p + step);
      const pMid = (p + pNext) * 0.5;

      let A, B, C, L0, R0;
      if (side === 0) {
        A = [p, 84]; B = [pMid, 32]; C = [pNext, 84]; L0 = [p, 32]; R0 = [pNext, 32];
      } else if (side === 1) {
        A = [p, 1116]; B = [pMid, 1168]; C = [pNext, 1116]; L0 = [p, 1168]; R0 = [pNext, 1168];
      } else if (side === 2) {
        A = [84, p]; B = [32, pMid]; C = [84, pNext]; L0 = [32, p]; R0 = [32, pNext];
      } else {
        A = [1116, p]; B = [1168, pMid]; C = [1116, pNext]; L0 = [1168, p]; R0 = [1168, pNext];
      }

      brush.set("microPen", PAL.ink, 0.95);
      hatchTriangle(B, A, C, 3.4);
      hatchTriangle(A, L0, B, 3.6);
      hatchTriangle(C, B, R0, 3.6);

      brush.set("finePen", PAL.ink, 1.05);
      brush.line(A[0], A[1], B[0], B[1]);
      brush.line(B[0], B[1], C[0], C[1]);
      brush.line(A[0], A[1], L0[0], L0[1]);
    }
  }

  // Secondary wave-scale (lahariya) inner border band (89..112)
  const sStep = 28;
  brush.set("finePen", PAL.ink, 0.95);
  for (let p = 116; p < 1084; p += sStep) {
    const pNext = min(1084, p + sStep);
    const pMid = (p + pNext) * 0.5;
    // Top & bottom scale arches
    for (let r = 0; r < 4; r++) {
      const h = 4 + r * 4.2;
      brush.line(p + 2, 112, pMid, 112 - h);
      brush.line(pMid, 112 - h, pNext - 2, 112);

      brush.line(p + 2, 1088, pMid, 1088 + h);
      brush.line(pMid, 1088 + h, pNext - 2, 1088);

      brush.line(112, p + 2, 112 - h, pMid);
      brush.line(112 - h, pMid, 112, pNext - 2);

      brush.line(1088, p + 2, 1088 + h, pMid);
      brush.line(1088 + h, pMid, 1088, pNext - 2);
    }
  }

  // Four Corner Lotus Rosettes (32..112)
  const corners = [[72, 72], [1128, 72], [72, 1128], [1128, 1128]];
  for (let [cx, cy] of corners) {
    brush.set("boldPen", PAL.ink, 1.0);
    drawDoubleFrame(cx - 40, cy - 40, 80, 80, 4, 4);
    brush.set("finePen", PAL.ink, 0.95);
    for (let a = 0; a < 360; a += 15) {
      const rIn = 6, rOut = (a % 45 === 0) ? 35 : 26;
      brush.line(cx + cos(a) * rIn, cy + sin(a) * rIn, cx + cos(a) * rOut, cy + sin(a) * rOut);
    }
    for (let r of [8, 14, 22, 30]) {
      brush.circle(cx, cy, r, 0.05);
    }
  }
}

// ============================================================================
// BANANA LEAF MIDRIB, DOUBLE-LINE VEINS & KACHNI LAMINA HATCHING
// ============================================================================

function renderBananaLeafPenWork() {
  const mx0 = 116, my0 = 920, mx1 = 1084, my1 = 280;
  const mdx = mx1 - mx0, mdy = my1 - my0;
  const mLen = sqrt(mdx * mdx + mdy * mdy);
  const tx = mdx / mLen, ty = mdy / mLen;
  const nx = -ty, ny = tx;

  // 1. Lateral veins & dense inter-vein kachni hatching
  const nStrips = 44;
  for (let side of [-1, 1]) {
    const vAngle = side === -1 ? -112 : 68;
    const vx = cos(vAngle), vy = sin(vAngle);
    const px = -vy, py = vx; // perpendicular to vein

    for (let s = -12; s < nStrips; s++) {
      const t0 = s / 34;
      const t1 = (s + 1) / 34;
      const bx0 = mx0 + mdx * t0, by0 = my0 + mdy * t0;
      const bx1 = mx0 + mdx * t1, by1 = my0 + mdy * t1;
      const reach = 960;

      // Double-line primary vein along (bx0, by0)
      brush.set("finePen", PAL.ink, 1.0);
      clippedLineLeaf(bx0, by0, bx0 + vx * reach, by0 + vy * reach);
      clippedLineLeaf(bx0 + px * 3.5, by0 + py * 3.5, bx0 + px * 3.5 + vx * reach, by0 + py * 3.5 + vy * reach);

      // Secondary sub-veins dividing the strip into 3 channels
      const sx1 = lerp(bx0, bx1, 0.36), sy1 = lerp(by0, by1, 0.36);
      const sx2 = lerp(bx0, bx1, 0.68), sy2 = lerp(by0, by1, 0.68);
      brush.set("microPen", PAL.ink, 0.85);
      clippedLineLeaf(sx1, sy1, sx1 + vx * reach, sy1 + vy * reach);
      clippedLineLeaf(sx2, sy2, sx2 + vx * reach, sy2 + vy * reach);

      // Dense parallel kachni ticks & herringbone hatching inside the 3 sub-channels
      const dStep = 5.5;
      for (let d = 6; d < reach; d += dStep) {
        const ax0 = bx0 + vx * d, ay0 = by0 + vy * d;
        const ax1 = sx1 + vx * d, ay1 = sy1 + vy * d;
        const ax2 = sx2 + vx * (d + 3), ay2 = sy2 + vy * (d + 3);
        const ax3 = bx1 + vx * d, ay3 = by1 + vy * d;

        if (isLeafVisible(ax0, ay0) || isLeafVisible(ax3, ay3)) {
          clippedLineLeaf(ax0, ay0, ax1, ay1);
          clippedLineLeaf(ax1, ay1, ax2, ay2);
          clippedLineLeaf(ax2, ay2, ax3, ay3);
        }
      }
    }
  }

  // 2. Central Banana Leaf Midrib double-lines & transverse vascular hatching
  const nMidSteps = 140;
  brush.set("microPen", PAL.ink, 0.95);
  for (let i = 0; i <= nMidSteps; i++) {
    const t = i / nMidSteps;
    const cx = lerp(mx0, mx1, t), cy = lerp(my0, my1, t);
    const w = lerp(22, 9, t);
    clippedLineLeaf(cx - nx * w, cy - ny * w, cx + nx * w, cy + ny * w);
  }

  brush.set("boldPen", PAL.ink, 1.1);
  for (let frac of [-1.0, -0.78, -0.42, 0.42, 0.78, 1.0]) {
    const segs = 32;
    for (let i = 0; i < segs; i++) {
      const t0 = i / segs, t1 = (i + 1) / segs;
      const x0 = lerp(mx0, mx1, t0) + nx * lerp(22, 9, t0) * frac;
      const y0 = lerp(my0, my1, t0) + ny * lerp(22, 9, t0) * frac;
      const x1 = lerp(mx0, mx1, t1) + nx * lerp(22, 9, t1) * frac;
      const y1 = lerp(my0, my1, t1) + ny * lerp(22, 9, t1) * frac;
      clippedLineLeaf(x0, y0, x1, y1);
    }
  }
}

// ============================================================================
// LOOSE FALLEN SCALES & RIVER WATER DROPLETS ON THE LEAF
// ============================================================================

function renderLooseScalesAndDroplets() {
  const spots = [
    [165, 185], [220, 155], [1025, 175], [975, 225],
    [175, 1015], [235, 975], [1020, 1020], [960, 990],
    [155, 430], [160, 770], [1040, 420], [1035, 780],
    [450, 155], [760, 155], [440, 1040], [770, 1040],
    [325, 470], [875, 720], [730, 620], [480, 380]
  ];

  for (let i = 0; i < spots.length; i++) {
    const [sx, sy] = spots[i];
    if (!isLeafVisible(sx, sy)) continue;

    if (i % 2 === 0) {
      // Fallen individual cycloid fish scale on the leaf
      const r = 10 + (i % 3) * 2;
      const ang = (i * 47) % 360;
      brush.noStroke();
      brush.wash(PAL.bellyLight, 235);
      const pts = circlePoly(sx, sy, r, 12);
      brush.beginShape(0);
      for (let p of pts) brush.vertex(p[0], p[1]);
      brush.endShape(true);
      brush.noWash();

      brush.set("finePen", PAL.ink, 0.95);
      brush.circle(sx, sy, r, 0.08);
      brush.set("microPen", PAL.ink, 0.85);
      for (let k = -3; k <= 3; k++) {
        const a = ang + k * 16;
        brush.line(
          sx + cos(a) * (r * 0.25), sy + sin(a) * (r * 0.25),
          sx + cos(a) * (r * 0.92), sy + sin(a) * (r * 0.92)
        );
      }
    } else {
      // Glistening water droplet on the waxy banana leaf
      const r = 5 + (i % 3) * 1.8;
      brush.set("finePen", PAL.ink, 0.9);
      brush.circle(sx, sy, r, 0.05);
      brush.set("wetSheen", PAL.pureWhite, 1.1);
      brush.line(sx - r * 0.35, sy - r * 0.35, sx + r * 0.1, sy - r * 0.45);
    }
  }
}

// ============================================================================
// HYPERREAL SILVER RIVER FISH PEN WORK (SCALES, GILLS, FINS, WET EYES)
// ============================================================================

function renderSingleFishPenWork(f, fIdx) {
  // 1. FINS: Segmented fin rays, inter-ray kachni hatching, and double-line margins
  renderFinRaysAndMembrane(f, fIdx);

  // 2. EVERY SCALE: Imbricated crescent contour + crescent of parallel black pen strokes
  renderFishScales(f, fIdx);

  // 3. PECTORAL FIN: Drawn over the flank with crisp rays & double-line border
  renderPectoralFin(f, fIdx);

  // 4. HEAD, OPERCULUM, GILL SLIT & SENSORY BARBELS
  renderHeadAndGillSlit(f, fIdx);

  // 5. DOUBLE-LINE BODY CONTOURS WITH KACHNI TICKS
  renderBodyDoubleContours(f, fIdx);

  // 6. WET HYPERREAL EYE (Iris striations, orbital rings, protected white reflections)
  renderWetEye(f, fIdx);
}

function renderFinRaysAndMembrane(f, fIdx) {
  // Caudal (Tail) Fin: 24 branched segmented rays + cross-membrane ticks
  const nTailRays = 24;
  for (let i = 0; i <= nTailRays; i++) {
    const t = i / nTailRays;
    const vBase = lerp(-0.88, 0.88, t);
    const pBase = f.pt(0.88, vBase);

    // Forked bilobed profile
    const lobeFactor = abs(t - 0.5) * 2; // 0 at center fork, 1 at outer tips
    const uTip = lerp(1.01, 1.165, pow(lobeFactor, 0.75));
    const vTip = lerp(-1.88, 1.82, t);
    const pTip = f.pt(uTip, vTip);
    const pMid = f.pt(lerp(0.88, uTip, 0.52), lerp(vBase, vTip, 0.48));

    brush.set(i === 0 || i === nTailRays ? "boldPen" : "finePen", PAL.ink, 0.95);
    clippedLineFish(pBase.x, pBase.y, pMid.x, pMid.y, fIdx);
    clippedLineFish(pMid.x, pMid.y, pTip.x, pTip.y, fIdx);

    // Secondary ray bifurcation near tip
    if (i > 0 && i < nTailRays) {
      const pBranch = f.pt(uTip - 0.01, vTip + (t < 0.5 ? 0.05 : -0.05));
      brush.set("microPen", PAL.ink, 0.85);
      clippedLineFish(pMid.x, pMid.y, pBranch.x, pBranch.y, fIdx);
    }

    // Transverse ray joint segments / membrane kachni ticks
    if (i < nTailRays) {
      const tNext = (i + 1) / nTailRays;
      const lfNext = abs(tNext - 0.5) * 2;
      const uTipN = lerp(1.01, 1.165, pow(lfNext, 0.75));
      const vTipN = lerp(-1.88, 1.82, tNext);
      const pTipN = f.pt(uTipN, vTipN);

      brush.set("microPen", PAL.ink, 0.8);
      for (let s = 1; s <= 6; s++) {
        const fSeg = s / 7;
        const xA = lerp(pBase.x, pTip.x, fSeg);
        const yA = lerp(pBase.y, pTip.y, fSeg);
        const xB = lerp(pBase.x, pTipN.x, fSeg);
        const yB = lerp(pBase.y, pTipN.y, fSeg);
        clippedLineFish(xA, yA, xB, yB, fIdx);
      }
      brush.set("finePen", PAL.ink, 0.95);
      clippedLineFish(pTip.x, pTip.y, pTipN.x, pTipN.y, fIdx);
    }
  }

  // Helper for Dorsal, Pelvic, Anal fins
  function drawRayedFin(u0, u1, vBaseSign, vReachMax, nRays) {
    let prevTip = null;
    for (let i = 0; i <= nRays; i++) {
      const t = i / nRays;
      const uB = lerp(u0, u1, t);
      const uT = lerp(u0 + 0.03, u1 + 0.02, t);
      const reach = vReachMax * (1.0 - 0.42 * pow(t, 0.8));
      const pB = f.pt(uB, vBaseSign * 0.94);
      const pT = f.pt(uT, vBaseSign * reach);

      brush.set(i <= 1 ? "boldPen" : "finePen", PAL.ink, 0.95);
      clippedLineFish(pB.x, pB.y, pT.x, pT.y, fIdx);

      if (prevTip) {
        brush.set("finePen", PAL.ink, 0.9);
        clippedLineFish(prevTip.x, prevTip.y, pT.x, pT.y, fIdx);
        brush.set("microPen", PAL.ink, 0.8);
        for (let s = 1; s <= 4; s++) {
          const fs = s / 5;
          clippedLineFish(
            lerp(prevTip.bx, prevTip.x, fs), lerp(prevTip.by, prevTip.y, fs),
            lerp(pB.x, pT.x, fs), lerp(pB.y, pT.y, fs),
            fIdx
          );
        }
      }
      prevTip = { x: pT.x, y: pT.y, bx: pB.x, by: pB.y };
    }
  }

  drawRayedFin(0.38, 0.58, -1, 1.76, 14); // Dorsal fin
  drawRayedFin(0.48, 0.56, 1, 1.54, 8);   // Pelvic fin
  drawRayedFin(0.68, 0.80, 1, 1.48, 10);  // Anal fin
}

function renderFishScales(f, fIdx) {
  const uStart = 0.245;
  const uEnd = 0.885;
  const nCols = f.cols;
  const nRows = f.rows;
  const du = (uEnd - uStart) / nCols;
  const dv = 1.86 / nRows;

  for (let c = 0; c < nCols; c++) {
    const uCol = uStart + (c + 0.5) * du;
    const rowShift = (c % 2) * 0.5;

    for (let r = 0; r < nRows; r++) {
      const vCenter = -0.93 + (r + rowShift) * dv;
      if (vCenter < -0.90 || vCenter > 0.90) continue;

      const pCenter = f.pt(uCol, vCenter);
      if (!isFishVisible(pCenter.x, pCenter.y, fIdx, true)) continue;

      const scaleH = dv * 0.54;
      const scaleW = du * 0.68;

      // Imbricated cycloid crescent contour points
      const pTop = f.pt(uCol - scaleW * 0.35, vCenter - scaleH);
      const pUpper = f.pt(uCol + scaleW * 0.32, vCenter - scaleH * 0.58);
      const pApex = f.pt(uCol + scaleW * 0.62, vCenter);
      const pLower = f.pt(uCol + scaleW * 0.32, vCenter + scaleH * 0.58);
      const pBot = f.pt(uCol - scaleW * 0.35, vCenter + scaleH);

      brush.set("finePen", PAL.ink, 0.95);
      clippedLineFish(pTop.x, pTop.y, pUpper.x, pUpper.y, fIdx, true);
      clippedLineFish(pUpper.x, pUpper.y, pApex.x, pApex.y, fIdx, true);
      clippedLineFish(pApex.x, pApex.y, pLower.x, pLower.y, fIdx, true);
      clippedLineFish(pLower.x, pLower.y, pBot.x, pBot.y, fIdx, true);

      // Crescent of parallel black pen hatching modeling the scale
      // Dorsal scales have denser, longer parallel strokes; belly scales have delicate ticks
      const dorsalWeight = constrain(map(vCenter, -0.9, 0.85, 1.0, 0.38), 0.38, 1.0);
      const nHatch = vCenter < -0.15 ? 6 : 5;
      brush.set("microPen", PAL.ink, 0.88);

      for (let h = 0; h < nHatch; h++) {
        const th = (h / (nHatch - 1)) * 2 - 1; // -1 to +1 across the crescent
        const vH = vCenter + th * scaleH * 0.78;
        const archFactor = 1.0 - th * th;
        const uTip = uCol + scaleW * (0.54 * archFactor - 0.12 * (1 - archFactor));
        const strokeLen = scaleW * (0.45 + 0.65 * dorsalWeight) * (0.65 + 0.35 * archFactor);
        const uBase = uTip - strokeLen;

        const pH0 = f.pt(uBase, vH * 0.99 + vCenter * 0.01);
        const pH1 = f.pt(uTip, vH);
        clippedLineFish(pH0.x, pH0.y, pH1.x, pH1.y, fIdx, true);
      }

      // Inner secondary crescent rim on larger mid-body scales
      if (dorsalWeight > 0.52) {
        const pInU = f.pt(uCol + scaleW * 0.08, vCenter - scaleH * 0.45);
        const pInA = f.pt(uCol + scaleW * 0.30, vCenter);
        const pInL = f.pt(uCol + scaleW * 0.08, vCenter + scaleH * 0.45);
        clippedLineFish(pInU.x, pInU.y, pInA.x, pInA.y, fIdx, true);
        clippedLineFish(pInA.x, pInA.y, pInL.x, pInL.y, fIdx, true);
      }

      // Lateral line sensory canal tube & pore along v ≈ 0
      if (abs(vCenter) < dv * 0.55) {
        brush.set("boldPen", PAL.ink, 0.95);
        const pL0 = f.pt(uCol - scaleW * 0.25, vCenter - dv * 0.07);
        const pL1 = f.pt(uCol + scaleW * 0.35, vCenter - dv * 0.07);
        const pL2 = f.pt(uCol - scaleW * 0.25, vCenter + dv * 0.07);
        const pL3 = f.pt(uCol + scaleW * 0.35, vCenter + dv * 0.07);
        clippedLineFish(pL0.x, pL0.y, pL1.x, pL1.y, fIdx, true);
        clippedLineFish(pL2.x, pL2.y, pL3.x, pL3.y, fIdx, true);
      }
    }
  }
}

function renderPectoralFin(f, fIdx) {
  const nRays = 11;
  let prevT = null;
  for (let i = 0; i <= nRays; i++) {
    const t = i / nRays;
    const pBase = f.pt(lerp(0.248, 0.258, t), lerp(0.38, 0.62, t));
    const uTip = lerp(0.415, 0.315, pow(t, 1.1));
    const vTip = lerp(1.02, 1.00, t) + 0.12 * sin(t * 180);
    const pTip = f.pt(uTip, vTip);

    brush.set(i <= 1 ? "boldPen" : "finePen", PAL.ink, 0.95);
    clippedLineFish(pBase.x, pBase.y, pTip.x, pTip.y, fIdx, false);

    if (prevT) {
      brush.set("finePen", PAL.ink, 0.9);
      clippedLineFish(prevT.x, prevT.y, pTip.x, pTip.y, fIdx, false);
      brush.set("microPen", PAL.ink, 0.8);
      for (let s = 1; s <= 4; s++) {
        const fs = s / 5;
        clippedLineFish(
          lerp(prevT.bx, prevT.x, fs), lerp(prevT.by, prevT.y, fs),
          lerp(pBase.x, pTip.x, fs), lerp(pBase.y, pTip.y, fs),
          fIdx, false
        );
      }
    }
    prevT = { x: pTip.x, y: pTip.y, bx: pBase.x, by: pBase.y };
  }
}

function renderHeadAndGillSlit(f, fIdx) {
  // 1. Gill Slit Filaments (comb of fine black pen teeth over the vermilion gill bed)
  const nFilaments = 24;
  brush.set("microPen", PAL.ink, 0.9);
  for (let i = 0; i <= nFilaments; i++) {
    const v = lerp(-0.78, 0.84, i / nFilaments);
    const uOp = 0.242 - 0.036 * v * v;
    const uOut = uOp + 0.021 * (1 - 0.4 * v * v);
    const p0 = f.pt(uOp, v);
    const p1 = f.pt(uOut, v + 0.02);
    clippedLineFish(p0.x, p0.y, p1.x, p1.y, fIdx);
  }

  // 2. Double-line Operculum, Pre-opercle, and Gill Slit borders
  const opCurves = [
    { uBase: 0.242, curve: 0.036, bold: true },
    { uBase: 0.236, curve: 0.036, bold: false },
    { uBase: 0.260, curve: 0.042, bold: true },
    { uBase: 0.178, curve: 0.028, bold: true },
    { uBase: 0.172, curve: 0.028, bold: false }
  ];

  for (let oc of opCurves) {
    const pts = [];
    for (let i = 0; i <= 16; i++) {
      const v = lerp(-0.84, 0.88, i / 16);
      const u = oc.uBase - oc.curve * v * v;
      const p = f.pt(u, v);
      pts.push([p.x, p.y]);
    }
    brush.set(oc.bold ? "boldPen" : "finePen", PAL.ink, 1.0);
    drawPolylineFish(pts, fIdx);
  }

  // 3. Radiating bony striations across the operculum & cheek
  brush.set("microPen", PAL.ink, 0.85);
  for (let i = 0; i <= 22; i++) {
    const v = lerp(-0.72, 0.78, i / 22);
    const u0 = 0.178 - 0.028 * v * v;
    const u1 = 0.235 - 0.036 * v * v;
    const p0 = f.pt(u0, v * 0.92);
    const p1 = f.pt(u1, v);
    clippedLineFish(p0.x, p0.y, p1.x, p1.y, fIdx);
  }

  // Cranial & cheek contour hatching
  for (let i = 0; i < 14; i++) {
    const t = i / 13;
    const v = lerp(-0.92, -0.35, t);
    const p0 = f.pt(0.05 + t * 0.03, v);
    const p1 = f.pt(0.168, v * 0.95);
    clippedLineFish(p0.x, p0.y, p1.x, p1.y, fIdx);
  }
  for (let i = 0; i < 12; i++) {
    const t = i / 11;
    const v = lerp(0.28, 0.86, t);
    const p0 = f.pt(0.06 + t * 0.03, v);
    const p1 = f.pt(0.168, v);
    clippedLineFish(p0.x, p0.y, p1.x, p1.y, fIdx);
  }

  // 4. Fleshy double-lined mouth lips & nostril rosette
  brush.set("boldPen", PAL.ink, 1.0);
  const lipPts1 = [], lipPts2 = [];
  for (let i = 0; i <= 8; i++) {
    const t = i / 8;
    const p1 = f.pt(lerp(0.002, 0.078, t), lerp(-0.05, 0.38, pow(t, 0.8)));
    const p2 = f.pt(lerp(0.012, 0.082, t), lerp(0.05, 0.48, pow(t, 0.8)));
    lipPts1.push([p1.x, p1.y]);
    lipPts2.push([p2.x, p2.y]);
  }
  drawPolylineFish(lipPts1, fIdx);
  brush.set("finePen", PAL.ink, 0.95);
  drawPolylineFish(lipPts2, fIdx);

  // Nostril pore
  const pNos = f.pt(0.062, -0.34);
  if (isFishVisible(pNos.x, pNos.y, fIdx)) {
    brush.set("finePen", PAL.ink, 0.9);
    brush.circle(pNos.x, pNos.y, 3.2, 0.05);
    brush.circle(pNos.x, pNos.y, 1.4, 0.05);
  }

  // 5. Sensory Barbels (delicate curving river-carp whiskers)
  const pBarb0 = f.pt(0.025, 0.22);
  const pBarb1 = f.pt(-0.04, 0.65);
  const pBarb2 = f.pt(-0.09, 1.15);
  if (isFishVisible(pBarb0.x, pBarb0.y, fIdx)) {
    brush.set("finePen", PAL.ink, 0.95);
    brush.line(pBarb0.x, pBarb0.y, pBarb1.x, pBarb1.y);
    brush.set("microPen", PAL.ink, 0.85);
    brush.line(pBarb1.x, pBarb1.y, pBarb2.x, pBarb2.y);
  }
}

function renderBodyDoubleContours(f, fIdx) {
  const nSteps = 50;
  for (let side of [-1, 1]) {
    const outerPts = [];
    const innerPts = [];
    for (let i = 0; i <= nSteps; i++) {
      const u = (i / nSteps) * 0.90;
      const pOut = f.pt(u, side * 1.0);
      const pIn = f.pt(u, side * 0.93);
      outerPts.push([pOut.x, pOut.y]);
      innerPts.push([pIn.x, pIn.y]);

      // Perpendicular kachni ticks between the double contour lines
      if (i % 1 === 0) {
        brush.set("microPen", PAL.ink, 0.85);
        clippedLineFish(pOut.x, pOut.y, pIn.x, pIn.y, fIdx);
      }
    }
    brush.set("boldPen", PAL.ink, 1.05);
    drawPolylineFish(outerPts, fIdx);
    brush.set("finePen", PAL.ink, 0.95);
    drawPolylineFish(innerPts, fIdx);
  }
}

function renderWetEye(f, fIdx) {
  const ec = f.eyeCenter;
  const er = f.eyeRadius;
  if (!isFishVisible(ec.x, ec.y, fIdx)) return;

  // Concentric double orbital rings with radial kachni ticks
  const radii = [er * 1.14, er * 0.96, er * 0.48];
  for (let r of radii) {
    brush.set(r > er ? "boldPen" : "finePen", PAL.ink, 1.0);
    const pts = circlePoly(ec.x, ec.y, r, 28);
    pts.push(pts[0]);
    drawPolylineFish(pts, fIdx);
  }

  // Radial iris striations & orbital rim ticks (automatically clipped around eyeSpecMask)
  brush.set("microPen", PAL.ink, 0.88);
  for (let a = 0; a < 360; a += 10) {
    const ca = cos(a), sa = sin(a);
    // Iris fibers
    clippedLineFish(
      ec.x + ca * (er * 0.49), ec.y + sa * (er * 0.49),
      ec.x + ca * (er * 0.95), ec.y + sa * (er * 0.95),
      fIdx
    );
    // Outer orbital ticks
    if (a % 20 === 0) {
      clippedLineFish(
        ec.x + ca * (er * 0.96), ec.y + sa * (er * 0.96),
        ec.x + ca * (er * 1.14), ec.y + sa * (er * 1.14),
        fIdx
      );
    }
  }

  // Dense velvet cross-hatching inside the pupil (avoiding white specular reflection)
  const step = 2.2;
  for (let dy = -er * 0.45; dy <= er * 0.45; dy += step) {
    const dx = sqrt(max(0, (er * 0.46) * (er * 0.46) - dy * dy));
    clippedLineFish(ec.x - dx, ec.y + dy, ec.x + dx, ec.y + dy, fIdx);
    clippedLineFish(ec.x + dy, ec.y - dx, ec.x + dy, ec.y + dx, fIdx);
  }
}

// ============================================================================
// FINAL WET SPECULAR HIGHLIGHTS & GLISTENING MUCILAGE SHEEN
// ============================================================================

function renderFinalWetHighlights() {
  brush.set("wetSheen", PAL.pureWhite, 1.05);

  for (let fIdx = 0; fIdx < fishes.length; fIdx++) {
    const f = fishes[fIdx];

    // 1. Bright wet corneal reflection crescent & pinpoint dot on eye
    const ec = f.eyeCenter;
    const er = f.eyeRadius;
    const sx = ec.x - er * 0.26;
    const sy = ec.y - er * 0.26;
    if (bodyMask[floor(sy) * W_CANVAS + floor(sx)] === fIdx) {
      brush.set("wetSheen", PAL.pureWhite, 1.35);
      for (let r = 1.5; r <= er * 0.20; r += 1.8) {
        brush.arc(sx, sy, r, 195, 345);
      }
      brush.line(sx - er * 0.1, sy - er * 0.05, sx + er * 0.1, sy - er * 0.1);
      // Secondary lower-right wet glint
      const sx2 = ec.x + er * 0.24, sy2 = ec.y + er * 0.22;
      brush.line(sx2 - 1.5, sy2, sx2 + 1.5, sy2);
    }

    // 2. Glistening scale apex highlights along the upper-flank convexity
    brush.set("wetSheen", PAL.pureWhite, 0.9);
    const uStart = 0.25, uEnd = 0.86;
    const du = (uEnd - uStart) / f.cols;
    const dv = 1.86 / f.rows;

    for (let c = 1; c < f.cols - 1; c++) {
      const uCol = uStart + (c + 0.5) * du;
      const rowShift = (c % 2) * 0.5;
      for (let r = 3; r <= 7; r++) {
        const vCenter = -0.93 + (r + rowShift) * dv;
        const pApex = f.pt(uCol + du * 0.35, vCenter);
        if (!isFishVisible(pApex.x, pApex.y, fIdx, true)) continue;

        if ((c + r) % 2 === 0) {
          const pU = f.pt(uCol + du * 0.18, vCenter - dv * 0.24);
          const pL = f.pt(uCol + du * 0.18, vCenter + dv * 0.24);
          brush.line(pU.x, pU.y, pApex.x, pApex.y);
          brush.line(pApex.x, pApex.y, pL.x, pL.y);
        }
      }
    }

    // 3. Longitudinal wet slime / mucilage shine streak on operculum & flank ridge
    brush.set("wetSheen", PAL.pureWhite, 1.1);
    const pOp0 = f.pt(0.14, -0.10);
    const pOp1 = f.pt(0.21, -0.06);
    if (isFishVisible(pOp0.x, pOp0.y, fIdx) && isFishVisible(pOp1.x, pOp1.y, fIdx)) {
      brush.line(pOp0.x, pOp0.y, pOp1.x, pOp1.y);
    }
  }
}

// Hyperreal Andean Tocapu Botanical Plate: Native Potatoes (Papas Nativas) & Maize (Choclo)
// Rendered in dense coloured-pencil layering with woven cochineal-red & alpaca-cream warp dividers

const SEED = 48291;

const PALETTE = {
  paper: "#e6dcc8",
  cream: "#efe6d5",
  creamDark: "#cbbba0",
  cochineal: "#9e1b24",
  cochinealBright: "#c42832",
  cochinealDeep: "#520b12",
  ochre: "#c9963e",
  ochreLight: "#e3bc6b",
  ochreDark: "#7d5b24",
  slateBg1: "#23272c",
  slateBg2: "#1b1e22",
  slateBg3: "#282c32",
  mustardBg1: "#876f3f",
  mustardBg2: "#7d6639",
  mustardBg3: "#826b3c",
  terraBg1: "#683327",
  terraBg2: "#602e23",
  terraBg3: "#653125",
  obsidian: "#141218",
  charcoal: "#242129",
  plumDark: "#2b1929",
  plumMid: "#4d243d",
  soilDark: "#2e251d",
  soilMid: "#5c4a38",
  soilLight: "#967e63"
};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Custom coloured-pencil and dry-media brushes tailored for 1200x1200 hyperrealism
  brush.add("prismacolor", {
    type: "default",
    weight: 0.42,
    scatter: 0.28,
    sharpness: 0.48,
    grain: 14,
    opacity: 95,
    spacing: 0.16,
    pressure: [0.55, 1.15, 0.5],
    noise: 0.35
  });

  brush.add("fine_pencil", {
    type: "default",
    weight: 0.22,
    scatter: 0.1,
    sharpness: 0.82,
    grain: 9,
    opacity: 145,
    spacing: 0.14,
    pressure: [0.4, 1.0, 0.4],
    noise: 0.2
  });

  brush.add("wax_burnish", {
    type: "default",
    weight: 0.6,
    scatter: 0.16,
    sharpness: 0.32,
    grain: 6,
    opacity: 165,
    spacing: 0.12,
    pressure: [0.35, 1.25, 0.35],
    noise: 0.15
  });

  brush.add("soil_stipple", {
    type: "spray",
    weight: 0.45,
    scatter: 1.6,
    opacity: 120,
    spacing: 0.35,
    pressure: [0.7, 1.1, 0.7]
  });
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.paper);
  brush.noField();

  const margin = 54;
  const bandW = 24;
  const cellW = (width - margin * 2 - bandW * 4) / 3; // 332 px per compartment

  // 3x3 Latin-square ground colors (Slate, Mustard, Terracotta) + Checkerboard specimens
  const cells = [
    // Row 0
    {
      row: 0, col: 0, bg: PALETTE.slateBg1, bgTone: "slate",
      type: "potato", variant: "huamantanga" // Purple-black with golden-ochre patches & ruby eyes
    },
    {
      row: 0, col: 1, bg: PALETTE.mustardBg1, bgTone: "mustard",
      type: "maize", variant: "sangre" // Blood-red & mahogany glossy cob
    },
    {
      row: 0, col: 2, bg: PALETTE.terraBg1, bgTone: "terracotta",
      type: "potato", variant: "leona" // Deep knobby obsidian-violet tuber with crusty soil
    },
    // Row 1
    {
      row: 1, col: 0, bg: PALETTE.terraBg2, bgTone: "terracotta",
      type: "maize", variant: "morado" // Jet-black & deep plum Maíz Morado
    },
    {
      row: 1, col: 1, bg: PALETTE.slateBg2, bgTone: "slate",
      type: "potato", variant: "pina" // Centerpiece: Rosette cochineal-red & ochre-marbled Papa Piña
    },
    {
      row: 1, col: 2, bg: PALETTE.mustardBg2, bgTone: "mustard",
      type: "maize", variant: "piscorunto" // Ochre-cream Cuzco kernels densely speckled with purple & crimson
    },
    // Row 2
    {
      row: 2, col: 0, bg: PALETTE.mustardBg3, bgTone: "mustard",
      type: "potato", variant: "huayro" // Elongated blood-crimson & charcoal segmented tuber
    },
    {
      row: 2, col: 1, bg: PALETTE.slateBg3, bgTone: "slate",
      type: "maize", variant: "chullpi" // Jewel mosaic cob: obsidian, ochre, cream & cochineal kernels
    },
    {
      row: 2, col: 2, bg: PALETTE.terraBg3, bgTone: "terracotta",
      type: "potato", variant: "qompis" // Russet-ochre netted skin with heavy soil grit & rosy eyes
    }
  ];

  // Compute pixel coordinates for each compartment
  for (let c of cells) {
    c.x = margin + bandW + c.col * (cellW + bandW);
    c.y = margin + bandW + c.row * (cellW + bandW);
    c.w = cellW;
    c.h = cellW;
    c.cx = c.x + cellW * 0.5;
    c.cy = c.y + cellW * 0.5;
  }

  // 1. Subtle outer archival paper grain
  drawPaperMarginTexture(margin);

  // 2. Render flat compartment grounds in color-grouped batches for watercolor cache efficiency
  drawCompartmentGrounds(cells);

  // 3. Render woven Tocapu warp-thread divider bands (cochineal-red & alpaca-cream)
  drawTocapuWarpGrid(margin, bandW, cellW);

  // 4. Render hyperreal botanical specimens inside each compartment
  for (let i = 0; i < cells.length; i++) {
    const c = cells[i];
    push();
    brush.clip([c.x + 2, c.y + 2, c.x + c.w - 2, c.y + c.h - 2]);
    if (c.type === "potato") {
      drawHyperrealPotato(c, i * 137 + 19);
    } else {
      drawHyperrealMaize(c, i * 251 + 73);
    }
    brush.noClip();
    pop();
  }

  // 5. Crisp inner compartment shadow & catalog frame finish
  drawCompartmentBevels(cells);

  noLoop();
}

// ============================================================================
// 1. PAPER MARGIN & COMPARTMENT GROUNDS
// ============================================================================

function drawPaperMarginTexture(margin) {
  brush.noFill();
  brush.noWash();
  brush.set("2H", "#cbbba0", 0.35);
  for (let i = 0; i < 220; i++) {
    let side = i % 4;
    let x1, y1, x2, y2;
    if (side === 0) {
      x1 = random(12, width - 12);
      y1 = random(10, margin - 4);
      x2 = x1 + random(-30, 30);
      y2 = y1 + random(-2, 2);
    } else if (side === 1) {
      x1 = random(12, width - 12);
      y1 = random(height - margin + 4, height - 10);
      x2 = x1 + random(-30, 30);
      y2 = y1 + random(-2, 2);
    } else if (side === 2) {
      x1 = random(10, margin - 4);
      y1 = random(12, height - 12);
      x2 = x1 + random(-2, 2);
      y2 = y1 + random(-30, 30);
    } else {
      x1 = random(width - margin + 4, width - 10);
      y1 = random(12, height - 12);
      x2 = x1 + random(-2, 2);
      y2 = y1 + random(-30, 30);
    }
    brush.line(x1, y1, x2, y2);
  }

  // Fine outer ruled catalog border
  brush.set("rotring", "#4a3b32", 0.45);
  brush.noFill();
  brush.rect(margin - 5, margin - 5, width - (margin - 5) * 2, height - (margin - 5) * 2, "corner");
}

function drawCompartmentGrounds(cells) {
  // Batch opaque base washes & subtle textured watercolor under-fills
  for (let c of cells) {
    brush.noStroke();
    brush.wash(c.bg, 242);
    brush.fill(c.bg, 95);
    brush.fillBleed(0.015, "in");
    brush.fillTexture(0.45, 0.25);
    brush.rect(c.x, c.y, c.w, c.h, "corner");
  }
  brush.noFill();
  brush.noWash();

  // Coloured-pencil vertical & diagonal woven tooth over each flat ground
  for (let c of cells) {
    let toothLight, toothDark;
    if (c.bgTone === "slate") {
      toothLight = "#383e47";
      toothDark = "#14171a";
    } else if (c.bgTone === "mustard") {
      toothLight = "#9e8550";
      toothDark = "#635029";
    } else {
      toothLight = "#7d4134";
      toothDark = "#471f17";
    }

    // Vertical warp-grain pencil hatching
    brush.noStroke();
    brush.hatchStyle("prismacolor", toothDark, 0.55);
    brush.hatch(5.5, 90, { rand: 0.025 });
    brush.rect(c.x + 2, c.y + 2, c.w - 4, c.h - 4, "corner");
    brush.noHatch();

    // Subtle horizontal weft-grain pass
    brush.hatchStyle("fine_pencil", toothLight, 0.42);
    brush.hatch(8.5, 0, { rand: 0.02 });
    brush.rect(c.x + 2, c.y + 2, c.w - 4, c.h - 4, "corner");
    brush.noHatch();

    // Soft overhead-light corner darkening (vignette) via fine diagonal pencil lines
    brush.set("prismacolor", toothDark, 0.5);
    for (let k = 0; k < 48; k++) {
      let d = map(k, 0, 48, 8, 75);
      // Top-left & top-right subtle corner grain
      brush.line(c.x + 2, c.y + d, c.x + d, c.y + 2);
      brush.line(c.x + c.w - d, c.y + 2, c.x + c.w - 2, c.y + d);
      // Bottom-left & bottom-right slightly deeper corner grain
      brush.line(c.x + 2, c.y + c.h - d, c.x + d, c.y + c.h - 2);
      brush.line(c.x + c.w - d, c.y + c.h - 2, c.x + c.w - 2, c.y + c.h - d);
    }
  }
}

// ============================================================================
// 2. WOVEN TOCAPU WARP-THREAD DIVIDERS (COCHINEAL-RED & ALPACA-CREAM)
// ============================================================================

function drawTocapuWarpGrid(margin, bandW, cellW) {
  const totalSpan = width - margin * 2;
  const bandPositions = [
    margin,
    margin + bandW + cellW,
    margin + (bandW + cellW) * 2,
    margin + (bandW + cellW) * 3
  ];

  // Fill the base of all 4 horizontal and 4 vertical warp bands with deep cochineal-red & cream stripes
  // Stripe offsets across the 24px band width:
  // [0..2]: obsidian selvedge, [2..7]: cochineal-red, [7..10.5]: alpaca-cream,
  // [10.5..13.5]: deep crimson core, [13.5..17]: alpaca-cream, [17..22]: cochineal-red, [22..24]: selvedge

  // Draw Horizontal Segments (between intersections)
  for (let r = 0; r < 4; r++) {
    let by = bandPositions[r];
    for (let c = 0; c < 3; c++) {
      let sx = bandPositions[c] + bandW;
      let sw = cellW;
      drawWarpBandSegment(sx, by, sw, bandW, true);
    }
  }

  // Draw Vertical Segments (between intersections)
  for (let c = 0; c < 4; c++) {
    let bx = bandPositions[c];
    for (let r = 0; r < 3; r++) {
      let sy = bandPositions[r] + bandW;
      let sh = cellW;
      drawWarpBandSegment(bx, sy, bandW, sh, false);
    }
  }

  // Draw the 16 Tocapu Woven Intersection Squares (24x24 px chacana / diamond locks)
  for (let r = 0; r < 4; r++) {
    for (let c = 0; c < 4; c++) {
      drawTocapuIntersection(bandPositions[c], bandPositions[r], bandW);
    }
  }
}

function drawWarpBandSegment(x, y, w, h, isHorizontal) {
  // Base wash in cochineal red
  brush.noStroke();
  brush.wash(PALETTE.cochineal, 245);
  brush.rect(x, y, w, h, "corner");
  brush.noWash();

  // Cream warp sub-bands
  brush.wash(PALETTE.cream, 245);
  if (isHorizontal) {
    brush.rect(x, y + 6.5, w, 3.8, "corner");
    brush.rect(x, y + 13.7, w, 3.8, "corner");
  } else {
    brush.rect(x + 6.5, y, 3.8, h, "corner");
    brush.rect(x + 13.7, y, 3.8, h, "corner");
  }
  brush.noWash();

  // Center deep crimson warp core
  brush.wash(PALETTE.cochinealDeep, 240);
  if (isHorizontal) {
    brush.rect(x, y + 10.3, w, 3.4, "corner");
  } else {
    brush.rect(x + 10.3, y, 3.4, h, "corner");
  }
  brush.noWash();

  // Woven warp-float texture (peinecillo alternating wool threads in coloured pencil)
  const step = 3.2;
  const span = isHorizontal ? w : h;
  const count = floor(span / step);

  for (let i = 0; i <= count; i++) {
    let t = i * step;
    let isEven = i % 2 === 0;

    if (isHorizontal) {
      let px = x + t;
      // Outer red warp ribs
      brush.set("fine_pencil", isEven ? PALETTE.cochinealBright : PALETTE.cochinealDeep, 0.65);
      brush.line(px, y + 1.8, px, y + 6.3);
      brush.line(px, y + 17.7, px, y + 22.2);

      // Alpaca-cream warp ribs with tiny cochineal peinecillo ticks
      brush.set("fine_pencil", isEven ? PALETTE.cream : "#cbb799", 0.65);
      brush.line(px, y + 6.6, px, y + 10.2);
      brush.line(px, y + 13.8, px, y + 17.4);

      // Alternating central geometric tic (Andean "kutij" motif)
      brush.set("fine_pencil", isEven ? PALETTE.cream : PALETTE.ochreLight, 0.6);
      if (i % 3 === 0) {
        brush.line(px, y + 10.6, px, y + 13.4);
      }
    } else {
      let py = y + t;
      brush.set("fine_pencil", isEven ? PALETTE.cochinealBright : PALETTE.cochinealDeep, 0.65);
      brush.line(x + 1.8, py, x + 6.3, py);
      brush.line(x + 17.7, py, x + 22.2, py);

      brush.set("fine_pencil", isEven ? PALETTE.cream : "#cbb799", 0.65);
      brush.line(x + 6.6, py, x + 10.2, py);
      brush.line(x + 13.8, py, x + 17.4, py);

      brush.set("fine_pencil", isEven ? PALETTE.cream : PALETTE.ochreLight, 0.6);
      if (i % 3 === 0) {
        brush.line(x + 10.6, py, x + 13.4, py);
      }
    }
  }

  // Crisp dark selvedge edge threads
  brush.set("rotring", "#1c1315", 0.55);
  if (isHorizontal) {
    brush.line(x, y + 0.8, x + w, y + 0.8);
    brush.line(x, y + h - 0.8, x + w, y + h - 0.8);
    brush.set("fine_pencil", PALETTE.creamDark, 0.4);
    brush.line(x, y + 6.5, x + w, y + 6.5);
    brush.line(x, y + 17.5, x + w, y + 17.5);
  } else {
    brush.line(x + 0.8, y, x + 0.8, y + h);
    brush.line(x + w - 0.8, y, x + w - 0.8, y + h);
    brush.set("fine_pencil", PALETTE.creamDark, 0.4);
    brush.line(x + 6.5, y, x + 6.5, y + h);
    brush.line(x + 17.5, y, x + 17.5, y + h);
  }
}

function drawTocapuIntersection(x, y, s) {
  // Mini woven Tocapu block at warp/weft crossings
  brush.noStroke();
  brush.wash(PALETTE.cochinealDeep, 250);
  brush.rect(x, y, s, s, "corner");

  brush.wash(PALETTE.cream, 245);
  brush.rect(x + 3.5, y + 3.5, s - 7, s - 7, "corner");

  brush.wash(PALETTE.cochineal, 250);
  brush.rect(x + 6.8, y + 6.8, s - 13.6, s - 13.6, "corner");

  brush.wash(PALETTE.ochreLight, 245);
  brush.rect(x + 9.8, y + 9.8, s - 19.6, s - 19.6, "corner");
  brush.noWash();

  // Crisscross diagonal warp stitches
  brush.set("fine_pencil", "#1c1315", 0.5);
  brush.noFill();
  brush.rect(x + 0.8, y + 0.8, s - 1.6, s - 1.6, "corner");
  brush.rect(x + 3.5, y + 3.5, s - 7, s - 7, "corner");
  brush.rect(x + 6.8, y + 6.8, s - 13.6, s - 13.6, "corner");

  brush.set("fine_pencil", PALETTE.cochineal, 0.55);
  brush.line(x + 3.5, y + 12, x + s - 3.5, y + 12);
  brush.line(x + 12, y + 3.5, x + 12, y + s - 3.5);
}

function drawCompartmentBevels(cells) {
  brush.noFill();
  brush.noWash();
  for (let c of cells) {
    // Inner shadow line along top & left to recess the compartment beneath the warp bands
    brush.set("fine_pencil", "#120f11", 0.65);
    brush.line(c.x + 1, c.y + 1.2, c.x + c.w - 1, c.y + 1.2);
    brush.line(c.x + 1.2, c.y + 1, c.x + 1.2, c.y + c.h - 1);

    // Subtle warm catchlight along bottom & right inner edge
    brush.set("fine_pencil", PALETTE.creamDark, 0.4);
    brush.line(c.x + 1.5, c.y + c.h - 1.2, c.x + c.w - 1, c.y + c.h - 1.2);
    brush.line(c.x + c.w - 1.2, c.y + 1.5, c.x + c.w - 1.2, c.y + c.h - 1);
  }
}

// ============================================================================
// 3. HYPERREAL ANDEAN POTATOES (PAPAS NATIVAS)
// ============================================================================

function getPotatoConfig(variant) {
  if (variant === "huamantanga") {
    // Purple-black with bold golden-ochre bicolor patches & ruby eyes
    return {
      rx: 108, ry: 88, tilt: -14,
      lobeFreq: 3, lobeAmp: 0.08,
      elongation: 1.0, curve: 0.04,
      baseDark: "#18101c", baseMid: "#331e38", baseLight: "#59385e",
      patchColorDark: "#7a531c", patchColorMid: "#b88433", patchColorLight: "#e0b35e",
      hasPatches: true, patchThresh: 0.51,
      eyeRimCol: "#8f1923", eyeBudCol: "#d93843", eyeSocketCol: "#12090e",
      highlightCol: "#e8d7c5",
      soilAmount: 1.0,
      eyeCount: 9
    };
  } else if (variant === "leona") {
    // Knobby round deep obsidian-violet tuber with pale cream-ochre eyes & heavy mountain soil
    return {
      rx: 102, ry: 98, tilt: 11,
      lobeFreq: 4, lobeAmp: 0.11,
      elongation: 0.96, curve: -0.02,
      baseDark: "#0e0c14", baseMid: "#211b2e", baseLight: "#433957",
      patchColorDark: "#4f1422", patchColorMid: "#781d31", patchColorLight: "#9c3046",
      hasPatches: true, patchThresh: 0.62,
      eyeRimCol: "#36273d", eyeBudCol: "#e3c478", eyeSocketCol: "#09070c",
      highlightCol: "#d5cee0",
      soilAmount: 1.35,
      eyeCount: 11
    };
  } else if (variant === "pina") {
    // Centerpiece: Papa Piña / Todosantos - pinecone-knobby cochineal-red & ochre-marbled tuber
    return {
      rx: 88, ry: 122, tilt: 18,
      lobeFreq: 5, lobeAmp: 0.125,
      elongation: 1.15, curve: 0.07,
      baseDark: "#3d0910", baseMid: "#821621", baseLight: "#b82834",
      patchColorDark: "#805a22", patchColorMid: "#c29240", patchColorLight: "#ebd594",
      hasPatches: true, patchThresh: 0.48,
      eyeRimCol: "#4a0a10", eyeBudCol: "#f0d584", eyeSocketCol: "#1f0407",
      highlightCol: "#f5e3d3",
      soilAmount: 0.95,
      eyeCount: 14
    };
  } else if (variant === "huayro") {
    // Elongated blood-crimson & dark mahogany segmented tuber
    return {
      rx: 82, ry: 120, tilt: -22,
      lobeFreq: 4, lobeAmp: 0.09,
      elongation: 1.12, curve: -0.08,
      baseDark: "#29070c", baseMid: "#66121b", baseLight: "#9e202b",
      patchColorDark: "#1c1217", patchColorMid: "#362028", patchColorLight: "#54343f",
      hasPatches: true, patchThresh: 0.58,
      eyeRimCol: "#38070c", eyeBudCol: "#d99b38", eyeSocketCol: "#140305",
      highlightCol: "#edd0cb",
      soilAmount: 0.85,
      eyeCount: 10
    };
  } else {
    // "qompis": Russet-ochre & dusty slate-brown crusted tuber with rosy cochineal eyes
    return {
      rx: 110, ry: 90, tilt: 8,
      lobeFreq: 3, lobeAmp: 0.095,
      elongation: 1.0, curve: 0.03,
      baseDark: "#332619", baseMid: "#6e5538", baseLight: "#ab895c",
      patchColorDark: "#452f24", patchColorMid: "#8a6845", patchColorLight: "#cfa974",
      hasPatches: true, patchThresh: 0.46,
      eyeRimCol: "#7d1b24", eyeBudCol: "#d13b47", eyeSocketCol: "#1f140e",
      highlightCol: "#f2e5ce",
      soilAmount: 1.45,
      eyeCount: 10
    };
  }
}

function drawHyperrealPotato(cell, seedOffset) {
  randomSeed(SEED + seedOffset);
  noiseSeed(SEED + seedOffset);

  const cfg = getPotatoConfig(cell.variant);
  const cx = cell.cx;
  const cy = cell.cy - 4;
  const cosT = cos(cfg.tilt);
  const sinT = sin(cfg.tilt);

  // Generate 3D lobes (low-frequency bulges) and eyes (recessed crescent craters)
  const lobes = [];
  for (let i = 0; i < 6; i++) {
    lobes.push({
      lx: random(-0.55, 0.55) * cfg.rx,
      ly: random(-0.55, 0.55) * cfg.ry,
      rad: random(0.42, 0.68) * max(cfg.rx, cfg.ry),
      amp: random(0.08, 0.2)
    });
  }

  // Distribute recessed potato eyes in a natural phyllotactic spiral (more crowded near crown)
  const eyes = [];
  for (let i = 0; i < cfg.eyeCount; i++) {
    let frac = (i + 0.5) / cfg.eyeCount;
    let ly = map(frac, 0, 1, -cfg.ry * 0.72, cfg.ry * 0.68);
    let maxW = sqrt(max(0.05, 1 - sq(ly / cfg.ry))) * cfg.rx * 0.76;
    let goldenAngle = i * 137.5 + random(-14, 14);
    let lx = sin(goldenAngle) * maxW * random(0.35, 0.92);
    let w = random(13, 21);
    let h = random(7, 11);
    let eyeAngle = atan2(ly * 0.35, lx) * 0.25 + random(-12, 12);
    eyes.push({ lx, ly, w, h, angle: eyeAngle, depth: random(0.24, 0.38) });
  }

  // Helper: convert local (lx, ly) to world (wx, wy)
  function toWorld(lx, ly) {
    // Apply slight banana/crescent curve
    let bendX = lx + cfg.curve * (ly * ly) / cfg.ry * 0.6;
    return {
      x: cx + bendX * cosT - ly * sinT,
      y: cy + bendX * sinT + ly * cosT
    };
  }

  // Helper: radial boundary distance at local angle a (degrees)
  function boundaryRadius(a) {
    let nx = cos(a);
    let ny = sin(a);
    let baseR = 1 / sqrt(sq(nx / cfg.rx) + sq(ny / cfg.ry));
    let nVal = noise(nx * 1.6 + 10, ny * 1.6 + 10);
    let lobeMod = 1 + cfg.lobeAmp * sin(a * cfg.lobeFreq + 35) + (nVal - 0.5) * 0.16;

    // Slight indentation where eyes approach the silhouette edge
    let px = nx * baseR * lobeMod;
    let py = ny * baseR * lobeMod;
    let eyeDip = 0;
    for (let e of eyes) {
      let d = dist(px, py, e.lx, e.ly);
      if (d < e.w * 1.8) {
        eyeDip += 0.045 * exp(-sq(d / (e.w * 0.95)));
      }
    }
    return baseR * (lobeMod - eyeDip);
  }

  // Helper: evaluate 3D height z(lx, ly) and surface normal at local coords
  function evalSurface(lx, ly) {
    let a = atan2(ly, lx);
    let maxR = boundaryRadius(a);
    let r = sqrt(lx * lx + ly * ly);
    let u = r / maxR;
    if (u >= 0.995) return null;

    // Base hemisphere dome
    let z = sqrt(max(0.001, 1 - u * u)) * 75;

    // Add organic lobe bulges
    for (let lb of lobes) {
      let d2 = sq(lx - lb.lx) + sq(ly - lb.ly);
      z += lb.amp * 28 * exp(-d2 / sq(lb.rad));
    }

    // Subtract recessed eye craters and add lower brow ridge
    let inEye = 0;
    for (let e of eyes) {
      let dx = lx - e.lx;
      let dy = ly - e.ly;
      let ca = cos(-e.angle);
      let sa = sin(-e.angle);
      let ex = (dx * ca - dy * sa) / e.w;
      let ey = (dx * sa + dy * ca) / e.h;
      let ed2 = ex * ex + ey * ey;
      if (ed2 < 3.2) {
        let crater = exp(-ed2 * 1.55);
        z -= e.depth * 34 * crater;
        // Raised brow lip just below the eye slit
        let browY = ey - 0.78;
        let brow = exp(-(ex * ex * 1.2 + browY * browY * 3.8));
        z += e.depth * 14 * brow;
        inEye = max(inEye, crater);
      }
    }

    return { z, u, inEye };
  }

  // 1. Ground Cast Shadow (Even Overhead Light -> tight dark occlusion + soft penumbra below)
  const shadowVerts = [];
  const shadowCoreVerts = [];
  for (let a = 0; a < 360; a += 8) {
    let r = boundaryRadius(a);
    let lx = cos(a) * r;
    let ly = sin(a) * r;
    let wp = toWorld(lx, ly);
    // Overhead light shifts shadow slightly downward (+y) and compresses it vertically
    shadowVerts.push([wp.x + 3, wp.y + 16 + sin(a) * 5]);
    shadowCoreVerts.push([wp.x * 0.92 + cx * 0.08 + 1, wp.y * 0.92 + (cy + 12) * 0.08 + 10]);
  }

  // Soft outer shadow wash
  brush.noStroke();
  brush.fill("#0b090c", 115);
  brush.fillBleed(0.18, "out");
  brush.fillTexture(0.5, 0.2);
  brush.beginShape(0.4);
  for (let v of shadowVerts) brush.vertex(v[0], v[1]);
  brush.endShape(true);

  // Tight occlusion shadow right beneath tuber
  brush.fill("#060507", 170);
  brush.fillBleed(0.06, "out");
  brush.beginShape(0.4);
  for (let v of shadowCoreVerts) brush.vertex(v[0], v[1]);
  brush.endShape(true);
  brush.noFill();

  // Coloured-pencil cross-hatched shadow bed on the compartment floor
  brush.set("prismacolor", "#0b090c", 0.65);
  for (let i = 0; i < 65; i++) {
    let a = random(15, 165);
    let r = boundaryRadius(a) * random(0.75, 1.06);
    let wp = toWorld(cos(a) * r, sin(a) * r);
    let len = random(10, 26);
    brush.line(wp.x - len * 0.5, wp.y + random(4, 15), wp.x + len * 0.5, wp.y + random(4, 15));
  }

  // 2. Potato Base Underpainting (Opaque wash + textured fill inside silhouette)
  const outlinePts = [];
  for (let a = 0; a < 360; a += 5) {
    let r = boundaryRadius(a);
    let wp = toWorld(cos(a) * r, sin(a) * r);
    outlinePts.push(wp);
  }

  brush.noStroke();
  brush.wash(cfg.baseDark, 245);
  brush.fill(cfg.baseMid, 145);
  brush.fillBleed(0.02, "in");
  brush.fillTexture(0.55, 0.35);
  brush.beginShape(0.35);
  for (let p of outlinePts) brush.vertex(p.x, p.y);
  brush.endShape(true);
  brush.noFill();
  brush.noWash();

  // 3. Dense Coloured-Pencil Cross-Contour Form Layering
  // Sample points across the tuber, compute 3D normal & cross-contour tangent, and lay down layered strokes
  const step = 4.6;
  const eps = 2.2;
  // Overhead slightly front-top-left light vector
  const Lx = -0.18, Ly = -0.45, Lz = 0.875;

  for (let ly = -cfg.ry * 1.12; ly <= cfg.ry * 1.12; ly += step) {
    for (let lx = -cfg.rx * 1.12; lx <= cfg.rx * 1.12; lx += step) {
      let jx = lx + random(-1.6, 1.6);
      let jy = ly + random(-1.6, 1.6);
      let s0 = evalSurface(jx, jy);
      if (!s0) continue;

      let sx1 = evalSurface(jx + eps, jy);
      let sy1 = evalSurface(jx, jy + eps);
      let dzdx = sx1 ? (sx1.z - s0.z) / eps : -jx * 0.5;
      let dzdy = sy1 ? (sy1.z - s0.z) / eps : -jy * 0.5;

      // World-space surface normal
      let gwx = dzdx * cosT - dzdy * sinT;
      let gwy = dzdx * sinT + dzdy * cosT;
      let invLen = 1 / sqrt(gwx * gwx + gwy * gwy + 1);
      let nx = -gwx * invLen;
      let ny = -gwy * invLen;
      let nz = invLen;

      // Diffuse illumination + edge fresnel darkening + bottom reflected ground bounce
      let diff = max(0, nx * Lx + ny * Ly + nz * Lz);
      let rimBounce = max(0, ny) * pow(s0.u, 2.2) * 0.28;
      let lightVal = constrain(diff * 0.88 + nz * 0.16 - pow(s0.u, 3.2) * 0.25, 0, 1);

      // Determine skin pigmentation (base vs bicolor ochre/cochineal patch)
      let patchNoise = noise(jx * 0.022 + 50, jy * 0.022 + 50) * 0.7 +
                       noise(jx * 0.065 + 120, jy * 0.065 + 120) * 0.3;
      let isPatch = cfg.hasPatches && (patchNoise > cfg.patchThresh);

      let colDark = isPatch ? cfg.patchColorDark : cfg.baseDark;
      let colMid = isPatch ? cfg.patchColorMid : cfg.baseMid;
      let colLight = isPatch ? cfg.patchColorLight : cfg.baseLight;

      let strokeCol;
      if (s0.inEye > 0.35) {
        strokeCol = cfg.eyeSocketCol;
      } else if (lightVal < 0.38) {
        strokeCol = lerpColor(color(colDark), color(colMid), map(lightVal, 0, 0.38, 0, 1));
      } else if (lightVal < 0.76) {
        strokeCol = lerpColor(color(colMid), color(colLight), map(lightVal, 0.38, 0.76, 0, 1));
      } else {
        strokeCol = lerpColor(color(colLight), color(cfg.highlightCol), map(lightVal, 0.76, 1.0, 0, 0.75));
      }

      // Cross-contour stroke angle follows the 3D surface curvature perpendicular to gradient
      let contourAng = atan2(ny, nx) + 90 + random(-8, 8);
      let wp = toWorld(jx, jy);
      let strokeLen = map(s0.u, 0, 1, 10.5, 5.5) * random(0.8, 1.2);
      let dx = cos(contourAng) * strokeLen * 0.5;
      let dy = sin(contourAng) * strokeLen * 0.5;

      // Primary cross-contour coloured-pencil stroke
      brush.set("prismacolor", strokeCol, random(0.65, 1.05));
      brush.line(wp.x - dx, wp.y - dy, wp.x + dx, wp.y + dy);

      // Secondary cross-hatch stroke for dense pigment tooth
      if (random() < 0.68) {
        let crossAng = contourAng + (lightVal < 0.45 ? 38 : -28);
        let cdx = cos(crossAng) * strokeLen * 0.42;
        let cdy = sin(crossAng) * strokeLen * 0.42;
        brush.set("fine_pencil", strokeCol, random(0.55, 0.85));
        brush.line(wp.x - cdx, wp.y - cdy, wp.x + cdx, wp.y + cdy);
      }

      // Specular waxy sheen on top-facing domes
      if (lightVal > 0.81 && s0.inEye < 0.15 && random() < 0.55) {
        brush.set("wax_burnish", cfg.highlightCol, random(0.45, 0.8));
        brush.line(wp.x - dx * 0.6, wp.y - dy * 0.6, wp.x + dx * 0.6, wp.y + dy * 0.6);
      }

      // Subtle reflected compartment color along the bottom rim
      if (rimBounce > 0.09 && ny > 0.35 && random() < 0.5) {
        let bounceCol = cell.bgTone === "mustard" ? PALETTE.ochre :
                        cell.bgTone === "terracotta" ? PALETTE.cochineal : "#5b6573";
        brush.set("prismacolor", bounceCol, 0.5);
        brush.line(wp.x - dx * 0.7, wp.y - dy * 0.7, wp.x + dx * 0.7, wp.y + dy * 0.7);
      }
    }
  }

  // 4. Detailed Recessed Potato Eyes (Dormant Buds, Scale Leaf Scars & Brow Ridges)
  for (let e of eyes) {
    let rCheck = boundaryRadius(atan2(e.ly, e.lx));
    if (sqrt(e.lx * e.lx + e.ly * e.ly) > rCheck * 0.88) continue;

    let ep = toWorld(e.lx, e.ly);
    let ang = cfg.tilt + e.angle;
    let ca = cos(ang);
    let sa = sin(ang);
    let ew = e.w;
    let eh = e.h;

    // Deep crescent shadow slit
    brush.set("fine_pencil", cfg.eyeSocketCol, 0.95);
    for (let k = -4; k <= 4; k++) {
      let t = k / 4;
      let x1 = ep.x + (-ew * 0.85) * ca - (t * eh * 0.35) * sa;
      let y1 = ep.y + (-ew * 0.85) * sa + (t * eh * 0.35) * ca;
      let x2 = ep.x + (ew * 0.85) * ca - (t * eh * 0.35) * sa;
      let y2 = ep.y + (ew * 0.85) * sa + (t * eh * 0.35) * ca;
      let midX = ep.x - (eh * 0.45 + t * 2) * sa;
      let midY = ep.y + (eh * 0.45 + t * 2) * ca;
      brush.spline([[x1, y1, 0.4], [midX, midY, 1.1], [x2, y2, 0.4]], 0.5);
    }

    // Cochineal / violet blushing around the eye rim
    brush.set("prismacolor", cfg.eyeRimCol, 0.75);
    for (let k = 0; k < 14; k++) {
      let a = map(k, 0, 13, -165, 165);
      let rx1 = cos(a) * ew * 0.75;
      let ry1 = sin(a) * eh * 0.65;
      let rx2 = cos(a) * ew * 1.18;
      let ry2 = sin(a) * eh * 1.08;
      let p1x = ep.x + rx1 * ca - ry1 * sa;
      let p1y = ep.y + rx1 * sa + ry1 * ca;
      let p2x = ep.x + rx2 * ca - ry2 * sa;
      let p2y = ep.y + rx2 * sa + ry2 * ca;
      brush.line(p1x, p1y, p2x, p2y);
    }

    // Illuminated lower brow ridge (scale-leaf scar catching the overhead light)
    brush.set("wax_burnish", cfg.highlightCol, 0.6);
    let bx1 = ep.x + (-ew * 0.75) * ca - (eh * 0.72) * sa;
    let by1 = ep.y + (-ew * 0.75) * sa + (eh * 0.72) * ca;
    let bmx = ep.x - (eh * 0.95) * sa;
    let bmy = ep.y + (eh * 0.95) * ca;
    let bx2 = ep.x + (ew * 0.75) * ca - (eh * 0.72) * sa;
    let by2 = ep.y + (ew * 0.75) * sa + (eh * 0.72) * ca;
    brush.spline([[bx1, by1, 0.3], [bmx, bmy, 0.95], [bx2, by2, 0.3]], 0.5);

    // Dormant meristem buds glowing inside the recessed socket (1 to 3 tiny nodules)
    let budCount = floor(random(1, 3.5));
    for (let b = 0; b < budCount; b++) {
      let boff = (b - (budCount - 1) * 0.5) * 5.5;
      let bx = ep.x + boff * ca;
      let by = ep.y + boff * sa;
      brush.set("wax_burnish", cfg.eyeBudCol, 0.75);
      brush.line(bx - 1.8, by + 0.5, bx + 1.8, by - 1.2);
      brush.set("fine_pencil", PALETTE.cream, 0.55);
      brush.line(bx - 0.8, by - 0.8, bx + 0.8, by - 1.5);
    }
  }

  // 5. Corky Lenticels, Periderm Skin Cracks, and Clinging Andean Soil Grit
  // Lenticels (tiny pale breathing pores across skin)
  for (let i = 0; i < 115; i++) {
    let a = random(360);
    let r = boundaryRadius(a) * sqrt(random(0.05, 0.88));
    let wp = toWorld(cos(a) * r, sin(a) * r);
    brush.set("fine_pencil", random() < 0.5 ? PALETTE.ochreLight : PALETTE.soilLight, 0.5);
    brush.line(wp.x - 0.9, wp.y, wp.x + 0.9, wp.y + 0.4);
  }

  // Clinging dry soil grit (clustered around eyes, lower flanks, and scattered on floor below)
  const gritCount = floor(180 * cfg.soilAmount);
  for (let i = 0; i < gritCount; i++) {
    let gx, gy;
    if (i < gritCount * 0.45) {
      // Clustered in and around recessed eyes
      let e = random(eyes);
      let ep = toWorld(e.lx + random(-e.w, e.w), e.ly + random(-e.h, e.h));
      gx = ep.x;
      gy = ep.y;
    } else if (i < gritCount * 0.82) {
      // Lower flank soil crust
      let a = random(360);
      let r = boundaryRadius(a) * random(0.45, 0.97);
      let wp = toWorld(cos(a) * r, sin(a) * r);
      gx = wp.x;
      gy = wp.y;
    } else {
      // Fallen soil crumbs on the flat compartment surface just below the tuber
      let a = random(20, 160);
      let r = boundaryRadius(a) * random(0.95, 1.18);
      let wp = toWorld(cos(a) * r, sin(a) * r);
      gx = wp.x + random(-8, 8);
      gy = wp.y + random(4, 18);
    }

    let gritCol = random() < 0.45 ? PALETTE.soilLight :
                  random() < 0.75 ? PALETTE.soilMid : PALETTE.soilDark;
    brush.set("fine_pencil", gritCol, random(0.5, 0.9));
    let gl = random(1.0, 2.8);
    let ga = random(360);
    brush.line(gx, gy, gx + cos(ga) * gl, gy + sin(ga) * gl);
  }

  // 6. Crisp Botanical Silhouette Contour & Stolon Scar
  for (let i = 0; i < outlinePts.length; i++) {
    let p1 = outlinePts[i];
    let p2 = outlinePts[(i + 1) % outlinePts.length];
    let isBottom = p1.y > cy;
    brush.set("fine_pencil", isBottom ? "#08060a" : cfg.baseDark, isBottom ? 0.85 : 0.6);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }
}

// ============================================================================
// 4. HYPERREAL ANDEAN MAIZE COBS (CHOCLO / MAÍZ NATIVO)
// ============================================================================

function getMaizeConfig(variant) {
  if (variant === "sangre") {
    // Blood-red & mahogany glossy Maíz Sangre de Cristo
    return {
      rx: 74, ry: 122, tilt: 6,
      rows: 13, cols: 9,
      chaffCol: "#4a1518",
      shankCol: "#b89b6a",
      silkCol: "#8c2327",
      paletteMode: "sangre"
    };
  } else if (variant === "morado") {
    // Black-kerneled Maíz Morado / Kculli with deep plum-crimson subsurface glow
    return {
      rx: 76, ry: 120, tilt: -5,
      rows: 13, cols: 9,
      chaffCol: "#3b1124",
      shankCol: "#785749",
      silkCol: "#a88254",
      paletteMode: "morado"
    };
  } else if (variant === "piscorunto") {
    // Ochre-cream large Cuzco kernels speckled with dark slate-purple & cochineal
    return {
      rx: 80, ry: 118, tilt: 5,
      rows: 11, cols: 8, // Giant Cuzco kernels!
      chaffCol: "#6e4e32",
      shankCol: "#c9ad79",
      silkCol: "#732029",
      paletteMode: "piscorunto"
    };
  } else {
    // "chullpi": Jewel mosaic cob (obsidian, ochre, alpaca-cream, and cochineal-red kernels)
    return {
      rx: 75, ry: 122, tilt: -6,
      rows: 14, cols: 9,
      chaffCol: "#4f3224",
      shankCol: "#bfa16f",
      silkCol: "#9e242b",
      paletteMode: "chullpi"
    };
  }
}

function getKernelColors(mode, r, c) {
  let n = noise(r * 0.45 + 10, c * 0.45 + 10);
  let rnd = random();

  if (mode === "sangre") {
    if (rnd < 0.25) {
      return {
        dark: "#260407", mid: "#5c0b12", bright: "#961b24",
        crown: "#c4353f", highlight: "#f7d5d0", speckles: false
      };
    } else if (rnd < 0.78) {
      return {
        dark: "#36070c", mid: "#7d131c", bright: "#b82530",
        crown: "#de4b49", highlight: "#fae2dc", speckles: rnd < 0.45,
        speckleCol: "#2b0508"
      };
    } else {
      // Warm ruby-ochre flame kernel
      return {
        dark: "#420b10", mid: "#8f1d24", bright: "#cf5334",
        crown: "#e69a4c", highlight: "#fcf0d9", speckles: true,
        speckleCol: "#4a080e"
      };
    }
  } else if (mode === "morado") {
    if (rnd < 0.65) {
      return {
        dark: "#08060a", mid: "#17111f", bright: "#322240",
        crown: "#4d2c59", highlight: "#ded5e8", speckles: false
      };
    } else {
      // Deep blood-plum kernel
      return {
        dark: "#12070e", mid: "#2e1122", bright: "#591d38",
        crown: "#7a2c49", highlight: "#ebd8e2", speckles: false
      };
    }
  } else if (mode === "piscorunto") {
    if (rnd < 0.16) {
      // Solid deep slate-purple accent kernel among the speckled ochre ones
      return {
        dark: "#140d1c", mid: "#2b1d38", bright: "#4c355e",
        crown: "#6b4f7d", highlight: "#e8dff0", speckles: true,
        speckleCol: "#d9b872"
      };
    } else {
      // Classic ochre-cream kernel heavily speckled with purple-black & cochineal
      return {
        dark: "#634821", mid: "#ab8443", bright: "#d9b671",
        crown: "#edd49a", highlight: "#fff8e8", speckles: true,
        speckleCol: rnd < 0.55 ? "#211429" : "#821720"
      };
    }
  } else {
    // "chullpi": Mosaic of obsidian, cochineal-red, golden-ochre, and bone-cream
    if (rnd < 0.32) {
      return {
        dark: "#0d0b12", mid: "#1f1a29", bright: "#3d344f",
        crown: "#594d6e", highlight: "#e2dce8", speckles: false
      };
    } else if (rnd < 0.62) {
      return {
        dark: "#36080d", mid: "#7a141e", bright: "#b52632",
        crown: "#d94848", highlight: "#fae0dc", speckles: false
      };
    } else if (rnd < 0.85) {
      return {
        dark: "#593b14", mid: "#9e712b", bright: "#cfa048",
        crown: "#e8c26b", highlight: "#fff5db", speckles: true,
        speckleCol: "#6e151c"
      };
    } else {
      return {
        dark: "#5e503d", mid: "#9e8b70", bright: "#cfc0a5",
        crown: "#e8dec8", highlight: "#ffffff", speckles: true,
        speckleCol: "#241926"
      };
    }
  }
}

function drawHyperrealMaize(cell, seedOffset) {
  randomSeed(SEED + seedOffset);
  noiseSeed(SEED + seedOffset);

  const cfg = getMaizeConfig(cell.variant);
  const cx = cell.cx;
  const cy = cell.cy - 6;
  const cosT = cos(cfg.tilt);
  const sinT = sin(cfg.tilt);

  function toWorld(lx, ly) {
    return {
      x: cx + lx * cosT - ly * sinT,
      y: cy + lx * sinT + ly * cosT
    };
  }

  // Tapered cob silhouette width profile for v in [0 (top crown) .. 1 (bottom base)]
  function cobRadiusAt(v) {
    // Plump barrel tapering cleanly at top crown and gently at base
    let topTaper = pow(constrain(v / 0.24, 0, 1), 0.52);
    let botTaper = pow(constrain((1 - v) / 0.16, 0, 1), 0.42);
    let belly = 0.88 + 0.16 * sin(v * 165);
    if (v < 0.24) return cfg.rx * topTaper * belly;
    if (v > 0.84) return cfg.rx * botTaper * belly;
    return cfg.rx * belly;
  }

  // 1. Cast Shadow on Compartment Floor (Even Overhead Light)
  const shPts = [];
  for (let i = 0; i <= 24; i++) {
    let v = i / 24;
    let ly = map(v, 0, 1, -cfg.ry, cfg.ry);
    let r = cobRadiusAt(v);
    let wp = toWorld(r + 4, ly + 15);
    shPts.push([wp.x, wp.y]);
  }
  for (let i = 24; i >= 0; i--) {
    let v = i / 24;
    let ly = map(v, 0, 1, -cfg.ry, cfg.ry);
    let r = cobRadiusAt(v);
    let wp = toWorld(-r + 2, ly + 15);
    shPts.push([wp.x, wp.y]);
  }

  brush.noStroke();
  brush.fill("#09080b", 125);
  brush.fillBleed(0.14, "out");
  brush.fillTexture(0.45, 0.2);
  brush.beginShape(0.35);
  for (let p of shPts) brush.vertex(p[0], p[1]);
  brush.endShape(true);
  brush.noFill();

  // Coloured-pencil shadow bed hatching around base and flanks
  brush.set("prismacolor", "#0b090d", 0.6);
  for (let i = 0; i < 60; i++) {
    let v = random(0.15, 1.02);
    let ly = map(v, 0, 1, -cfg.ry, cfg.ry);
    let r = cobRadiusAt(constrain(v, 0, 1));
    let side = random() < 0.5 ? -1 : 1;
    let wp = toWorld(side * r * random(0.85, 1.08), ly + random(6, 16));
    brush.line(wp.x - 9, wp.y, wp.x + 9, wp.y);
  }

  // 2. Woody Pedicel / Shank & Dried Husk Bract Remnants at Base
  drawCobShankAndHusks(toWorld, cfg);

  // 3. Dark Alveolar Cob Core Underpainting (fills crevices between kernels)
  const corePts = [];
  for (let i = 0; i <= 20; i++) {
    let v = i / 20;
    let ly = map(v, 0, 1, -cfg.ry, cfg.ry);
    let wp = toWorld(cobRadiusAt(v) * 0.96, ly);
    corePts.push(wp);
  }
  for (let i = 20; i >= 0; i--) {
    let v = i / 20;
    let ly = map(v, 0, 1, -cfg.ry, cfg.ry);
    let wp = toWorld(-cobRadiusAt(v) * 0.96, ly);
    corePts.push(wp);
  }

  brush.noStroke();
  brush.wash("#140b0e", 248);
  brush.fill(cfg.chaffCol, 150);
  brush.fillBleed(0.02, "in");
  brush.beginShape(0.3);
  for (let p of corePts) brush.vertex(p.x, p.y);
  brush.endShape(true);
  brush.noFill();
  brush.noWash();

  // 4. Generate 3D Plump Kernels on the Cylinder Surface
  // Pick 1 or 2 recessed sockets where a kernel was shelled out to expose papery glumes!
  const missingRow = floor(cfg.rows * 0.55);
  const missingCol = floor(cfg.cols * 0.45);
  const kernels = [];

  for (let r = 0; r < cfg.rows; r++) {
    let v0 = (r + 0.12) / cfg.rows;
    let v1 = (r + 0.92) / cfg.rows;
    let vc = (v0 + v1) * 0.5;
    let ly0 = map(v0, 0, 1, -cfg.ry, cfg.ry);
    let ly1 = map(v1, 0, 1, -cfg.ry, cfg.ry);
    let kh = (ly1 - ly0) * 1.08;
    let cobR = cobRadiusAt(vc);

    // Fewer columns at the very top apex
    let activeCols = r === 0 ? max(5, cfg.cols - 2) : (r === 1 ? cfg.cols - 1 : cfg.cols);

    for (let c = 0; c < activeCols; c++) {
      // Cylindrical angle phi in [-82 deg .. +82 deg]
      let stagger = (r % 2 === 0 ? -0.18 : 0.18) / activeCols;
      let u0 = (c / activeCols) + stagger;
      let u1 = ((c + 1) / activeCols) + stagger;
      let phi0 = map(constrain(u0, 0, 1), 0, 1, -84, 84);
      let phi1 = map(constrain(u1, 0, 1), 0, 1, -84, 84);
      let phiC = (phi0 + phi1) * 0.5;

      let lx0 = sin(phi0) * cobR;
      let lx1 = sin(phi1) * cobR;
      let kw = abs(lx1 - lx0) * 1.06;
      if (kw < 3.5) continue;

      let lxC = (lx0 + lx1) * 0.5;
      let lyC = (ly0 + ly1) * 0.5 + (c % 2 === 0 ? -0.8 : 0.8) + cos(phiC) * 2.5;
      let depthSort = cos(phiC) - abs(vc - 0.45) * 0.15;

      kernels.push({
        r, c, vc, phiC,
        lx: lxC, ly: lyC,
        kw, kh,
        depthSort,
        isMissing: (r === missingRow && c === missingCol),
        kCols: getKernelColors(cfg.paletteMode, r, c)
      });
    }
  }

  // Sort kernels back-to-front (outer edges first, front-center last) so overlapping is 3D accurate
  kernels.sort((a, b) => a.depthSort - b.depthSort);

  for (let k of kernels) {
    if (k.isMissing) {
      drawEmptyKernelSocket(k, toWorld, cfg);
    } else {
      drawSingleKernel(k, toWorld, cfg);
    }
  }

  // 5. Twisted Corn Silk Strands at Crown & Loose Fallen Kernel Beside Base
  drawCornSilkCrown(toWorld, cfg);
  drawLooseFallenKernel(cell, toWorld, cfg);
}

function drawSingleKernel(k, toWorld, cfg) {
  const { lx, ly, kw, kh, phiC, vc, kCols } = k;
  const hw = kw * 0.5;
  const hh = kh * 0.5;

  // Global cylinder lighting factor (overhead + front illumination)
  const cylNx = sin(phiC);
  const cylNz = cos(phiC);
  const cylNy = map(vc, 0, 1, -0.55, 0.48);
  const globalLight = constrain(cylNz * 0.68 - cylNy * 0.35 - cylNx * 0.15 + 0.15, 0.12, 1.0);

  // 1. Deep alveolar shadow crease around kernel perimeter
  const kPts = [
    toWorld(lx - hw * 0.72, ly + hh * 0.92), // bottom-left base
    toWorld(lx - hw * 1.02, ly - hh * 0.12), // mid-left shoulder
    toWorld(lx - hw * 0.58, ly - hh * 0.92), // top-left crown
    toWorld(lx + hw * 0.58, ly - hh * 0.92), // top-right crown
    toWorld(lx + hw * 1.02, ly - hh * 0.12), // mid-right shoulder
    toWorld(lx + hw * 0.72, ly + hh * 0.92)  // bottom-right base
  ];

  brush.set("fine_pencil", "#090508", 0.9);
  brush.beginShape(0.45);
  for (let p of kPts) brush.vertex(p.x, p.y);
  brush.endShape(true);

  // Papery chaff glume scale peeking out at the base of the kernel
  if (vc > 0.18 && random() < 0.7) {
    let gp1 = toWorld(lx - hw * 0.55, ly + hh * 0.82);
    let gp2 = toWorld(lx, ly + hh * 1.05);
    let gp3 = toWorld(lx + hw * 0.55, ly + hh * 0.82);
    brush.set("fine_pencil", cfg.chaffCol, 0.65);
    brush.line(gp1.x, gp1.y, gp2.x, gp2.y);
    brush.line(gp2.x, gp2.y, gp3.x, gp3.y);
  }

  // 2. Dense Coloured-Pencil Cross-Contour & Longitudinal Pericarp Layering
  // Horizontal arched contour bands from kernel base (uY = 0.85) to crown (uY = -0.85)
  const vSteps = max(6, floor(kh * 0.55));
  for (let i = 0; i <= vSteps; i++) {
    let t = i / vSteps; // 0 = bottom base, 1 = top crown
    let uY = lerp(0.84, -0.84, t);
    // Plump shield profile width at height uY
    let wProfile = sin(t * 165) * 0.35 + 0.72;
    if (t > 0.8) wProfile *= map(t, 0.8, 1.0, 1.0, 0.65);
    let spanW = hw * wProfile * 0.92;

    // Local 3D dome lighting (overhead light hits upper-middle dome t in [0.55..0.88])
    let localNy = -cos(t * 180);
    let domeLight = constrain(globalLight * (0.45 + 0.65 * sin(t * 160) + (t > 0.5 ? 0.22 : -0.15)), 0, 1);

    let bandCol;
    if (domeLight < 0.36) {
      bandCol = lerpColor(color(kCols.dark), color(kCols.mid), map(domeLight, 0, 0.36, 0, 1));
    } else if (domeLight < 0.74) {
      bandCol = lerpColor(color(kCols.mid), color(kCols.bright), map(domeLight, 0.36, 0.74, 0, 1));
    } else {
      bandCol = lerpColor(color(kCols.bright), color(kCols.crown), map(domeLight, 0.74, 1.0, 0, 1));
    }

    let pLeft = toWorld(lx - spanW, ly + uY * hh);
    let pMid = toWorld(lx, ly + (uY - 0.14) * hh);
    let pRight = toWorld(lx + spanW, ly + uY * hh);

    brush.set("prismacolor", bandCol, 0.85);
    brush.spline([[pLeft.x, pLeft.y, 0.5], [pMid.x, pMid.y, 1.1], [pRight.x, pRight.y, 0.5]], 0.45);
  }

  // Longitudinal pericarp striations (fine coloured-pencil lines curving from base to crown)
  const hSteps = max(4, floor(kw * 0.42));
  for (let j = 0; j <= hSteps; j++) {
    let s = map(j, 0, hSteps, -0.82, 0.82);
    let sideShade = 1 - sq(s) * 0.55;
    let lVal = globalLight * sideShade;
    let striaCol = lVal < 0.45 ? kCols.dark : (lVal < 0.78 ? kCols.mid : kCols.bright);

    let pBot = toWorld(lx + s * hw * 0.68, ly + hh * 0.82);
    let pBelly = toWorld(lx + s * hw * 0.95, ly - hh * 0.05);
    let pTop = toWorld(lx + s * hw * 0.52, ly - hh * 0.82);

    brush.set("fine_pencil", striaCol, 0.65);
    brush.spline([[pBot.x, pBot.y, 0.4], [pBelly.x, pBelly.y, 0.95], [pTop.x, pTop.y, 0.4]], 0.4);
  }

  // 3. Aleurone Speckles / Striations (for Piscorunto, Sangre, Chullpi)
  if (kCols.speckles) {
    let spCount = floor(map(kw, 5, 22, 4, 14));
    for (let s = 0; s < spCount; s++) {
      let sx = lx + random(-hw * 0.68, hw * 0.68);
      let sy = ly + random(-hh * 0.65, hh * 0.55);
      let sp1 = toWorld(sx, sy);
      let sp2 = toWorld(sx + random(-0.8, 0.8), sy - random(1.2, 3.2));
      brush.set("fine_pencil", kCols.speckleCol, random(0.6, 0.9));
      brush.line(sp1.x, sp1.y, sp2.x, sp2.y);
    }
  }

  // 4. Stylar Scar / Dimple at Kernel Apex
  if (kw > 8) {
    let d1 = toWorld(lx - hw * 0.22, ly - hh * 0.52);
    let d2 = toWorld(lx + hw * 0.22, ly - hh * 0.52);
    brush.set("fine_pencil", kCols.dark, 0.65);
    brush.line(d1.x, d1.y, d2.x, d2.y);
  }

  // 5. Waxy Specular Highlights (Overhead illumination gleaming off the glossy pericarp dome)
  if (globalLight > 0.36 && kw > 5.5) {
    let hlShiftX = -sin(phiC) * hw * 0.18;
    let hlW = hw * map(globalLight, 0.36, 1.0, 0.25, 0.52);
    let hlY = ly - hh * 0.28;

    let h1 = toWorld(lx + hlShiftX - hlW, hlY + 0.8);
    let hm = toWorld(lx + hlShiftX, hlY - 0.8);
    let h2 = toWorld(lx + hlShiftX + hlW, hlY + 0.8);

    brush.set("wax_burnish", kCols.highlight, map(globalLight, 0.36, 1.0, 0.45, 0.95));
    brush.spline([[h1.x, h1.y, 0.4], [hm.x, hm.y, 1.15], [h2.x, h2.y, 0.4]], 0.45);

    // Pinpoint crisp specular glint on the most front-facing kernels
    if (globalLight > 0.72) {
      let g1 = toWorld(lx + hlShiftX - hlW * 0.45, hlY - 0.3);
      let g2 = toWorld(lx + hlShiftX + hlW * 0.45, hlY - 0.3);
      brush.set("fine_pencil", "#ffffff", 0.75);
      brush.line(g1.x, g1.y, g2.x, g2.y);
    }
  }
}

function drawEmptyKernelSocket(k, toWorld, cfg) {
  // Hyperreal botanical detail: a recessed socket where 1 kernel was shelled out, showing papery glumes
  const { lx, ly, kw, kh } = k;
  const hw = kw * 0.48;
  const hh = kh * 0.48;

  brush.set("prismacolor", "#0b0608", 0.95);
  for (let i = -3; i <= 3; i++) {
    let p1 = toWorld(lx - hw * 0.8, ly + (i / 3) * hh * 0.7);
    let p2 = toWorld(lx + hw * 0.8, ly + (i / 3) * hh * 0.7);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Papery cream and cochineal glume bracts cupping the empty alveolus
  brush.set("fine_pencil", PALETTE.creamDark, 0.7);
  let c1 = toWorld(lx - hw * 0.75, ly - hh * 0.4);
  let cm = toWorld(lx, ly + hh * 0.65);
  let c2 = toWorld(lx + hw * 0.75, ly - hh * 0.4);
  brush.spline([[c1.x, c1.y, 0.5], [cm.x, cm.y, 1.0], [c2.x, c2.y, 0.5]], 0.45);

  brush.set("fine_pencil", PALETTE.cochineal, 0.6);
  let r1 = toWorld(lx - hw * 0.5, ly + hh * 0.2);
  let r2 = toWorld(lx + hw * 0.5, ly + hh * 0.2);
  brush.line(r1.x, r1.y, r2.x, r2.y);
}

function drawCobShankAndHusks(toWorld, cfg) {
  const by = cfg.ry;
  // Woody fibrous pedicel / shank protruding slightly at the bottom
  for (let i = -10; i <= 10; i++) {
    let t = i / 10;
    let xTop = t * 24;
    let xBot = t * 15;
    let p1 = toWorld(xTop, by - 4);
    let p2 = toWorld(xBot, by + 22 - abs(t) * 5);
    let col = abs(t) > 0.6 ? "#3b2c1e" : (t < 0 ? cfg.shankCol : "#856a46");
    brush.set("fine_pencil", col, 0.75);
    brush.line(p1.x, p1.y, p2.x, p2.y);
  }

  // Cut woody pith ring at the very bottom of the shank
  let sLeft = toWorld(-14, by + 19);
  let sMid = toWorld(0, by + 24);
  let sRight = toWorld(14, by + 19);
  brush.set("prismacolor", PALETTE.creamDark, 0.75);
  brush.spline([[sLeft.x, sLeft.y, 0.5], [sMid.x, sMid.y, 1.0], [sRight.x, sRight.y, 0.5]], 0.4);
  brush.set("fine_pencil", "#2e2015", 0.7);
  brush.line(sLeft.x + 2, sLeft.y, sRight.x - 2, sRight.y);

  // Striated dry papery husk bract remnants clasping the lower left & right base
  for (let side of [-1, 1]) {
    for (let s = 0; s < 14; s++) {
      let f = s / 13;
      let startX = side * lerp(6, 26, f);
      let startY = by + lerp(14, 2, f);
      let midX = side * lerp(28, 68, f);
      let midY = by - lerp(6, 38, f);
      let tipX = side * lerp(42, 78, f);
      let tipY = by - lerp(28, 72, f) + sin(f * 180) * 6;

      let p1 = toWorld(startX, startY);
      let p2 = toWorld(midX, midY);
      let p3 = toWorld(tipX, tipY);

      let huskCol = s % 3 === 0 ? "#785c3c" : (s % 2 === 0 ? "#c7af82" : "#9c7c52");
      if (cfg.paletteMode === "morado" && s % 4 === 0) huskCol = "#5e2438";
      brush.set("fine_pencil", huskCol, 0.65);
      brush.spline([[p1.x, p1.y, 0.6], [p2.x, p2.y, 0.9], [p3.x, p3.y, 0.3]], 0.45);
    }
  }
}

function drawCornSilkCrown(toWorld, cfg) {
  // Fine twisted golden-ochre and cochineal-brown dried silk threads emerging from the apex
  const ty = -cfg.ry;
  for (let i = 0; i < 18; i++) {
    let sx = random(-16, 16);
    let sy = ty + random(-2, 6);
    let mx = sx + random(-18, 18);
    let my = ty - random(6, 16);
    let ex = mx + random(-14, 14);
    let ey = my + random(-6, 10);

    let p1 = toWorld(sx, sy);
    let p2 = toWorld(mx, my);
    let p3 = toWorld(ex, ey);

    let silkCol = i % 3 === 0 ? cfg.silkCol : (i % 2 === 0 ? PALETTE.ochreLight : "#593e25");
    brush.set("fine_pencil", silkCol, random(0.4, 0.65));
    brush.spline([[p1.x, p1.y, 0.7], [p2.x, p2.y, 0.6], [p3.x, p3.y, 0.25]], 0.6);
  }
}

function drawLooseFallenKernel(cell, toWorld, cfg) {
  // A single shelled kernel resting beside the cob base on the compartment floor
  const side = (cell.row + cell.col) % 2 === 0 ? -1 : 1;
  const kp = toWorld(side * (cfg.rx * 0.85), cfg.ry * 0.88);
  const kx = kp.x;
  const ky = kp.y + 8;

  // Tiny cast shadow under the loose kernel
  brush.set("prismacolor", "#08060a", 0.85);
  brush.line(kx - 7, ky + 4.5, kx + 7, ky + 4.5);
  brush.line(kx - 5, ky + 5.8, kx + 5, ky + 5.8);

  const kCols = getKernelColors(cfg.paletteMode, 3, 3);
  // White-cream pointed tip (pedicel attachment of the shelled kernel)
  const tipX = kx - side * 7.5;
  const tipY = ky + 1.5;

  for (let i = -4; i <= 4; i++) {
    let t = i / 4;
    let col = t < -0.2 ? kCols.bright : (t < 0.4 ? kCols.mid : kCols.dark);
    brush.set("prismacolor", col, 0.75);
    brush.spline([
      [tipX, tipY + t * 1.5, 0.4],
      [kx, ky + t * 4.5, 1.0],
      [kx + side * 7.5, ky + t * 3.2, 0.5]
    ], 0.45);
  }

  // Pale cream germ/tip & waxy highlight on the loose kernel
  brush.set("fine_pencil", PALETTE.cream, 0.7);
  brush.line(tipX, tipY, tipX + side * 3.2, tipY - 0.5);
  brush.set("wax_burnish", kCols.highlight, 0.65);
  brush.line(kx - 2.5, ky - 2.2, kx + 3.5, ky - 2.2);
}

// Hyperreal Trompe-l'Oeil Stage from the Stalls
// Crushed-velvet curtain in carmine & oxblood, charcoal mass shadows,
// raw sienna & bright ochre marker glazes on gilt proscenium mouldings,
// receding grisaille colonnade backdrop, hard footlights & crisp bullion fringe.

const PAL = {
  // Monochrome / Grisaille Architecture & Stalls (Sepia-Charcoal)
  inkBlack: "#080606",
  charcoalDark: "#120e0d",
  umberDeep: "#1f1916",
  slateUmber: "#332b26",
  warmGrayDark: "#4d433b",
  warmGrayMid: "#6e6256",
  stoneMid: "#918373",
  stoneLight: "#b5a692",
  parchment: "#d9ccb8",
  chalkWarm: "#efe4d2",
  footlightWhite: "#fff9ed",

  // Gilt Proscenium & Bullion Fringe (Raw Sienna & Bright Ochre)
  siennaShadow: "#2e1705",
  siennaDeep: "#522b0a",
  rawSienna: "#8c4f17",
  siennaWarm: "#b56c1d",
  ochreBright: "#de9e28",
  ochreLight: "#f5c445",
  goldSpecular: "#ffefb5",

  // Crushed Velvet Accent (Oxblood & Carmine)
  voidOxblood: "#0a0204",
  deepOxblood: "#190408",
  darkOxblood: "#2e060e",
  oxblood: "#4c0916",
  carmineShadow: "#6e0d20",
  carmine: "#96132b",
  carmineBright: "#bf1d38",
  velvetRose: "#de3b50",
  velvetUplight: "#f26d68",
  velvetSpecular: "#ffb5a1"
};

const VP_X = 510;
const VP_Y = 645;
const BACKDROP_Y = 758;

function resetBrushState() {
  brush.noWash();
  brush.noFill();
  brush.noMass();
  brush.noHatch();
  brush.noField();
  brush.set("HB", PAL.charcoalDark, 0.5);
}

function polyWash(pts, col, opacity) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noMass();
  brush.noHatch();
  brush.wash(col, opacity);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function polyFill(pts, col, opacity, bleed = 0.12, tex = 0.4, border = 0.25) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noMass();
  brush.noHatch();
  brush.fill(col, opacity);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function polyMass(pts, brushName, col, opts) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noFill();
  brush.noHatch();
  brush.mass(brushName, col, opts);
  brush.beginShape(0.05);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function polyHatch(pts, brushName, col, weight, dist, angle, opts) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noFill();
  brush.noMass();
  brush.hatchStyle(brushName, col, weight);
  brush.hatch(dist, angle, opts);
  brush.beginShape(0);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  resetBrushState();
}

function apronY(x) {
  let u = constrain((x - 140) / 920, 0, 1);
  return 922 + 26 * sin(u * 180);
}

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(42719);
  noiseSeed(8831);
}

function draw() {
  translate(-width / 2, -height / 2);
  background(PAL.charcoalDark);
  resetBrushState();

  // 1. Base Underpainting & Atmospheric Stage Glow
  drawBaseUnderpainting();

  // 2. Trompe-l'Oeil Receding Colonnade Backdrop (Monochrome Grisaille)
  drawTrompeLoeilBackdrop();

  // 3. Raked Stage Floor, Footlight Glare Pools & Upward Cast Shadows
  drawRakedStageFloor();

  // 4. Left Curtain Wing & Upper Scalloped Valance
  drawLeftCurtainAndValance();

  // 5. Hero Half-Drawn Crushed-Velvet Curtain (Carmine, Oxblood & Charcoal Mass)
  drawMainCrushedVelvetCurtain();

  // 6. Crisp Bullion Fringe, Braid Galon & Tie-Back Tassels
  drawAllCurtainFringes();

  // 7. Gilt Proscenium Arch & Pilasters (Raw Sienna & Bright Ochre Marker Glazes)
  drawGiltProscenium();

  // 8. Stage Apron Lip, Footlight Cowls, Stalls Foreground & Dusty Uplight Rays
  drawFootlightsAndStalls();

  noLoop();
}

// ============================================================================
// 1. BASE UNDERPAINTING
// ============================================================================
function drawBaseUnderpainting() {
  // Deep warm grisaille paper ground in center stage opening
  polyWash([[140, 110], [1060, 110], [1060, 960], [140, 960]], PAL.umberDeep, 255);

  // Soft watercolor glow centered around the vanishing point & lower backdrop
  polyFill([[180, 220], [880, 220], [880, 770], [180, 770]], PAL.warmGrayDark, 95, 0.25, 0.45, 0.2);
  polyFill([[250, 420], [780, 420], [820, 765], [210, 765]], PAL.stoneMid, 85, 0.3, 0.4, 0.2);
  polyFill([[330, 530], [700, 530], [740, 760], [290, 760]], PAL.parchment, 90, 0.35, 0.35, 0.15);
}

// ============================================================================
// 2. TROMPE-L'OEIL RECEDING COLONNADE BACKDROP
// ============================================================================
function drawTrompeLoeilBackdrop() {
  // Backdrop clipping region: x in [160, 900], y in [140, BACKDROP_Y]
  brush.clip([160, 140, 900, BACKDROP_Y]);

  // Distant atmospheric rotunda sky/vault glow around (VP_X, VP_Y)
  for (let r = 240; r >= 30; r -= 35) {
    let t = map(r, 30, 240, 1, 0);
    let col = lerpColor(color(PAL.warmGrayDark), color(PAL.chalkWarm), t * 0.85);
    let pts = [];
    for (let a = 0; a < 360; a += 15) {
      pts.push([VP_X + cos(a) * r * 0.95, (VP_Y - 35) + sin(a) * r * 1.15]);
    }
    polyWash(pts, col, 65);
  }

  // False perspective marble floor painted on the canvas drop (from VP_Y=645 to BACKDROP_Y=758)
  polyWash([[160, VP_Y], [900, VP_Y], [900, BACKDROP_Y], [160, BACKDROP_Y]], PAL.stoneLight, 150);
  polyWash([[260, VP_Y + 25], [760, VP_Y + 25], [860, BACKDROP_Y], [180, BACKDROP_Y]], PAL.chalkWarm, 130);

  // Perspective floor tiles on the painted drop
  intPaintedFloorGrid();

  // Distant Triumphal Rotunda & Statue at the end of the colonnade (depth d = 0.72..0.88)
  drawDistantRotunda();

  // 5 Receding Pairs of Monumental Colonnade Bays (drawn back-to-front)
  const depths = [0.68, 0.55, 0.41, 0.24, 0.05];
  for (let i = 0; i < depths.length; i++) {
    let dCurr = depths[i];
    let dNext = i > 0 ? depths[i - 1] : 0.78;
    drawColonnadeBay(dCurr, dNext, i);
  }

  // Long upward shadows cast across the backdrop from the footlights & scenic wings
  drawBackdropUpwardShadows();

  // Trompe-l'oeil canvas texture & bottom roller batten at y = BACKDROP_Y
  drawBackdropCanvasAndBatten();

  brush.noClip();
  resetBrushState();
}

function bilerpPt(d, rx, ry) {
  // d = 0 is foreground of backdrop, d = 1 is at (VP_X, VP_Y)
  // At d = 0: x spans [150, 870], y spans [120, BACKDROP_Y]
  let x0 = lerp(150, 870, rx);
  let y0 = lerp(120, BACKDROP_Y, ry);
  return [lerp(x0, VP_X, d), lerp(y0, VP_Y, d)];
}

function intPaintedFloorGrid() {
  // Horizontal perspective lines on painted drop
  let rows = 11;
  for (let r = 0; r <= rows; r++) {
    let u = pow(r / rows, 1.55); // foreshortened spacing
    let y = lerp(VP_Y + 4, BACKDROP_Y, u);
    let nextU = pow((r + 1) / rows, 1.55);
    let yNext = lerp(VP_Y + 4, BACKDROP_Y, min(1, nextU));

    // Alternating dark/light perspective marble checks
    if (r < rows) {
      for (let c = -8; c <= 8; c++) {
        if ((r + c + 16) % 2 === 0) {
          let x1Top = VP_X + c * 52 * ((y - VP_Y) / (BACKDROP_Y - VP_Y));
          let x2Top = VP_X + (c + 1) * 52 * ((y - VP_Y) / (BACKDROP_Y - VP_Y));
          let x1Bot = VP_X + c * 52 * ((yNext - VP_Y) / (BACKDROP_Y - VP_Y));
          let x2Bot = VP_X + (c + 1) * 52 * ((yNext - VP_Y) / (BACKDROP_Y - VP_Y));
          polyWash([[x1Top, y], [x2Top, y], [x2Bot, yNext], [x1Bot, yNext]], PAL.warmGrayMid, 75);
        }
      }
    }

    brush.set("2H", PAL.warmGrayDark, map(u, 0, 1, 0.2, 0.45));
    brush.line(160, y, 890, y);
  }

  // Radiating floor perspective lines
  for (let c = -10; c <= 10; c++) {
    let xBot = VP_X + c * 52;
    brush.set("2H", PAL.warmGrayDark, 0.3);
    brush.line(VP_X, VP_Y + 4, xBot, BACKDROP_Y);
  }
}

function drawDistantRotunda() {
  // Misty classical rotunda & dome around (VP_X, VP_Y)
  let cx = VP_X;
  let cy = VP_Y;

  // Dome coffered interior
  let domePts = [];
  for (let a = 180; a <= 360; a += 10) {
    domePts.push([cx + cos(a) * 72, (cy - 68) + sin(a) * 62]);
  }
  polyWash(domePts, PAL.warmGrayMid, 120);

  // Coffer ribs in distant dome
  brush.set("2H", PAL.slateUmber, 0.28);
  for (let a = 195; a <= 345; a += 25) {
    let ex = cx + cos(a) * 70;
    let ey = (cy - 68) + sin(a) * 60;
    brush.line(cx, cy - 122, ex, ey);
  }
  for (let r = 0.35; r <= 0.95; r += 0.2) {
    brush.arc(cx, cy - 68, 65 * r, 185, 355);
  }

  // Distant colonnade columns inside rotunda
  for (let i = -4; i <= 4; i++) {
    let colX = cx + i * 15;
    let colW = 4.5;
    let colTop = cy - 68;
    let colBot = cy + 4;
    polyWash([
      [colX - colW / 2, colTop],
      [colX + colW / 2, colTop],
      [colX + colW / 2, colBot],
      [colX - colW / 2, colBot]
    ], i % 2 === 0 ? PAL.parchment : PAL.stoneLight, 180);

    brush.set("rotring", PAL.slateUmber, 0.25);
    brush.line(colX - colW / 2, colTop, colX - colW / 2, colBot);
    brush.line(colX + colW / 2, colTop, colX + colW / 2, colBot);
  }

  // Classical equestrian/allegorical statue silhouette in center of rotunda
  // Plinth
  polyWash([[cx - 11, cy - 22], [cx + 11, cy - 22], [cx + 13, cy + 4], [cx - 13, cy + 4]], PAL.slateUmber, 190);
  polyWash([[cx - 9, cy - 22], [cx + 4, cy - 22], [cx + 4, cy + 2], [cx - 9, cy + 2]], PAL.parchment, 150);
  // Figure silhouette lit from below
  polyWash([[cx - 6, cy - 52], [cx + 5, cy - 54], [cx + 8, cy - 22], [cx - 7, cy - 22]], PAL.warmGrayDark, 210);
  brush.set("2H", PAL.footlightWhite, 0.35);
  brush.line(cx - 4, cy - 23, cx - 3, cy - 48);
  brush.line(cx - 8, cy - 22, cx + 8, cy - 22);
}

function drawColonnadeBay(dCurr, dNext, bayIdx) {
  // Compute ceiling barrel vault arch between dCurr and dNext
  let pL_curr = bilerpPt(dCurr, 0.16, 0.34);
  let pR_curr = bilerpPt(dCurr, 0.84, 0.34);
  let pL_next = bilerpPt(dNext, 0.16, 0.34);
  let pR_next = bilerpPt(dNext, 0.84, 0.34);

  let cx_curr = (pL_curr[0] + pR_curr[0]) * 0.5;
  let cy_curr = pL_curr[1];
  let rad_curr = (pR_curr[0] - pL_curr[0]) * 0.5;

  let cx_next = (pL_next[0] + pR_next[0]) * 0.5;
  let cy_next = pL_next[1];
  let rad_next = (pR_next[0] - pL_next[0]) * 0.5;

  // Draw Barrel Vault Band between dNext and dCurr
  let vaultSegs = 12;
  for (let s = 0; s < vaultSegs; s++) {
    let a1 = 180 + (s / vaultSegs) * 180;
    let a2 = 180 + ((s + 1) / vaultSegs) * 180;

    let v1 = [cx_curr + cos(a1) * rad_curr, cy_curr + sin(a1) * rad_curr * 0.72];
    let v2 = [cx_curr + cos(a2) * rad_curr, cy_curr + sin(a2) * rad_curr * 0.72];
    let v3 = [cx_next + cos(a2) * rad_next, cy_next + sin(a2) * rad_next * 0.72];
    let v4 = [cx_next + cos(a1) * rad_next, cy_next + sin(a1) * rad_next * 0.72];

    // Uplight from footlights hits lower side-walls of the vault more than the top crown
    let sinMid = abs(cos((a1 + a2) * 0.5));
    let shadeCol = sinMid > 0.55 ? PAL.stoneLight : (sinMid > 0.25 ? PAL.warmGrayMid : PAL.slateUmber);
    polyWash([v1, v2, v3, v4], shadeCol, 195);

    // Inset sunken coffer inside each vault panel
    let c1 = [lerp(v1[0], v3[0], 0.18), lerp(v1[1], v3[1], 0.18)];
    let c2 = [lerp(v2[0], v4[0], 0.18), lerp(v2[1], v4[1], 0.18)];
    let c3 = [lerp(v3[0], v1[0], 0.18), lerp(v3[1], v1[1], 0.18)];
    let c4 = [lerp(v4[0], v2[0], 0.18), lerp(v4[1], v2[1], 0.18)];
    polyWash([c1, c2, c3, c4], PAL.umberDeep, 175);

    // Coffer bottom edge catches upward footlight
    brush.set("rotring", PAL.chalkWarm, map(dCurr, 0, 0.7, 0.45, 0.2));
    brush.line(c1[0], c1[1], c4[0], c4[1]);
    brush.set("rotring", PAL.charcoalDark, map(dCurr, 0, 0.7, 0.5, 0.22));
    brush.line(c1[0], c1[1], c2[0], c2[1]);
    brush.line(c2[0], c2[1], c3[0], c3[1]);
  }

  // Transverse arch rib at dCurr
  let ribW = (1 - dCurr) * 18 + 3;
  for (let s = 0; s < vaultSegs; s++) {
    let a1 = 180 + (s / vaultSegs) * 180;
    let a2 = 180 + ((s + 1) / vaultSegs) * 180;
    let rIn = rad_curr;
    let rOut = rad_curr + ribW;
    let p1 = [cx_curr + cos(a1) * rIn, cy_curr + sin(a1) * rIn * 0.72];
    let p2 = [cx_curr + cos(a2) * rIn, cy_curr + sin(a2) * rIn * 0.72];
    let p3 = [cx_curr + cos(a2) * rOut, cy_curr + sin(a2) * rOut * 0.72];
    let p4 = [cx_curr + cos(a1) * rOut, cy_curr + sin(a1) * rOut * 0.72];
    polyWash([p1, p2, p3, p4], PAL.parchment, 200);
    brush.set("rotring", PAL.umberDeep, map(dCurr, 0, 0.7, 0.55, 0.25));
    brush.line(p1[0], p1[1], p2[0], p2[1]);
    brush.line(p4[0], p4[1], p3[0], p3[1]);
  }

  // Draw Left & Right Colonnade Entablature, Columns & Plinths for this Bay
  drawSideColonnadeWall(dCurr, dNext, true, bayIdx);
  drawSideColonnadeWall(dCurr, dNext, false, bayIdx);
}

function drawSideColonnadeWall(dCurr, dNext, isLeft, bayIdx) {
  let rxOuter = isLeft ? 0.06 : 0.94;
  let rxInner = isLeft ? 0.17 : 0.83;

  // Entablature connecting dCurr and dNext
  let entTop_c = bilerpPt(dCurr, rxInner, 0.30);
  let entBot_c = bilerpPt(dCurr, rxInner, 0.37);
  let entTop_n = bilerpPt(dNext, rxInner, 0.30);
  let entBot_n = bilerpPt(dNext, rxInner, 0.37);

  polyWash([entTop_c, entTop_n, entBot_n, entBot_c], PAL.warmGrayMid, 220);

  // Underside (soffit) of entablature lit from below by footlights
  let soffitOut_c = bilerpPt(dCurr, isLeft ? rxInner - 0.035 : rxInner + 0.035, 0.38);
  let soffitOut_n = bilerpPt(dNext, isLeft ? rxInner - 0.035 : rxInner + 0.035, 0.38);
  polyWash([entBot_c, entBot_n, soffitOut_n, soffitOut_c], PAL.chalkWarm, 210);

  // Dentil & cornice lines receding to VP
  brush.set("rotring", PAL.charcoalDark, map(dCurr, 0, 0.7, 0.55, 0.25));
  brush.line(entTop_c[0], entTop_c[1], entTop_n[0], entTop_n[1]);
  brush.line(entBot_c[0], entBot_c[1], entBot_n[0], entBot_n[1]);

  let midY_c = lerp(entTop_c[1], entBot_c[1], 0.5);
  let midY_n = lerp(entTop_n[1], entBot_n[1], 0.5);
  brush.set("rotring", PAL.footlightWhite, map(dCurr, 0, 0.7, 0.45, 0.2));
  brush.line(entBot_c[0], midY_c, entBot_n[0], midY_n);

  // Outer aisle shadow wall behind columns
  let wallTop_c = bilerpPt(dCurr, rxOuter, 0.37);
  let wallBot_c = bilerpPt(dCurr, rxOuter, 0.99);
  let wallTop_n = bilerpPt(dNext, rxOuter, 0.37);
  let wallBot_n = bilerpPt(dNext, rxOuter, 0.99);
  polyWash([wallTop_c, wallTop_n, wallBot_n, wallBot_c], PAL.umberDeep, 215);

  // Cross-hatching in deep side-aisle shadow
  polyHatch(
    [wallTop_c, wallTop_n, wallBot_n, wallBot_c],
    "2B", PAL.charcoalDark, 0.45, map(dCurr, 0, 0.7, 5, 9), isLeft ? 35 : -35, { rand: 0.08 }
  );

  // Draw the Outer Pilaster & Inner Free-Standing Corinthian Column at dCurr
  drawGrisailleColumn(dCurr, isLeft ? rxOuter + 0.02 : rxOuter - 0.02, isLeft, true);
  drawGrisailleColumn(dCurr, rxInner, isLeft, false);
}

function drawGrisailleColumn(d, rx, isLeft, isPilaster) {
  let scaleF = 1 - d;
  let colW = (isPilaster ? 34 : 42) * scaleF;
  if (colW < 3) return;

  let pCap = bilerpPt(d, rx, 0.38);
  let pColBot = bilerpPt(d, rx, 0.81);
  let pPlinthBot = bilerpPt(d, rx, 0.99);

  let cx = pCap[0];
  let yCap = pCap[1];
  let yColBot = pColBot[1];
  let yPlinthBot = pPlinthBot[1];
  let r = colW * 0.5;

  // 1. Column Shaft (with upward footlight gradient & upward shadow from plinth)
  let xL = cx - r;
  let xR = cx + r;

  // Base shadow tone of shaft
  polyWash([[xL, yCap], [xR, yCap], [xR, yColBot], [xL, yColBot]], isPilaster ? PAL.warmGrayDark : PAL.stoneMid, 245);

  // Lit side of column facing the center stage footlights
  let litX1 = isLeft ? cx - r * 0.25 : cx - r;
  let litX2 = isLeft ? cx + r : cx + r * 0.25;
  polyWash([[litX1, yCap], [litX2, yCap], [litX2, yColBot], [litX1, yColBot]], isPilaster ? PAL.stoneMid : PAL.parchment, 225);

  // Intense footlight glow on lower half of column shaft
  let yMid = lerp(yCap, yColBot, 0.45);
  if (!isPilaster) {
    polyWash([[litX1, yMid], [litX2, yMid], [litX2, yColBot], [litX1, yColBot]], PAL.chalkWarm, 185);
    polyWash([[ isLeft ? cx + r * 0.2 : cx - r * 0.85, lerp(yCap, yColBot, 0.62)],
              [ isLeft ? cx + r * 0.85 : cx - r * 0.2, lerp(yCap, yColBot, 0.62)],
              [ isLeft ? cx + r * 0.85 : cx - r * 0.2, yColBot],
              [ isLeft ? cx + r * 0.2 : cx - r * 0.85, yColBot]], PAL.footlightWhite, 165);
  }

  // Upward diagonal shadow cast by the projecting pedestal cornice onto the lower shaft!
  let shadowH = (yColBot - yCap) * 0.14;
  polyWash([
    [xL, yColBot],
    [xR, yColBot],
    [xR, yColBot - shadowH * (isLeft ? 0.5 : 1.1)],
    [xL, yColBot - shadowH * (isLeft ? 1.1 : 0.5)]
  ], PAL.umberDeep, 175);

  // Fluting lines along the column shaft
  let flutes = 8;
  for (let f = 0; f <= flutes; f++) {
    let ang = map(f, 0, flutes, 180, 360);
    let fx = cx + cos(ang) * r;
    let isLitFlute = (isLeft && f >= 4) || (!isLeft && f <= 4);
    brush.set("rotring", isLitFlute ? PAL.warmGrayDark : PAL.charcoalDark, map(scaleF, 0.3, 1, 0.22, 0.5));
    brush.line(fx, yCap + 6 * scaleF, fx, yColBot - 4 * scaleF);

    // Crisp highlight ridge next to flute
    if (isLitFlute && f > 0 && f < flutes && !isPilaster) {
      brush.set("2H", PAL.footlightWhite, map(scaleF, 0.3, 1, 0.2, 0.4));
      brush.line(fx + 1.2 * scaleF, lerp(yCap, yColBot, 0.35), fx + 1.2 * scaleF, yColBot - 5 * scaleF);
    }
  }

  // Horizontal contour hatching on shadow side of column
  let hSteps = floor(22 * scaleF);
  brush.set("2B", PAL.charcoalDark, 0.35 * scaleF + 0.15);
  for (let h = 0; h < hSteps; h++) {
    let hy = map(h, 0, hSteps, yCap + 8 * scaleF, yColBot - 6 * scaleF);
    let sx1 = isLeft ? xL : cx + r * 0.15;
    let sx2 = isLeft ? cx - r * 0.1 : xR;
    brush.line(sx1, hy, sx2, hy + (isLeft ? 2 : -2) * scaleF);
  }

  // 2. Corinthian Capital (lit from underneath, casting upward shadow onto architrave)
  let capH = 26 * scaleF;
  let capTopW = r * 1.45;
  // Upper shadow of capital
  polyWash([
    [cx - capTopW, yCap - 4 * scaleF],
    [cx + capTopW, yCap - 4 * scaleF],
    [cx + r * 1.05, yCap + capH],
    [cx - r * 1.05, yCap + capH]
  ], PAL.slateUmber, 240);

  // Acanthus leaves catching upward footlight
  let tiers = 3;
  for (let t = 0; t < tiers; t++) {
    let ty = yCap + map(t, 0, tiers, 2 * scaleF, capH);
    let tw = map(t, 0, tiers, capTopW * 0.95, r * 1.05);
    brush.set("rotring", PAL.chalkWarm, 0.45 * scaleF + 0.15);
    brush.line(cx - tw, ty, cx + tw, ty);
    brush.set("rotring", PAL.charcoalDark, 0.45 * scaleF + 0.15);
    brush.line(cx - tw, ty - 2 * scaleF, cx + tw, ty - 2 * scaleF);
  }
  // Volutes at capital corners
  brush.set("rotring", PAL.footlightWhite, 0.4 * scaleF + 0.15);
  brush.circle(cx - capTopW * 0.82, yCap + 4 * scaleF, 4.5 * scaleF, 0.1);
  brush.circle(cx + capTopW * 0.82, yCap + 4 * scaleF, 4.5 * scaleF, 0.1);

  // 3. Attic Base & High Panelled Pedestal (Plinth)
  let pW = r * 1.38;
  // Attic base rings (brightly lit on bottom edge)
  polyWash([[cx - pW, yColBot - 6 * scaleF], [cx + pW, yColBot - 6 * scaleF], [cx + pW, yColBot + 5 * scaleF], [cx - pW, yColBot + 5 * scaleF]], PAL.parchment, 240);
  brush.set("rotring", PAL.footlightWhite, 0.55 * scaleF + 0.15);
  brush.line(cx - pW, yColBot + 3 * scaleF, cx + pW, yColBot + 3 * scaleF);
  brush.set("rotring", PAL.charcoalDark, 0.5 * scaleF + 0.15);
  brush.line(cx - pW, yColBot - 5 * scaleF, cx + pW, yColBot - 5 * scaleF);

  // Pedestal Die (Main Box)
  polyWash([
    [cx - pW, yColBot + 5 * scaleF],
    [cx + pW, yColBot + 5 * scaleF],
    [cx + pW * 1.08, yPlinthBot],
    [cx - pW * 1.08, yPlinthBot]
  ], isPilaster ? PAL.slateUmber : PAL.warmGrayMid, 245);

  // Lit inner face of Pedestal
  let pFaceX1 = isLeft ? cx - pW * 0.2 : cx - pW;
  let pFaceX2 = isLeft ? cx + pW : cx + pW * 0.2;
  polyWash([
    [pFaceX1, yColBot + 6 * scaleF],
    [pFaceX2, yColBot + 6 * scaleF],
    [pFaceX2, yPlinthBot],
    [pFaceX1, yPlinthBot]
  ], PAL.stoneLight, 235);

  // Inset coffered panel on pedestal face
  let inPad = 5 * scaleF;
  let panX1 = pFaceX1 + inPad;
  let panX2 = pFaceX2 - inPad;
  let panY1 = yColBot + 12 * scaleF;
  let panY2 = yPlinthBot - 10 * scaleF;
  if (panX2 > panX1 && panY2 > panY1) {
    polyWash([[panX1, panY1], [panX2, panY1], [panX2, panY2], [panX1, panY2]], PAL.warmGrayDark, 150);
    // Bottom edge of sunken panel catches upward footlight
    brush.set("rotring", PAL.charcoalDark, 0.45 * scaleF + 0.15);
    brush.line(panX1, panY2, panX2, panY2);
    brush.set("rotring", PAL.footlightWhite, 0.5 * scaleF + 0.15);
    brush.line(panX1, panY1, panX2, panY1);
  }

  // Crisp architectural outlines on pedestal
  brush.set("rotring", PAL.charcoalDark, 0.5 * scaleF + 0.15);
  brush.rect(cx - pW, yColBot + 5 * scaleF, pW * 2, yPlinthBot - (yColBot + 5 * scaleF), "corner");
}

function drawBackdropUpwardShadows() {
  // Dramatic diagonal upward shadows thrown onto the upper left and right of the painted backdrop
  polyWash([[160, 140], [430, 140], [310, 420], [160, 520]], PAL.charcoalDark, 115);
  polyWash([[640, 140], [900, 140], [900, 560], [740, 390]], PAL.charcoalDark, 130);
}

function drawBackdropCanvasAndBatten() {
  // Subtle woven linen canvas texture across the painted drop
  brush.set("2H", PAL.parchment, 0.18);
  for (let y = 180; y < BACKDROP_Y; y += 14) {
    brush.line(170, y + random(-1, 1), 880, y + random(-1, 1));
  }

  // Trompe-l'oeil reveal: subtle diagonal tension ripples near the bottom roller batten
  for (let i = 0; i < 9; i++) {
    let rx = map(i, 0, 8, 220, 760);
    brush.set("2H", PAL.footlightWhite, 0.28);
    brush.line(rx, BACKDROP_Y - 3, rx + 26, BACKDROP_Y - 19);
    brush.set("2H", PAL.umberDeep, 0.28);
    brush.line(rx + 2, BACKDROP_Y - 2, rx + 28, BACKDROP_Y - 18);
  }

  // Heavy cylindrical wooden batten at bottom of painted backdrop (y = BACKDROP_Y - 5 to BACKDROP_Y + 4)
  polyWash([[160, BACKDROP_Y - 5], [900, BACKDROP_Y - 5], [900, BACKDROP_Y + 3], [160, BACKDROP_Y + 3]], PAL.umberDeep, 245);
  // Bright footlight reflection along bottom edge of wooden roller bar
  brush.set("rotring", PAL.chalkWarm, 0.55);
  brush.line(160, BACKDROP_Y + 1, 900, BACKDROP_Y + 1);
  // Crisp shadow under the roller bar onto the real stage floor
  brush.set("rotring", PAL.inkBlack, 0.85);
  brush.line(160, BACKDROP_Y + 4, 900, BACKDROP_Y + 4);
}

// ============================================================================
// 3. RAKED STAGE FLOOR & FOOTLIGHT GLARE
// ============================================================================
function drawRakedStageFloor() {
  // Build stage floor polygon from y = BACKDROP_Y down to curved apron edge
  let stagePts = [[140, BACKDROP_Y], [1060, BACKDROP_Y]];
  for (let x = 1060; x >= 140; x -= 25) {
    stagePts.push([x, apronY(x)]);
  }
  polyWash(stagePts, PAL.slateUmber, 255);

  // Warm footlight glow washing backward from the 6 footlight positions
  const footX = [255, 385, 515, 645, 775, 905];
  for (let i = 0; i < footX.length; i++) {
    let fx = footX[i];
    let fy = apronY(fx) - 6;
    // Wide warm sienna/ochre cone
    polyFill([
      [fx - 28, fy],
      [fx + 28, fy],
      [lerp(fx + 95, VP_X, 0.25), BACKDROP_Y],
      [lerp(fx - 95, VP_X, 0.25), BACKDROP_Y]
    ], PAL.stoneLight, 70, 0.2, 0.35, 0.15);

    // Intense chalk-gold pool right in front of the lamp cowl
    polyWash([
      [fx - 42, fy],
      [fx + 42, fy],
      [fx + 75, fy - 75],
      [fx - 75, fy - 75]
    ], PAL.parchment, 110);

    polyWash([
      [fx - 26, fy],
      [fx + 26, fy],
      [fx + 45, fy - 38],
      [fx - 45, fy - 38]
    ], PAL.goldSpecular, 145);
  }

  // Dark upward/backward shadow wedges between footlights
  for (let i = 0; i < footX.length - 1; i++) {
    let mx = (footX[i] + footX[i + 1]) * 0.5;
    let my = apronY(mx);
    polyWash([
      [mx - 14, my - 8],
      [mx + 14, my - 8],
      [lerp(mx + 38, VP_X, 0.15), BACKDROP_Y],
      [lerp(mx - 38, VP_X, 0.15), BACKDROP_Y]
    ], PAL.umberDeep, 130);
  }

  // Perspective wooden stage floorboards converging toward (VP_X, VP_Y)
  let numPlanks = 34;
  for (let p = 0; p <= numPlanks; p++) {
    let xApron = map(p, 0, numPlanks, 80, 1120);
    let yAp = apronY(constrain(xApron, 140, 1060));
    // Intersect line from (VP_X, VP_Y) to (xApron, yAp) with y = BACKDROP_Y
    let tBack = (BACKDROP_Y - VP_Y) / (yAp - VP_Y);
    let xBack = lerp(VP_X, xApron, tBack);

    // Plank seam line
    brush.set("rotring", PAL.charcoalDark, 0.48);
    brush.line(xBack, BACKDROP_Y, xApron, yAp);

    // Highlight edge next to plank seam where footlight grazes the wood
    brush.set("2H", PAL.chalkWarm, 0.28);
    brush.line(xBack + 1.2, BACKDROP_Y, xApron + 1.8, yAp);

    // Wood grain & cross plank joints inside each board
    if (p < numPlanks) {
      let xApronNext = map(p + 1, 0, numPlanks, 80, 1120);
      let xBackNext = lerp(VP_X, xApronNext, tBack);

      // 3 fine woodgrain lines per plank
      for (let g = 1; g <= 3; g++) {
        let gu = g / 4;
        let gx1 = lerp(xBack, xBackNext, gu);
        let gx2 = lerp(xApron, xApronNext, gu);
        brush.set("2H", g === 2 ? PAL.umberDeep : PAL.warmGrayDark, 0.22);
        brush.line(gx1, BACKDROP_Y, gx2, yAp);
      }

      // Staggered horizontal plank end-joints & twin nail heads
      let jointT = 0.2 + ((p * 37) % 65) / 100;
      let jy = lerp(BACKDROP_Y, yAp, jointT);
      let jx1 = lerp(xBack, xApron, jointT);
      let jx2 = lerp(xBackNext, xApronNext, jointT);
      brush.set("rotring", PAL.charcoalDark, 0.4);
      brush.line(jx1, jy, jx2, jy);
      brush.set("2H", PAL.footlightWhite, 0.3);
      brush.line(jx1, jy + 1.2, jx2, jy + 1.2);
    }
  }

  // Horizontal perspective scuff marks and dusty footlight sheen on the raked boards
  for (let s = 0; s < 45; s++) {
    let sy = random(BACKDROP_Y + 6, 932);
    let sx = random(180, 860);
    let len = map(sy, BACKDROP_Y, 935, 18, 55);
    let isGlint = sy > 855 && random() < 0.55;
    brush.set("cpencil", isGlint ? PAL.goldSpecular : PAL.warmGrayMid, isGlint ? 0.38 : 0.25);
    brush.line(sx - len * 0.5, sy, sx + len * 0.5, sy + random(-1, 1));
  }

  // Deep shadow cast by the left and right curtains onto the stage floor
  polyWash([[140, BACKDROP_Y], [310, BACKDROP_Y], [320, 928], [140, 928]], PAL.inkBlack, 185);
  polyWash([[655, BACKDROP_Y], [1060, BACKDROP_Y], [1060, 935], [645, 925]], PAL.inkBlack, 200);
}

// ============================================================================
// 4. LEFT CURTAIN WING & UPPER SCALLOPED VALANCE
// ============================================================================
function drawLeftCurtainAndValance() {
  // --- A. LEFT SIDE CURTAIN DRAPE (x = 140..285, y = 130..912) ---
  let leftCurtainBase = [
    [140, 130], [295, 130],
    [275, 360], [248, 580],
    [282, 906], [140, 912]
  ];
  polyWash(leftCurtainBase, PAL.darkOxblood, 255);

  // 4 Vertical Folds on Left Wing Curtain
  let lFolds = [
    { xTop: 155, xMid: 152, xBot: 155, w: 28, lit: 0.3 },
    { xTop: 190, xMid: 182, xBot: 195, w: 32, lit: 0.6 },
    { xTop: 230, xMid: 212, xBot: 235, w: 34, lit: 0.85 },
    { xTop: 272, xMid: 242, xBot: 272, w: 28, lit: 1.0 }
  ];

  for (let i = 0; i < lFolds.length; i++) {
    let f = lFolds[i];
    // Deep charcoal-oxblood valley on left of fold
    let valleyPts = [
      [f.xTop - f.w * 0.5, 135],
      [f.xTop - f.w * 0.1, 135],
      [f.xMid - f.w * 0.1, 580],
      [f.xBot - f.w * 0.1, 906],
      [f.xBot - f.w * 0.5, 908],
      [f.xMid - f.w * 0.5, 580]
    ];
    polyMass(valleyPts, "charcoal", PAL.voidOxblood, {
      precision: 0.65, strength: 0.55, gradient: 0.25, outline: false
    });

    // Carmine crown of fold
    let crownPts = [
      [f.xTop - f.w * 0.15, 135],
      [f.xTop + f.w * 0.35, 135],
      [f.xMid + f.w * 0.35, 580],
      [f.xBot + f.w * 0.35, 906],
      [f.xBot - f.w * 0.15, 906],
      [f.xMid - f.w * 0.15, 580]
    ];
    polyWash(crownPts, f.lit > 0.7 ? PAL.carmine : PAL.oxblood, 210);

    // Lower footlight uplight on left curtain fold
    let lowPts = [
      [f.xMid - f.w * 0.1, 540],
      [f.xMid + f.w * 0.3, 540],
      [f.xBot + f.w * 0.35, 906],
      [f.xBot - f.w * 0.1, 906]
    ];
    polyWash(lowPts, f.lit > 0.7 ? PAL.carmineBright : PAL.carmine, 175);

    // Crushed velvet anisotropic texture along left curtain fold
    for (let y = 160; y < 895; y += 7) {
      let t = (y - 135) / (906 - 135);
      let cx = t < 0.58
        ? lerp(f.xTop, f.xMid, t / 0.58)
        : lerp(f.xMid, f.xBot, (t - 0.58) / 0.42);
      let n = noise(cx * 0.03, y * 0.025);
      let col = PAL.carmine;
      if (t > 0.55 && n > 0.48 && f.lit > 0.5) {
        col = n > 0.64 ? PAL.velvetUplight : PAL.velvetRose;
      } else if (n < 0.38) {
        col = PAL.darkOxblood;
      }
      brush.set("cpencil", col, map(n, 0, 1, 0.3, 0.65));
      brush.line(cx - f.w * 0.25, y, cx + f.w * 0.25, y + sin(y * 3) * 3);
    }
  }

  // --- B. UPPER GRAND SCALLOPED VALANCE (PELMET) (x = 140..1060, y = 115..310) ---
  // 3 lush festoon swags across the top proscenium opening
  const swags = [
    { x1: 145, x2: 430, drop: 265 },
    { x1: 405, x2: 745, drop: 292 },
    { x1: 715, x2: 1055, drop: 270 }
  ];

  for (let s = 0; s < swags.length; s++) {
    let sw = swags[s];
    let basePts = [[sw.x1, 115], [sw.x2, 115]];
    for (let u = 1; u >= 0; u -= 0.05) {
      let x = lerp(sw.x1, sw.x2, u);
      let y = 145 + sin(u * 180) * (sw.drop - 145);
      basePts.push([x, y]);
    }
    // Cast shadow onto backdrop/curtain below swag
    let shadPts = basePts.map(p => [p[0], p[1] + 14]);
    polyWash(shadPts, PAL.inkBlack, 175);

    // Base oxblood body of swag
    polyWash(basePts, PAL.deepOxblood, 250);

    // Concentric catenary folds inside each swag
    for (let f = 1; f <= 5; f++) {
      let fu = f / 5;
      let foldCurve = [];
      for (let u = 0; u <= 1.001; u += 0.05) {
        let x = lerp(sw.x1 + 10, sw.x2 - 10, u);
        let maxD = lerp(140, sw.drop - 8, fu);
        let y = 128 + sin(u * 180) * (maxD - 128) + sin(u * 540 + f * 40) * 4;
        foldCurve.push([x, y]);
      }

      // Charcoal shadow above fold ridge (upward shadow from footlights!)
      brush.set("charcoal", PAL.voidOxblood, 1.1);
      brush.spline(foldCurve.map(p => [p[0], p[1] - 7, 0.8]), 0.4);

      // Carmine & rose highlight on bottom of fold ridge (lit from footlights below!)
      brush.set("marker", fu > 0.6 ? PAL.carmineBright : PAL.carmine, 0.85);
      brush.spline(foldCurve.map(p => [p[0], p[1] + 2, 0.7]), 0.4);

      brush.set("cpencil", fu > 0.75 ? PAL.velvetRose : PAL.carmineBright, 0.45);
      brush.spline(foldCurve.map(p => [p[0], p[1] + 4, 0.6]), 0.4);
    }
  }
}

// ============================================================================
// 5. HERO HALF-DRAWN CRUSHED-VELVET CURTAIN (CARMINE, OXBLOOD & CHARCOAL MASS)
// ============================================================================
// Helper to evaluate a point on the main right curtain at fold index u in [0, 1] and vertical t in [0, 1]
function evalMainCurtainPt(u, t, ridgeOffset = 0) {
  // u = 0 is the sweeping inner leading edge; u = 1 is the right proscenium edge (x ~ 1055)
  // t = 0 is top batten (y = 128); t = 0.58 is the golden tie-back waist (y = 578); t = 1.0 is stage floor (y = 915)
  let xTop = lerp(325, 1055, pow(u, 0.88));
  let yTop = 128;

  let xWaist = lerp(835, 1048, pow(u, 0.92));
  let yWaist = lerp(575, 590, u);

  let xBot = lerp(685, 1055, pow(u, 0.85));
  let yBot = lerp(908, 924, u);

  let x, y;
  if (t <= 0.58) {
    let lt = t / 0.58;
    // Heavy catenary sag in the upper swag
    let sag = sin(lt * 180);
    x = lerp(xTop, xWaist, pow(lt, 0.82)) - (1 - u) * 58 * sag;
    y = lerp(yTop, yWaist, lt) + (1 - u * 0.5) * 42 * sag;
  } else {
    let lt = (t - 0.58) / 0.42;
    // Cascading bell-skirt below tie-back, buckling as it pools on the floor
    let flare = sin(lt * 180);
    let floorBuckle = lt > 0.78 ? sin((lt - 0.78) / 0.22 * 360) * 14 * (1 - u * 0.4) : 0;
    x = lerp(xWaist, xBot, pow(lt, 0.75)) - (1 - u) * 28 * flare + floorBuckle;
    y = lerp(yWaist, yBot, lt);
  }

  // Organic crushed-velvet ripple along each fold
  let ripple = sin(t * 520 + u * 410) * 5 * (1 - 0.3 * u);
  return [x + ripple + ridgeOffset, y];
}

function drawMainCrushedVelvetCurtain() {
  // 1. Cast a deep theatrical shadow behind the main curtain onto the backdrop & stage floor
  let shadowOutline = [];
  for (let t = 0; t <= 1.001; t += 0.04) {
    let p = evalMainCurtainPt(0, t);
    shadowOutline.push([p[0] - 22, p[1] - 10]);
  }
  shadowOutline.push([1060, 925], [1060, 125]);
  polyWash(shadowOutline, PAL.inkBlack, 195);

  // 2. Solid Oxblood Foundation Silhouette of the Main Curtain
  let curtainOutline = [];
  for (let t = 0; t <= 1.001; t += 0.03) {
    curtainOutline.push(evalMainCurtainPt(0, t));
  }
  for (let u = 0.1; u <= 1.001; u += 0.1) {
    curtainOutline.push(evalMainCurtainPt(u, 1.0));
  }
  curtainOutline.push([1060, 128]);
  polyWash(curtainOutline, PAL.deepOxblood, 255);

  // 3. Watercolor Bleed Undertones in Carmine & Dark Oxblood (batched for performance)
  let midBody = [];
  for (let t = 0.15; t <= 0.98; t += 0.05) midBody.push(evalMainCurtainPt(0.02, t));
  for (let t = 0.98; t >= 0.15; t -= 0.05) midBody.push(evalMainCurtainPt(0.75, t));
  polyFill(midBody, PAL.oxblood, 150, 0.15, 0.45, 0.3);

  let lowerUplightBody = [];
  for (let t = 0.45; t <= 1.0; t += 0.05) lowerUplightBody.push(evalMainCurtainPt(0.0, t));
  for (let t = 1.0; t >= 0.45; t -= 0.05) lowerUplightBody.push(evalMainCurtainPt(0.65, t));
  polyFill(lowerUplightBody, PAL.carmine, 140, 0.18, 0.4, 0.25);

  // 4. Sculpting the 10 Heavy tubular & crushed folds (u from 0 to 1)
  const numFolds = 10;
  for (let f = 0; f < numFolds; f++) {
    let uL = f / numFolds;
    let uMid = (f + 0.45) / numFolds;
    let uR = (f + 1.0) / numFolds;

    // A. Deep Shadow Valley on the right/upper side of each fold using CHARCOAL MASS
    let valleyPoly = [];
    for (let t = 0.02; t <= 0.98; t += 0.06) {
      valleyPoly.push(evalMainCurtainPt(lerp(uMid, uR, 0.35), t, -3));
    }
    for (let t = 0.98; t >= 0.02; t -= 0.06) {
      valleyPoly.push(evalMainCurtainPt(uR, t, 3));
    }
    polyMass(valleyPoly, "charcoal", f % 2 === 0 ? PAL.voidOxblood : PAL.inkBlack, {
      precision: 0.62,
      strength: 0.58,
      gradient: 0.35,
      outline: false
    });

    // B. Rich Carmine Mid-Tone Crown Polygon along each fold ridge
    let crownPoly = [];
    for (let t = 0.02; t <= 0.99; t += 0.05) {
      crownPoly.push(evalMainCurtainPt(uL, t, 2));
    }
    for (let t = 0.99; t >= 0.02; t -= 0.05) {
      crownPoly.push(evalMainCurtainPt(lerp(uMid, uR, 0.4), t, -2));
    }
    let crownCol = f < 6 ? PAL.carmine : PAL.carmineShadow;
    polyWash(crownPoly, crownCol, 185);

    // C. Footlight Uplight Zone on the lower & left-facing bell of each fold
    if (f < 8) {
      let litPoly = [];
      for (let t = 0.32; t <= 0.99; t += 0.05) {
        litPoly.push(evalMainCurtainPt(lerp(uL, uMid, 0.15), t));
      }
      for (let t = 0.99; t >= 0.32; t -= 0.05) {
        litPoly.push(evalMainCurtainPt(lerp(uL, uMid, 0.85), t));
      }
      polyWash(litPoly, f < 4 ? PAL.carmineBright : PAL.carmine, 165);
    }

    // D. Hyperreal Crushed-Velvet Pile Strokes & Anisotropic Specular Facets
    let steps = 95;
    for (let s = 0; s < steps; s++) {
      let t = map(s, 0, steps - 1, 0.02, 0.99);
      let pL = evalMainCurtainPt(uL, t);
      let pMid = evalMainCurtainPt(uMid, t);
      let pR = evalMainCurtainPt(uR, t);

      // Compute crushed-velvet noise field (fractured islands of specular sheen)
      let n1 = noise(f * 2.7 + t * 8.5, t * 14.0);
      let n2 = noise(f * 5.1 + 20, t * 28.0);
      let crushVal = n1 * 0.65 + n2 * 0.35;

      // Stronger footlight uplight on lower curtain (t > 0.4) and inner folds (f < 6)
      let footBoost = map(t, 0.2, 0.95, 0.0, 0.32, true) * map(f, 0, 9, 1.0, 0.35);
      let totalLuminance = crushVal + footBoost;

      // Cross-contour shadow strokes into the trough
      brush.set("2B", PAL.voidOxblood, map(n1, 0, 1, 0.35, 0.75));
      brush.line(pMid[0], pMid[1], pR[0], pR[1]);

      // Mid-tone carmine velvet nap strokes
      brush.set("cpencil", totalLuminance > 0.55 ? PAL.carmineBright : PAL.oxblood, 0.55);
      brush.line(pL[0], pL[1], pMid[0], pMid[1]);

      // Crushed-velvet fractured highlight facets!
      if (totalLuminance > 0.60) {
        let hx1 = lerp(pL[0], pMid[0], 0.15);
        let hy1 = lerp(pL[1], pMid[1], 0.15);
        let hx2 = lerp(pL[0], pMid[0], 0.82);
        let hy2 = lerp(pL[1], pMid[1], 0.82);

        // Glossy marker micro-glaze on crushed velvet facet
        if (s % 2 === 0) {
          brush.set("marker", totalLuminance > 0.76 ? PAL.velvetUplight : PAL.velvetRose, 0.45);
          brush.line(hx1, hy1, hx2, hy2 - 2);
        }

        // Crisp silky pile threads catching the hard footlight
        let specCol = totalLuminance > 0.82 ? PAL.velvetSpecular : (totalLuminance > 0.72 ? PAL.velvetUplight : PAL.velvetRose);
        brush.set("cpencil", specCol, map(totalLuminance, 0.6, 1.0, 0.3, 0.65));
        brush.line(hx1, hy1 + 1, hx2, hy2 - 1);

        // Pinpoint warm amber/ochre footlight glint on the very brightest crushed ridges near the bottom
        if (totalLuminance > 0.85 && t > 0.52) {
          brush.set("rotring", PAL.goldSpecular, 0.28);
          brush.line(lerp(hx1, hx2, 0.3), lerp(hy1, hy2, 0.3), lerp(hx1, hx2, 0.75), lerp(hy1, hy2, 0.75));
        }
      }
    }

    // Continuous deep charcoal core spline running down each fold trough
    let troughSpline = [];
    for (let t = 0.02; t <= 0.99; t += 0.04) {
      let pt = evalMainCurtainPt(lerp(uMid, uR, 0.78), t);
      troughSpline.push([pt[0], pt[1], map(sin(t * 180), 0, 1, 0.4, 1.0)]);
    }
    brush.set("charcoal", PAL.inkBlack, 0.95);
    brush.spline(troughSpline, 0.45);
  }

  // 5. Horizontal & Diagonal Crushed Folds where the Curtain Pools on the Stage Floor (y = 855..925)
  drawCurtainFloorPooling();

  // 6. Upward Shadow Cast by the Tie-Back Rope onto the Gathered Curtain Waist
  polyMass([
    [825, 575], [1045, 592],
    [1045, 540], [835, 520]
  ], "charcoal", PAL.inkBlack, {
    precision: 0.6, strength: 0.65, gradient: 0.4, outline: false
  });
}

function drawCurtainFloorPooling() {
  // Heavy buckled horizontal folds at the bottom hem (x = 685..1045, y = 860..922)
  for (let b = 0; b < 7; b++) {
    let bx1 = map(b, 0, 6, 685, 980);
    let bx2 = bx1 + random(45, 75);
    let by = map(b, 0, 6, 902, 916) + (b % 2 === 0 ? -8 : 4);

    // Charcoal shadow pocket above the floor buckle
    polyMass([
      [bx1, by - 18], [bx2, by - 14],
      [bx2 - 6, by], [bx1 + 6, by - 2]
    ], "charcoal", PAL.voidOxblood, { precision: 0.65, strength: 0.5, gradient: 0.3, outline: false });

    // Bright footlight-kissed velvet roll on the floor
    let rollPts = [
      [bx1, by - 2],
      [(bx1 + bx2) * 0.5, by - 9, 0.9],
      [bx2, by + 2]
    ];
    brush.set("marker", PAL.carmineBright, 0.75);
    brush.spline(rollPts, 0.5);
    brush.set("cpencil", PAL.velvetUplight, 0.55);
    brush.spline(rollPts.map(p => [p[0], p[1] + 2, 0.8]), 0.5);
    brush.set("rotring", PAL.velvetSpecular, 0.32);
    brush.spline(rollPts.map(p => [p[0], p[1] + 3.5, 0.6]), 0.5);
  }
}

// ============================================================================
// 6. CRISP-ENOUGH-TO-TOUCH CURTAIN FRINGE, BRAID GALON & TIE-BACK TASSELS
// ============================================================================
function drawAllCurtainFringes() {
  // 1. Upper Valance Scallop Fringe (3 swags)
  const swags = [
    { x1: 145, x2: 430, drop: 265 },
    { x1: 405, x2: 745, drop: 292 },
    { x1: 715, x2: 1055, drop: 270 }
  ];
  for (let s = 0; s < swags.length; s++) {
    let sw = swags[s];
    let pts = [];
    for (let u = 0; u <= 1.001; u += 0.015) {
      let x = lerp(sw.x1, sw.x2, u);
      let y = 145 + sin(u * 180) * (sw.drop - 145);
      pts.push([x, y]);
    }
    drawCrispBullionFringeAlongPath(pts, 24, 0.85, false);
  }

  // 2. Left Curtain Inner Edge Fringe
  let leftEdgePts = [];
  for (let y = 260; y <= 905; y += 8) {
    let t = (y - 135) / (906 - 135);
    let x = t < 0.58 ? lerp(290, 248, t / 0.58) : lerp(248, 282, (t - 0.58) / 0.42);
    leftEdgePts.push([x + sin(y * 2.5) * 2, y]);
  }
  drawCrispBullionFringeAlongPath(leftEdgePts, 20, 0.8, true);

  // 3. HERO FRINGE: Main Half-Drawn Curtain Upper Catenary Edge (t = 0.04 to 0.58)
  let mainUpperEdge = [];
  for (let t = 0.04; t <= 0.585; t += 0.006) {
    mainUpperEdge.push(evalMainCurtainPt(0, t));
  }
  drawCrispBullionFringeAlongPath(mainUpperEdge, 34, 1.15, false);

  // 4. HERO FRINGE: Main Curtain Lower Cascading Edge (t = 0.58 to 1.0)
  let mainLowerEdge = [];
  for (let t = 0.58; t <= 1.001; t += 0.008) {
    mainLowerEdge.push(evalMainCurtainPt(0, t));
  }
  drawCrispBullionFringeAlongPath(mainLowerEdge, 28, 1.1, true);

  // 5. Bottom Hem Bullion Fringe Pooling on the Stage Boards
  let floorHemPts = [];
  for (let u = 0; u <= 0.88; u += 0.015) {
    let p = evalMainCurtainPt(u, 1.0);
    floorHemPts.push([p[0], p[1] + sin(u * 900) * 3]);
  }
  drawCrispBullionFringeAlongPath(floorHemPts, 18, 1.05, false);

  // 6. Heavy Braided Gold Tie-Back Rope & Twin Imperial Bullion Tassels at (835..1055, 575)
  drawTieBackAndImperialTassels();
}

function drawCrispBullionFringeAlongPath(pts, baseLen, scaleMult, isSideEdge) {
  if (!pts || pts.length < 2) return;

  // A. Woven Gold & Sienna Galon Header Braid Ribbon along the curve
  let ribbonW = 6.5 * scaleMult;
  // Dark shadow under the ribbon
  brush.set("rotring", PAL.inkBlack, 0.7 * scaleMult);
  brush.spline(pts.map(p => [p[0] + 1, p[1] + 2, 0.8]), 0.35);

  // Raw sienna base ribbon
  brush.set("marker", PAL.rawSienna, 0.65 * scaleMult);
  brush.spline(pts.map(p => [p[0], p[1] - ribbonW * 0.4, 0.8]), 0.35);

  // Bright ochre middle glaze on ribbon
  brush.set("marker", PAL.ochreBright, 0.45 * scaleMult);
  brush.spline(pts.map(p => [p[0], p[1] - ribbonW * 0.2, 0.7]), 0.35);

  // Crisp upper and lower metallic edge threads of the galon braid
  brush.set("rotring", PAL.siennaShadow, 0.4 * scaleMult);
  brush.spline(pts.map(p => [p[0], p[1] - ribbonW, 0.7]), 0.35);
  brush.set("rotring", PAL.goldSpecular, 0.42 * scaleMult);
  brush.spline(pts.map(p => [p[0], p[1], 0.8]), 0.35);

  // B. Individual Hanging Twisted Bullion Fringe Strands & Drops
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    let x = p[0];
    let y = p[1];

    // Cross-stitch diamond embroidery inside the galon header tape
    if (i < pts.length - 1) {
      let pn = pts[i + 1];
      brush.set("rotring", i % 2 === 0 ? PAL.goldSpecular : PAL.siennaDeep, 0.3 * scaleMult);
      brush.line(x, y - ribbonW, pn[0], pn[1]);
      brush.line(x, y, pn[0], pn[1] - ribbonW);
    }

    // Scalloped fringe length modulation
    let isTasselDrop = (i % 4 === 0);
    let wave = sin(i * 32) * 3.5 * scaleMult;
    let strandLen = (baseLen + wave + (isTasselDrop ? 6.5 * scaleMult : 0)) * (isSideEdge ? 0.78 : 1.0);

    // Slight sway from gravity
    let endX = x + (isSideEdge ? -3.5 : sin(i * 19) * 1.2);
    let endY = y + strandLen;

    // 1. Crisp cast shadow of this fringe cord onto the velvet/backdrop
    brush.set("rotring", PAL.inkBlack, 0.42 * scaleMult);
    brush.line(x + 2.2, y + 1, endX + 2.5, endY + 1);

    // 2. Dark raw-sienna core of twisted bullion wire
    brush.set("rotring", PAL.siennaDeep, 0.48 * scaleMult);
    brush.line(x, y, endX, endY);

    // 3. Bright ochre body thread
    brush.set("cpencil", PAL.ochreBright, 0.42 * scaleMult);
    brush.line(x - 0.5, y + 1, endX - 0.5, endY - 1);

    // 4. Crisp specular wire twists & bottom bullion bead (lit by hard footlight below!)
    let footIntensity = map(y, 180, 910, 0.55, 1.0, true);
    let glintCol = footIntensity > 0.75 ? PAL.footlightWhite : PAL.goldSpecular;
    brush.set("rotring", glintCol, (0.32 + 0.12 * footIntensity) * scaleMult);

    // Segmented spiral twist ticks down the strand so the edge feels tactile & touchable
    let numBeads = floor(strandLen / 5.5);
    for (let b = 1; b <= numBeads; b++) {
      let bt = b / (numBeads + 1);
      let bx = lerp(x, endX, bt);
      let by = lerp(y, endY, bt);
      brush.line(bx - 1.1, by - 0.6, bx + 0.9, by + 0.8);
    }

    // Terminal bullion pom/drop on every 4th strand
    if (isTasselDrop) {
      // Tiny bell cap in raw sienna
      brush.set("rotring", PAL.rawSienna, 0.65 * scaleMult);
      brush.line(endX - 2.2 * scaleMult, endY - 2, endX + 2.2 * scaleMult, endY - 2);
      // Bright gold bottom rim of pom drop
      brush.set("rotring", PAL.goldSpecular, 0.55 * scaleMult);
      brush.circle(endX, endY + 1.5 * scaleMult, 2.2 * scaleMult, 0.08);
      brush.set("rotring", PAL.footlightWhite, 0.35 * scaleMult);
      brush.line(endX - 1.8 * scaleMult, endY + 2.8 * scaleMult, endX + 1.8 * scaleMult, endY + 2.8 * scaleMult);
    }
  }
}

function drawTieBackAndImperialTassels() {
  // Heavy twisted bullion rope wrapping the curtain waist from (832, 575) to (1055, 520)
  let ropePts = [];
  let steps = 28;
  for (let i = 0; i <= steps; i++) {
    let u = i / steps;
    let rx = lerp(830, 1055, u);
    let ry = lerp(575, 515, u) + sin(u * 180) * 26;
    ropePts.push([rx, ry]);
  }

  // Deep shadow above and below the thick twisted cable
  brush.set("charcoal", PAL.inkBlack, 1.3);
  brush.spline(ropePts.map(p => [p[0], p[1] - 9, 0.9]), 0.4);
  brush.set("rotring", PAL.inkBlack, 0.9);
  brush.spline(ropePts.map(p => [p[0], p[1] + 9, 0.9]), 0.4);

  // Individual diagonal cable twists along the rope
  for (let i = 0; i < ropePts.length - 1; i++) {
    let p1 = ropePts[i];
    let p2 = ropePts[i + 1];
    let mx = (p1[0] + p2[0]) * 0.5;
    let my = (p1[1] + p2[1]) * 0.5;

    // Raw sienna & ochre marker glaze for each bulbous rope twist
    brush.set("marker", PAL.rawSienna, 0.9);
    brush.line(p1[0], p1[1] - 5, p2[0], p2[1] + 5);
    brush.set("marker", PAL.ochreBright, 0.65);
    brush.line(p1[0], p1[1] + 1, p2[0], p2[1] + 6);

    // Crisp dark divider and bright footlight lower rim on each twist
    brush.set("rotring", PAL.siennaShadow, 0.55);
    brush.line(p1[0], p1[1] - 7, p2[0], p2[1] + 7);
    brush.set("rotring", PAL.goldSpecular, 0.5);
    brush.line(mx - 3, my + 6, mx + 4, my + 4);
  }

  // Draw Two Grand Imperial Bullion Tassels hanging at (915, 605) and (958, 635)
  drawSingleImperialTassel(912, 598, 1.15);
  drawSingleImperialTassel(956, 626, 1.0);
}

function drawSingleImperialTassel(tx, ty, sc) {
  // Suspension cord from tie-back rope
  brush.set("rotring", PAL.siennaDeep, 0.8 * sc);
  brush.line(tx, ty - 24 * sc, tx, ty);
  brush.set("rotring", PAL.goldSpecular, 0.45 * sc);
  brush.line(tx - 1.5, ty - 24 * sc, tx - 1.5, ty);

  // Cast shadow of the tassel onto the red velvet behind it
  polyWash([
    [tx - 16 * sc, ty],
    [tx + 24 * sc, ty],
    [tx + 32 * sc, ty + 95 * sc],
    [tx - 18 * sc, ty + 95 * sc]
  ], PAL.inkBlack, 195);

  // Turned wooden/gilt Acorn MouldHead of tassel
  polyWash([
    [tx - 14 * sc, ty + 4 * sc],
    [tx + 14 * sc, ty + 4 * sc],
    [tx + 18 * sc, ty + 22 * sc],
    [tx - 18 * sc, ty + 22 * sc]
  ], PAL.rawSienna, 245);

  // Marker glaze & crisp rings on tassel head
  brush.set("marker", PAL.ochreBright, 0.8 * sc);
  brush.line(tx - 13 * sc, ty + 15 * sc, tx + 13 * sc, ty + 15 * sc);
  brush.set("rotring", PAL.siennaShadow, 0.55 * sc);
  brush.line(tx - 15 * sc, ty + 6 * sc, tx + 15 * sc, ty + 6 * sc);
  brush.line(tx - 18 * sc, ty + 22 * sc, tx + 18 * sc, ty + 22 * sc);
  brush.set("rotring", PAL.goldSpecular, 0.55 * sc);
  brush.line(tx - 17 * sc, ty + 20 * sc, tx + 17 * sc, ty + 20 * sc);
  brush.line(tx - 12 * sc, ty + 11 * sc, tx + 12 * sc, ty + 11 * sc);

  // Dense Skirt of Crisp Twisted Bullion Fringe Cords
  let skirtTop = ty + 23 * sc;
  let skirtBot = ty + 88 * sc;
  let numCords = 21;
  for (let c = 0; c < numCords; c++) {
    let u = map(c, 0, numCords - 1, -1, 1);
    let x1 = tx + u * 16 * sc;
    let x2 = tx + u * 23 * sc;
    let y2 = skirtBot + cos(u * 90) * 6 * sc;

    let isLit = abs(u - 0.15) < 0.55;
    brush.set("rotring", PAL.siennaShadow, 0.5 * sc);
    brush.line(x1, skirtTop, x2, y2);

    brush.set("cpencil", isLit ? PAL.ochreLight : PAL.rawSienna, 0.45 * sc);
    brush.line(x1 + 0.6, skirtTop + 2, x2 + 0.6, y2 - 2);

    // Crisp metallic wire beads catching the footlight along the tassel skirt
    if (isLit || c % 2 === 0) {
      brush.set("rotring", isLit ? PAL.footlightWhite : PAL.goldSpecular, 0.35 * sc);
      for (let b = 0.2; b <= 0.95; b += 0.18) {
        let bx = lerp(x1, x2, b);
        let by = lerp(skirtTop, y2, b);
        brush.line(bx - 1, by, bx + 1, by + 1);
      }
      // Crisp bright tip at bottom of bullion cord
      brush.circle(x2, y2, 1.4 * sc, 0.05);
    }
  }
}

// ============================================================================
// 7. GILT PROSCENIUM MOULDINGS (RAW SIENNA & BRIGHT OCHRE MARKER GLAZES)
// ============================================================================
function drawGiltProscenium() {
  // Left Pier: x in [0, 148], y in [120, 945]
  // Right Pier: x in [1052, 1200], y in [120, 945]
  // Top Architrave & Cornice: x in [0, 1200], y in [0, 138] + Corner Spandrels

  drawProsceniumPier(0, 148, true);
  drawProsceniumPier(1052, 1200, false);
  drawProsceniumTopArch();
}

function drawProsceniumPier(x1, x2, isLeft) {
  let w = x2 - x1;
  let innerX = isLeft ? x2 : x1;
  let outerX = isLeft ? x1 : x2;

  // 1. Deep Umber/Sienna Shadow Ground
  polyWash([[x1, 115], [x2, 115], [x2, 955], [x1, 955]], PAL.siennaShadow, 255);

  // 2. Glossy Marker Glazes in Raw Sienna & Bright Ochre (strongest near lower footlights & inner bevel)
  // Vertical marker glaze bands
  let bands = 7;
  for (let b = 0; b < bands; b++) {
    let u1 = b / bands;
    let u2 = (b + 1) / bands;
    let bx = lerp(innerX, outerX, (u1 + u2) * 0.5);
    let col = b < 2 ? PAL.ochreBright : (b < 5 ? PAL.rawSienna : PAL.siennaDeep);

    brush.set("marker", col, 1.25);
    brush.line(bx, 135, bx, 945);
  }

  // Intense bright ochre & gold marker glaze on the lower half (y = 520..940) from the hard footlight
  for (let m = 0; m < 8; m++) {
    let mx = lerp(innerX + (isLeft ? -10 : 10), lerp(innerX, outerX, 0.65), m / 7);
    brush.set("marker", m < 4 ? PAL.ochreLight : PAL.ochreBright, 1.0);
    brush.line(mx, 520 + m * 20, mx, 935);
  }

  // 3. High Panelled Dado Base of Proscenium Pier (y = 755..945)
  let dadoTop = 755;
  let dadoBot = 945;
  // Projecting dado cap moulding (brightly lit underneath by footlights!)
  polyWash([[x1, dadoTop - 16], [x2, dadoTop - 16], [x2, dadoTop + 4], [x1, dadoTop + 4]], PAL.siennaDeep, 240);
  brush.set("marker", PAL.ochreLight, 0.9);
  brush.line(x1, dadoTop + 1, x2, dadoTop + 1);
  brush.set("rotring", PAL.footlightWhite, 0.65);
  brush.line(x1, dadoTop + 4, x2, dadoTop + 4);
  // Upward shadow cast by dado cap onto pilaster shaft above
  polyWash([[x1, dadoTop - 42], [x2, dadoTop - 42], [x2, dadoTop - 16], [x1, dadoTop - 16]], PAL.inkBlack, 180);

  // Sunken gilded panel inside dado
  let pad = 22;
  polyWash([[x1 + pad, dadoTop + 22], [x2 - pad, dadoTop + 22], [x2 - pad, dadoBot - 22], [x1 + pad, dadoBot - 22]], PAL.siennaShadow, 210);
  brush.set("marker", PAL.rawSienna, 0.85);
  brush.rect(x1 + pad + 4, dadoTop + 26, w - (pad + 4) * 2, (dadoBot - dadoTop) - 52, "corner");
  // Crisp highlight on top inside edge (facing down toward footlights!)
  brush.set("rotring", PAL.goldSpecular, 0.65);
  brush.line(x1 + pad, dadoTop + 22, x2 - pad, dadoTop + 22);
  brush.set("rotring", PAL.inkBlack, 0.65);
  brush.line(x1 + pad, dadoBot - 22, x2 - pad, dadoBot - 22);

  // 4. Fluted Gilt Pilaster & Coffered Relief Rosettes (y = 210..735)
  let pilX1 = x1 + 26;
  let pilX2 = x2 - 26;
  let numFlutes = 5;
  for (let f = 0; f <= numFlutes; f++) {
    let fx = map(f, 0, numFlutes, pilX1, pilX2);
    brush.set("rotring", PAL.siennaShadow, 0.55);
    brush.line(fx, 215, fx, 730);
    brush.set("rotring", PAL.goldSpecular, 0.38);
    brush.line(fx + (isLeft ? 2.2 : -2.2), 215, fx + (isLeft ? 2.2 : -2.2), 730);
  }

  // Carved horizontal relief bands with acanthus & rosette bosses along the inner moulding
  let bandX1 = isLeft ? x2 - 26 : x1 + 4;
  let bandX2 = isLeft ? x2 - 4 : x1 + 26;
  let bandCx = (bandX1 + bandX2) * 0.5;
  for (let y = 230; y <= 730; y += 42) {
    // Upward shadow above each carved rosette
    polyWash([[bandX1, y - 18], [bandX2, y - 18], [bandX2, y - 4], [bandX1, y - 4]], PAL.inkBlack, 170);
    // Marker glaze on rosette
    brush.set("marker", y > 500 ? PAL.ochreLight : PAL.ochreBright, 0.7);
    brush.circle(bandCx, y, 8, 0.1);
    // Crisp footlight highlight on bottom half of rosette
    brush.set("rotring", PAL.footlightWhite, 0.48);
    brush.arc(bandCx, y, 8.5, 15, 165);
    brush.set("rotring", PAL.siennaShadow, 0.45);
    brush.arc(bandCx, y, 8.5, 195, 345);
  }

  // 5. Gilt Corinthian Capital at Top of Pier (y = 140..215)
  // Deep upward shadow above capital
  polyWash([[x1, 132], [x2, 132], [x2, 155], [x1, 155]], PAL.inkBlack, 210);
  // Acanthus scroll tiers
  for (let t = 0; t < 3; t++) {
    let ty = 158 + t * 18;
    brush.set("marker", t === 2 ? PAL.ochreLight : PAL.rawSienna, 0.85);
    brush.line(x1 + 12, ty, x2 - 12, ty);
    brush.set("rotring", PAL.goldSpecular, 0.55);
    brush.line(x1 + 10, ty + 4, x2 - 10, ty + 4);
    brush.set("rotring", PAL.inkBlack, 0.55);
    brush.line(x1 + 10, ty - 4, x2 - 10, ty - 4);
  }

  // Crisp inner vertical bevel of the proscenium arch catching the stage footlights
  brush.set("marker", PAL.ochreLight, 0.9);
  brush.line(innerX + (isLeft ? -5 : 5), 140, innerX + (isLeft ? -5 : 5), 940);
  brush.set("rotring", PAL.footlightWhite, 0.65);
  brush.line(innerX + (isLeft ? -1.5 : 1.5), 140, innerX + (isLeft ? -1.5 : 1.5), 940);
  brush.set("rotring", PAL.inkBlack, 0.8);
  brush.line(innerX, 140, innerX, 945);
}

function drawProsceniumTopArch() {
  // 1. Curved Corner Spandrels (connecting y = 135 at center to y = 250 at x = 148 and x = 1052)
  let leftSpandrel = [[148, 125], [330, 125]];
  for (let a = 270; a >= 180; a -= 10) {
    leftSpandrel.push([330 + cos(a) * 182, 255 + sin(a) * 130]);
  }
  polyWash(leftSpandrel, PAL.siennaDeep, 250);

  let rightSpandrel = [[870, 125], [1052, 125], [1052, 255]];
  for (let a = 0; a >= -90; a -= 10) {
    rightSpandrel.push([870 + cos(a) * 182, 255 + sin(a) * 130]);
  }
  polyWash(rightSpandrel, PAL.siennaDeep, 250);

  // Marker glazes & curved moulding highlights on spandrels
  for (let side = 0; side < 2; side++) {
    let cx = side === 0 ? 330 : 870;
    let cy = 255;
    let startA = side === 0 ? 180 : 270;
    let endA = side === 0 ? 270 : 360;

    let arcPts = [];
    for (let a = startA; a <= endA; a += 8) {
      arcPts.push([cx + cos(a) * 182, cy + sin(a) * 130, 0.8]);
    }
    // Glossy ochre marker glaze along curved arch soffit
    brush.set("marker", PAL.ochreBright, 1.1);
    brush.spline(arcPts, 0.4);
    brush.set("rotring", PAL.goldSpecular, 0.65);
    brush.spline(arcPts.map(p => [p[0], p[1] + 3, 0.8]), 0.4);
    brush.set("rotring", PAL.inkBlack, 0.75);
    brush.spline(arcPts.map(p => [p[0], p[1] - 5, 0.8]), 0.4);

    // Gilded spandrel medallion
    let mx = side === 0 ? 205 : 995;
    let my = 175;
    brush.set("marker", PAL.rawSienna, 0.95);
    brush.circle(mx, my, 24, 0.1);
    brush.set("marker", PAL.ochreBright, 0.7);
    brush.circle(mx, my + 4, 16, 0.1);
    brush.set("rotring", PAL.goldSpecular, 0.5);
    brush.arc(mx, my, 24, 15, 165);
    brush.set("rotring", PAL.inkBlack, 0.55);
    brush.arc(mx, my, 24, 195, 345);
  }

  // 2. Main Horizontal Proscenium Architrave & Coffered Cornice (x = 0..1200, y = 0..136)
  polyWash([[0, 0], [1200, 0], [1200, 136], [0, 136]], PAL.siennaShadow, 255);

  // Layered Horizontal Marker Glazes in Raw Sienna & Bright Ochre
  const mouldingLevels = [
    { y: 18, w: 1.2, col: PAL.siennaDeep },
    { y: 42, w: 1.4, col: PAL.rawSienna },
    { y: 68, w: 1.3, col: PAL.siennaWarm },
    { y: 98, w: 1.5, col: PAL.ochreBright },
    { y: 122, w: 1.2, col: PAL.ochreLight },
    { y: 132, w: 0.9, col: PAL.goldSpecular }
  ];
  for (let i = 0; i < mouldingLevels.length; i++) {
    let m = mouldingLevels[i];
    brush.set("marker", m.col, m.w);
    brush.line(0, m.y, 1200, m.y);
  }

  // Coffered Rosette Panels across the Frieze (y = 48..96)
  for (let cx = 60; cx <= 1140; cx += 68) {
    if (abs(cx - 600) < 95) continue; // leave space for grand central cartouche
    polyWash([[cx - 26, 48], [cx + 26, 48], [cx + 26, 94], [cx - 26, 94]], PAL.inkBlack, 185);
    brush.set("marker", PAL.rawSienna, 0.75);
    brush.rect(cx - 22, 52, 44, 38, "corner");

    // Bottom edge of coffer recessed frame catches upward footlight
    brush.set("rotring", PAL.goldSpecular, 0.5);
    brush.line(cx - 26, 48, cx + 26, 48);
    brush.set("rotring", PAL.inkBlack, 0.55);
    brush.line(cx - 26, 94, cx + 26, 94);

    // Gilded rosette boss inside coffer
    brush.set("marker", PAL.ochreBright, 0.65);
    brush.circle(cx, 71, 11, 0.1);
    brush.set("rotring", PAL.footlightWhite, 0.45);
    brush.arc(cx, 71, 11, 20, 160);
  }

  // Egg-and-Dart & Dentil Moulding Course along y = 108..126
  for (let dx = 16; dx < 1190; dx += 18) {
    // Upward shadow above each dentil block
    polyWash([[dx, 102], [dx + 10, 102], [dx + 10, 112], [dx, 112]], PAL.inkBlack, 200);
    // Ochre face & bright bottom edge of dentil block
    polyWash([[dx, 112], [dx + 10, 112], [dx + 10, 124], [dx, 124]], PAL.ochreBright, 225);
    brush.set("rotring", PAL.footlightWhite, 0.45);
    brush.line(dx, 124, dx + 10, 124);
  }

  // Razor-sharp horizontal cornice shadow and specular lines
  const lineY = [28, 46, 96, 126, 135];
  for (let i = 0; i < lineY.length; i++) {
    let ly = lineY[i];
    brush.set("rotring", PAL.inkBlack, 0.7);
    brush.line(0, ly - 2, 1200, ly - 2);
    brush.set("rotring", i >= 3 ? PAL.footlightWhite : PAL.goldSpecular, 0.55);
    brush.line(0, ly + 1.5, 1200, ly + 1.5);
  }

  // 3. Grand Central Baroque Cartouche at (600, 78)
  drawCentralGiltCartouche(600, 78);
}

function drawCentralGiltCartouche(cx, cy) {
  // Deep upward cast shadow behind the cartouche onto the upper cornice
  let shadPts = [];
  for (let a = 0; a < 360; a += 15) {
    shadPts.push([cx + cos(a) * 98, (cy - 14) + sin(a) * 58]);
  }
  polyMass(shadPts, "charcoal", PAL.inkBlack, { precision: 0.65, strength: 0.6, gradient: 0.3, outline: false });

  // Baroque scrolled shield body in raw sienna & bright ochre
  let shieldPts = [];
  for (let a = 0; a < 360; a += 12) {
    let rMod = 1 + 0.12 * cos(a * 4);
    shieldPts.push([cx + cos(a) * 86 * rMod, cy + sin(a) * 48 * rMod]);
  }
  polyWash(shieldPts, PAL.rawSienna, 250);

  // Glossy marker glazes across the lower scroll work of the cartouche
  brush.set("marker", PAL.ochreBright, 1.3);
  brush.arc(cx, cy, 68, 15, 165);
  brush.set("marker", PAL.ochreLight, 1.1);
  brush.arc(cx, cy + 8, 52, 25, 155);

  // Central oval medallion inside cartouche
  let ovalPts = [];
  for (let a = 0; a < 360; a += 15) {
    ovalPts.push([cx + cos(a) * 38, cy + sin(a) * 26]);
  }
  polyWash(ovalPts, PAL.siennaShadow, 235);
  brush.set("marker", PAL.siennaWarm, 0.9);
  brush.circle(cx, cy + 4, 22, 0.15);

  // Acanthus scrolls & theatrical garland framing the cartouche
  for (let side = -1; side <= 1; side += 2) {
    let scrollPts = [
      [cx + side * 38, cy - 26, 0.6],
      [cx + side * 78, cy - 12, 0.9],
      [cx + side * 88, cy + 18, 1.0],
      [cx + side * 52, cy + 42, 0.8],
      [cx + side * 12, cy + 48, 0.7]
    ];
    brush.set("marker", PAL.ochreBright, 0.95);
    brush.spline(scrollPts, 0.5);
    brush.set("rotring", PAL.inkBlack, 0.65);
    brush.spline(scrollPts.map(p => [p[0], p[1] - 4, p[2]]), 0.5);
    brush.set("rotring", PAL.footlightWhite, 0.6);
    brush.spline(scrollPts.map(p => [p[0], p[1] + 3, p[2]]), 0.5);
  }

  // Crisp gold highlight on bottom crest & crown of cartouche
  brush.set("rotring", PAL.footlightWhite, 0.65);
  brush.arc(cx, cy, 38, 20, 160);
  brush.line(cx - 28, cy + 46, cx + 28, cy + 46);
}

// ============================================================================
// 8. FOOTLIGHT COWLS, STAGE APRON, STALLS FOREGROUND & DUSTY UPLIGHT
// ============================================================================
function drawFootlightsAndStalls() {
  const footX = [255, 385, 515, 645, 775, 905];

  // 1. Dusty Volumetric Uplight Cones & Floating Dust Motes in the Air
  for (let i = 0; i < footX.length; i++) {
    let fx = footX[i];
    let fy = apronY(fx) - 6;

    // Subtle diagonal spray beams rising from each footlight
    for (let r = 0; r < 5; r++) {
      let ang = map(r, 0, 4, -118, -62);
      let beamLen = random(240, 420);
      let ex = fx + cos(ang) * beamLen;
      let ey = fy + sin(ang) * beamLen;
      brush.set("spray", r === 2 ? PAL.goldSpecular : PAL.parchment, 0.65);
      brush.line(fx, fy - 8, ex, ey);
    }

    // Crisp illuminated dust motes suspended in the expectant air above the footlights
    for (let m = 0; m < 28; m++) {
      let d = random(25, 480);
      let a = random(-125, -55);
      let mx = fx + cos(a) * d + random(-18, 18);
      let my = fy + sin(a) * d;
      if (my > 155 && mx > 165 && mx < 1035) {
        let isOverVelvet = mx > 680 || (mx > 400 && my < 480);
        let moteCol = isOverVelvet
          ? (random() < 0.5 ? PAL.velvetSpecular : PAL.goldSpecular)
          : (random() < 0.6 ? PAL.footlightWhite : PAL.ochreLight);
        brush.set("rotring", moteCol, random(0.22, 0.45));
        brush.line(mx, my, mx + 1.2, my - 0.8);
      }
    }
  }

  // 2. Curved Wooden Stage Apron Front Face (y = apronY(x) to apronY(x) + 68)
  let apronFace = [];
  for (let x = 0; x <= 1200; x += 25) {
    apronFace.push([x, apronY(constrain(x, 140, 1060))]);
  }
  for (let x = 1200; x >= 0; x -= 25) {
    apronFace.push([x, apronY(constrain(x, 140, 1060)) + 72]);
  }
  polyWash(apronFace, PAL.umberDeep, 255);

  // Carved bullnose lip at top of stage apron
  let lipPts = [];
  for (let x = 0; x <= 1200; x += 25) {
    lipPts.push([x, apronY(constrain(x, 140, 1060)), 0.8]);
  }
  brush.set("marker", PAL.rawSienna, 0.95);
  brush.spline(lipPts, 0.4);
  brush.set("rotring", PAL.goldSpecular, 0.6);
  brush.spline(lipPts.map(p => [p[0], p[1] - 1.5, 0.8]), 0.4);
  brush.set("rotring", PAL.inkBlack, 0.85);
  brush.spline(lipPts.map(p => [p[0], p[1] + 5, 0.9]), 0.4);

  // Recessed wooden apron panels along the front face
  for (let px = 80; px <= 1040; px += 110) {
    let py1 = apronY(constrain(px, 140, 1060)) + 14;
    let py2 = apronY(constrain(px + 85, 140, 1060)) + 14;
    polyWash([[px, py1], [px + 85, py2], [px + 85, py2 + 42], [px, py1 + 42]], PAL.charcoalDark, 210);
    brush.set("rotring", PAL.siennaWarm, 0.45);
    brush.line(px, py1, px + 85, py2);
    brush.set("rotring", PAL.inkBlack, 0.55);
    brush.line(px, py1 + 42, px + 85, py2 + 42);
  }

  // 3. The 6 Clam-Shell Footlight Cowls (seen from behind in the stalls, with blinding rim halos)
  for (let i = 0; i < footX.length; i++) {
    let fx = footX[i];
    let fy = apronY(fx) - 2;
    let cw = 26;
    let ch = 19;

    // Blinding incandescent halo spilling out from inside the shell
    let haloPts = [];
    for (let a = 180; a <= 360; a += 15) {
      haloPts.push([fx + cos(a) * (cw + 10), (fy - 2) + sin(a) * (ch + 10)]);
    }
    polyWash(haloPts, PAL.footlightWhite, 220);

    // Dark cast-iron / bronze outer back shell of footlight cowl
    let shellPts = [];
    for (let a = 180; a <= 360; a += 12) {
      shellPts.push([fx + cos(a) * cw, fy + sin(a) * ch]);
    }
    shellPts.push([fx + cw + 4, fy + 5], [fx - cw - 4, fy + 5]);
    polyWash(shellPts, PAL.inkBlack, 255);

    // Fluted ribs on the back of the metal clam-shell cowl
    for (let r = -3; r <= 3; r++) {
      let rx1 = fx + r * 5.5;
      let rx2 = fx + r * 7.5;
      let ry1 = fy - ch * sqrt(max(0, 1 - pow((r * 5.5) / cw, 2)));
      brush.set("rotring", PAL.warmGrayDark, 0.42);
      brush.line(rx1, ry1 + 2, rx2, fy + 4);
    }

    // Incandescent gold-white rim outline around the top of the cowl hood
    brush.set("rotring", PAL.footlightWhite, 0.75);
    brush.arc(fx, fy, cw + 1.5, 190, 350);
    brush.set("rotring", PAL.ochreLight, 0.55);
    brush.arc(fx, fy, cw + 3.5, 185, 355);

    // Base mounting flange on apron lip
    brush.set("rotring", PAL.rawSienna, 0.6);
    brush.line(fx - cw - 5, fy + 5, fx + cw + 5, fy + 5);
  }

  // 4. Stalls Foreground & Orchestra Pit Balustrade (y = 995..1200)
  polyWash([[0, 995], [1200, 995], [1200, 1200], [0, 1200]], PAL.inkBlack, 255);

  // Curved brass & velvet orchestra pit rail at y ~ 1035
  let railPts = [];
  for (let x = 0; x <= 1200; x += 30) {
    let u = x / 1200;
    railPts.push([x, 1025 + sin(u * 180) * 24, 0.8]);
  }
  // Faint oxblood velvet padding on pit rail
  brush.set("marker", PAL.darkOxblood, 1.3);
  brush.spline(railPts.map(p => [p[0], p[1] + 6, 0.9]), 0.4);
  // Warm brass rail catching faint bounce light from the stage
  brush.set("marker", PAL.rawSienna, 0.75);
  brush.spline(railPts, 0.4);
  brush.set("rotring", PAL.ochreBright, 0.48);
  brush.spline(railPts.map(p => [p[0], p[1] - 2, 0.7]), 0.4);

  // Silhouettes of curved stall seat backs in the immediate foreground (y = 1085..1200)
  const seatX = [110, 340, 580, 820, 1060];
  for (let s = 0; s < seatX.length; s++) {
    let sx = seatX[s];
    let sy = 1135 + (s % 2) * 14;
    let sw = 98;
    let sh = 65;

    let seatPts = [];
    for (let a = 180; a <= 360; a += 12) {
      seatPts.push([sx + cos(a) * sw, (sy + 30) + sin(a) * sh]);
    }
    seatPts.push([sx + sw, 1200], [sx - sw, 1200]);

    // Charcoal mass shadow for the stall seat silhouette
    polyMass(seatPts, "charcoal", PAL.inkBlack, {
      precision: 0.55, strength: 0.65, gradient: 0.2, outline: true
    });

    // Subtle gilt-wood & velvet rim glint on the top crest of the stall seat back
    brush.set("cpencil", PAL.siennaDeep, 0.55);
    brush.arc(sx, sy + 30, sw * 0.85, 215, 325);
    brush.set("rotring", PAL.rawSienna, 0.35);
    brush.arc(sx, sy + 28, sw * 0.82, 235, 305);
  }
}

