function drawOrganicBlob(cx, cy, rx, ry, steps, irregularity) {
  brush.beginShape(0.65);
  for (let i = 0; i < steps; i++) {
    let ang = (i / steps) * 360;
    let n = noise(cx * 0.01 + cos(ang) * 1.3, cy * 0.01 + sin(ang) * 1.3);
    let radX = rx * (1 + (n - 0.5) * 2 * irregularity);
    let radY = ry * (1 + (n - 0.5) * 2 * irregularity);
    brush.vertex(cx + cos(ang) * radX, cy + sin(ang) * radY);
  }
  brush.endShape(CLOSE);
}

