function drawOrganicBand(x1, y1, x2, y2, steps) {
  brush.beginShape(0.4);
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = y1 + (noise(t * 6, 1.2) - 0.5) * 10;
    brush.vertex(x, y);
  }
  for (let i = steps; i >= 0; i--) {
    let t = i / steps;
    let x = lerp(x1, x2, t);
    let y = y2 + (noise(t * 6, 4.7) - 0.5) * 14;
    brush.vertex(x, y);
  }
  brush.endShape(CLOSE);
}

// ============================================================================
// 3. SIKKU KOLAM (EXACT GRAPH TOPOLOGY + HYPERREAL RICE FLOUR + TOE SMUDGE)
// ============================================================================
function drawSikkuKolam() {
  const cx = 615;
  const cy = 588;
  const S = 74; // Grid spacing between pulli (dots)

  // Toe smudge zone parameters (bottom-right of kolam, brushed by bare foot)
  const smudgeCenter = { x: 785, y: 808 };
  const smudgeRadius = 148;
  const dragAngle = -132; // Direction the toe brushed through (up and left)

  // Helper: evaluate how strongly a point (x, y) is affected by the toe smudge (0 = crisp, 1 = fully smudged)
  function getSmudgeFactor(x, y) {
    // Transform into smudge-aligned elliptical coordinates
    let dx = x - smudgeCenter.x;
    let dy = y - smudgeCenter.y;
    let ca = cos(-dragAngle);
    let sa = sin(-dragAngle);
    let ux = dx * ca - dy * sa;
    let uy = dx * sa + dy * ca;
    let d = sqrt((ux / 145) * (ux / 145) + (uy / 95) * (uy / 95));
    if (d >= 1.15) return 0;
    if (d <= 0.45) return 1;
    return map(d, 0.45, 1.15, 1, 0);
  }

  // Step 3A: Define the 61-dot octagonal + cardinal tip Pulli Grid
  function hasDot(i, j) {
    let ai = abs(i);
    let aj = abs(j);
    if (ai <= 4 && aj <= 4 && ai + aj <= 6) return true;
    if ((ai === 5 && aj === 0) || (ai === 0 && aj === 5)) return true;
    return false;
  }

  // Symmetric port rules (D4 dihedral symmetry) creating central lotus, braided rings & outer loops
  function isSymmetricPortOpen(mx, my) {
    let u = max(abs(mx), abs(my));
    let v = min(abs(mx), abs(my));
    let key = u.toFixed(1) + "_" + v.toFixed(1);
    // Curated D4-symmetric closed internal ports for intricate traditional Sikku mandala
    const closedPorts = new Set([
      "1.5_0.0", // Caps the central 4-petal lotus
      "2.0_0.5", // Separates inner star from middle braid
      "2.5_2.0", // Corner loop turn
      "3.5_0.0", // Cardinal inner loop
      "3.0_1.5", // Octagonal petal turn
      "4.0_0.5"  // Outer cardinal neck
    ]);
    return !closedPorts.has(key);
  }

  function isNPortOpen(i, j) {
    if (!hasDot(i, j) || !hasDot(i, j - 1)) return false;
    return isSymmetricPortOpen(i, j - 0.5);
  }

  function isEPortOpen(i, j) {
    if (!hasDot(i, j) || !hasDot(i + 1, j)) return false;
    return isSymmetricPortOpen(i + 0.5, j);
  }

  function dotPos(i, j) {
    // Subtle hand-placed human irregularity on the grid
    let jx = (noise(i * 0.7 + 10, j * 0.7 + 10) - 0.5) * 3.2;
    let jy = (noise(i * 0.7 + 30, j * 0.7 + 30) - 0.5) * 3.2;
    return { x: cx + i * S + jx, y: cy + j * S + jy };
  }

  // Quadrants around dot (i, j): 0 = NW, 1 = NE, 2 = SE, 3 = SW
  function quadAnchor(i, j, q) {
    let p = dotPos(i, j);
    let r = 0.255 * S;
    let sx = (q === 1 || q === 2) ? 1 : -1;
    let sy = (q === 2 || q === 3) ? 1 : -1;
    return { x: p.x + sx * r, y: p.y + sy * r };
  }

  // Port transition between two connected quadrants
  function getStepTransition(i, j, q, viaPort) {
    let p = dotPos(i, j);
    let rCap = (abs(i) + abs(j) >= 5) ? 0.44 * S : 0.375 * S;

    if (viaPort === "N") {
      if (isNPortOpen(i, j)) {
        let p2 = dotPos(i, j - 1);
        return {
          next: { i: i, j: j - 1, q: q === 0 ? 2 : 3, arrivedVia: "S" },
          mid: { x: (p.x + p2.x) * 0.5, y: (p.y + p2.y) * 0.5, pressure: 0.82, isCap: false }
        };
      } else {
        return {
          next: { i: i, j: j, q: q === 0 ? 1 : 0, arrivedVia: "N" },
          mid: { x: p.x, y: p.y - rCap, pressure: 1.18, isCap: true }
        };
      }
    }
    if (viaPort === "S") {
      if (isNPortOpen(i, j + 1)) {
        let p2 = dotPos(i, j + 1);
        return {
          next: { i: i, j: j + 1, q: q === 3 ? 1 : 0, arrivedVia: "N" },
          mid: { x: (p.x + p2.x) * 0.5, y: (p.y + p2.y) * 0.5, pressure: 0.82, isCap: false }
        };
      } else {
        return {
          next: { i: i, j: j, q: q === 3 ? 2 : 3, arrivedVia: "S" },
          mid: { x: p.x, y: p.y + rCap, pressure: 1.18, isCap: true }
        };
      }
    }
    if (viaPort === "E") {
      if (isEPortOpen(i, j)) {
        let p2 = dotPos(i + 1, j);
        return {
          next: { i: i + 1, j: j, q: q === 1 ? 3 : 0, arrivedVia: "W" },
          mid: { x: (p.x + p2.x) * 0.5, y: (p.y + p2.y) * 0.5, pressure: 0.82, isCap: false }
        };
      } else {
        return {
          next: { i: i, j: j, q: q === 1 ? 2 : 1, arrivedVia: "E" },
          mid: { x: p.x + rCap, y: p.y, pressure: 1.18, isCap: true }
        };
      }
    }
    if (viaPort === "W") {
      if (isEPortOpen(i - 1, j)) {
        let p2 = dotPos(i - 1, j);
        return {
          next: { i: i - 1, j: j, q: q === 0 ? 2 : 1, arrivedVia: "E" },
          mid: { x: (p.x + p2.x) * 0.5, y: (p.y + p2.y) * 0.5, pressure: 0.82, isCap: false }
        };
      } else {
        return {
          next: { i: i, j: j, q: q === 0 ? 3 : 0, arrivedVia: "W" },
          mid: { x: p.x - rCap, y: p.y, pressure: 1.18, isCap: true }
        };
      }
    }
  }

  function getPortsOfQuad(q) {
    if (q === 0) return ["N", "W"];
    if (q === 1) return ["N", "E"];
    if (q === 2) return ["S", "E"];
    return ["S", "W"];
  }

  // Trace all closed Sikku Kolam loops
  const visited = new Set();
  const cycles = [];

  for (let i = -5; i <= 5; i++) {
    for (let j = -5; j <= 5; j++) {
      if (!hasDot(i, j)) continue;
      for (let q = 0; q < 4; q++) {
        let key = `${i}_${j}_${q}`;
        if (visited.has(key)) continue;

        let pts = [];
        let curr = { i: i, j: j, q: q };
        let ports = getPortsOfQuad(curr.q);
        let nextPort = ports[0];
        let safety = 0;

        while (!visited.has(`${curr.i}_${curr.j}_${curr.q}`) && safety < 600) {
          visited.add(`${curr.i}_${curr.j}_${curr.q}`);
          let qa = quadAnchor(curr.i, curr.j, curr.q);
          pts.push({ x: qa.x, y: qa.y, pressure: 0.95 });

          let step = getStepTransition(curr.i, curr.j, curr.q, nextPort);
          pts.push(step.mid);

          curr = step.next;
          let nextPorts = getPortsOfQuad(curr.q);
          nextPort = (nextPorts[0] === curr.arrivedVia) ? nextPorts[1] : nextPorts[0];
          safety++;
        }

        if (pts.length >= 4) {
          // Close the loop smoothly by wrapping first 2 points
          pts.push({ x: pts[0].x, y: pts[0].y, pressure: pts[0].pressure });
          pts.push({ x: pts[1].x, y: pts[1].y, pressure: pts[1].pressure });
          cycles.push(pts);
        }
      }
    }
  }

  // Step 3B: Render the Toe Smudge Base Wash FIRST (so dragged flour blends into damp stone)
  drawToeSmudgeUnderlayer(smudgeCenter, dragAngle);

  // Step 3C: Split cycle paths into crisp vs. smudged sub-segments and render layers
  const crispChunks = [];
  const smudgeChunks = [];

  for (let pts of cycles) {
    // Subdivide control points slightly for finer smudge thresholding and grain placement
    let dense = [];
    for (let k = 0; k < pts.length - 1; k++) {
      let a = pts[k];
      let b = pts[k + 1];
      dense.push(a);
      dense.push({
        x: (a.x + b.x) * 0.5 + random(-0.6, 0.6),
        y: (a.y + b.y) * 0.5 + random(-0.6, 0.6),
        pressure: (a.pressure + b.pressure) * 0.5
      });
    }
    dense.push(pts[pts.length - 1]);

    let currCrisp = [];
    let currSmudge = [];

    for (let pt of dense) {
      let sf = getSmudgeFactor(pt.x, pt.y);
      if (sf < 0.45) {
        currCrisp.push([pt.x, pt.y, pt.pressure * (1 - sf * 0.4)]);
        if (currSmudge.length >= 3) smudgeChunks.push(currSmudge);
        currSmudge = [];
      } else {
        currSmudge.push([pt.x, pt.y, pt.pressure, sf]);
        if (currCrisp.length >= 3) crispChunks.push(currCrisp);
        currCrisp = [];
      }
    }
    if (currCrisp.length >= 3) crispChunks.push(currCrisp);
    if (currSmudge.length >= 3) smudgeChunks.push(currSmudge);
  }

  // Layer 1 of Kolam: Subtle damp contact shadow directly beneath crisp flour lines
  for (let chunk of crispChunks) {
    let shadowPts = chunk.map(p => [p[0] + 1.8, p[1] + 2.2, p[2] * 0.9]);
    brush.set("charcoal", "#120e10", 0.55);
    brush.spline(shadowPts, 0.55);
  }

  // Layer 2 of Kolam: Ghosted, wiped remnants of the kolam lines inside the toe-smudge zone
  for (let sChunk of smudgeChunks) {
    // Faint stained trace at original position
    let ghostPts = sChunk.map(p => [p[0], p[1], p[2] * 0.55]);
    brush.set("flour_chalk", "#6e7787", 0.65);
    brush.spline(ghostPts, 0.5);

    // Dragged/smeared duplicate displaced along toe motion vector
    let dragPts = sChunk.map(p => {
      let d = p[3] * random(18, 42);
      return [
        p[0] + cos(dragAngle) * d + random(-3, 3),
        p[1] + sin(dragAngle) * d + random(-3, 3),
        p[2] * 0.75
      ];
    });
    brush.set("flour_smudge", "#9ba5b5", 0.85);
    brush.spline(dragPts, 0.45);
  }

  // Layer 3 of Kolam: Granular chalky halo along all crisp flour lines
  for (let chunk of crispChunks) {
    brush.set("flour_spray", "#9aa5b8", 0.72);
    brush.spline(chunk, 0.55);
    brush.set("flour_chalk", "#c2cad8", 0.88);
    brush.spline(chunk, 0.55);
  }

  // Layer 4 of Kolam: Crisp, high-relief white rice-flour core sitting on top of the stone
  for (let chunk of crispChunks) {
    brush.set("flour_core", "#e4e8f0", 0.95);
    brush.spline(chunk, 0.55);

    // Brightest chalky crest catching the pre-sunrise light (with slight finger-pinch double-ridge)
    let crestPts = chunk.map(p => [p[0] - 0.6, p[1] - 0.8, p[2] * 0.82]);
    brush.set("cpencil", "#f7f6f2", 0.68);
    brush.spline(crestPts, 0.55);
  }

  // Step 3D: Render the 61 Pulli (Rice-Flour Dots) + scattered grains around each dot
  for (let i = -5; i <= 5; i++) {
    for (let j = -5; j <= 5; j++) {
      if (!hasDot(i, j)) continue;
      let p = dotPos(i, j);
      let sf = getSmudgeFactor(p.x, p.y);

      if (sf < 0.35) {
        // Crisp pinched mound of rice flour
        brush.noStroke();
        brush.wash("#120e10", 130);
        brush.circle(p.x + 1.5, p.y + 1.8, 7.2, 0.3);
        brush.wash("#cdd4e0", 215);
        brush.circle(p.x, p.y, 6.4, 0.38);
        brush.wash("#f7f6f2", 240);
        brush.circle(p.x - 0.6, p.y - 0.6, 4.5, 0.32);
        brush.noWash();

        // Textured dry chalk rim & stray flour granules around the pulli
        brush.set("charcoal", "#ffffff", 0.38);
        brush.circle(p.x - 0.4, p.y - 0.4, 4.2, 0.45);

        brush.set("cpencil", "#e2e6ee", 0.32);
        for (let g = 0; g < 9; g++) {
          let ga = random(360);
          let gd = random(5.5, 14.5);
          let gx = p.x + cos(ga) * gd;
          let gy = p.y + sin(ga) * gd;
          brush.line(gx, gy, gx + random(0.8, 2.0), gy + random(0.8, 2.0));
        }
      } else {
        // Smudged pulli dot: smeared into a comet-like streak toward dragAngle
        let streakLen = sf * 38;
        brush.set("flour_smudge", "#a8b2c2", 0.9);
        brush.line(p.x, p.y, p.x + cos(dragAngle) * streakLen, p.y + sin(dragAngle) * streakLen);
        brush.set("charcoal", "#d8dde6", 0.48);
        brush.line(p.x, p.y, p.x + cos(dragAngle) * streakLen * 0.6, p.y + sin(dragAngle) * streakLen * 0.6);
      }
    }
  }

  // Step 3E: Delicate traditional corner flourishes (lotus buds at the 4 cardinal tips)
  const cardinals = [
    { x: cx, y: cy - 5 * S - 36, ang: -90 },
    { x: cx + 5 * S + 36, y: cy, ang: 0 },
    { x: cx, y: cy + 5 * S + 36, ang: 90 },
    { x: cx - 5 * S - 36, y: cy, ang: 180 }
  ];
  for (let c of cardinals) {
    drawCardinalFlourish(c.x, c.y, c.ang);
  }

  // Step 3F: Thousands of fine individual rice-flour granules along the edges of the kolam
  const grainCols = ["#ffffff", "#e6eaf2", "#bac3d4"];
  for (let gc of grainCols) {
    brush.set("cpencil", gc, 0.28);
    for (let chunk of crispChunks) {
      for (let k = 0; k < chunk.length; k += 2) {
        if (random() < 0.55) {
          let pt = chunk[k];
          let a = random(360);
          let r = random(3.5, 12.5);
          let gx = pt[0] + cos(a) * r;
          let gy = pt[1] + sin(a) * r;
          brush.line(gx, gy, gx + random(0.7, 2.1), gy + random(0.7, 2.1));
        }
      }
    }
  }

  // Step 3G: Detailed Toe-Brush Smudge Overlays (skin-ridge streaks & pushed flour crumbs)
  drawToeSmudgeOverlayer(smudgeCenter, dragAngle);
}

function drawCardinalFlourish(x, y, ang) {
  push();
  translate(x, y);
  rotate(ang);
  // Central stem & two curling side volutes
  const curls = [
    [[-4, 0, 0.9], [8, 0, 1.0], [22, 0, 0.7]],
    [[0, -5, 0.8], [10, -14, 1.0], [4, -24, 0.9], [-5, -18, 0.7]],
    [[0, 5, 0.8], [10, 14, 1.0], [4, 24, 0.9], [-5, 18, 0.7]]
  ];
  for (let c of curls) {
    brush.set("flour_chalk", "#b8c1d1", 0.7);
    brush.spline(c, 0.55);
    brush.set("flour_core", "#eceff5", 0.8);
    brush.spline(c, 0.55);
  }
  brush.noStroke();
  brush.wash("#f5f4f0", 230);
  brush.circle(29, 0, 4.5, 0.3);
  brush.noWash();
  pop();
}

function drawToeSmudgeUnderlayer(center, dragAngle) {
  // Damp skin-pressure mark where the toe disturbed the water film & smeared powder into pores
  brush.noStroke();
  brush.fill("#161317", 110);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.65, 0.35);
  drawOrganicBlob(center.x + 15, center.y + 12, 95, 65, 12, 0.25);

  brush.fill("#667080", 72);
  brush.fillBleed(0.45, "out");
  brush.fillTexture(0.82, 0.42);
  drawOrganicBlob(center.x - 18, center.y - 16, 110, 74, 12, 0.3);
  brush.noFill();
}

function drawToeSmudgeOverlayer(center, dragAngle) {
  // Directional chalky drag marks swept by the big toe & second toe
  const smearColors = ["#7c8696", "#a2acb8", "#cad0db", "#e8ebf0"];
  for (let s = 0; s < 52; s++) {
    let col = smearColors[floor(map(s, 0, 52, 0, smearColors.length))];
    let spread = random(-68, 68);
    let perpAngle = dragAngle + 90;
    let sx = center.x + cos(perpAngle) * spread + random(-25, 35);
    let sy = center.y + sin(perpAngle) * spread + random(-25, 35);
    let len = random(32, 105) * (1 - abs(spread) / 95);

    let curvePts = [
      [sx, sy, 1.1],
      [sx + cos(dragAngle - 6) * len * 0.5, sy + sin(dragAngle - 6) * len * 0.5, 0.8],
      [sx + cos(dragAngle - 12) * len, sy + sin(dragAngle - 12) * len, 0.2]
    ];

    if (s % 3 === 0) {
      brush.set("flour_smudge", col, random(0.45, 0.95));
    } else {
      brush.set("charcoal", col, random(0.28, 0.55));
    }
    brush.spline(curvePts, 0.4);
  }

  // Clumped damp rice-flour crumbs pushed to the leading (upper-left) edge of the toe smear
  for (let i = 0; i < 85; i++) {
    let spread = random(-65, 65);
    let distAlong = random(25, 95);
    let perp = dragAngle + 90;
    let cx = center.x + cos(dragAngle) * distAlong + cos(perp) * spread + random(-8, 8);
    let cy = center.y + sin(dragAngle) * distAlong + sin(perp) * spread + random(-8, 8);

    brush.set("charcoal", random() < 0.6 ? "#f2f4f7" : "#b8c1d1", random(0.25, 0.52));
    brush.line(cx, cy, cx + random(1.5, 4.0), cy + random(1.5, 4.0));
  }
}

// ============================================================================
// 4. MARGIN CROP: HAMMERED BRASS POT (CHEMBU) WITH RICE FLOUR AT UPPER-LEFT
// ============================================================================
function drawBrassPotMargin() {
  const px = 48;
  const py = 355;
  const bellyR = 168;
  const neckR = 112;
  const rimR = 126;
  const mouthR = 98;

  // 1. Cast shadow & dark wet water ring on the laterite stone beneath the pot
  brush.noStroke();
  brush.wash("#0d0a0c", 195);
  brush.circle(px + 22, py + 26, bellyR * 1.06, 0.22);
  brush.wash("#161d29", 135);
  brush.circle(px + 34, py + 38, bellyR * 1.14, 0.28);
  brush.noWash();

  // Wet ring outline
  brush.set("charcoal", "#120d0e", 0.65);
  brush.arc(px + 12, py + 14, bellyR * 1.08, -65, 115);

  // 2. Rounded hammered brass belly
  brush.noStroke();
  brush.wash("#3b2810", 235);
  brush.circle(px, py, bellyR, 0.12);

  // Layered watercolor/wash metallic tonal zones on the brass shoulder
  brush.fill("#6e4f1f", 145);
  brush.fillBleed(0.25, "in");
  brush.fillTexture(0.65, 0.35);
  brush.circle(px + 8, py - 6, bellyR * 0.92, 0.15);

  // Cool pre-sunrise sky-blue reflection on the northeast curve of the brass belly
  brush.fill("#4f6885", 110);
  brush.fillBleed(0.35, "out");
  drawOrganicBlob(px + 78, py - 58, 62, 85, 12, 0.2);

  // Warm golden-brass midtone on the southeast curve
  brush.fill("#b58938", 130);
  brush.fillBleed(0.3, "out");
  drawOrganicBlob(px + 65, py + 62, 68, 75, 12, 0.2);
  brush.noFill();

  // Hammered brass facets (small concentric & radial strokes catching dawn light & shadow)
  const facetArcs = [
    { col: "#261909", rMin: 118, rMax: 164, a1: 40, a2: 145, w: 0.75 },
    { col: "#8c6728", rMin: 115, rMax: 158, a1: -55, a2: 75, w: 0.65 },
    { col: "#cfa44e", rMin: 120, rMax: 152, a1: -15, a2: 55, w: 0.55 },
    { col: "#7694b5", rMin: 122, rMax: 160, a1: -75, a2: -10, w: 0.60 },
    { col: "#bfd6ed", rMin: 132, rMax: 150, a1: -58, a2: -22, w: 0.45 }
  ];

  for (let fa of facetArcs) {
    brush.set("brass_sheen", fa.col, fa.w);
    for (let r = fa.rMin; r <= fa.rMax; r += 6.5) {
      let span = random(18, 42);
      let startA = random(fa.a1, fa.a2 - span);
      brush.arc(px, py, r, startA, startA + span);
    }
  }

  // 3. Constricted dark neck shadow just outside the rolled rim
  brush.set("charcoal", "#1f1407", 0.95);
  brush.arc(px, py, neckR, -85, 125);
  brush.set("2B", "#382610", 0.75);
  brush.arc(px, py, neckR + 5, -80, 120);

  // 4. Rolled brass rim (catching bright sky-blue & pale gold speculars)
  brush.noStroke();
  brush.wash("#59411b", 230);
  brush.circle(px, py, rimR, 0.08);
  brush.noWash();

  brush.set("brass_sheen", "#d4ae59", 0.85);
  brush.arc(px, py, rimR - 4, -75, 105);
  brush.set("brass_sheen", "#f0d58c", 0.55);
  brush.arc(px, py, rimR - 6, -35, 45);
  brush.set("brass_sheen", "#a8c5e3", 0.65);
  brush.arc(px, py, rimR - 3, -72, -18);
  brush.set("pen", "#241708", 0.55);
  brush.arc(px, py, rimR + 1, -85, 115);

  // 5. Interior mouth holding coarse white rice flour (with finger-scoop hollows)
  brush.noStroke();
  brush.wash("#1c1512", 245);
  brush.circle(px, py, mouthR, 0.08);

  // Mound of rice flour inside the pot
  brush.wash("#9aa4b5", 225);
  drawOrganicBlob(px - 6, py + 4, mouthR * 0.86, mouthR * 0.82, 14, 0.14);
  brush.wash("#d5dce8", 230);
  drawOrganicBlob(px - 10, py - 2, mouthR * 0.72, mouthR * 0.68, 14, 0.16);
  brush.wash("#f4f3ef", 220);
  drawOrganicBlob(px - 16, py - 10, mouthR * 0.50, mouthR * 0.46, 12, 0.18);

  // Three curved finger-scoop indentations in the flour mound
  const scoops = [
    { x: px + 22, y: py - 16, r: 22 },
    { x: px + 28, y: py + 12, r: 20 },
    { x: px + 8, y: py + 32, r: 21 }
  ];
  for (let sc of scoops) {
    brush.wash("#838e9e", 165);
    brush.circle(sc.x, sc.y, sc.r, 0.25);
    brush.set("charcoal", "#f7f6f2", 0.35);
    brush.arc(sc.x, sc.y, sc.r, 130, 290);
    brush.noStroke();
  }
  brush.noWash();

  // Granular flour texture inside pot and spilled powder on the brass rim & stone beside it
  brush.set("flour_spray", "#e6eaf2", 0.85);
  brush.line(px - 25, py - 35, px + 35, py + 35);
  brush.set("flour_chalk", "#f2f4f7", 0.65);
  brush.arc(px, py, rimR - 5, 5, 48); // Flour dust clinging to rim where hand reached in

  // Pinch of spilled flour grains on the laterite stone just below the brass pot
  brush.set("flour_spray", "#cfd6e3", 0.65);
  brush.line(px + 95, py + 135, px + 145, py + 168);
  brush.set("cpencil", "#f5f4f0", 0.3);
  for (let i = 0; i < 45; i++) {
    let gx = px + random(75, 175);
    let gy = py + random(105, 195);
    brush.line(gx, gy, gx + random(1, 2.5), gy + random(1, 2.5));
  }
}

// ============================================================================
// 5. MARGIN CROP: SLIVER OF BARE FOOT & TOES AT BOTTOM-RIGHT
// ============================================================================
function drawBareFootMargin() {
  // The bare left forefoot & toes enter from the bottom-right margin (x = 815..1200, y = 840..1200)
  // angled toward the upper-left (-132 deg), right beside the smudged kolam loop!

  // 1. Soft damp cast shadow under the toes & forefoot on the wet laterite
  brush.noStroke();
  brush.wash("#0d090b", 215);
  drawPolygonShape([
    [822, 888], [880, 825], [965, 818], [1065, 845],
    [1168, 910], [1205, 975], [1205, 1205], [895, 1205], [842, 1015]
  ], 0.45);
  brush.noWash();

  // 2. Forefoot body (cropping into bottom-right corner)
  brush.noStroke();
  brush.wash("#3d2219", 240);
  drawPolygonShape([
    [868, 965], [925, 895], [1005, 885], [1095, 912],
    [1182, 968], [1210, 1020], [1210, 1210], [920, 1210], [875, 1065]
  ], 0.5);

  // Watercolor skin shading on the dorsal forefoot (warm dusky umber + cool dawn sky sheen)
  brush.fill("#593326", 145);
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.55, 0.3);
  drawOrganicBlob(1045, 1065, 135, 115, 12, 0.18);

  brush.fill("#4f5d70", 95);
  brush.fillBleed(0.35, "out");
  drawOrganicBlob(1085, 1015, 110, 85, 12, 0.22);
  brush.noFill();

  // 3. Five Toes (Big toe closest to the kolam smudge, cascading to 5th toe on the right)
  const toes = [
    // Big toe (Hallux)
    {
      bx: 892, by: 968, tx: 836, ty: 882, wBase: 36, wTip: 33,
      nailW: 21, nailL: 22, hasFlour: true, flourAmt: 1.0
    },
    // Second toe (slightly longer reach, brushed right through the outer loop)
    {
      bx: 948, by: 922, tx: 892, ty: 834, wBase: 22, wTip: 19,
      nailW: 13, nailL: 14, hasFlour: true, flourAmt: 0.85
    },
    // Third toe
    {
      bx: 1002, by: 916, tx: 954, ty: 836, wBase: 21, wTip: 18,
      nailW: 12, nailL: 13, hasFlour: true, flourAmt: 0.35
    },
    // Fourth toe
    {
      bx: 1056, by: 928, tx: 1018, ty: 856, wBase: 19, wTip: 16,
      nailW: 11, nailL: 11, hasFlour: false, flourAmt: 0
    },
    // Little toe
    {
      bx: 1108, by: 956, tx: 1080, ty: 896, wBase: 17, wTip: 14,
      nailW: 9, nailL: 9, hasFlour: false, flourAmt: 0
    }
  ];

  for (let idx = 0; idx < toes.length; idx++) {
    let t = toes[idx];
    let ang = atan2(t.ty - t.by, t.tx - t.bx);
    let perp = ang + 90;

    // Toe base polygon
    let p1 = [t.bx - cos(perp) * t.wBase, t.by - sin(perp) * t.wBase];
    let p2 = [t.tx - cos(perp) * t.wTip, t.ty - sin(perp) * t.wTip];
    let p3 = [t.tx + cos(ang) * (t.wTip * 0.85), t.ty + sin(ang) * (t.wTip * 0.85)];
    let p4 = [t.tx + cos(perp) * t.wTip, t.ty + sin(perp) * t.wTip];
    let p5 = [t.bx + cos(perp) * t.wBase, t.by + sin(perp) * t.wBase];

    // Deep shadow on left/underside of toe
    brush.noStroke();
    brush.wash("#291510", 240);
    drawPolygonShape([p1, p2, p3, p4, p5], 0.55);

    // Warm dusky brown skin midtone
    let m1 = [lerp(p1[0], p5[0], 0.18), lerp(p1[1], p5[1], 0.18)];
    let m2 = [lerp(p2[0], p4[0], 0.15), lerp(p2[1], p4[1], 0.15)];
    brush.wash("#5e3729", 215);
    drawPolygonShape([m1, m2, p3, p4, p5], 0.55);

    // Cool twilight-blue skin sheen along the upper-right dorsal ridge of each toe
    let h1 = [lerp(p1[0], p5[0], 0.48), lerp(p1[1], p5[1], 0.48)];
    let h2 = [lerp(p2[0], p4[0], 0.48), lerp(p2[1], p4[1], 0.48)];
    brush.wash("#687082", 95);
    drawPolygonShape([h1, h2, p3, p4, p5], 0.5);
    brush.noWash();

    // Knuckle skin creases across the toe joint
    let jx = lerp(t.bx, t.tx, 0.48);
    let jy = lerp(t.by, t.ty, 0.48);
    brush.set("2B", "#2b1610", 0.35);
    brush.line(
      jx - cos(perp) * (t.wTip * 0.65),
      jy - sin(perp) * (t.wTip * 0.65),
      jx + cos(perp) * (t.wTip * 0.65),
      jy + sin(perp) * (t.wTip * 0.65)
    );

    // Toenail bed
    let nx = lerp(t.bx, t.tx, 0.78);
    let ny = lerp(t.by, t.ty, 0.78);
    let nw = t.nailW;
    let nl = t.nailL;
    let n1 = [nx - cos(perp) * nw - cos(ang) * (nl * 0.45), ny - sin(perp) * nw - sin(ang) * (nl * 0.45)];
    let n2 = [nx - cos(perp) * (nw * 0.9) + cos(ang) * (nl * 0.55), ny - sin(perp) * (nw * 0.9) + sin(ang) * (nl * 0.55)];
    let n3 = [nx + cos(perp) * (nw * 0.9) + cos(ang) * (nl * 0.55), ny + sin(perp) * (nw * 0.9) + sin(ang) * (nl * 0.55)];
    let n4 = [nx + cos(perp) * nw - cos(ang) * (nl * 0.45), ny + sin(perp) * nw - sin(ang) * (nl * 0.45)];

    brush.noStroke();
    brush.wash("#8c716b", 210);
    drawPolygonShape([n1, n2, n3, n4], 0.35);
    // Pale lunula & cool pre-sunrise sky reflection on nail
    brush.wash("#aeb5c4", 130);
    brush.circle(nx + cos(perp) * (nw * 0.2), ny + sin(perp) * (nw * 0.2), nw * 0.55, 0.25);
    brush.noWash();

    // Nail fold contour
    brush.set("pen", "#331a14", 0.28);
    brush.spline([n1, n2, n3, n4], 0.3);

    // White rice-flour dust clinging to the toe tip & left edge where it brushed the kolam!
    if (t.hasFlour) {
      brush.set("flour_chalk", "#d5dce8", 0.62 * t.flourAmt);
      brush.spline([p1, p2, p3], 0.45);
      brush.set("charcoal", "#f4f5f7", 0.42 * t.flourAmt);
      brush.spline([p2, p3, n2], 0.4);

      brush.set("cpencil", "#ffffff", 0.28);
      for (let g = 0; g < floor(24 * t.flourAmt); g++) {
        let gx = p3[0] + random(-18, 16);
        let gy = p3[1] + random(-14, 18);
        brush.line(gx, gy, gx + random(0.8, 2.0), gy + random(0.8, 2.0));
      }
    }

    // Deep inter-digital cleft shadow between adjacent toes
    brush.set("charcoal", "#170b08", 0.55);
    brush.spline([p1, [lerp(p1[0], p2[0], 0.5), lerp(p1[1], p2[1], 0.5)], p2], 0.3);
  }
}

function drawPolygonShape(pts, curv) {
  brush.beginShape(curv);
  for (let p of pts) {
    brush.vertex(p[0], p[1]);
  }
  brush.endShape(CLOSE);
}

// ============================================================================
// 6. FINAL PRE-SUNRISE ATMOSPHERIC DETAILS & STRAY RICE GRAINS
// ============================================================================
function drawFinalDawnDetails() {
  // Subtle pre-sunrise cool blue rim light catching damp areas at the margins
  brush.noStroke();
  brush.wash("#2a394f", 32);
  drawOrganicBlob(980, 210, 220, 140, 10, 0.25);
  drawOrganicBlob(180, 990, 210, 160, 10, 0.25);
  brush.noWash();

  // Scattered pinch of loose rice-flour grains near the center and outer loops
  brush.set("cpencil", "#e8ecf2", 0.26);
  for (let i = 0; i < 120; i++) {
    let ang = random(360);
    let rad = random(40, 440);
    let gx = 615 + cos(ang) * rad;
    let gy = 588 + sin(ang) * rad;
    if (gy > 155) {
      brush.line(gx, gy, gx + random(0.8, 2.2), gy + random(0.8, 2.2));
    }
  }
}

// Hyperreal Study of Scrunched Tie-Dyed Silk (Bandhani / Shibori)
// Watercolor washes (madder red, turmeric yellow, deep indigo) with capillary fold-bleed,
// opaque pale resist rings, low raking side-light crescent shadows, and fine pen stippling.

const SEED = 48291;

// Light vector: low, raking side-light from upper-left (azimuth ~206 deg, elevation ~21 deg)
const LIGHT_DIR = { x: -0.838, y: -0.410, z: 0.360 };

// Muted Earth-Tone Natural Dye Palette
const PALETTE = {
  silkGround: "#EFE5D4",
  silkLight: "#FBF5E9",
  silkWarm: "#E8D8BE",
  silkShadow: "#C4B197",
  silkDeepShadow: "#94826D",

  // Madder Red (Rubia tinctorum)
  madderLight: "#B84A39",
  madderMid: "#962F23",
  madderDark: "#6E1D16",
  madderDeep: "#47110E",
  madderSun: "#D46A56",

  // Turmeric Yellow (Curcuma longa)
  turmericLight: "#E2B552",
  turmericMid: "#C98B27",
  turmericDark: "#9E6414",
  turmericDeep: "#6E420B",
  turmericSun: "#F0CC78",

  // Deep Indigo (Indigofera tinctoria)
  indigoLight: "#465C70",
  indigoMid: "#26384A",
  indigoDark: "#172432",
  indigoDeep: "#0D151F",
  indigoSun: "#6C8399",

  // Capillary Wicking / Overlap Earth Tones
  wickOlive: "#575B38",
  wickRusset: "#A84E24",
  wickPlum: "#381F26",

  // Pen & Stipple Inks
  inkSepia: "#1E1614",
  inkIndigo: "#111924",
  inkMadder: "#2E1210",
  inkWarm: "#3B2A22"
};

let knots = [];

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  brush.scaleBrushes(3);
  angleMode(DEGREES);
  randomSeed(SEED);
  noiseSeed(SEED);

  // Custom brushes tailored for silk washes, opaque resist rings, silk threads, and stippling
  brush.add("silk_wash", {
    type: "default",
    weight: 10,
    scatter: 0.55,
    sharpness: 0.14,
    grain: 14,
    opacity: 32,
    spacing: 0.28,
    pressure: [0.3, 1.0, 0.3],
    noise: 0.7
  });

  brush.add("resist_gouache", {
    type: "default",
    weight: 2.4,
    scatter: 0.08,
    sharpness: 0.52,
    grain: 7,
    opacity: 215,
    spacing: 0.14,
    pressure: [0.6, 1.15, 0.6],
    noise: 0.35
  });

  brush.add("silk_sheen", {
    type: "default",
    weight: 0.55,
    scatter: 0.06,
    sharpness: 0.82,
    grain: 18,
    opacity: 75,
    spacing: 0.2,
    pressure: [0.2, 1.0, 0.2],
    noise: 0.5
  });

  brush.add("stipple_cluster", {
    type: "custom",
    weight: 0.65,
    scatter: 0.38,
    opacity: 195,
    spacing: 0.85,
    pressure: [0.7, 1.1, 0.7],
    tip: (_m) => {
      _m.circle(0, 0, 0.9);
      _m.circle(0.55, -0.35, 0.55);
    },
    rotate: "random",
    markerTip: false,
    noise: 0.4
  });

  // Custom vector field aligned with cloth drape and scrunched tension creases
  brush.addField("silk_drape", (t, field) => {
    for (let col = 0; col < field.length; col++) {
      for (let row = 0; row < field[0].length; row++) {
        let x = (col / field.length) * 1200;
        let y = (row / field[0].length) * 1200;
        let st = getClothBase(x, y);
        // Tangent to the height contour + subtle scrunch cross-tension
        let tangentAngle = atan2(st.gx, -st.gy);
        let crinkle = (noise(col * 0.18, row * 0.18) - 0.5) * 36;
        field[col][row] = tangentAngle + crinkle;
      }
    }
    return field;
  });

  generateKnots();
}

// ============================================================================
// TOPOGRAPHY, DYE ZONING & 3D SURFACE MODEL
// ============================================================================

// Base macro + meso cloth height and gradient at fabric coordinates (u, v)
function getClothBase(u, v) {
  // Primary diagonal sweeping folds (running ~38 degrees across frame)
  let rotU = u * 0.788 + v * 0.615;
  let rotV = -u * 0.615 + v * 0.788;

  let warp1 = (noise(u * 0.0016 + 10, v * 0.0016 + 20) - 0.5) * 240;
  let warp2 = (noise(u * 0.0032 + 50, v * 0.0032 + 80) - 0.5) * 110;

  let phase1 = (rotU + warp1) * 0.0175;
  // Asymmetric ridge profile (sharper crests, broader valleys like real silk)
  let s1 = sin( degrees(phase1) );
  let ridge1 = s1 + 0.28 * sin( degrees(phase1 * 2 + 0.4) );

  // Secondary intersecting scrunch folds
  let phase2 = (rotV * 0.7 + rotU * 0.35 + warp2) * 0.029;
  let s2 = sin( degrees(phase2) );
  let ridge2 = (1.0 - abs(s2)) * 2.0 - 1.0; // sharp silk crease ridges

  // Tertiary micro-crumples
  let crumple = (noise(u * 0.0085, v * 0.0085) - 0.5) * 1.4;

  let env = 0.75 + 0.5 * noise(u * 0.0012 + 90, v * 0.0012 + 40);
  let h = (ridge1 * 42 + ridge2 * 16 + crumple * 9) * env;

  return { h, rotU, rotV, warp1, warp2, ridge1, ridge2 };
}

function getClothState(u, v) {
  let eps = 2.5;
  let b0 = getClothBase(u, v);
  let bx = getClothBase(u + eps, v);
  let by = getClothBase(u, v + eps);

  let gx = (bx.h - b0.h) / eps;
  let gy = (by.h - b0.h) / eps;

  // Surface normal N = normalize(-gx, -gy, 1)
  let invLen = 1.0 / sqrt(gx * gx + gy * gy + 1.0);
  let nx = -gx * invLen;
  let ny = -gy * invLen;
  let nz = 1.0 * invLen;

  // Dot product with low raking side-light
  let light = nx * LIGHT_DIR.x + ny * LIGHT_DIR.y + nz * LIGHT_DIR.z;

  // 3D-to-2D screen projection with foreshortening over ridges
  let sx = u - gx * 15.5 + b0.h * 0.22;
  let sy = v - gy * 15.5 - b0.h * 0.48;

  return {
    u, v,
    x: sx,
    y: sy,
    h: b0.h,
    gx, gy,
    nx, ny, nz,
    light,
    ridge1: b0.ridge1,
    ridge2: b0.ridge2
  };
}

// Rotated fabric coordinates (p, q) for traditional bandhani diamond medallions
function getPatternCoords(u, v) {
  let du = u - 600;
  let dv = v - 600;
  // Subtle organic fabric weave shear
  let shearU = (noise(u * 0.0018 + 300, v * 0.0018 + 100) - 0.5) * 65;
  let shearV = (noise(u * 0.0018 + 700, v * 0.0018 + 500) - 0.5) * 65;
  du += shearU;
  dv += shearV;

  let ang = 31;
  let p = du * cos(ang) + dv * sin(ang);
  let q = -du * sin(ang) + dv * cos(ang);
  return { p, q };
}

// Determines dye zone ("madder", "turmeric", "indigo") and capillary bleed weights at (u, v)
function getDyeZone(u, v, h = 0) {
  let pc = getPatternCoords(u, v);
  let cell = 310;

  // Capillary wicking noise: dye bleeds further along fold creases and valleys
  let wick = (noise(u * 0.012, v * 0.012) - 0.5) * 48
           + (noise(u * 0.035, v * 0.035) - 0.5) * 18
           - h * 0.42;

  // Diamond medallion metric
  let lp = ((pc.p % cell) + cell) % cell - cell * 0.5;
  let lq = ((pc.q % cell) + cell) % cell - cell * 0.5;
  let diamondDist = abs(lp) + abs(lq) + wick * 0.85;

  // Macro diagonal band metric for alternating medallion colors
  let cellIdxP = floor((pc.p + 5000 * cell) / cell);
  let cellIdxQ = floor((pc.q + 5000 * cell) / cell);
  let medallionType = (cellIdxP + cellIdxQ) % 2;

  // Determine primary dye color & secondary wicking tone
  if (diamondDist < 78) {
    // Medallion core
    return medallionType === 0 ? "indigo" : "madder";
  } else if (diamondDist < 126) {
    // Luminous turmeric yellow ring / frame around medallions
    return "turmeric";
  } else if (diamondDist < 212) {
    // Broad field between diamond frames
    return medallionType === 0 ? "madder" : "indigo";
  } else {
    // Outer lattice intersection border
    return (diamondDist < 248) ? "turmeric" : "indigo";
  }
}

// Generate rhythmic constellations of bound knots in fabric space (u, v)
function generateKnots() {
  knots = [];
  let cell = 310;
  let usedPositions = [];

  function addKnot(p, q, baseRadius, role) {
    // Inverse transform from pattern (p, q) back to approximate (u, v)
    let ang = -31;
    let du = p * cos(ang) + q * sin(ang);
    let dv = -p * sin(ang) + q * cos(ang);
    let u = du + 600;
    let v = dv + 600;

    // Hand-tied artisanal organic jitter
    u += random(-3.2, 3.2);
    v += random(-3.2, 3.2);

    if (u < -90 || u > 1290 || v < -90 || v > 1290) return;

    // Prevent excessive overlap in fabric space
    for (let i = 0; i < usedPositions.length; i++) {
      let d = dist(u, v, usedPositions[i].u, usedPositions[i].v);
      if (d < (baseRadius + usedPositions[i].r) * 1.15) return;
    }

    let st = getClothState(u, v);
    if (st.x < -70 || st.x > 1270 || st.y < -70 || st.y > 1270) return;

    usedPositions.push({ u, v, r: baseRadius });

    let dye = getDyeZone(u, v, st.h);
    knots.push({
      u, v,
      x: st.x,
      y: st.y,
      r: baseRadius * random(0.92, 1.08),
      role, // "queen", "medallion", "lattice", "cluster"
      dye,
      state: st,
      pleatCount: floor(random(7, 12)),
      pleatPhase: random(360),
      eccentricity: random(0.88, 1.06),
      doubleRing: role === "queen" || (role === "medallion" && random() < 0.25)
    });
  }

  // Populate across the diamond lattice cells covering the canvas
  for (let cp = -3; cp <= 3; cp++) {
    for (let cq = -3; cq <= 3; cq++) {
      let cx = (cp + 0.5) * cell;
      let cy = (cq + 0.5) * cell;

      // 1. Central Queen Knot (large double-bound focal crater)
      addKnot(cx, cy, 19.5, "queen");

      // 2. Inner 8-dot Rosette Ring
      let r1 = 52;
      for (let i = 0; i < 8; i++) {
        let a = i * 45;
        addKnot(cx + cos(a) * r1, cy + sin(a) * r1, 12.8, "medallion");
      }

      // 3. Outer 16-dot Scalloped Diamond Medallion Ring
      for (let i = 0; i < 16; i++) {
        let a = i * 22.5;
        // Diamond-modulated radius
        let r2 = 96 + 14 * cos(a * 4);
        addKnot(cx + cos(a) * r2, cy + sin(a) * r2, 11.2, "medallion");
      }

      // 4. Cardinal 3-dot Ekdali Clusters pointing toward diamond corners
      let cardinalAngles = [0, 90, 180, 270];
      for (let ca of cardinalAngles) {
        let dBase = 138;
        addKnot(cx + cos(ca) * dBase, cy + sin(ca) * dBase, 11.5, "cluster");
        addKnot(cx + cos(ca - 9) * (dBase + 26), cy + sin(ca - 9) * (dBase + 26), 10.2, "cluster");
        addKnot(cx + cos(ca + 9) * (dBase + 26), cy + sin(ca + 9) * (dBase + 26), 10.2, "cluster");
        addKnot(cx + cos(ca) * (dBase + 50), cy + sin(ca) * (dBase + 50), 9.5, "cluster");
      }

      // 5. Double-Row Diamond Lattice Chains along the cell borders
      let steps = 7;
      let half = cell * 0.5;
      let corners = [
        [cx, cy - half],
        [cx + half, cy],
        [cx, cy + half],
        [cx - half, cy]
      ];
      for (let side = 0; side < 4; side++) {
        let pA = corners[side];
        let pB = corners[(side + 1) % 4];
        // Normal to the diamond edge for parallel double rows
        let dx = pB[0] - pA[0];
        let dy = pB[1] - pA[1];
        let len = sqrt(dx * dx + dy * dy);
        let nx = -dy / len;
        let ny = dx / len;

        for (let s = 0; s <= steps; s++) {
          let t = s / steps;
          let bx = lerp(pA[0], pB[0], t);
          let by = lerp(pA[1], pB[1], t);
          // Inner and outer parallel rows of the lattice band
          addKnot(bx + nx * 15, by + ny * 15, 11.0, "lattice");
          addKnot(bx - nx * 15, by - ny * 15, 11.0, "lattice");
        }
      }
    }
  }

  // Sort knots from top-left to bottom-right / back-to-front for natural 3D overlapping
  knots.sort((a, b) => (a.y - a.state.h * 0.4) - (b.y - b.state.h * 0.4));
}

// ============================================================================
// MAIN RENDER PIPELINE
// ============================================================================

function draw() {
  translate(-width / 2, -height / 2);
  background(PALETTE.silkGround);

  // STAGE 1: Soft Watercolor Washes (Madder Red, Turmeric Yellow, Deep Indigo)
  renderWatercolorWashes();

  // STAGE 2: Raking Side-Light Cloth Topography, Fold Shadows & Silk Anisotropic Sheen
  renderClothTopographyAndSheen();

  // STAGE 3: Tension Crinkles Connecting Neighbouring Knots Across Ridges
  renderInterKnotTensionCreases();

  // STAGE 4: Puckered Knot Craters, Pale Resist Rings, Crescent Shadows & Fine Pen Stippling
  renderAllKnots();

  // STAGE 5: Final Raking Light Rim Highlights & Micro-Stipple Accents
  renderFinalHighlightsAndMicroDetail();

  noLoop();
}

// ============================================================================
// STAGE 1: WATERCOLOR WASHES (BATCHED BY PIGMENT FOR BLEED & TEXTURE)
// ============================================================================

function renderWatercolorWashes() {
  brush.noStroke();
  brush.noHatch();

  let turmericShapes = [];
  let madderShapes = [];
  let indigoShapes = [];
  let bleedAndShadowShapes = [];

  // Sample a dense jittered grid in fabric space to build organic wicking dye patches
  let step = 88;
  for (let u = -80; u <= 1280; u += step) {
    for (let v = -80; v <= 1280; v += step) {
      let cu = u + random(-24, 24);
      let cv = v + random(-24, 24);
      let st = getClothState(cu, cv);
      let zone = getDyeZone(cu, cv, st.h);

      // Build an organic polygon stretched slightly along the fold contour
      let foldAngle = atan2(st.gx, -st.gy);
      let pts = [];
      let numVerts = 10;
      let baseR = step * random(0.78, 1.12);

      for (let i = 0; i < numVerts; i++) {
        let a = (i / numVerts) * 360;
        // Stretch along the fold ridge/trough so dye wicks along creases
        let stretch = 1.0 + 0.38 * abs(cos(a - foldAngle));
        let rad = baseR * stretch * (0.75 + 0.45 * noise(cu * 0.02 + cos(a), cv * 0.02 + sin(a)));
        let pu = cu + cos(a) * rad;
        let pv = cv + sin(a) * rad;
        let pst = getClothState(pu, pv);
        pts.push([pst.x, pst.y]);
      }

      if (zone === "turmeric") {
        turmericShapes.push({ pts, light: st.light, h: st.h });
      } else if (zone === "madder") {
        madderShapes.push({ pts, light: st.light, h: st.h });
      } else {
        indigoShapes.push({ pts, light: st.light, h: st.h });
      }

      // Capillary bleed shapes at fold edges & leeward shadow troughs
      let gradMag = sqrt(st.gx * st.gx + st.gy * st.gy);
      if (gradMag > 0.48 || st.light < 0.05) {
        let bPts = [];
        let bR = step * random(0.55, 0.85);
        for (let i = 0; i < 8; i++) {
          let a = (i / 8) * 360;
          let stretch = 1.0 + 0.65 * abs(cos(a - foldAngle));
          let rad = bR * stretch * random(0.75, 1.2);
          let pst = getClothState(cu + cos(a) * rad, cv + sin(a) * rad);
          bPts.push([pst.x, pst.y]);
        }
        bleedAndShadowShapes.push({ pts: bPts, zone, light: st.light });
      }
    }
  }

  // Helper to draw a polygon with brush.beginShape
  function drawWashPoly(pts, curvature = 0.45) {
    brush.beginShape(curvature);
    for (let i = 0; i < pts.length; i++) {
      brush.vertex(pts[i][0], pts[i][1]);
    }
    brush.endShape(true);
  }

  // 1A. Turmeric Yellow Washes (dyed first, luminous golden ochre & raw sienna)
  brush.fillBleed(0.38, "out");
  brush.fillTexture(0.65, 0.42);
  for (let s of turmericShapes) {
    let col = s.light > 0.25 ? PALETTE.turmericLight : (s.light > -0.05 ? PALETTE.turmericMid : PALETTE.turmericDark);
    let op = map(constrain(s.light, -0.5, 0.7), -0.5, 0.7, 115, 78);
    brush.fill(col, op);
    drawWashPoly(s.pts, 0.5);
  }

  // 1B. Madder Red Washes (earthy crimson, terracotta, burnt rose)
  brush.fillBleed(0.42, "out");
  brush.fillTexture(0.72, 0.52);
  for (let s of madderShapes) {
    let col = s.light > 0.3 ? PALETTE.madderLight : (s.light > -0.05 ? PALETTE.madderMid : PALETTE.madderDark);
    let op = map(constrain(s.light, -0.5, 0.7), -0.5, 0.7, 130, 88);
    brush.fill(col, op);
    drawWashPoly(s.pts, 0.48);
  }

  // 1C. Deep Indigo Washes (mineral woad, Prussian midnight, slate indigo)
  brush.fillBleed(0.40, "out");
  brush.fillTexture(0.76, 0.58);
  for (let s of indigoShapes) {
    let col = s.light > 0.3 ? PALETTE.indigoLight : (s.light > -0.05 ? PALETTE.indigoMid : PALETTE.indigoDark);
    let op = map(constrain(s.light, -0.5, 0.7), -0.5, 0.7, 145, 95);
    brush.fill(col, op);
    drawWashPoly(s.pts, 0.48);
  }

  // 1D. Capillary Wicking & Fold-Edge Bleed Glazes (olive, russet, deep plum, indigo trough)
  brush.fillBleed(0.48, "out");
  brush.fillTexture(0.80, 0.65);
  for (let s of bleedAndShadowShapes) {
    let col;
    if (s.zone === "turmeric") {
      col = s.light < 0 ? PALETTE.wickOlive : PALETTE.wickRusset;
    } else if (s.zone === "madder") {
      col = s.light < 0 ? PALETTE.wickPlum : PALETTE.madderDeep;
    } else {
      col = s.light < 0 ? PALETTE.indigoDeep : PALETTE.wickPlum;
    }
    brush.fill(col, s.light < 0 ? 78 : 52);
    drawWashPoly(s.pts, 0.55);
  }

  brush.noFill();
}

// ============================================================================
// STAGE 2: TOPOGRAPHIC FOLD SHADOWS & SILK ANISOTROPIC SHEEN
// ============================================================================

function renderClothTopographyAndSheen() {
  // 2A. Soft dry/wash modeling along the leeward shadow slopes & sunlit ridges
  for (let i = 0; i < 650; i++) {
    let u = random(-60, 1260);
    let v = random(-60, 1260);
    let st = getClothState(u, v);
    let zone = getDyeZone(u, v, st.h);

    // Follow the contour of the fold ridge
    let contourDir = atan2(st.gx, -st.gy);
    let pts = [];
    let curU = u;
    let curV = v;
    let stepLen = 16;

    for (let s = 0; s < 5; s++) {
      let cst = getClothState(curU, curV);
      pts.push([cst.x, cst.y, s === 2 ? 1.15 : 0.55]);
      let dir = atan2(cst.gx, -cst.gy) + random(-12, 12);
      curU += cos(dir) * stepLen;
      curV += sin(dir) * stepLen;
    }

    if (st.light < 0.05) {
      // Leeward side-lit fold shadow
      let shadowCol = zone === "indigo" ? PALETTE.indigoDeep :
                      (zone === "madder" ? PALETTE.madderDeep : PALETTE.turmericDeep);
      let w = map(st.light, -0.6, 0.05, 1.4, 0.55);
      brush.set("silk_wash", shadowCol, w);
      brush.spline(pts, 0.5);
    } else if (st.light > 0.38) {
      // Sunlit windward slope catching low raking side-light
      let sunCol = zone === "turmeric" ? PALETTE.turmericSun :
                   (zone === "madder" ? PALETTE.madderSun : PALETTE.indigoSun);
      let w = map(st.light, 0.38, 0.85, 0.45, 1.15);
      brush.set("silk_wash", sunCol, w);
      brush.spline(pts, 0.5);
    }
  }

  // 2B. Fine silk weave sheen & micro-pleat lines across the ridges
  brush.field("silk_drape");
  for (let i = 0; i < 1600; i++) {
    let u = random(-40, 1240);
    let v = random(-40, 1240);
    let st = getClothState(u, v);
    if (st.x < -20 || st.x > 1220 || st.y < -20 || st.y > 1220) continue;

    let zone = getDyeZone(u, v, st.h);
    let contourDir = atan2(st.gx, -st.gy);

    if (st.light > 0.32) {
      // Warm silk highlight thread catching grazing light
      let col = st.light > 0.58 ? PALETTE.silkLight :
                (zone === "turmeric" ? PALETTE.turmericSun :
                (zone === "madder" ? PALETTE.madderSun : PALETTE.indigoSun));
      brush.set("silk_sheen", col, random(0.35, 0.75));
      brush.flowLine(st.x, st.y, random(22, 58), contourDir + random(-15, 15));
    } else if (st.light < 0.02) {
      // Deep crease shadow grain
      let col = zone === "indigo" ? PALETTE.indigoDeep :
                (zone === "madder" ? PALETTE.madderDeep : PALETTE.inkWarm);
      brush.set("2B", col, random(0.28, 0.52));
      brush.flowLine(st.x, st.y, random(18, 46), contourDir + random(-10, 10));
    } else {
      // Midtone dye-wicking capillary fiber lines (perpendicular to fold)
      let wickDir = atan2(st.gy, st.gx) + random(-20, 20);
      let col = zone === "turmeric" ? PALETTE.turmericDark :
                (zone === "madder" ? PALETTE.madderDark : PALETTE.indigoDark);
      brush.set("2H", col, random(0.25, 0.45));
      brush.flowLine(st.x, st.y, random(14, 34), wickDir);
    }
  }
  brush.noField();
}

// ============================================================================
// STAGE 3: INTER-KNOT TENSION CREASES (BRIDGING CRINKLES)
// ============================================================================

function renderInterKnotTensionCreases() {
  // In bound tie-dye silk, the binding thread pulls tension pleats directly between adjacent knots
  for (let i = 0; i < knots.length; i++) {
    let k1 = knots[i];
    for (let j = i + 1; j < knots.length; j++) {
      let k2 = knots[j];
      let dFabric = dist(k1.u, k1.v, k2.u, k2.v);
      if (dFabric > 24 && dFabric < 68) {
        // Draw 1 to 2 delicate pinched tension creases bridging k1 and k2
        let midU = (k1.u + k2.u) * 0.5;
        let midV = (k1.v + k2.v) * 0.5;
        let mst = getClothState(midU, midV);

        let ang = atan2(k2.y - k1.y, k2.x - k1.x);
        let perpX = -sin(ang);
        let perpY = cos(ang);

        let offset = random(-2.5, 2.5);
        let bow = random(-4.5, 4.5);

        let p1x = k1.x + cos(ang) * (k1.r * 0.75) + perpX * offset;
        let p1y = k1.y + sin(ang) * (k1.r * 0.75) + perpY * offset;
        let pmx = mst.x + perpX * (offset + bow);
        let pmy = mst.y + perpY * (offset + bow);
        let p2x = k2.x - cos(ang) * (k2.r * 0.75) + perpX * offset;
        let p2y = k2.y - sin(ang) * (k2.r * 0.75) + perpY * offset;

        // Shadow side of the tension pleat
        let shadowCol = k1.dye === "indigo" ? PALETTE.inkIndigo :
                        (k1.dye === "madder" ? PALETTE.inkMadder : PALETTE.inkWarm);
        brush.set("pen", shadowCol, 0.24);
        brush.spline([[p1x, p1y, 0.4], [pmx, pmy, 0.9], [p2x, p2y, 0.4]], 0.45);

        // Raking highlight along the top edge of the tension pleat if sunlit
        if (mst.light > 0.15) {
          brush.set("silk_sheen", PALETTE.silkWarm, 0.38);
          brush.spline([
            [p1x - perpX * 1.3, p1y - perpY * 1.3, 0.3],
            [pmx - perpX * 1.3, pmy - perpY * 1.3, 0.85],
            [p2x - perpX * 1.3, p2y - perpY * 1.3, 0.3]
          ], 0.45);
        }
      }
    }
  }
}

// ============================================================================
// STAGE 4: PUCKERED KNOT CRATERS, RESIST RINGS, CRESCENT SHADOWS & STIPPLING
// ============================================================================

// Helper: projects a local point on a knot's puckered cone (radius dr, angle theta, height dz)
function projectKnotPoint(k, dr, theta, dz = 0) {
  let st = k.state;
  // Local elliptical distortion from cloth gradient + hand-tied eccentricity
  let ca = cos(theta);
  let sa = sin(theta);

  // Pleat radial modulation (pinched silk crinkles around the knot perimeter)
  let pleatWave = 1.0 + 0.085 * cos(k.pleatCount * theta + k.pleatPhase)
                      + 0.045 * sin((k.pleatCount - 3) * theta - k.pleatPhase * 0.7);

  let rMod = dr * pleatWave;
  let du = ca * rMod * k.eccentricity;
  let dv = sa * rMod / k.eccentricity;

  // Foreshortening from cloth surface slope + upward crater elevation shift along (-gx, -gy) & screen Y
  let sx = k.x + du * (1.0 - st.gx * 0.18) - st.gx * dz * 0.45 + dz * 0.18;
  let sy = k.y + dv * (1.0 - st.gy * 0.18) - st.gy * dz * 0.45 - dz * 0.55;

  return { x: sx, y: sy, pleatWave };
}

function renderAllKnots() {
  let lightAngle = atan2(LIGHT_DIR.y, LIGHT_DIR.x); // ~ -154 deg (upper-left)
  let shadowAngle = lightAngle + 180;               // ~ +26 deg (lower-right)

  for (let idx = 0; idx < knots.length; idx++) {
    let k = knots[idx];
    let r = k.r;
    let st = k.state;

    // Height of the puckered knot cone rim
    let coneHeight = r * 0.52;

    // ------------------------------------------------------------------------
    // 1. CAST CRESCENT SHADOW & OUTER WICKED DYE HALO
    // ------------------------------------------------------------------------
    let haloCol = k.dye === "indigo" ? PALETTE.indigoDeep :
                  (k.dye === "madder" ? PALETTE.madderDeep : PALETTE.turmericDeep);
    let inkCol = k.dye === "indigo" ? PALETTE.inkIndigo :
                 (k.dye === "madder" ? PALETTE.inkMadder : PALETTE.inkSepia);

    // 1a. Outer capillary dye-concentration halo around the knot base
    let haloPts = [];
    for (let a = 0; a <= 360; a += 30) {
      let pt = projectKnotPoint(k, r * 1.12, a, 0);
      haloPts.push([pt.x, pt.y, 0.75]);
    }
    brush.set("2B", haloCol, 0.65);
    brush.spline(haloPts, 0.5);

    // 1b. Raking Side-Light Cast Crescent Shadow on the leeward (lower-right) side
    // Shadow extends further when the cloth slope angles away from the light
    let shadowReach = map(constrain(st.light, -0.5, 0.7), -0.5, 0.7, 1.85, 1.35);
    for (let pass = 0; pass < 3; pass++) {
      let frac = (pass + 1) / 3;
      let cPts = [];
      let span = lerp(115, 72, frac);
      for (let da = -span; da <= span; da += 18) {
        let a = shadowAngle + da;
        let reach = 1.0 + (shadowReach - 1.0) * frac * pow(cos( map(da, -span, span, -90, 90) ), 1.3);
        let pt = projectKnotPoint(k, r * reach, a, -coneHeight * 0.12 * frac);
        let press = cos( map(da, -span, span, -80, 80) );
        cPts.push([pt.x, pt.y, press]);
      }
      brush.set("charcoal", haloCol, lerp(0.75, 0.42, pass / 2));
      brush.spline(cPts, 0.45);
    }

    // ------------------------------------------------------------------------
    // 2. THE RAISED PALE RESIST RING (OPAQUE SILK RESERVE + 3D CONE SHADING)
    // ------------------------------------------------------------------------
    // Build the pale resist collar between r * 0.42 and r * 0.88, lifted by coneHeight
    let ringRadii = [r * 0.82, r * 0.64, r * 0.48];
    for (let ri = 0; ri < ringRadii.length; ri++) {
      let rad = ringRadii[ri];
      // Rim elevation peaks around r * 0.58
      let zElev = coneHeight * (ri === 1 ? 1.0 : (ri === 0 ? 0.65 : 0.82));

      // Sunlit half of the resist ring (facing upper-left lightAngle)
      let sunPts = [];
      for (let da = -115; da <= 115; da += 20) {
        let a = lightAngle + da;
        let pt = projectKnotPoint(k, rad, a, zElev);
        let press = map( abs(da), 0, 115, 1.15, 0.55 );
        sunPts.push([pt.x, pt.y, press]);
      }
      let sunResistCol = st.light > 0.05 ? PALETTE.silkLight : PALETTE.silkWarm;
      brush.set("resist_gouache", sunResistCol, ri === 1 ? 0.68 : 0.52);
      brush.spline(sunPts, 0.5);

      // Shadowed half of the resist ring (facing lower-right shadowAngle)
      let shdPts = [];
      for (let da = -105; da <= 105; da += 20) {
        let a = shadowAngle + da;
        let pt = projectKnotPoint(k, rad, a, zElev * 0.88);
        let press = map( abs(da), 0, 105, 1.1, 0.55 );
        shdPts.push([pt.x, pt.y, press]);
      }
      let shdResistCol = st.light < -0.1 ? PALETTE.silkDeepShadow : PALETTE.silkShadow;
      brush.set("resist_gouache", shdResistCol, ri === 1 ? 0.64 : 0.48);
      brush.spline(shdPts, 0.5);
    }

    // Crisp sunlit rim highlight on the upper-left crest of the knot crater
    if (st.light > -0.25) {
      let rimPts = [];
      for (let da = -75; da <= 75; da += 18) {
        let a = lightAngle + da;
        let pt = projectKnotPoint(k, r * 0.58, a, coneHeight * 1.06);
        rimPts.push([pt.x, pt.y, cos(da)]);
      }
      brush.set("resist_gouache", "#FFFDF7", 0.42);
      brush.spline(rimPts, 0.5);
    }

    // Optional outer second resist ring for large double-bound "queen" knots
    if (k.doubleRing) {
      let outerRad = r * 1.28;
      let oSunPts = [];
      for (let da = -110; da <= 110; da += 22) {
        let pt = projectKnotPoint(k, outerRad, lightAngle + da, coneHeight * 0.35);
        oSunPts.push([pt.x, pt.y, 0.85]);
      }
      brush.set("resist_gouache", PALETTE.silkWarm, 0.44);
      brush.spline(oSunPts, 0.5);

      let oShdPts = [];
      for (let da = -105; da <= 105; da += 22) {
        let pt = projectKnotPoint(k, outerRad, shadowAngle + da, coneHeight * 0.28);
        oShdPts.push([pt.x, pt.y, 0.85]);
      }
      brush.set("resist_gouache", PALETTE.silkShadow, 0.42);
      brush.spline(oShdPts, 0.5);
    }

    // ------------------------------------------------------------------------
    // 3. CENTRAL PUCKERED CRATER PIT (CONCAVE DIMPLE AT APEX)
    // ------------------------------------------------------------------------
    // Inside the pale ring sits the tiny dyed dimple/pit where the pinched tip was dipped
    let centerPt = projectKnotPoint(k, 0, 0, coneHeight * 0.45);
    let pitCol = k.dye === "indigo" ? PALETTE.indigoDeep :
                 (k.dye === "madder" ? PALETTE.madderDeep :
                 (random() < 0.5 ? PALETTE.madderDark : PALETTE.turmericDeep));

    let pitPts = [];
    for (let a = 0; a <= 360; a += 45) {
      let pt = projectKnotPoint(k, r * 0.24, a, coneHeight * 0.52);
      pitPts.push([pt.x, pt.y, 0.9]);
    }
    brush.set("resist_gouache", pitCol, 0.55);
    brush.spline(pitPts, 0.5);

    // Deep pinhole shadow on the upper-left inner wall of the concave crater
    brush.set("rotring", inkCol, 0.42);
    let pIn1 = projectKnotPoint(k, r * 0.22, lightAngle - 55, coneHeight * 0.55);
    let pIn2 = projectKnotPoint(k, r * 0.14, lightAngle, coneHeight * 0.42);
    let pIn3 = projectKnotPoint(k, r * 0.22, lightAngle + 55, coneHeight * 0.55);
    brush.spline([[pIn1.x, pIn1.y, 0.5], [pIn2.x, pIn2.y, 1.1], [pIn3.x, pIn3.y, 0.5]], 0.5);

    // ------------------------------------------------------------------------
    // 4. FINE PEN STIPPLING & CRINKLED THREAD SHADOWS
    // ------------------------------------------------------------------------
    // 4a. Radial crinkled thread-pinch lines (pleats radiating from crater across the ring)
    let numPleats = k.pleatCount;
    for (let p = 0; p < numPleats; p++) {
      let a = (p / numPleats) * 360 + k.pleatPhase + random(-8, 8);
      let isShadowSide = cos(a - shadowAngle) > -0.1;

      // Inner pleat tick (from central crater into the resist ring)
      let p0 = projectKnotPoint(k, r * 0.24, a, coneHeight * 0.55);
      let p1 = projectKnotPoint(k, r * 0.52, a + random(-5, 5), coneHeight * 0.95);
      brush.set("rotring", inkCol, isShadowSide ? 0.26 : 0.18);
      brush.line(p0.x, p0.y, p1.x, p1.y);

      // Outer crinkled thread shadow (from outer waist of the resist ring into the cloth)
      let p2 = projectKnotPoint(k, r * 0.78, a + random(-4, 4), coneHeight * 0.6);
      let p3 = projectKnotPoint(k, r * random(1.18, 1.52), a + random(-10, 10), 0);
      brush.set("pen", inkCol, isShadowSide ? 0.28 : 0.19);
      brush.line(p2.x, p2.y, p3.x, p3.y);
    }

    // 4b. Helical binding-thread constriction marks around the knot neck ("crinkled thread shadow")
    for (let tArc = 0; tArc < 3; tArc++) {
      let startA = shadowAngle - 95 + tArc * 48 + random(-12, 12);
      let endA = startA + random(38, 62);
      let neckR = r * random(0.84, 1.02);
      let neckZ = coneHeight * random(0.25, 0.55);
      let tPts = [];
      for (let a = startA; a <= endA; a += 15) {
        let pt = projectKnotPoint(k, neckR, a, neckZ);
        tPts.push([pt.x, pt.y, 0.8]);
      }
      brush.set("rotring", inkCol, 0.25);
      brush.spline(tPts, 0.4);
    }

    // 4c. Stipple cluster pass along the outer dye-ring and leeward crescent shadow
    let stippleArcPts = [];
    for (let da = -110; da <= 110; da += 22) {
      let a = shadowAngle + da;
      let pt = projectKnotPoint(k, r * random(0.92, 1.15), a, coneHeight * 0.2);
      stippleArcPts.push([pt.x, pt.y, cos(da * 0.75)]);
    }
    brush.set("stipple_cluster", inkCol, 0.42);
    brush.spline(stippleArcPts, 0.45);

    // 4d. Individual fine pen stipple dots around the dot-ring, crater rim, and crescent shadow
    let numStipples = floor(map(r, 9, 21, 22, 42));
    for (let s = 0; s < numStipples; s++) {
      // Bias stipples toward the shadow crescent while keeping delicate stippling all around the ring
      let a;
      if (s < numStipples * 0.62) {
        a = shadowAngle + randomGaussian(0, 58);
      } else {
        a = random(360);
      }

      // Choose radial band: outer ring edge (60%), inner crater edge (25%), or cast crescent shadow (15%)
      let bandRoll = random();
      let sRad, sZ;
      if (bandRoll < 0.58) {
        sRad = r * random(0.82, 1.08);
        sZ = coneHeight * 0.45;
      } else if (bandRoll < 0.82) {
        sRad = r * random(0.24, 0.44);
        sZ = coneHeight * 0.78;
      } else {
        sRad = r * random(1.08, 1.58);
        sZ = 0;
      }

      let pt = projectKnotPoint(k, sRad, a, sZ);
      let dotLen = random(0.65, 1.45);
      let dotAng = a + 90 + random(-25, 25);

      brush.set("rotring", s % 3 === 0 ? PALETTE.inkSepia : inkCol, random(0.22, 0.36));
      brush.line(
        pt.x,
        pt.y,
        pt.x + cos(dotAng) * dotLen,
        pt.y + sin(dotAng) * dotLen
      );
    }
  }
}

// ============================================================================
// STAGE 5: FINAL RAKING RIM HIGHLIGHTS & CREVICE MICRO-STIPPLING
// ============================================================================

function renderFinalHighlightsAndMicroDetail() {
  // 5A. Fine pen stippling along the sharpest cloth crease ridges and deep shadow troughs
  for (let i = 0; i < 950; i++) {
    let u = random(-20, 1220);
    let v = random(-20, 1220);
    let st = getClothState(u, v);
    if (st.x < 0 || st.x > 1200 || st.y < 0 || st.y > 1200) continue;

    // Stipple along sharp secondary silk creases or deep side-lit fold shadows
    if (st.ridge2 > 0.62 || st.light < -0.18) {
      let zone = getDyeZone(u, v, st.h);
      let col = zone === "indigo" ? PALETTE.inkIndigo :
                (zone === "madder" ? PALETTE.inkMadder : PALETTE.inkSepia);
      let dotLen = random(0.7, 1.6);
      let ang = atan2(st.gx, -st.gy) + random(-20, 20);
      brush.set("rotring", col, random(0.20, 0.34));
      brush.line(st.x, st.y, st.x + cos(ang) * dotLen, st.y + sin(ang) * dotLen);
    }
  }

  // 5B. Crisp raking light catch-lights on the highest sunlit silk ridges
  for (let i = 0; i < 180; i++) {
    let u = random(0, 1200);
    let v = random(0, 1200);
    let st = getClothState(u, v);
    if (st.light > 0.52 && st.ridge2 > 0.45) {
      let contourDir = atan2(st.gx, -st.gy);
      let len = random(10, 26);
      let p1 = getClothState(u - cos(contourDir) * len * 0.5, v - sin(contourDir) * len * 0.5);
      let p2 = getClothState(u + cos(contourDir) * len * 0.5, v + sin(contourDir) * len * 0.5);

      brush.set("resist_gouache", PALETTE.silkLight, random(0.24, 0.40));
      brush.spline([[p1.x, p1.y, 0.3], [st.x, st.y, 1.0], [p2.x, p2.y, 0.3]], 0.5);
    }
  }
}

