function setStroke(name, col, weight = 1) {
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.set(name, col, weight);
}

function drawWashPoly(pts, col, alpha = 235, curvature = 0.15) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noFill();
  brush.noHatch();
  brush.noMass();
  brush.wash(col, alpha);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noWash();
}

function drawWatercolorPoly(pts, col, alpha = 90, bleed = 0.16, tex = 0.55, border = 0.4, curvature = 0.05) {
  if (!pts || pts.length < 3) return;
  brush.noStroke();
  brush.noWash();
  brush.noHatch();
  brush.noMass();
  brush.fill(col, alpha);
  brush.fillBleed(bleed, "out");
  brush.fillTexture(tex, border);
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
  brush.noFill();
}

function octVertex(r, idx, cx = CX, cy = CY) {
  let ang = 22.5 + idx * 45;
  return [cx + r * cos(ang), cy + r * sin(ang)];
}

function octRingPts(r, cx = CX, cy = CY) {
  let pts = [];
  for (let i = 0; i < 8; i++) {
    pts.push(octVertex(r, i, cx, cy));
  }
  return pts;
}

function heartPoint(tDeg, scaleVal, cx = CX, cy = CY) {
  let x = 16 * pow(sin(tDeg), 3);
  let y = -(13 * cos(tDeg) - 5 * cos(2 * tDeg) - 2 * cos(3 * tDeg) - cos(4 * tDeg));
  return [cx + x * scaleVal, cy + (y - 3.0) * scaleVal];
}

function buildHeartArcTable(scaleVal, cx = CX, cy = CY) {
  let samples = [];
  let totalLen = 0;
  let steps = 180;
  let prev = heartPoint(0, scaleVal, cx, cy);
  samples.push({ t: 0, x: prev[0], y: prev[1], s: 0, tx: 1, ty: 0 });
  for (let i = 1; i <= steps; i++) {
    let t = (i / steps) * 180;
    let p = heartPoint(t, scaleVal, cx, cy);
    let dx = p[0] - prev[0];
    let dy = p[1] - prev[1];
    let d = sqrt(dx * dx + dy * dy);
    totalLen += d;
    let mag = d > 0.0001 ? d : 1;
    samples.push({ t: t, x: p[0], y: p[1], s: totalLen, tx: dx / mag, ty: dy / mag });
    prev = p;
  }
  return { samples, totalLen };
}

function sampleHeartAtArc(table, targetS) {
  let s = constrain(targetS, 0, table.totalLen);
  let arr = table.samples;
  for (let i = 1; i < arr.length; i++) {
    if (arr[i].s >= s) {
      let s0 = arr[i - 1].s;
      let s1 = arr[i].s;
      let f = s1 > s0 ? (s - s0) / (s1 - s0) : 0;
      let x = lerp(arr[i - 1].x, arr[i].x, f);
      let y = lerp(arr[i - 1].y, arr[i].y, f);
      let ang = atan2(arr[i].ty, arr[i].tx);
      return { x, y, ang };
    }
  }
  let last = arr[arr.length - 1];
  return { x: last.x, y: last.y, ang: atan2(last.ty, last.tx) };
}

function pointInPoly(px, py, poly) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    let xi = poly[i][0], yi = poly[i][1];
    let xj = poly[j][0], yj = poly[j][1];
    let intersect = ((yi > py) !== (yj > py)) &&
      (px < (xj - xi) * (py - yi) / ((yj - yi) || 0.00001) + xi);
    if (intersect) inside = !inside;
  }
  return inside;
}

function minDistToPoly(px, py, poly) {
  let minD = 999999;
  for (let i = 0; i < poly.length; i++) {
    let dx = px - poly[i][0];
    let dy = py - poly[i][1];
    let d = sqrt(dx * dx + dy * dy);
    if (d < minD) minD = d;
  }
  return minD;
}

