function drawCowrie(x, y, len, wid, ang, pal, mouthUp = true, seedVal = 0.5) {
  let rx = len * 0.5;
  let ry = wid * 0.5;
  let cA = cos(ang);
  let sA = sin(ang);

  const toW = (u, v) => [x + u * cA - v * sA, y + u * sA + v * cA];

  // 1. Soft cast shadow onto the recessed putty bed (towards lower-right +45 deg)
  let shX = wid * 0.22;
  let shY = wid * 0.25;
  setStroke("charcoal", "#1c130e", max(0.35, wid * 0.065));
  let shP1 = toW(-rx * 0.65, ry * 0.15);
  let shP2 = toW(0, ry * 0.35);
  let shP3 = toW(rx * 0.65, ry * 0.15);
  brush.spline([
    [shP1[0] + shX, shP1[1] + shY, 0.4],
    [shP2[0] + shX, shP2[1] + shY, 1.0],
    [shP3[0] + shX, shP3[1] + shY, 0.4]
  ], 0.5);

  // 2. Crisp egg-shaped cowrie silhouette with rostrate ends and chipped margin
  let contour = [];
  let nPts = 14;
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * 360;
    let ca = cos(a);
    let sa = sin(a);
    let plump = 1.0 - 0.12 * ca; // slightly broader at posterior
    let rostrum = pow(abs(ca), 4) * 0.09 * (ca > 0 ? 1 : -1);
    let u = (ca + rostrum) * rx;
    let v = sa * ry * plump;
    if (seedVal > 0.35 && i === 3) {
      v *= 0.87; // realistic chipped outer lip indentation
    }
    contour.push(toW(u, v));
  }
  drawWashPoly(contour, pal.base, 242, 0.25);

  // 3. Colored pencil surface shading & iridescent nacre sheen
  let archFracs = [-0.72, -0.44, 0.44, 0.72];
  for (let k = 0; k < archFracs.length; k++) {
    let vf = archFracs[k];
    let midPt = toW(0, vf * ry);
    let lightDot = ((midPt[0] - x) * LIGHT_X + (midPt[1] - y) * LIGHT_Y) / max(1, ry);
    let col = lightDot > 0.15 ? (k % 2 === 0 ? pal.nacre2 : pal.nacre1) : (lightDot < -0.15 ? pal.shadow : pal.mid);
    let wgt = (abs(vf) > 0.6 ? 0.38 : 0.45) * (wid / 16);
    setStroke("cpencil", col, constrain(wgt, 0.24, 0.65));
    let pA = toW(-rx * 0.76, vf * ry * 0.42);
    let pB = toW(-rx * 0.08, vf * ry * 0.96);
    let pC = toW(rx * 0.76, vf * ry * 0.38);
    brush.spline([
      [pA[0], pA[1], 0.3],
      [pB[0], pB[1], 0.95],
      [pC[0], pC[1], 0.3]
    ], 0.45);
  }

  // Core shadow on lower-right curve of shell
  setStroke("cpencil", pal.shadow, constrain(0.45 * (wid / 16), 0.26, 0.65));
  brush.line(
    x + wid * 0.16 - cA * rx * 0.45, y + wid * 0.18 - sA * rx * 0.45,
    x + wid * 0.16 + cA * rx * 0.45, y + wid * 0.18 + sA * rx * 0.45
  );

  if (mouthUp) {
    // 4A. Ventral view: callused lips, cupped mouth shadow, labial teeth & chipped lip
    setStroke("cpencil", pal.lip, constrain(0.45 * (wid / 15), 0.26, 0.6));
    let l1 = toW(-rx * 0.75, -ry * 0.22);
    let l2 = toW(rx * 0.75, -ry * 0.2);
    let l3 = toW(-rx * 0.75, ry * 0.22);
    let l4 = toW(rx * 0.75, ry * 0.2);
    brush.line(l1[0], l1[1], l2[0], l2[1]);
    brush.line(l3[0], l3[1], l4[0], l4[1]);

    // Cupped shadow inside the mouth (shifted slightly toward upper-left overhanging lip)
    let cupOffX = LIGHT_X * wid * 0.045;
    let cupOffY = LIGHT_Y * wid * 0.045;
    let m1 = toW(-rx * 0.82, 0);
    let m2 = toW(-rx * 0.2, ry * 0.06);
    let m3 = toW(rx * 0.3, -ry * 0.05);
    let m4 = toW(rx * 0.82, 0);

    setStroke("2B", pal.deep, constrain(0.55 * (wid / 14), 0.32, 0.78));
    brush.spline([
      [m1[0] + cupOffX, m1[1] + cupOffY, 0.4],
      [m2[0] + cupOffX, m2[1] + cupOffY, 1.0],
      [m3[0] + cupOffX, m3[1] + cupOffY, 0.95],
      [m4[0] + cupOffX, m4[1] + cupOffY, 0.4]
    ], 0.4);

    // Deepest aperture crevice
    setStroke("rotring", "#170b08", constrain(0.32 * (wid / 15), 0.2, 0.45));
    brush.line(m1[0], m1[1], m4[0], m4[1]);

    // Delicate labial & columellar teeth ticks
    let numTeeth = floor(constrain(len * 0.34, 5, 9));
    for (let t = 0; t < numTeeth; t++) {
      let uf = map(t, 0, numTeeth - 1, -0.66, 0.66);
      let isChip = (t === numTeeth - 2 && seedVal > 0.3);
      let tLen = isChip ? ry * 0.38 : ry * 0.26;

      // Shadow tooth groove
      setStroke("2H", isChip ? pal.deep : pal.shadow, 0.22);
      let tp1 = toW(uf * rx, -ry * 0.05);
      let tp2 = toW(uf * rx, - tLen);
      let tp3 = toW(uf * rx, ry * 0.05);
      let tp4 = toW(uf * rx, tLen);
      brush.line(tp1[0], tp1[1], tp2[0], tp2[1]);
      brush.line(tp3[0], tp3[1], tp4[0], tp4[1]);

      // Lit tooth ridge catching upper-left light
      setStroke("cpencil", pal.highlight, 0.24);
      let hp1 = toW((uf + 0.03) * rx, ry * 0.07);
      let hp2 = toW((uf + 0.03) * rx, tLen * 0.85);
      brush.line(hp1[0], hp1[1], hp2[0], hp2[1]);
    }
  } else {
    // 4B. Dorsal view: glossy porcelain dome, mantle line, cupped terminal notches
    let n1 = toW(-rx * 0.86, 0);
    let n2 = toW(rx * 0.86, 0);
    setStroke("2B", pal.deep, 0.38);
    brush.line(n1[0], n1[1], n1[0] + cA * 2.2, n1[1] + sA * 2.2);
    brush.line(n2[0], n2[1], n2[0] - cA * 2.2, n2[1] - sA * 2.2);

    // Faint dorsal mantle sulcus line
    setStroke("cpencil", pal.warm, 0.26);
    let d1 = toW(-rx * 0.72, ry * 0.12);
    let d2 = toW(rx * 0.72, ry * 0.08);
    brush.line(d1[0], d1[1], d2[0], d2[1]);

    // Chipped anterior lip edge
    if (seedVal > 0.25) {
      let cp1 = toW(rx * 0.62, ry * 0.58);
      let cp2 = toW(rx * 0.82, ry * 0.32);
      setStroke("2H", pal.deep, 0.24);
      brush.line(cp1[0], cp1[1], cp2[0], cp2[1]);
      setStroke("cpencil", pal.highlight, 0.28);
      brush.line(cp1[0] - 0.8, cp1[1] - 0.8, cp2[0] - 0.8, cp2[1] - 0.8);
    }
  }

  // 5. Burnished upper-left highlight & nacre gleam
  let hx = x + LIGHT_X * wid * 0.21;
  let hy = y + LIGHT_Y * wid * 0.21;
  setStroke("cpencil", pal.nacre2, constrain(0.48 * (wid / 15), 0.28, 0.65));
  brush.line(hx - cA * rx * 0.42, hy - sA * rx * 0.42, hx + cA * rx * 0.42, hy + sA * rx * 0.42);

  setStroke("cpencil", pal.highlight, constrain(0.42 * (wid / 15), 0.26, 0.58));
  brush.line(hx - cA * rx * 0.3, hy - sA * rx * 0.3, hx + cA * rx * 0.22, hy + sA * rx * 0.22);
}

function drawPeriwinkle(x, y, rad, ang, pal, mouthUp = true, seedVal = 0.5) {
  let cA = cos(ang);
  let sA = sin(ang);
  const toW = (u, v) => [x + u * cA - v * sA, y + u * sA + v * cA];

  // 1. Cast shadow on bed towards lower-right
  let shX = rad * 0.32;
  let shY = rad * 0.35;
  setStroke("charcoal", "#1c130e", constrain(rad * 0.08, 0.32, 0.75));
  brush.arc(x + shX, y + shY, rad * 0.82, 15, 115);

  // 2. Plump turbinate snail silhouette with pointed conical spire at +u
  let pts = [];
  let nPts = 12;
  for (let i = 0; i < nPts; i++) {
    let a = (i / nPts) * 360;
    let ca = cos(a);
    let sa = sin(a);
    let spireStretch = ca > 0 ? 1.0 + 0.38 * pow(ca, 3) : 0.94;
    let u = ca * rad * spireStretch;
    let v = sa * rad * (1.0 - 0.14 * ca);
    if (mouthUp && i === 9 && seedVal > 0.3) {
      v *= 0.84; // chipped outer lip indentation
    }
    pts.push(toW(u, v));
  }
  drawWashPoly(pts, pal.base, 242, 0.25);

  // 3. Global shading & nacre sheen
  setStroke("cpencil", pal.shadow, constrain(rad * 0.042, 0.26, 0.55));
  brush.arc(x + rad * 0.12, y + rad * 0.12, rad * 0.78, 10, 115);

  setStroke("cpencil", pal.nacre2, constrain(rad * 0.045, 0.28, 0.58));
  brush.arc(x - rad * 0.1, y - rad * 0.1, rad * 0.72, 190, 295);

  if (mouthUp) {
    // 4A. Aperture-up view: cupped shadow inside mouth, pearly inner lip, chipped outer lip
    let mCenter = toW(-rad * 0.22, rad * 0.16);
    let mRad = rad * 0.46;

    // Nacre sheen inside lower-right inner lip of mouth
    setStroke("cpencil", pal.nacre1, constrain(rad * 0.042, 0.25, 0.52));
    brush.arc(mCenter[0], mCenter[1], mRad * 0.85, -15, 125);

    // Deep cupped shadow tucked under the upper-left rim of the mouth
    let cupX = mCenter[0] + LIGHT_X * mRad * 0.22;
    let cupY = mCenter[1] + LIGHT_Y * mRad * 0.22;
    setStroke("2B", pal.deep, constrain(rad * 0.055, 0.32, 0.68));
    brush.arc(cupX, cupY, mRad * 0.65, 135, 315);

    setStroke("rotring", "#160a07", constrain(rad * 0.032, 0.2, 0.38));
    brush.arc(cupX, cupY, mRad * 0.48, 155, 295);

    // Chipped outer lip edge catching window light
    setStroke("2H", pal.shadow, 0.22);
    let ch1 = toW(-rad * 0.55, rad * 0.48);
    let ch2 = toW(-rad * 0.32, rad * 0.32);
    let ch3 = toW(-rad * 0.12, rad * 0.58);
    brush.line(ch1[0], ch1[1], ch2[0], ch2[1]);
    brush.line(ch2[0], ch2[1], ch3[0], ch3[1]);

    // Burnished white columella & chipped lip rim
    setStroke("cpencil", pal.highlight, constrain(rad * 0.038, 0.25, 0.48));
    let col1 = toW(-rad * 0.05, -rad * 0.12);
    let col2 = toW(-rad * 0.38, rad * 0.28);
    brush.line(col1[0], col1[1], col2[0], col2[1]);
    brush.line(ch2[0], ch2[1], ch3[0], ch3[1]);

    // Spire whorls at +u
    for (let w = 1; w <= 2; w++) {
      let u0 = rad * (0.32 + w * 0.26);
      let sw = rad * (0.58 - w * 0.18);
      let sp1 = toW(u0, -sw);
      let sp2 = toW(u0 + rad * 0.1, 0);
      let sp3 = toW(u0, sw);
      setStroke("2H", pal.shadow, 0.22);
      brush.spline([[sp1[0], sp1[1], 0.4], [sp2[0], sp2[1], 0.9], [sp3[0], sp3[1], 0.4]], 0.4);
    }
  } else {
    // 4B. Spire-up view: tight logarithmic whorl spiral & cupped umbilical/lip notch
    let spCenter = toW(rad * 0.18, 0);
    let spiralPts = [];
    let highlightPts = [];
    let turns = 2.6;
    let steps = 14;
    for (let i = 0; i <= steps; i++) {
      let f = i / steps;
      let a = ang + f * turns * 360;
      let r = rad * 0.78 * (1 - f * 0.86);
      spiralPts.push([
         lerp(x, spCenter[0], f) + r * cos(a),
         lerp(y, spCenter[1], f) + r * sin(a),
         0.4 + 0.5 * (1 - f)
      ]);
      if (i < 8) {
        highlightPts.push([
          lerp(x, spCenter[0], f) + (r * 0.85) * cos(a) + LIGHT_X * 1.4,
          lerp(y, spCenter[1], f) + (r * 0.85) * sin(a) + LIGHT_Y * 1.4,
          0.6
        ]);
      }
    }
    setStroke("2H", pal.shadow, 0.24);
    brush.spline(spiralPts, 0.5);

    setStroke("cpencil", pal.highlight, 0.28);
    brush.spline(highlightPts, 0.5);

    // Small cupped notch shadow at outer lip termination
    let lipP = toW(-rad * 0.68, rad * 0.35);
    setStroke("2B", pal.deep, 0.35);
    brush.line(lipP[0], lipP[1], lipP[0] + cA * 2.5, lipP[1] + sA * 2.5);
  }

  // 5. Burnished upper-left highlight on body whorl
  let hx = x + LIGHT_X * rad * 0.38;
  let hy = y + LIGHT_Y * rad * 0.38;
  setStroke("cpencil", pal.highlight, constrain(rad * 0.045, 0.28, 0.55));
  brush.arc(x, y, rad * 0.62, 200, 265);
  brush.line(hx - 1.2, hy + 1.2, hx + 1.2, hy - 1.2);
}

function drawRiceShell(x, y, len, wid, ang, pal, seedVal = 0.5) {
  let rx = len * 0.5;
  let ry = wid * 0.5;
  let cA = cos(ang);
  let sA = sin(ang);
  const toW = (u, v) => [x + u * cA - v * sA, y + u * sA + v * cA];

  // 1. Cast shadow
  setStroke("2B", "#1d140f", constrain(wid * 0.06, 0.25, 0.48));
  let s1 = toW(-rx * 0.55, ry * 0.2);
  let s2 = toW(rx * 0.55, ry * 0.2);
  brush.line(s1[0] + 2.0, s1[1] + 2.2, s2[0] + 2.0, s2[1] + 2.2);

  // 2. Slender fusiform rice-shell body wash
  let pts = [
    toW(-rx, 0),
    toW(-rx * 0.45, -ry * 0.82),
    toW(0.05 * rx, -ry),
    toW(rx * 0.65, -ry * 0.68),
    toW(rx, 0),
    toW(rx * 0.65, ry * 0.68),
    toW(0.05 * rx, ry),
    toW(-rx * 0.45, ry * 0.82)
  ];
  drawWashPoly(pts, pal.base, 240, 0.22);

  // 3. Lower-right shading & upper-left nacre
  setStroke("cpencil", pal.shadow, 0.28);
  brush.line(
    x + 1.5 - cA * rx * 0.55, y + 1.5 - sA * rx * 0.55,
    x + 1.5 + cA * rx * 0.55, y + 1.5 + sA * rx * 0.55
  );

  setStroke("cpencil", seedVal > 0.5 ? pal.nacre2 : pal.nacre1, 0.3);
  brush.line(
    x - 1.2 - cA * rx * 0.5, y - 1.2 - sA * rx * 0.5,
    x - 1.2 + cA * rx * 0.5, y - 1.2 + sA * rx * 0.5
  );

  // 4. Spire suture at +u and narrow cupped aperture at -u with chipped lip
  let sp1 = toW(rx * 0.35, -ry * 0.72);
  let sp2 = toW(rx * 0.45, ry * 0.72);
  setStroke("2H", pal.shadow, 0.2);
  brush.line(sp1[0], sp1[1], sp2[0], sp2[1]);

  // Cupped shadow in narrow rice-shell mouth
  let m1 = toW(-rx * 0.82, ry * 0.12);
  let m2 = toW(rx * 0.08, ry * 0.28);
  setStroke("rotring", pal.deep, 0.25);
  brush.line(m1[0], m1[1], m2[0], m2[1]);

  // Chipped lip edge & burnished highlight streak
  setStroke("cpencil", pal.highlight, 0.32);
  let h1 = toW(-rx * 0.5, ry * 0.42);
  let h2 = toW(rx * 0.02, ry * 0.52);
  brush.line(h1[0], h1[1], h2[0], h2[1]);

  let bx = x + LIGHT_X * wid * 0.22;
  let by = y + LIGHT_Y * wid * 0.22;
  brush.line(bx - cA * rx * 0.42, by - sA * rx * 0.42, bx + cA * rx * 0.35, by + sA * rx * 0.35);
}

function drawTellinPetal(x, y, len, wid, ang, pal, seedVal = 0.5) {
  let rx = len * 0.5;
  let ry = wid * 0.5;
  let cA = cos(ang);
  let sA = sin(ang);
  const toW = (u, v) => [x + u * cA - v * sA, y + u * sA + v * cA];

  // 1. Cast shadow
  setStroke("charcoal", "#1d140f", 0.38);
  let sh1 = toW(-rx * 0.5, ry * 0.25);
  let sh2 = toW(rx * 0.65, ry * 0.45);
  brush.line(sh1[0] + 2.5, sh1[1] + 2.8, sh2[0] + 2.5, sh2[1] + 2.8);

  // 2. Wedge/fan bivalve silhouette (pointed umbo at -rx, flared margin at +rx)
  let pts = [
    toW(-rx, 0),
    toW(-rx * 0.35, -ry * 0.62),
    toW(rx * 0.35, -ry * 0.98),
    toW(rx * 0.82, -ry * 0.72),
    toW(rx * (seedVal > 0.4 ? 0.92 : 1.0), 0), // chipped ventral margin
    toW(rx * 0.82, ry * 0.72),
    toW(rx * 0.35, ry * 0.98),
    toW(-rx * 0.35, ry * 0.62)
  ];
  drawWashPoly(pts, pal.base, 240, 0.22);

  // 3. Concave valve interior: cupped shadow on upper-left hinge cavity
  let cupX = x + LIGHT_X * wid * 0.16 - cA * rx * 0.22;
  let cupY = y + LIGHT_Y * wid * 0.16 - sA * rx * 0.22;
  setStroke("cpencil", pal.shadow, 0.38);
  brush.line(cupX - sA * ry * 0.4, cupY + cA * ry * 0.4, cupX + cA * rx * 0.45, cupY + sA * rx * 0.45);

  setStroke("2B", pal.deep, 0.3);
  let umbo = toW(-rx * 0.75, 0);
  brush.line(umbo[0], umbo[1], umbo[0] + cA * 3.5, umbo[1] + sA * 3.5);

  // 4. Iridescent nacre interior & burnished chipped ventral lip on lower-right
  setStroke("cpencil", pal.nacre2, 0.36);
  let n1 = toW(rx * 0.25, -ry * 0.65);
  let n2 = toW(rx * 0.68, 0);
  let n3 = toW(rx * 0.25, ry * 0.65);
  brush.spline([[n1[0], n1[1], 0.4], [n2[0], n2[1], 0.9], [n3[0], n3[1], 0.4]], 0.45);

  setStroke("cpencil", pal.highlight, 0.35);
  let r1 = toW(rx * 0.55, -ry * 0.68);
  let r2 = toW(rx * 0.9, 0);
  let r3 = toW(rx * 0.55, ry * 0.68);
  brush.spline([[r1[0], r1[1], 0.4], [r2[0], r2[1], 0.95], [r3[0], r3[1], 0.4]], 0.45);
}

