function drawParlorBackground() {
  // Warm antique rag paper & directional window light washes from upper-left
  drawWatercolorPoly(
    [[0, 0], [1200, 0], [1200, 1200], [0, 1200]],
    "#dfd2be", 45, 0.12, 0.45, 0.2
  );
  drawWatercolorPoly(
    [[450, 350], [1200, 150], [1200, 1200], [150, 1200]],
    "#cbb9a1", 55, 0.25, 0.55, 0.35
  );
  drawWatercolorPoly(
    [[700, 650], [1200, 500], [1200, 1200], [500, 1200]],
    "#b59f86", 65, 0.28, 0.6, 0.4
  );

  // Subtle woven linen ground texture around the outer perimeter
  setStroke("2H", "#c4b299", 0.25);
  for (let i = 20; i < 1180; i += 14) {
    if (i > 120 && i < 1080) {
      brush.line(20, i, 125, i);
      brush.line(1075, i, 1180, i);
      brush.line(i, 20, i, 125);
      brush.line(i, 1075, i, 1180);
    } else {
      brush.line(20, i, 1180, i);
      brush.line(i, 20, i, 1180);
    }
  }

  // Deep cast shadow of the octagonal shadowbox towards lower-right
  let shOct1 = octRingPts(542, CX + 22, CY + 25);
  let shOct2 = octRingPts(548, CX + 34, CY + 38);
  drawWatercolorPoly(shOct2, "#9c866e", 85, 0.32, 0.6, 0.35);
  drawWatercolorPoly(shOct1, "#6b5542", 105, 0.22, 0.65, 0.45);
  drawWashPoly(octRingPts(535, CX + 12, CY + 14), "#423124", 160, 0.02);
}

function drawBrassHardware() {
  // Two antique brass butt-hinges on the Left vertical side (x ~ 106, y = 435 & 765)
  let hingeYs = [435, 765];
  for (let h = 0; h < hingeYs.length; h++) {
    let hy = hingeYs[h];
    let hx = 93;
    // Cast shadow of hinge
    drawWashPoly([[hx + 3, hy - 34], [hx + 22, hy - 34], [hx + 22, hy + 40], [hx + 3, hy + 40]], "#473526", 150, 0.05);
    // Brass plate & knuckles in watercolour glazes
    drawWatercolorPoly([[hx, hy - 36], [hx + 18, hy - 36], [hx + 18, hy + 36], [hx, hy + 36]], "#9c7b3e", 160, 0.08, 0.5, 0.4);
    drawWashPoly([[hx + 1, hy - 35], [hx + 15, hy - 35], [hx + 15, hy + 35], [hx + 1, hy + 35]], "#b89652", 210, 0.02);

    // Hinge knuckles & pins
    for (let k = -24; k <= 24; k += 16) {
      setStroke("2B", "#4a3516", 0.35);
      brush.line(hx, hy + k, hx + 15, hy + k);
      setStroke("cpencil", "#f2e2b6", 0.42);
      brush.line(hx + 3, hy + k - 10, hx + 3, hy + k - 2);
    }
    setStroke("rotring", "#3b280e", 0.26);
    brush.rect(hx, hy - 35, 15, 70, "corner");
  }

  // Antique brass hook & clasp on the Right vertical side (x ~ 1094, y = 600)
  let cx = 1092;
  let cy = 600;
  drawWashPoly([[cx, cy - 30], [cx + 16, cy - 24], [cx + 16, cy + 32], [cx, cy + 36]], "#423022", 160, 0.05);
  drawWatercolorPoly([[cx - 2, cy - 28], [cx + 13, cy - 22], [cx + 13, cy + 28], [cx - 2, cy + 28]], "#8f6e34", 170, 0.08, 0.5, 0.4);
  drawWashPoly([[cx, cy - 26], [cx + 11, cy - 20], [cx + 11, cy + 20], [cx, cy + 26]], "#ad8a49", 220, 0.05);

  // Hook loop & highlight
  setStroke("2B", "#3d2910", 0.38);
  brush.arc(cx + 8, cy, 9, -70, 90);
  setStroke("cpencil", "#f5e4b8", 0.4);
  brush.line(cx + 3, cy - 20, cx + 3, cy + 16);
  brush.arc(cx + 7, cy - 1, 8, -60, 40);
}

function drawMahoganyFrame() {
  let rOuter = 536;
  let rCrownOut = 514;
  let rCrownIn = 456;
  let rBevelIn = 434;
  let rBoxIn = 418;

  // Base solid warm underwash for the entire frame ring so no background bleeds through
  for (let i = 0; i < 8; i++) {
    let ni = (i + 1) % 8;
    let quad = [
      octVertex(rOuter, i), octVertex(rOuter, ni),
      octVertex(rBoxIn, ni), octVertex(rBoxIn, i)
    ];
    drawWashPoly(quad, "#7d3d20", 245, 0.01);
  }

  // Side lighting profiles for the 8 octagonal facets
  // i=0: BR, i=1: B, i=2: BL, i=3: L, i=4: TL (brightest), i=5: T, i=6: TR, i=7: R
  const outerCols = ["#4a1e0f", "#572413", "#78381e", "#994e2c", "#b5653c", "#9e522f", "#7a391f", "#522111"];
  const crownCols = ["#592614", "#692e18", "#853f22", "#9c4e2b", "#ad5c36", "#994c29", "#7d3a1e", "#612a16"];
  // Inward-sloping inner bevel reverses lighting! (BR, B, R catch the upper-left light)
  const innerBevelCols = ["#ad5f38", "#9c512c", "#783a1f", "#522211", "#3d170b", "#4f2010", "#75381d", "#994e2b"];
  const rabbetCols = ["#6e341b", "#632d17", "#471e0f", "#2b1007", "#210b04", "#2b1007", "#471e0f", "#632d17"];

  for (let i = 0; i < 8; i++) {
    let ni = (i + 1) % 8;
    let pOut1 = octVertex(rOuter, i), pOut2 = octVertex(rOuter, ni);
    let pCrO1 = octVertex(rCrownOut, i), pCrO2 = octVertex(rCrownOut, ni);
    let pCrI1 = octVertex(rCrownIn, i), pCrI2 = octVertex(rCrownIn, ni);
    let pBv1 = octVertex(rBevelIn, i), pBv2 = octVertex(rBevelIn, ni);
    let pBx1 = octVertex(rBoxIn, i), pBx2 = octVertex(rBoxIn, ni);

    // 1. Outer chamfer bevel in watercolour glaze
    drawWashPoly([pOut1, pOut2, pCrO2, pCrO1], outerCols[i], 210, 0.01);
    drawWatercolorPoly([pOut1, pOut2, pCrO2, pCrO1], outerCols[i], 95, 0.14, 0.6, 0.45);

    // 2. Main Mahogany Crown Molding in layered warm watercolour glazes
    drawWashPoly([pCrO1, pCrO2, pCrI2, pCrI1], crownCols[i], 200, 0.01);
    drawWatercolorPoly([pCrO1, pCrO2, pCrI2, pCrI1], "#a85831", 75, 0.18, 0.65, 0.4);
    drawWatercolorPoly([pCrO1, pCrO2, pCrI2, pCrI1], crownCols[i], 110, 0.15, 0.7, 0.5);

    // 3. Inward-sloping Ogee Bevel
    drawWashPoly([pCrI1, pCrI2, pBv2, pBv1], innerBevelCols[i], 220, 0.01);
    drawWatercolorPoly([pCrI1, pCrI2, pBv2, pBv1], innerBevelCols[i], 95, 0.12, 0.55, 0.4);

    // 4. Deep Shadowbox Rabbet Wall
    drawWashPoly([pBv1, pBv2, pBx2, pBx1], rabbetCols[i], 240, 0.01);

    // 5. Fine Mahogany Wood-Grain Figure & Pores along the facet
    let numGrains = 11;
    for (let g = 1; g < numGrains; g++) {
      let f = g / numGrains;
      let rG = lerp(rCrownIn + 4, rCrownOut - 4, f);
      let g1 = octVertex(rG, i);
      let g2 = octVertex(rG, ni);
      let midX = lerp(g1[0], g2[0], 0.5) + sin(g * 47 + i * 30) * 3.5;
      let midY = lerp(g1[1], g2[1], 0.5) + cos(g * 47 + i * 30) * 3.5;

      setStroke("cpencil", g % 3 === 0 ? "#381409" : "#5e2512", 0.32);
      brush.spline([
        [g1[0], g1[1], 0.5],
        [midX, midY, 0.9],
        [g2[0], g2[1], 0.5]
      ], 0.35);

      if (i >= 3 && i <= 5 && g % 4 === 0) {
        // Chatoyant warm amber ribbon highlight on lit upper-left facets
        setStroke("cpencil", "#d98b55", 0.28);
        brush.line(
          lerp(g1[0], g2[0], 0.15), lerp(g1[1], g2[1], 0.15),
          lerp(g1[0], g2[0], 0.85), lerp(g1[1], g2[1], 0.85)
        );
      }
    }

    // Satinwood / Boxwood Inlay Stringing Lines & Molding Arrises
    setStroke("cpencil", (i >= 3 && i <= 5) ? "#ebd7b2" : "#9c7e54", 0.36);
    brush.line(pCrO1[0], pCrO1[1], pCrO2[0], pCrO2[1]);
    brush.line(pCrI1[0], pCrI1[1], pCrI2[0], pCrI2[1]);

    setStroke("cpencil", "#dec9a4", 0.34);
    brush.line(pBv1[0], pBv1[1], pBv2[0], pBv2[1]);

    setStroke("rotring", "#240c05", 0.32);
    brush.line(pOut1[0], pOut1[1], pOut2[0], pOut2[1]);
    brush.line(pBx1[0], pBx1[1], pBx2[0], pBx2[1]);

    // Crisp miter joint line at corner i
    setStroke("rotring", "#210a04", 0.38);
    brush.line(pOut1[0], pOut1[1], pBx1[0], pBx1[1]);
    setStroke("cpencil", "#b87348", 0.25);
    brush.line(pOut1[0] + 1.2, pOut1[1] + 1.2, pBx1[0] + 1.2, pBx1[1] + 1.2);
  }
}

function drawInteriorGround() {
  // Deep recessed putty & dyed cotton-wool ground inside R = 418
  drawWashPoly(octRingPts(419), "#362c24", 255, 0.01);

  // Subtle tonal variations across the concentric rings in muted earth & faded moss
  drawWatercolorPoly(octRingPts(414), "#473b31", 95, 0.15, 0.65, 0.4);
  drawWashPoly(octRingPts(341), "#30362f", 180, 0.01); // muted Victorian slate-moss ring
  drawWashPoly(octRingPts(237), "#3b3028", 210, 0.01);
  drawWashPoly(octRingPts(139), "#2e231d", 235, 0.02);

  // Watercolor heart under-blush at center
  let heartUnder = [];
  for (let a = 0; a < 360; a += 10) {
    heartUnder.push(heartPoint(a, 5.25));
  }
  drawWatercolorPoly(heartUnder, "#6e352c", 110, 0.18, 0.55, 0.4);
}

function drawCedarDividers() {
  // Draws the thin geometric cedar & bone-paper compartment dividers + cast shadows
  const ringRadii = [417, 341, 237, 139];

  // 1. Radial cedar struts between R = 237 and R = 417
  for (let i = 0; i < 8; i++) {
    let p1 = octVertex(237, i);
    let p2 = octVertex(417, i);

    // Cast shadow onto shells/bed to lower-right
    setStroke("charcoal", "#1a110c", 0.65);
    brush.line(p1[0] + 3.0, p1[1] + 3.2, p2[0] + 3.0, p2[1] + 3.2);

    // Cedar strip body
    setStroke("marker", "#69341c", 0.55);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    // Bone-paper / boxwood top stringing
    setStroke("cpencil", "#e0cfb2", 0.34);
    brush.line(p1[0], p1[1], p2[0], p2[1]);

    setStroke("rotring", "#2b1208", 0.22);
    brush.line(p1[0] + 1.2, p1[1] + 1.2, p2[0] + 1.2, p2[1] + 1.2);
  }

  // 2. Concentric octagonal cedar dividers
  for (let rIdx = 0; rIdx < ringRadii.length; rIdx++) {
    let r = ringRadii[rIdx];
    for (let i = 0; i < 8; i++) {
      let ni = (i + 1) % 8;
      let p1 = octVertex(r, i);
      let p2 = octVertex(r, ni);

      setStroke("charcoal", "#1a110c", 0.65);
      brush.line(p1[0] + 2.8, p1[1] + 3.0, p2[0] + 2.8, p2[1] + 3.0);

      setStroke("marker", "#69341c", 0.58);
      brush.line(p1[0], p1[1], p2[0], p2[1]);

      setStroke("cpencil", "#e3d3b6", 0.36);
      brush.line(p1[0], p1[1], p2[0], p2[1]);
    }
  }
}

