function populateOuterGallery() {
  // Ring 4 (R = 341..417): 8 trapezoidal border compartments
  const palCycle = [PALETTES.shellPink, PALETTES.oyster, PALETTES.coral, PALETTES.paleLilac, PALETTES.earthOchre];

  for (let i = 0; i < 8; i++) {
    let ni = (i + 1) % 8;
    let midAng = 45 + i * 45;

    // Sub-row A (Outer, R = 401): 13 tightly packed Rice Shells in chevron alignment
    let aOut1 = octVertex(401, i), aOut2 = octVertex(401, ni);
    let nOuter = 13;
    for (let k = 0; k < nOuter; k++) {
      let f = (k + 0.7) / (nOuter + 0.4);
      let px = lerp(aOut1[0], aOut2[0], f);
      let py = lerp(aOut1[1], aOut2[1], f);
      let tilt = f < 0.5 ? midAng + 22 : midAng - 22;
      let pal = (k % 2 === 0) ? PALETTES.oyster : (k % 4 === 1 ? PALETTES.shellPink : PALETTES.paleLilac);
      drawRiceShell(px, py, 19, 8.5, tilt, pal, (k * 0.37) % 1);
    }

    // Sub-row B (Middle, R = 376): 2 corner Periwinkles + 7 plump Cowries
    let aMid1 = octVertex(376, i), aMid2 = octVertex(376, ni);
    let nMid = 9;
    for (let k = 0; k < nMid; k++) {
      let f = (k + 0.65) / (nMid + 0.3);
      let px = lerp(aMid1[0], aMid2[0], f);
      let py = lerp(aMid1[1], aMid2[1], f);
      if (k === 0 || k === nMid - 1) {
        drawPeriwinkle(px, py, 11.5, midAng + (k === 0 ? 40 : -40), PALETTES.paleLilac, true, 0.6);
      } else {
        let isCenter = (k === 4);
        let cLen = isCenter ? 28 : 24;
        let cWid = isCenter ? 19 : 16.5;
        let pal = isCenter ? PALETTES.coral : palCycle[(k + i) % palCycle.length];
        let mUp = (k % 2 === 1);
        drawCowrie(px, py, cLen, cWid, midAng + 90, pal, mUp, (k * 0.29) % 1);
      }
    }

    // Sub-row C (Inner, R = 353): 11 beaded Periwinkles & Rice Shells along inner cedar rail
    let aIn1 = octVertex(353, i), aIn2 = octVertex(353, ni);
    let nIn = 11;
    for (let k = 0; k < nIn; k++) {
      let f = (k + 0.65) / (nIn + 0.3);
      let px = lerp(aIn1[0], aIn2[0], f);
      let py = lerp(aIn1[1], aIn2[1], f);
      let pal = (k % 3 === 0) ? PALETTES.shellPink : ((k % 3 === 1) ? PALETTES.oyster : PALETTES.paleLilac);
      drawPeriwinkle(px, py, 10, midAng + k * 35, pal, k % 2 === 0, (k * 0.41) % 1);
    }
  }
}

function populateMiddleRosettes() {
  // Ring 3 (R = 237..341): 8 circular compass rosettes + spandrel corner clusters
  for (let i = 0; i < 8; i++) {
    let midAng = 45 + i * 45;
    let rRos = 289;
    let rx = CX + rRos * cos(midAng);
    let ry = CY + rRos * sin(midAng);

    // Subtle circular cedar/bone collar around each rosette (radius 44)
    setStroke("charcoal", "#1f1510", 0.5);
    brush.circle(rx + 2, ry + 2, 44, 0.08);
    setStroke("cpencil", "#d8c5a4", 0.32);
    brush.circle(rx, ry, 44, 0.06);

    // 1. Spandrel corners of the trapezoidal sector (outside the 44px rosette)
    let cornerOffsets = [
      { r: 324, da: -15.5, type: "cowrie", pal: PALETTES.earthOchre },
      { r: 324, da: 15.5, type: "cowrie", pal: PALETTES.earthOchre },
      { r: 298, da: -17, type: "peri", pal: PALETTES.oyster },
      { r: 298, da: 17, type: "peri", pal: PALETTES.oyster },
      { r: 254, da: -14.5, type: "cowrie", pal: PALETTES.shellPink },
      { r: 254, da: 14.5, type: "cowrie", pal: PALETTES.shellPink },
      { r: 274, da: -16.5, type: "rice", pal: PALETTES.paleLilac },
      { r: 274, da: 16.5, type: "rice", pal: PALETTES.paleLilac }
    ];
    for (let c = 0; c < cornerOffsets.length; c++) {
      let co = cornerOffsets[c];
      let a = midAng + co.da;
      let cx = CX + co.r * cos(a);
      let cy = CY + co.r * sin(a);
      if (co.type === "cowrie") {
        drawCowrie(cx, cy, 21, 14.5, a, co.pal, true, 0.55);
      } else if (co.type === "peri") {
        drawPeriwinkle(cx, cy, 10.5, a + 45, co.pal, c % 2 === 0, 0.6);
      } else {
        drawRiceShell(cx, cy, 18, 8, a + 90, co.pal, 0.5);
      }
    }

    // 2. Rosette Outer Ring (r = 32): 12 Tellin & Rice shell petals radiating outward
    for (let p = 0; p < 12; p++) {
      let pa = midAng + p * 30;
      let px = rx + 31.5 * cos(pa);
      let py = ry + 31.5 * sin(pa);
      let pal = (p % 2 === 0) ? (i % 2 === 0 ? PALETTES.shellPink : PALETTES.paleLilac) : PALETTES.oyster;
      if (p % 2 === 0) {
        drawTellinPetal(px, py, 21, 11.5, pa, pal, 0.6);
      } else {
        drawRiceShell(px, py, 19, 8.5, pa, pal, 0.4);
      }
    }

    // 3. Rosette Middle Ring (r = 16.5): 7 Periwinkles in a tight pearly ring
    for (let p = 0; p < 7; p++) {
      let pa = midAng + p * (360 / 7);
      let px = rx + 16.5 * cos(pa);
      let py = ry + 16.5 * sin(pa);
      let pal = (p % 2 === 0) ? PALETTES.paleLilac : PALETTES.oyster;
      drawPeriwinkle(px, py, 8.8, pa + 60, pal, p % 2 === 0, 0.5);
    }

    // 4. Rosette Center Jewel: 1 Plump Coral/RoseUmber Cowrie (mouth-up)
    drawCowrie(rx, ry, 22, 15.5, midAng, i % 2 === 0 ? PALETTES.coral : PALETTES.roseUmber, true, 0.7);
  }
}

function populateInnerStarBand() {
  // Ring 2 (R = 139..237): Concentric 16-fold Star of Tellins, Cowries & Periwinkles

  // Sub-ring A (R = 219): 32 concave Tellin valve petals forming a scalloped wreath
  for (let k = 0; k < 32; k++) {
    let a = k * 11.25;
    let px = CX + 219 * cos(a);
    let py = CY + 219 * sin(a);
    let pal = (k % 4 === 0) ? PALETTES.coral : ((k % 2 === 0) ? PALETTES.oyster : PALETTES.paleLilac);
    drawTellinPetal(px, py, 24, 12.5, a, pal, (k * 0.31) % 1);
  }

  // Sub-ring B (R = 198): 16 Periwinkles nestled between the tellin bases
  for (let k = 0; k < 16; k++) {
    let a = 11.25 + k * 22.5;
    let px = CX + 198 * cos(a);
    let py = CY + 198 * sin(a);
    let pal = (k % 2 === 0) ? PALETTES.earthOchre : PALETTES.shellPink;
    drawPeriwinkle(px, py, 10.5, a + 45, pal, true, 0.6);
  }

  // Sub-ring C (R = 182): 16 Large Hero Cowries (alternating mouth-up and glossy dorsum-up)
  for (let k = 0; k < 16; k++) {
    let a = k * 22.5;
    let px = CX + 182 * cos(a);
    let py = CY + 182 * sin(a);
    let pal = (k % 4 === 0) ? PALETTES.coral : ((k % 4 === 1) ? PALETTES.shellPink : ((k % 4 === 2) ? PALETTES.oyster : PALETTES.paleLilac));
    drawCowrie(px, py, 27, 18.5, a, pal, k % 2 === 0, (k * 0.43) % 1);
  }

  // Sub-ring D (R = 154): 28 tightly packed Rice Shells & Periwinkles framing the central plaque
  for (let k = 0; k < 28; k++) {
    let a = k * (360 / 28);
    let px = CX + 154 * cos(a);
    let py = CY + 154 * sin(a);
    if (k % 2 === 0) {
      drawRiceShell(px, py, 19, 8.5, a + 90, PALETTES.oyster, 0.5);
    } else {
      drawPeriwinkle(px, py, 9.2, a, PALETTES.paleLilac, k % 4 === 1, 0.5);
    }
  }
}

function populateHeartMedallion() {
  // Ring 1 (R = 0..139): Oyster & Pale-Lilac Rice-Shell Ground + Central Heart Mosaic

  // Precompute outer boundary of the Heart (scale = 5.15) for exact geometric exclusion
  let heartBorder = [];
  for (let a = 0; a < 360; a += 4) {
    heartBorder.push(heartPoint(a, 5.15));
  }

  // 1. Background paving around the Heart (inside R = 132, outside heartBorder + 11px margin)
  let bgRadii = [125, 110, 95, 80, 65, 50, 35];
  for (let rIdx = 0; rIdx < bgRadii.length; rIdx++) {
    let r = bgRadii[rIdx];
    let nShells = floor((TWO_PI * r) / 14.5);
    for (let k = 0; k < nShells; k++) {
      let a = (k / nShells) * 360 + (rIdx % 2) * (180 / nShells);
      let px = CX + r * cos(a);
      let py = CY + r * sin(a);

      if (!pointInPoly(px, py, heartBorder) && minDistToPoly(px, py, heartBorder) > 11.5) {
        let pal = ((k + rIdx) % 3 === 0) ? PALETTES.paleLilac : PALETTES.oyster;
        if (rIdx === 0 && k % 3 === 0) {
          drawPeriwinkle(px, py, 8.8, a + 30, pal, true, 0.5);
        } else {
          drawRiceShell(px, py, 16.5, 7.5, a + 90, pal, (k * 0.27) % 1);
        }
      }
    }
  }

  // Fill the top cleft pocket above the heart (around x = 600, y = 515..558)
  let cleftPositions = [
    [CX, 548, 90], [CX - 11, 535, 75], [CX + 11, 535, 105], [CX, 524, 90]
  ];
  for (let c = 0; c < cleftPositions.length; c++) {
    let cp = cleftPositions[c];
    if (!pointInPoly(cp[0], cp[1], heartBorder)) {
      drawRiceShell(cp[0], cp[1], 15, 7, cp[2], PALETTES.oyster, 0.4);
    }
  }

  // 2. THE HEART-SHAPED CENTRE (5 Concentric Heart Contours)

  // Contour 1 (Outer Heart Border, scale = 5.05): Plump Coral & RoseUmber Cowries
  let t1 = buildHeartArcTable(5.05);
  let nH1 = 12;
  for (let k = 1; k < nH1; k++) {
    let sample = sampleHeartAtArc(t1, (k / nH1) * t1.totalLen);
    let dx = sample.x - CX;
    let pal = (k % 2 === 0) ? PALETTES.coral : PALETTES.roseUmber;
    // Right lobe shell
    drawCowrie(sample.x, sample.y, 21.5, 14.5, sample.ang, pal, true, (k * 0.33) % 1);
    // Symmetric Left lobe shell
    drawCowrie(CX - dx, sample.y, 21.5, 14.5, 180 - sample.ang, pal, true, (k * 0.33) % 1);
  }
  // Top cleft jewel & bottom tip jewel of outer heart
  let topCleft1 = heartPoint(0, 5.05);
  let botTip1 = heartPoint(180, 5.05);
  drawPeriwinkle(topCleft1[0], topCleft1[1] + 2, 10.5, -90, PALETTES.coral, true, 0.7);
  drawCowrie(botTip1[0], botTip1[1] - 3, 22, 15, 90, PALETTES.roseUmber, true, 0.8);

  // Contour 2 (scale = 3.85): Shell-Pink & Pale-Lilac Periwinkles (mouth-up)
  let t2 = buildHeartArcTable(3.85);
  let nH2 = 10;
  for (let k = 1; k < nH2; k++) {
    let sample = sampleHeartAtArc(t2, (k / nH2) * t2.totalLen);
    let dx = sample.x - CX;
    let pal = (k % 2 === 0) ? PALETTES.shellPink : PALETTES.paleLilac;
    drawPeriwinkle(sample.x, sample.y, 9.6, sample.ang + 45, pal, true, 0.6);
    drawPeriwinkle(CX - dx, sample.y, 9.6, 135 - sample.ang, pal, true, 0.6);
  }
  let topCleft2 = heartPoint(0, 3.85);
  let botTip2 = heartPoint(180, 3.85);
  drawPeriwinkle(topCleft2[0], topCleft2[1] + 2, 9.2, -90, PALETTES.shellPink, false, 0.5);
  drawPeriwinkle(botTip2[0], botTip2[1] - 2, 9.8, 90, PALETTES.shellPink, true, 0.5);

  // Contour 3 (scale = 2.75): Oyster-White & Shell-Pink Rice Shells set radially like lace
  let t3 = buildHeartArcTable(2.75);
  let nH3 = 9;
  for (let k = 1; k < nH3; k++) {
    let sample = sampleHeartAtArc(t3, (k / nH3) * t3.totalLen);
    let dx = sample.x - CX;
    let pal = (k % 2 === 0) ? PALETTES.oyster : PALETTES.shellPink;
    drawRiceShell(sample.x, sample.y, 16, 7.2, sample.ang + 90, pal, 0.5);
    drawRiceShell(CX - dx, sample.y, 16, 7.2, 90 - sample.ang, pal, 0.5);
  }
  let topCleft3 = heartPoint(0, 2.75);
  let botTip3 = heartPoint(180, 2.75);
  drawRiceShell(topCleft3[0], topCleft3[1] + 2, 15, 7, 90, PALETTES.oyster, 0.4);
  drawRiceShell(botTip3[0], botTip3[1] - 2, 16, 7.2, 90, PALETTES.oyster, 0.4);

  // Contour 4 (scale = 1.65): Glossy Coral & Shell-Pink Cowries (dorsum-up nacre domes)
  let t4 = buildHeartArcTable(1.65);
  let nH4 = 5;
  for (let k = 1; k < nH4; k++) {
    let sample = sampleHeartAtArc(t4, (k / nH4) * t4.totalLen);
    let dx = sample.x - CX;
    let pal = (k % 2 === 0) ? PALETTES.coral : PALETTES.shellPink;
    drawCowrie(sample.x, sample.y, 18.5, 13, sample.ang, pal, false, 0.6);
    drawCowrie(CX - dx, sample.y, 18.5, 13, 180 - sample.ang, pal, false, 0.6);
  }
  let botTip4 = heartPoint(180, 1.65);
  drawPeriwinkle(botTip4[0], botTip4[1] - 2, 8.5, 90, PALETTES.paleLilac, true, 0.5);

