// ============================================================================
// ENVIRONMENT SHADER FOR HYPERREAL CHROME
// ============================================================================
function sampleChromeTone(nx, ny, nz, ripple = 0) {
  // Analytical studio environment reflection value [0..1]
  // Chrome reflects sharp dark horizon bands, bright softboxes, and secondary bounce
  let reflY = ny * 0.78 + nz * 0.42 + sin(nx * 190 + ripple * 80) * 0.14;
  let reflX = nx * 0.85 - ny * 0.25;

  let val = 0.5;
  if (reflY < -0.42) {
    // Upper studio softbox + dark ceiling cut
    val = map(reflY, -0.85, -0.42, 0.18, 0.96, true);
  } else if (reflY < -0.12) {
    // Primary blinding white softbox reflection
    val = map(abs(reflY + 0.27), 0, 0.15, 1.0, 0.72, true);
  } else if (reflY < 0.16) {
    // Razor-sharp dark horizon core (signature of chrome)
    val = map(abs(reflY - 0.02), 0, 0.14, 0.02, 0.22, true);
  } else if (reflY < 0.46) {
    // Secondary bright table/vellum bounce reflection
    val = map( abs(reflY - 0.31), 0, 0.15, 0.92, 0.44, true);
  } else {
    // Lower dark floor & fin inter-reflection
    val = map(reflY, 0.46, 0.95, 0.35, 0.06, true);
  }

  // Rim enhancement
  let fresnel = pow(constrain(1.0 - abs(nz), 0, 1), 2.2);
  if (reflX < -0.35) val = constrain(val + fresnel * 0.35, 0, 1);
  if (reflX > 0.45) val = constrain(val - 0.15 + fresnel * 0.25, 0, 1);

  return constrain(val, 0, 1);
}

function chromeColorFromVal(v) {
  if (v < 0.11) return PAL.chromeBlack;
  if (v < 0.23) return PAL.chromeDeep;
  if (v < 0.38) return PAL.chromeDark;
  if (v < 0.54) return PAL.chromeMid;
  if (v < 0.70) return PAL.chromeSteel;
  if (v < 0.84) return PAL.chromeLight;
  if (v < 0.93) return PAL.chromeBright;
  return PAL.chromeWhite;
}

// ============================================================================
// DRAFTING BOARD & STACKED TRACING SHEETS
// ============================================================================
function drawDraftingBoard() {
  background(PAL.board);

  // Subtle board wash texture
  brush.noStroke();
  brush.fill(PAL.boardDark, 55);
  brush.fillBleed(0.35, "out");
  brush.fillTexture(0.65, 0.25);
  drawRectPoly(-20, -20, 1240, 1240);
  brush.noFill();

  // Faint drafting board grid in the exposed margins
  brush.set("2H", "#8b98a6", 0.45);
  for (let x = 60; x < 1200; x += 60) {
    if (x < 300 || x > 1100) brush.line(x, 0, x, 1200);
  }
  for (let y = 60; y < 1200; y += 60) {
    if (y < 260 || y > 1080) brush.line(0, y, 1200, y);
  }
}

function drawTracingSheet(cfg) {
  push();
  translate(cfg.cx, cfg.cy);
  rotate(cfg.angle);

  let hw = cfg.w / 2;
  let hh = cfg.h / 2;

  // Soft drop shadow under the left and top sheet edges
  brush.noFill();
  brush.noWash();
  for (let i = 1; i <= 4; i++) {
    brush.set("charcoal", "#4a5662", (5 - i) * 0.45);
    brush.line(-hw - i * 2.5, -hh + 4, -hw - i * 2.5, hh + i * 2);
    brush.line(-hw - 2, -hh - i * 2, hw, -hh - i * 2);
    brush.line(-hw - 2, hh + i * 2.5, hw, hh + i * 2.5);
  }

  // Translucent vellum paper wash (veils underlying ghost drawings!)
  brush.noStroke();
  brush.wash(cfg.washCol, cfg.washAlpha);
  drawRectPoly(-hw, -hh, cfg.w, cfg.h);
  brush.noWash();

  // Milky blue-grey watercolor veil patches across the sheet
  brush.fill(cfg.watercolorCol, cfg.wcAlpha);
  brush.fillBleed(0.28, "in");
  brush.fillTexture(0.55, 0.35);
  drawRectPoly(-hw + 18, -hh + 18, cfg.w - 36, cfg.h - 36);
  brush.noFill();

  // Crisp physical paper edge and double drafting border
  brush.set("2H", "#ffffff", 0.9);
  brush.line(-hw, -hh, hw, -hh);
  brush.line(-hw, -hh, -hw, hh);
  brush.set("2H", "#7c8b99", 0.65);
  brush.line(-hw, hh, hw, hh);
  brush.line(hw, -hh, hw, hh);

  // Inner technical border line with zone ticks
  let bm = 28;
  brush.set("2H", cfg.sheetIndex === 3 ? "#5d7182" : "#8092a1", 0.55);
  brush.line(-hw + bm, -hh + bm, hw - bm, -hh + bm);
  brush.line(-hw + bm, -hh + bm, -hw + bm, hh - bm);
  brush.line(-hw + bm, hh - bm, hw - bm, hh - bm);

  for (let t = -hw + bm + 120; t < hw - bm; t += 140) {
    brush.line(t, -hh + bm - 8, t, -hh + bm + 6);
    brush.line(t, hh - bm - 6, t, hh - bm + 8);
  }
  for (let t = -hh + bm + 120; t < hh - bm; t += 140) {
    brush.line(-hw + bm - 8, t, -hw + bm + 6, t);
  }

  pop();
}

function drawRectPoly(x, y, w, h) {
  brush.beginShape(0);
  brush.vertex(x, y);
  brush.vertex(x + w, y);
  brush.vertex(x + w, y + h);
  brush.vertex(x, y + h);
  brush.endShape(CLOSE);
}

