  brush.noStroke();
  brush.fill(isFirst ? "#7c9ab3" : "#6b8091", isFirst ? 45 : 38);
  brush.fillBleed(0.22, "out");
  brush.fillTexture(0.5, 0.3);
  // Cylinder ghost mass
  drawRotatedBoxPoly(635, 495, 360, 390, -19);
