    let rx = 188 + sin(i * 18) * 14 + (i > 9 ? 12 : 0);
    let ry = rx * 0.33;
    brush.set("2H", i % 3 === 0 ? colPrimary : colSecondary, i % 3 === 0 ? 0.75 : 0.45);
    drawEllipseWireframe(0, fy, rx, ry, i % 4 === 0);
  }

  // Ghost piston & connecting rod schematic inside cylinder
  if (isFirst) {
    brush.set("2H", PAL.ghostBlue, 0.85);
    drawEllipseWireframe(0, -210, 112, 36, true);
    drawEllipseWireframe(0, -115, 112, 36, false);
    brush.circle(0, -165, 28, 0.1);
    brush.line(-24, -165, 45, 155);
    brush.line(24, -165, 85, 155);
  }

  // Ghost rocker cover wireframe box
  drawPerspectiveBox(0, -420, 210, 145, 78, colPrimary, 0.75);
  pop();

  // Ghost Crankcase nested ellipse guides
  push();
  translate(810, 845);
  rotate(24);
  brush.set("2H", colPrimary, 0.75);
  brush.line(-310, 0, 310, 0);
  brush.line(0, -220, 0, 220);
  let radii = [255, 215, 175, 115, 58];
  for (let r of radii) {
    drawEllipseWireframe(0, 0, r, r * 0.64, r === 215);
  }
  pop();

  // Ghost Exhaust Pipe Spline + Cross-section stations
  let exPts = getExhaustCenterline();
  brush.set("HB", colPrimary, 0.85);
  brush.spline(exPts, 0.5);

  for (let i = 0; i < exPts.length - 1; i++) {
    let p = exPts[i];
    let pNext = exPts[i + 1];
    let ang = atan2(pNext[1] - p[1], pNext[0] - p[0]);
    push();
    translate(p[0], p[1]);
    rotate(ang + 90);
    brush.set("2H", colSecondary, 0.55);
    drawEllipseWireframe(0, 0, 54, 24, true);
    pop();
  }
}

