function drawIntakeBellmouth(cx, cy) {
  push();
  translate(cx, cy);
  rotate(32);

  // Draftsman's ellipse construction cage
  brush.set("2H", PAL.guideBlue, 0.7);
  drawDashedLine(-160, 0, 160, 0, 14, 6);
  drawDashedLine(0, -180, 0, 140, 14, 6);

  let rings = [
    { y: 70, rx: 58, ry: 26 },
    { y: 30, rx: 64, ry: 29 },
    { y: -15, rx: 82, ry: 38 },
    { y: -55, rx: 118, ry: 54 },
    { y: -72, rx: 126, ry: 58 }
  ];

  for (let r of rings) {
    brush.set("2H", PAL.guideBlue, 0.55);
    drawEllipseWireframe(0, r.y, r.rx, r.ry, true);
  }

  // Half-rendered chrome velocity stack throat
  for (let a = -165; a <= 15; a += 3) {
    let t = map(a, -165, 15, -1, 1);
    let nx = sin(a);
    let ny = -0.25;
    let nz = cos(a);
    let v = sampleChromeTone(nx, ny, nz, 0.3);
    let col = chromeColorFromVal(v);

    let x1 = cos(a) * 60;
    let y1 = 55 + sin(a) * 26;
    let x2 = cos(a) * 120;
    let y2 = -55 + sin(a) * 54;

    brush.set("micro_graphite", col, map( abs(v - 0.5), 0, 0.5, 0.6, 1.3));
    brush.line(x1, y1, x2, y2);
  }

  // Deep throat shadow inside bellmouth
  for (let r = 12; r < 95; r += 3.5) {
    brush.set("2B", r < 55 ? PAL.chromeBlack : PAL.chromeDark, 1.1);
    brush.arc(0, -58, r, 195, 345);
  }

  // Specular flared lip
  brush.set("specular_blade", PAL.chromeWhite, 1.4);
  brush.arc(0, -55, 120, 200, 265);
  brush.arc(0, -55, 118, 295, 340);

  pop();
}

// ============================================================================
// MAIN CYLINDER BLOCK & 14 HYPERREAL COOLING FINS
// ============================================================================
function drawCylinderAndFins() {
  push();
  translate(680, 690);
  rotate(-19);

  // Heavy Cylinder Base Flange & Hold-Down Nuts
  drawCylinderBaseFlange(0, -10, 175, 58);

  let finCount = 14;
  let finSpacing = 24.5;
  let finThick = 9.2;

  for (let i = 0; i < finCount; i++) {
    let fy = -38 - i * finSpacing;
    // Fins widen progressively toward the combustion head
    let rx = 182 + i * 2.2 + sin(i * 35) * 5;
    if (i < 2) rx -= (2 - i) * 14;
    let ry = rx * 0.33;

    // 1. Deep Recessed Shadow Slot above this fin (between Fin i and Fin i+1)
    let barrelRx = rx * 0.68;
    let barrelRy = ry * 0.68;
    for (let a = 12; a <= 168; a += 2.2) {
      let rad = a;
      let bx = cos(rad) * barrelRx;
      let by = fy - finThick + sin(rad) * barrelRy;
      let slotH = finSpacing - finThick + 2;

      // Ambient occlusion + reflected sliver inside the cooling slot
      let nx = cos(rad);
      let isReflectedSliver = (a > 52 && a < 66) || (a > 118 && a < 128);
      let slotCol = isReflectedSliver ? PAL.chromeSteel : (a > 70 && a < 115 ? PAL.chromeBlack : PAL.chromeDeep);

      brush.set("rotring", slotCol, 1.25);
      brush.line(bx, by, bx, by - slotH);
    }

    // 2. Top Visible Bevel / Shelf of Fin i (around the front-left & front-right curves)
    for (let a = -15; a <= 195; a += 2.5) {
      let pOuter = getFinProfilePoint(a, rx, ry);
      let pInner = getFinProfilePoint(a, rx * 0.72, ry * 0.72);

      // Top surface catches sky reflection on the left and right wings
      let topVal = sampleChromeTone(cos(a) * 0.5, -0.75, sin(a) * 0.5, i * 0.12);
      // Cast shadow from the fin above except near the outer rim
      let rimCol = topVal > 0.7 ? PAL.chromeLight : PAL.chromeMid;
      brush.set("micro_graphite", PAL.chromeDark, 0.85);
      brush.line(pInner.x, fy - finThick + pInner.y, pOuter.x, fy - finThick + pOuter.y);

      // Outer 30% of top shelf catches bright sky reflection
      let pMid = getFinProfilePoint(a, rx * 0.86, ry * 0.86);
      brush.set("micro_graphite", rimCol, 0.9);
      brush.line(pMid.x, fy - finThick + pMid.y, pOuter.x, fy - finThick + pOuter.y);
    }

    // 3. Front Machined Polished Edge of Fin i (Thickness = finThick)
    // High-resolution micro-vertical and contour strokes for liquid mirror chrome
    for (let a = -12; a <= 192; a += 1.1) {
      let p = getFinProfilePoint(a, rx, ry);
      let nx = cos(a - 90);
      let nz = sin(a - 90);
      let ny = 0.08 * sin(a * 3 + i * 19);

      // Pushrod cast shadow zone on the right side of the fins (around a = 25..58)
      let inPushrodShadow = (a > 24 && a < 62);
      let v = sampleChromeTone(nx, ny, nz, i * 0.07);
      if (inPushrodShadow) v *= 0.28;

      let col = chromeColorFromVal(v);
      brush.set("chrome_shader", col, 0.95);
      brush.line(p.x, fy + p.y, p.x, fy - finThick + p.y);

      // Extra razor-sharp pure white specular bars on the polished fin face
      if (v > 0.88 && !inPushrodShadow) {
        brush.set("specular_blade", PAL.chromeWhite, 1.15);
        brush.line(p.x, fy + p.y - 1, p.x, fy - finThick + p.y + 1);
      }
    }

    // 4. Crisp Upper and Lower Bevel Rim Lines of each Fin
    drawFinEdgeContour(0, fy - finThick, rx, ry, true, i);
    drawFinEdgeContour(0, fy, rx, ry, false, i);

    // 5. Vertical Tie-Rod Bosses & Machined Cooling Notches
    let bossAngles = [38, 82, 132, 166];
    for (let ba of bossAngles) {
      let bp = getFinProfilePoint(ba, rx * 0.97, ry * 0.97);
      brush.set("rotring", PAL.chromeBlack, 1.1);
      brush.line(bp.x - 4, fy + bp.y, bp.x - 4, fy - finThick + bp.y);
      brush.set("specular_blade", PAL.chromeWhite, 0.95);
      brush.line(bp.x + 2, fy + bp.y, bp.x + 2, fy - finThick + bp.y);
    }
  }

  pop();
}

function getFinProfilePoint(angDeg, rx, ry) {
  // Creates an authentic squared-ellipse / machined motorcycle fin profile with notches
  let x = cos(angDeg) * rx;
  let y = sin(angDeg) * ry;

  // Slight squaring of the cheeks (superellipse blend)
  let sq = 0.12 * sin(angDeg * 2);
  x *= (1 + sq * 0.15);
  y *= (1 - sq * 0.15);

  // Machined cooling notches at 82 and 132 degrees
  if (abs(angDeg - 82) < 3.5 || abs(angDeg - 132) < 3.5) {
    x *= 0.93;
    y *= 0.93;
  }
  return { x, y };
}

function drawFinEdgeContour(cx, cy, rx, ry, isTopEdge, finIdx) {
  let step = 4;
  for (let a = -10; a < 190; a += step) {
    let p1 = getFinProfilePoint(a, rx, ry);
    let p2 = getFinProfilePoint(a + step, rx, ry);

    let nx = cos(a - 90);
    let nz = sin(a - 90);
    let v = sampleChromeTone(nx, isTopEdge ? -0.35 : 0.35, nz, finIdx * 0.05);

    if (isTopEdge) {
      // Top edge catches intense white highlight along front-left and front-right
      let isSpec = (v > 0.55) && !(a > 26 && a < 60);
      brush.set(isSpec ? "specular_blade" : "rotring", isSpec ? PAL.chromeWhite : PAL.chromeDark, isSpec ? 1.1 : 0.65);
    } else {
      // Bottom edge has crisp dark underside line
      brush.set("rotring", v < 0.35 ? PAL.chromeBlack : PAL.chromeDeep, 0.8);
    }
    brush.line(cx + p1.x, cy + p1.y, cx + p2.x, cy + p2.y);
  }
}

function drawCylinderBaseFlange(cx, cy, rx, ry) {
  // Heavy cast & polished base collar with 4 hold-down hex nuts
  for (let a = 0; a <= 180; a += 2) {
    let x = cx + cos(a) * rx;
    let y = cy + sin(a) * ry;
    let v = sampleChromeTone(cos(a - 90), 0.1, sin(a - 90), 0);
    brush.set("chrome_shader", chromeColorFromVal(v), 1.1);
    brush.line(x, y, x, y + 18);
  }
  // Base hold-down hex nuts with washers
  let nutAngles = [28, 72, 118, 158];
  for (let na of nutAngles) {
    let nx = cx + cos(na) * (rx * 0.95);
    let ny = cy + sin(na) * (ry * 0.95) - 4;
    drawHexBolt3D(nx, ny, 14, -90, true);
  }
}

// ============================================================================
// DOMED CHROME ROCKER BOX / CYLINDER HEAD
// ============================================================================
function drawRockerHead() {
  push();
  translate(680, 690);
  rotate(-19);

  let baseY = -384;
  let rx = 206;
  let ry = 68;

  // Lower Rocker Housing (Polished Aluminum / Chrome Box)
  for (let a = -15; a <= 195; a += 1.2) {
    let p = getFinProfilePoint(a, rx, ry);
    let nx = cos(a - 90);
    let nz = sin(a - 90);

    for (let h = 0; h < 54; h += 4) {
      let domeCurve = map(h, 0, 54, 0.15, -0.55);
      let shrink = h > 36 ? map(h, 36, 54, 1.0, 0.88) : 1.0;
      let v = sampleChromeTone(nx, domeCurve, nz, h * 0.01);
      // Deep horizon band cutting across the middle of the rocker cover
      if (h > 18 && h < 30 && a > 35 && a < 155) v *= 0.18;

      let col = chromeColorFromVal(v);
      brush.set("chrome_shader", col, 1.15);
      brush.line(p.x * shrink, baseY - h + p.y * shrink, p.x * shrink, baseY - h - 5 + p.y * shrink);
    }
  }

  // Upper Split Rocker Domes (Twin polished chrome crowns)
  let domes = [
    { cx: -78, cy: baseY - 62, rx: 98, ry: 34, h: 42 },
    { cx: 78, cy: baseY - 62, rx: 98, ry: 34, h: 42 }
  ];

  for (let d of domes) {
    // Sculpt each dome with compound elliptical contours
    for (let layer = 0; layer <= 18; layer++) {
      let t = layer / 18;
      let lrx = d.rx * sqrt(1 - t * t * 0.78);
      let lry = d.ry * sqrt(1 - t * t * 0.78);
      let ly = d.cy - t * d.h;

      for (let a = 0; a < 360; a += 5) {
        let x1 = d.cx + cos(a) * lrx;
        let y1 = ly + sin(a) * lry;
        let x2 = d.cx + cos(a + 5) * lrx;
        let y2 = ly + sin(a + 5) * lry;

        let nx = cos(a) * (1 - t * 0.4);
        let ny = -0.35 - t * 0.65;
        let nz = sin(a) * (1 - t * 0.4);
        let v = sampleChromeTone(nx, ny, nz, 0.2);

        brush.set("chrome_shader", chromeColorFromVal(v), 1.05);
        brush.line(x1, y1, x2, y2);

        if (v > 0.90 && layer % 2 === 0) {
          brush.set("specular_blade", PAL.chromeWhite, 1.25);
          brush.line(x1, y1, x2, y2);
        }
      }
    }

    // Rocker cover perimeter hex bolts & bright specular crown flare
    let boltPos = [
      [-d.rx * 0.78, d.ry * 0.45],
      [0, d.ry * 0.88],
      [d.rx * 0.78, d.ry * 0.45],
      [-d.rx * 0.65, -d.ry * 0.65],
      [d.rx * 0.65, -d.ry * 0.65]
    ];
    for (let bp of boltPos) {
      drawHexBolt3D(d.cx + bp[0], d.cy + bp[1] - 6, 11, -90, true);
    }
  }

  // Split-seam Gasket Line & Deep Shadow Groove between Lower & Upper Rocker Cover
  for (let a = -5; a < 185; a += 3) {
    let p1 = getFinProfilePoint(a, rx * 0.96, ry * 0.96);
    let p2 = getFinProfilePoint(a + 3, rx * 0.96, ry * 0.96);
    brush.set("rotring", PAL.chromeBlack, 1.4);
    brush.line(p1.x, baseY - 40 + p1.y, p2.x, baseY - 40 + p2.y);
    brush.set("specular_blade", PAL.chromeWhite, 1.0);
    brush.line(p1.x, baseY - 42.5 + p1.y, p2.x, baseY - 42.5 + p2.y);
  }

  pop();
}

// ============================================================================
// TWIN CHROME PUSHROD TUBES & TAPPET COLLARS
// ============================================================================
function drawPushrodTubes() {
  let tubes = [
    { x1: 752, y1: 695, x2: 598, y2: 315, r: 20 },
    { x1: 822, y1: 668, x2: 662, y2: 288, r: 20 }
  ];

  for (let idx = 0; idx < tubes.length; idx++) {
    let tb = tubes[idx];
    let dx = tb.x2 - tb.x1;
    let dy = tb.y2 - tb.y1;
    let len = sqrt(dx * dx + dy * dy);
    let ang = atan2(dy, dx);

    push();
    translate(tb.x1, tb.y1);
    rotate(ang + 90);

    // Cast shadow onto the cooling fins behind the pushrod tube
    brush.noStroke();
    brush.wash(PAL.chromeBlack, 155);
    drawRectPoly(-tb.r - 12, -len + 15, tb.r * 1.4, len - 30);
    brush.noWash();

    // Longitudinal high-contrast chrome cylinder striping
    let strips = 26;
    for (let s = 0; s <= strips; s++) {
      let u = map(s, 0, strips, -1, 1);
      let x = u * tb.r;
      let nx = u;
      let nz = sqrt(max(0, 1 - u * u));
      let ny = -0.15;

      // Classic cylindrical mirror reflection bands
      let v = sampleChromeTone(nx, ny, nz, idx * 0.4);
      // Sharp dark core reflection at u = -0.15..0.18 and blinding white at u = -0.52 and +0.48
      if (u > -0.18 && u < 0.14) v = 0.04;
      else if (abs(u + 0.52) < 0.16) v = 0.98;
      else if (abs(u - 0.46) < 0.14) v = 0.94;

      let col = chromeColorFromVal(v);
      brush.set(v > 0.9 ? "specular_blade" : "chrome_shader", col, 1.15);
      brush.line(x, 0, x, -len);
    }

    // Flared Tappet Collars & Spring Keeper Rings (Bottom, Middle-low, and Top)
    let collarPositions = [-18, -42, -135, -158, -len + 26, -len + 8];
    for (let cy of collarPositions) {
      let cr = (cy === -135 || cy === -42) ? tb.r + 7.5 : tb.r + 4.5;
      let ch = 14;
      for (let s = -cr; s <= cr; s += 1.6) {
        let u = s / cr;
        let v = sampleChromeTone(u, 0.22, sqrt(max(0, 1 - u * u)), 0.1);
        brush.set("rotring", chromeColorFromVal(v), 1.0);
        brush.line(s, cy + (s * s) / (cr * 3.5), s, cy - ch + (s * s) / (cr * 3.5));
      }
      // Crisp white specular ring on top of collar
      brush.set("specular_blade", PAL.chromeWhite, 1.25);
      brush.arc(0, cy - ch, cr, 15, 78);
      brush.arc(0, cy - ch, cr, 110, 165);
      // Dark shadow beneath collar
      brush.set("rotring", PAL.chromeBlack, 1.2);
      brush.arc(0, cy + 2, cr, 10, 170);
    }

    // Crisp outer contour lines
    brush.set("rotring", PAL.chromeBlack, 0.85);
    brush.line(-tb.r, 0, -tb.r, -len);
    brush.line(tb.r, 0, tb.r, -len);

    pop();
  }
}

// ============================================================================
// CRANKCASE / TIMING GEAR COVER & PERIMETER HEX BOLTS
// ============================================================================
function drawCrankcaseAndTimingCover() {
  let cx = 810;
  let cy = 845;

  push();
  translate(cx, cy);
  rotate(24);

  let aspect = 0.64;

  // 1. Outer Crankcase Machined Bevel & Recessed Case Rim (R = 250 down to 212)
  for (let a = 0; a < 360; a += 1.5) {
    let x1 = cos(a) * 252;
    let y1 = sin(a) * 252 * aspect;
    let x2 = cos(a) * 212;
    let y2 = sin(a) * 212 * aspect;

    let nx = cos(a) * 0.75;
    let ny = sin(a) * 0.75;
    let nz = 0.55;
    let v = sampleChromeTone(nx, ny, nz, 0.15);

    brush.set("chrome_shader", chromeColorFromVal(v), 1.15);
    brush.line(x1, y1, x2, y2);
  }

  // 2. Main Domed Chrome Timing Cover Plate (R = 212 down to 105)
  // Rendered with radial & concentric mirror reflections (classic liquid horizon across the dome)
  for (let r = 104; r <= 212; r += 2.6) {
    let domeT = map(r, 104, 212, 0.25, 0.85);
    for (let a = 0; a < 360; a += 4) {
      let x1 = cos(a) * r;
      let y1 = sin(a) * r * aspect;
      let x2 = cos(a + 4) * r;
      let y2 = sin(a + 4) * r * aspect;

      let nx = cos(a) * domeT;
      let ny = sin(a) * domeT - 0.12;
      let nz = sqrt(max(0, 1 - domeT * domeT));

      let v = sampleChromeTone(nx, ny, nz, r * 0.008);
      brush.set("chrome_shader", chromeColorFromVal(v), 1.1);
      brush.line(x1, y1, x2, y2);

      if (v > 0.91 && r % 5 < 2.6) {
        brush.set("specular_blade", PAL.chromeWhite, 1.25);
        brush.line(x1, y1, x2, y2);
      }
    }
  }

  // 3. Stepped Inner Points Cover / Ignition Medallion (R = 104 down to 0)
  for (let r = 6; r < 104; r += 2.2) {
    for (let a = 0; a < 360; a += 6) {
      let x1 = cos(a) * r - 12;
      let y1 = sin(a) * r * aspect - 6;
      let x2 = cos(a + 6) * r - 12;
      let y2 = sin(a + 6) * r * aspect - 6;

      // Inverted conical bevel between r=78 and r=104, flat mirror inside r=78
      let isBevel = r > 78;
      let nx = isBevel ? -cos(a) * 0.65 : cos(a) * 0.18;
      let ny = isBevel ? -sin(a) * 0.65 : sin(a) * 0.18 + (y1 / 110);
      let nz = isBevel ? 0.6 : 0.92;

      let v = sampleChromeTone(nx, ny, nz, 0.05);
      brush.set("micro_graphite", chromeColorFromVal(v), 1.0);
      brush.line(x1, y1, x2, y2);
    }
  }

  // Deep shadow groove rings at step boundaries (R = 250, 212, 104, 78)
  let stepRadii = [252, 212, 104, 78];
  for (let sr of stepRadii) {
    let offset = sr <= 104 ? -12 : 0;
    let offsetY = sr <= 104 ? -6 : 0;
    for (let a = 0; a < 360; a += 3) {
      let x1 = offset + cos(a) * sr;
      let y1 = offsetY + sin(a) * sr * aspect;
      let x2 = offset + cos(a + 3) * sr;
      let y2 = offsetY + sin(a + 3) * sr * aspect;
      brush.set("rotring", PAL.chromeBlack, 1.35);
      brush.line(x1, y1, x2, y2);

      // Adjacent white bevel lip
      if (a > 175 && a < 335) {
        brush.set("specular_blade", PAL.chromeWhite, 1.2);
        brush.line(x1 + 2, y1 + 2, x2 + 2, y2 + 2);
      }
    }
  }

  // 4. Perimeter Ring of 10 Socket-Head / Hex Bolts around R = 230
  for (let b = 0; b < 10; b++) {
    let ba = b * 36 + 14;
    let bx = cos(ba) * 231;
    let by = sin(ba) * 231 * aspect;

    // Local draftsman's construction cross for each bolt!
    brush.set("2H", PAL.guideBlue, 0.5);
    brush.line(bx - 22, by, bx + 22, by);
    brush.line(bx, by - 22, bx, by + 22);

    drawHexBolt3D(bx, by, 14.5, -145, true);
  }

  // 5. Inner Medallion Center Hex Nut & 3 Recessed Screws
  drawHexBolt3D(-12, -6, 18, -145, true);
  for (let s = 0; s < 3; s++) {
    let sa = s * 120 + 30;
    drawHexBolt3D(-12 + cos(sa) * 56, -6 + sin(sa) * 56 * aspect, 8.5, -145, false);
  }

  pop();
}

// ============================================================================
// HYPERREAL 3D HEX / ALLEN BOLT RENDERER
// ============================================================================
function drawHexBolt3D(x, y, radius, extrudeAngle, hasWasher) {
  push();
  translate(x, y);

  let dx = cos(extrudeAngle) * (radius * 0.55);
  let dy = sin(extrudeAngle) * (radius * 0.55);

  // Cast shadow under bolt head
  brush.noStroke();
  brush.wash(PAL.chromeBlack, 190);
  brush.circle(-dx * 0.55, -dy * 0.55, radius * 1.15, 0.08);
  brush.noWash();

  // Polished Washer
  if (hasWasher) {
    brush.set("rotring", PAL.chromeDeep, 1.2);
    brush.circle(0, 0, radius * 1.28, 0.05);
    brush.set("specular_blade", PAL.chromeWhite, 1.1);
    brush.arc(0, 0, radius * 1.25, 185, 315);
  }

  // 6 Hex Flats (Extruded Sides from Base to Crown)
  let hexPtsBase = [];
  let hexPtsTop = [];
  for (let i = 0; i < 6; i++) {
    let a = i * 60 + 18;
    let px = cos(a) * radius;
    let py = sin(a) * radius * 0.78;
    hexPtsBase.push([px, py]);
    hexPtsTop.push([px + dx, py + dy]);
  }

  // Render the 3 visible side facets of the hex head with distinct chrome reflections
  let facetTones = [PAL.chromeWhite, PAL.chromeBlack, PAL.chromeMid, PAL.chromeDeep, PAL.chromeLight, PAL.chromeBright];
  for (let i = 0; i < 6; i++) {
    let ni = (i + 1) % 6;
    let b1 = hexPtsBase[i], b2 = hexPtsBase[ni];
    let t1 = hexPtsTop[i], t2 = hexPtsTop[ni];

    for (let s = 0; s <= 1; s += 0.14) {
      let sx1 = lerp(b1[0], b2[0], s);
      let sy1 = lerp(b1[1], b2[1], s);
      let sx2 = lerp(t1[0], t2[0], s);
      let sy2 = lerp(t1[1], t2[1], s);
      brush.set("rotring", facetTones[i], 0.9);
      brush.line(sx1, sy1, sx2, sy2);
    }
    // Crisp vertical crease between hex flats
    brush.set("rotring", i === 0 || i === 5 ? PAL.chromeWhite : PAL.chromeBlack, 0.85);
    brush.line(b1[0], b1[1], t1[0], t1[1]);
  }

  // Crown Face of Bolt (Chamfered Chrome Dome + Recessed Allen Socket)
  for (let r = 2; r < radius * 0.85; r += 1.6) {
    let isSocket = r < radius * 0.44;
    brush.set("rotring", isSocket ? PAL.chromeBlack : PAL.chromeLight, 0.95);
    brush.circle(dx, dy, r, 0.04);
  }

  // Blinding white specular crescent on the chamfered crown edge
  brush.set("specular_blade", PAL.chromeWhite, 1.35);
  brush.arc(dx, dy, radius * 0.78, 175, 310);
  brush.arc(dx, dy, radius * 0.44, 15, 145);

  pop();
}

// ============================================================================
// SWEEPING CHROME EXHAUST HEADER PIPE (FOREGROUND LIQUID MIRROR)
// ============================================================================
function getExhaustCenterline() {
  return [
    [488, 365],
    [365, 395],
    [255, 470],
    [212, 585],
    [238, 715],
    [345, 835],
    [515, 965],
    [685, 1115]
  ];
}

function sampleCatmullRom(pts, tGlobal) {
  let n = pts.length - 1;
  let scaled = constrain(tGlobal, 0, 0.9999) * n;
  let idx = floor(scaled);
  let t = scaled - idx;

  let p0 = pts[max(0, idx - 1)];
  let p1 = pts[idx];
  let p2 = pts[min(n, idx + 1)];
  let p3 = pts[min(n, idx + 2)];

  let t2 = t * t;
  let t3 = t2 * t;

  let x = 0.5 * ((2 * p1[0]) + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3);
  let y = 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3);

  let dx = 0.5 * ((-p0[0] + p2[0]) + 2 * (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t + 3 * (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t2);
  let dy = 0.5 * ((-p0[1] + p2[1]) + 2 * (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t + 3 * (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t2);

  let len = sqrt(dx * dx + dy * dy) || 1;
  return { x, y, tx: dx / len, ty: dy / len, nx: -dy / len, ny: dx / len };
}

function drawExhaustHeader() {
  let pts = getExhaustCenterline();
  let pipeR = 54;

  // 1. Cast Shadow of the Exhaust Pipe onto the Engine & Tracing Sheet behind it
  for (let s = 0.04; s < 0.92; s += 0.008) {
    let c = sampleCatmullRom(pts, s);
    brush.set("charcoal", "#242e38", 2.2);
    brush.line(
      c.x + 18 - c.nx * (pipeR * 0.7),
      c.y + 24 - c.ny * (pipeR * 0.7),
      c.x + 18 + c.nx * (pipeR * 0.85),
      c.y + 24 + c.ny * (pipeR * 0.85)
    );
  }

  // 2. Subtle Chrome Heat-Tint Wash (amber-straw & steely blue near the exhaust port bend)
  for (let s = 0.03; s < 0.36; s += 0.045) {
    let c = sampleCatmullRom(pts, s);
    brush.noStroke();
    brush.fill(s < 0.18 ? PAL.heatBlue : PAL.warmBrass, 42);
    brush.fillBleed(0.25, "in");
    brush.fillTexture(0.4, 0.2);
    brush.circle(c.x, c.y, pipeR * 0.85, 0.12);
    brush.noFill();
  }

  // 3. High-Resolution 3D Tube Mirror Reflection Rendering
  // March along cross-section u in [-1..1] and longitudinal s in [0..1]
  let uSteps = 34;
  let sSteps = 135;

  for (let ui = 0; ui <= uSteps; ui++) {
    let u = map(ui, 0, uSteps, -1, 1);
    let nz = sqrt(max(0, 1 - u * u));

    for (let si = 0; si < sSteps; si++) {
      let s1 = si / sSteps;
      let s2 = (si + 1) / sSteps;
      let c1 = sampleCatmullRom(pts, s1);
      let c2 = sampleCatmullRom(pts, s2);

      let x1 = c1.x + c1.nx * (u * pipeR);
      let y1 = c1.y + c1.ny * (u * pipeR);
      let x2 = c2.x + c2.nx * (u * pipeR);
      let y2 = c2.y + c2.ny * (u * pipeR);

      // Compute 3D surface normal in world space
      let wnx = c1.nx * u + c1.tx * 0.18 * sin(s1 * 520);
      let wny = c1.ny * u + c1.ty * 0.18 * cos(s1 * 520);

      // Reflection of the cooling fins along the inner side of the bend!
      let finReflectionRipple = (u < -0.25 && s1 < 0.65) ? sin(s1 * 2800) * 0.35 : 0;
      let v = sampleChromeTone(wnx, wny + finReflectionRipple * 0.3, nz, s1 * 1.4);

      // Enhance signature liquid-chrome dark core & bright specular ribbons along the bend
      if (abs(u - 0.08 * sin(s1 * 380)) < 0.15) {
        v *= 0.14; // Liquid jet-black core ribbon
      } else if (abs(u + 0.48 - 0.12 * cos(s1 * 310)) < 0.13) {
        v = 0.98;  // Primary blinding white highlight ribbon
      } else if (abs(u - 0.56 + 0.08 * sin(s1 * 420)) < 0.10) {
        v = 0.93;  // Secondary softbox reflection ribbon
      }

      let col = chromeColorFromVal(v);
      let bName = v > 0.90 ? "specular_blade" : (v < 0.18 ? "rotring" : "chrome_shader");
      let wgt = v > 0.90 ? 1.35 : 1.05;

      brush.set(bName, col, wgt);
      brush.line(x1, y1, x2, y2);
    }
  }

  // 4. Cross-Contour Elliptical Reflection Rings & Draftsman's Station Guides on the Pipe
  for (let s = 0.08; s < 0.95; s += 0.09) {
    let c = sampleCatmullRom(pts, s);
    let ang = atan2(c.ty, c.tx) + 90;
    push();
    translate(c.x, c.y);
    rotate(ang);
    // Faint draftsman's station ellipse peeking beyond the chrome wall
    brush.set("2H", PAL.guideBlue, 0.55);
    drawEllipseWireframe(0, 0, pipeR + 14, 22, s < 0.3 || s > 0.75);
    // Crisp cross-contour graphite shading inside the pipe
    brush.set("micro_graphite", PAL.chromeLight, 0.65);
    brush.arc(0, 0, pipeR * 0.95, 195, 345);
    pop();
  }

  // 5. Crisp Outer Boundary Silhouettes of the Chrome Pipe
  for (let side of [-1, 1]) {
    for (let si = 0; si < sSteps; si++) {
      let c1 = sampleCatmullRom(pts, si / sSteps);
      let c2 = sampleCatmullRom(pts, (si + 1) / sSteps);
      brush.set("rotring", PAL.chromeBlack, 0.95);
      brush.line(
        c1.x + c1.nx * side * pipeR,
        c1.y + c1.ny * side * pipeR,
        c2.x + c2.nx * side * pipeR,
        c2.y + c2.ny * side * pipeR
      );
      // Inner rim highlight just inside the dark edge
      brush.set("specular_blade", PAL.chromeWhite, 0.95);
      brush.line(
        c1.x + c1.nx * side * (pipeR - 3.2),
        c1.y + c1.ny * side * (pipeR - 3.2),
        c2.x + c2.nx * side * (pipeR - 3.2),
        c2.y + c2.ny * side * (pipeR - 3.2)
      );
    }
  }

  // 6. Finned Exhaust Port Clamp Flange & Mounting Studs at Cylinder Head
  let port = sampleCatmullRom(pts, 0.015);
  push();
  translate(port.x, port.y);
  rotate(atan2(port.ty, port.tx) + 90);
  for (let ring = 0; ring < 3; ring++) {
    let ry = ring * 13;
    let rRad = pipeR + 16 - ring * 2.5;
    for (let s = -rRad; s <= rRad; s += 1.8) {
      let u = s / rRad;
      let v = sampleChromeTone(u, -0.2, sqrt(max(0, 1 - u * u)), ring * 0.2);
      brush.set("rotring", chromeColorFromVal(v), 1.1);
      brush.line(s, ry, s, ry + 8);
    }
    brush.set("specular_blade", PAL.chromeWhite, 1.2);
    brush.line(-rRad * 0.7, ry, -rRad * 0.2, ry);
  }
  drawHexBolt3D(-pipeR - 12, 12, 12, -120, true);
  drawHexBolt3D(pipeR + 12, 12, 12, -120, true);
  pop();
}

