// ============================================================================
// GEOMETRIC & DRAFTING HELPER PRIMITIVES
// ============================================================================
function drawRotatedBoxPoly(cx, cy, w, h, ang) {
  let hw = w / 2, hh = h / 2;
  let ca = cos(ang), sa = sin(ang);
  let corners = [[-hw, -hh], [hw, -hh], [hw, hh], [-hw, hh]];
  brush.beginShape(0);
  for (let c of corners) {
    let rx = cx + c[0] * ca - c[1] * sa;
    let ry = cy + c[0] * sa + c[1] * ca;
    brush.vertex(rx, ry);
  }
  brush.endShape(CLOSE);
}

function drawEllipseWireframe(cx, cy, rx, ry, withAxes) {
  let step = 10;
  for (let a = 0; a < 360; a += step) {
    let x1 = cx + cos(a) * rx;
    let y1 = cy + sin(a) * ry;
    let x2 = cx + cos(a + step) * rx;
    let y2 = cy + sin(a + step) * ry;
    brush.line(x1, y1, x2, y2);
  }
  if (withAxes) {
    brush.line(cx - rx - 16, cy, cx + rx + 16, cy);
    brush.line(cx, cy - ry - 14, cx, cy + ry + 14);
    // Axis end ticks
    brush.line(cx - rx, cy - 6, cx - rx, cy + 6);
    brush.line(cx + rx, cy - 6, cx + rx, cy + 6);
  }
}

function drawPerspectiveBox(cx, cy, w, d, h, col, wgt) {
  brush.set("2H", col, wgt);
  let hw = w / 2, hd = d * 0.34;
  // Bottom & top rhombuses
  for (let yOff of [0, -h]) {
    brush.line(cx - hw, cy + yOff, cx, cy + yOff - hd);
    brush.line(cx, cy + yOff - hd, cx + hw, cy + yOff);
    brush.line(cx + hw, cy + yOff, cx, cy + yOff + hd);
    brush.line(cx, cy + yOff + hd, cx - hw, cy + yOff);
  }
  // Vertical pillars
  brush.line(cx - hw, cy, cx - hw, cy - h);
  brush.line(cx + hw, cy, cx + hw, cy - h);
  brush.line(cx, cy - hd, cx, cy - hd - h);
  brush.line(cx, cy + hd, cx, cy + hd - h);
}

function drawDashedLine(x1, y1, x2, y2, dashLen, gapLen) {
  let dx = x2 - x1, dy = y2 - y1;
  let distTotal = sqrt(dx * dx + dy * dy);
  let ux = dx / distTotal, uy = dy / distTotal;
  let cur = 0;
  while (cur < distTotal) {
    let endD = min(cur + dashLen, distTotal);
    brush.line(x1 + ux * cur, y1 + uy * cur, x1 + ux * endD, y1 + uy * endD);
    cur += dashLen + gapLen;
  }
}

function drawRectWire(x, y, w, h) {
  brush.line(x, y, x + w, y);
  brush.line(x + w, y, x + w, y + h);
  brush.line(x + w, y + h, x, y + h);
  brush.line(x, y + h, x, y);
}

function drawArrowHead(x, y, dirDeg, size) {
  let a1 = dirDeg + 155;
  let a2 = dirDeg - 155;
  brush.line(x, y, x + cos(a1) * size, y + sin(a1) * size);
  brush.line(x, y, x + cos(a2) * size, y + sin(a2) * size);
}

// Vector stroke lettering for authentic draftsman's technical annotations
function drawTechnicalGlyphs(x, y, str, rotDeg, sz) {
  push();
  translate(x, y);
  rotate(rotDeg);
  brush.set("rotring", PAL.guideBlue, 0.55);

  let cx = 0;
  let w = sz * 0.62;
  let h = sz;

  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    if (ch !== " ") {
      // Minimalist architectural stroke characters
      if ("0OQD".includes(ch)) {
        drawRectWire(cx, -h, w, h);
        if (ch === "0") brush.line(cx, 0, cx + w, -h);
      } else if (ch === "1" || ch === "I") {
        brush.line(cx + w * 0.5, 0, cx + w * 0.5, -h);
      } else if ("235S".includes(ch)) {
        brush.line(cx, -h, cx + w, -h);
        brush.line(cx, -h * 0.5, cx + w, -h * 0.5);
        brush.line(cx, 0, cx + w, 0);
        brush.line(cx + w, -h, cx + w, -h * 0.5);
        brush.line(cx, -h * 0.5, cx, 0);
      } else if (ch === "4") {
        brush.line(cx, -h, cx, -h * 0.45);
        brush.line(cx, -h * 0.45, cx + w, -h * 0.45);
        brush.line(cx + w * 0.75, -h, cx + w * 0.75, 0);
      } else if ("68B".includes(ch)) {
        drawRectWire(cx, -h, w, h);
        brush.line(cx, -h * 0.5, cx + w, -h * 0.5);
      } else if ("AhrR".includes(ch)) {
        brush.line(cx, 0, cx, -h);
        brush.line(cx, -h, cx + w, -h);
        brush.line(cx + w, -h, cx + w, -h * 0.45);
        brush.line(cx, -h * 0.45, cx + w, -h * 0.45);
        brush.line(cx + w * 0.4, -h * 0.45, cx + w, 0);
      } else if ("EFPL".includes(ch)) {
        brush.line(cx, 0, cx, -h);
        if (ch !== "L") brush.line(cx, -h, cx + w, -h);
        if (ch !== "L") brush.line(cx, -h * 0.5, cx + w * 0.8, -h * 0.5);
        if (ch === "E" || ch === "L") brush.line(cx, 0, cx + w, 0);
        if (ch === "P") brush.line(cx + w, -h, cx + w, -h * 0.5);
      } else if ("NTY".includes(ch)) {
        brush.line(cx + w * 0.5, 0, cx + w * 0.5, -h);
        brush.line(cx, -h, cx + w, -h);
      } else if (ch === "/" || ch === "-") {
        brush.line(cx, -h * 0.3, cx + w, -h * 0.7);
      } else if (ch === ".") {
        brush.circle(cx + w * 0.3, -1, 1.5, 0);
      } else {
        brush.line(cx, 0, cx, -h);
        brush.line(cx, -h, cx + w, 0);
        brush.line(cx + w, 0, cx + w, -h);
      }
    }
    cx += w + sz * 0.32;
  }
  pop();
}

