// Helper: Queue a cloison polygon in a specific depth layer
function addCloison(layer, pts, color, outlineWeight = 1.0, curvature = 0.05, useWatercolor = true) {
  if (!pts || pts.length < 3) return;
  let clean = [];
  for (let i = 0; i < pts.length; i++) {
    let p = pts[i];
    if (clean.length === 0) {
      clean.push(p);
    } else {
      let prev = clean[clean.length - 1];
      if ( hypot(p[0] - prev[0], p[1] - prev[1]) > 1.5 ) {
        clean.push(p);
      }
    }
  }
  if (clean.length > 2) {
    let first = clean[0];
    let last = clean[clean.length - 1];
    if (hypot(first[0] - last[0], first[1] - last[1]) < 1.5) {
      clean.pop();
    }
  }
  if (clean.length < 3) return;

  // Approximate polygon area to decide whether full watercolor simulation is needed
  let area = 0;
  for (let i = 0; i < clean.length; i++) {
    let j = (i + 1) % clean.length;
    area += clean[i][0] * clean[j][1] - clean[j][0] * clean[i][1];
  }
  area = Math.abs(area) * 0.5;

  cloisonQueue.push({
    layer,
    pts: clean,
    color,
    outlineWeight,
    curvature,
    useWatercolor: useWatercolor && area > 480,
    area
  });
}

function hypot(dx, dy) {
  return Math.sqrt(dx * dx + dy * dy);
}

// Helper: Generate points along an elliptical arc
function arcPts(cx, cy, rx, ry, aStart, aEnd, steps = 16) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let a = aStart + (aEnd - aStart) * t;
    pts.push([cx + rx * cos(a), cy + ry * sin(a)]);
  }
  return pts;
}

// Helper: Full ellipse polygon
function ellipsePoly(cx, cy, rx, ry, steps = 28) {
  let pts = [];
  for (let i = 0; i < steps; i++) {
    let a = (i / steps) * 360;
    pts.push([cx + rx * cos(a), cy + ry * sin(a)]);
  }
  return pts;
}

// Helper: 3D Cylindrical / Frustum band between two heights and two angles (0..180 = front face)
function cylBand(cx, yTop, rxTop, ryTop, yBot, rxBot, ryBot, a1, a2, steps = 10) {
  let pts = [];
  for (let i = 0; i <= steps; i++) {
    let a = a1 + (a2 - a1) * (i / steps);
    pts.push([cx + rxTop * cos(a), yTop + ryTop * sin(a)]);
  }
  for (let i = steps; i >= 0; i--) {
    let a = a1 + (a2 - a1) * (i / steps);
    pts.push([cx + rxBot * cos(a), yBot + ryBot * sin(a)]);
  }
  return pts;
}

// Helper: Rounded rectangle polygon
function roundRectPoly(x, y, w, h, r, stepsCorner = 5) {
  let pts = [];
  let corners = [
    [x + w - r, y + r, -90, 0],
    [x + w - r, y + h - r, 0, 90],
    [x + r, y + h - r, 90, 180],
    [x + r, y + r, 180, 270]
  ];
  for (let c of corners) {
    for (let i = 0; i <= stepsCorner; i++) {
      let a = c[2] + (c[3] - c[2]) * (i / stepsCorner);
      pts.push([c[0] + r * cos(a), c[1] + r * sin(a)]);
    }
  }
  return pts;
}

function drawPolyShape(pts, curvature = 0.05) {
  brush.beginShape(curvature);
  for (let i = 0; i < pts.length; i++) {
    brush.vertex(pts[i][0], pts[i][1]);
  }
  brush.endShape(true);
}

