  const Y_BASE = 892, RX_BASE = 90, RY_BASE = 26;
  const Y_RINGB1 = 858, RX_RB1 = 93, RY_RB1 = 25;
  const Y_RINGB2 = 834, RX_RB2 = 91, RY_RB2 = 24;
