  const Y_NOZ1 = 408, RX_NOZ1 = 25, RY_NOZ1 = 6;
  const Y_NOZ2 = 374, RX_NOZ2 = 16, RY_NOZ2 = 4;
  const Y_TIP = 332, RX_TIP = 6.5, RY_TIP = 2.2;

  // Circumferential angle splits across the front of the cylinder (180 = left, 0 = right)
  const A = [180, 160, 140, 124, 102, 58, 24, 0];

  // Helper to build a full horizontal tier of cloisons
  function buildTier(layer, y1, rx1, ry1, y2, rx2, ry2, cols, weight = 0.95) {
    for (let i = 0; i < A.length - 1; i++) {
      addCloison(
        layer,
        cylBand(cx, y1, rx1, ry1, y2, rx2, ry2, A[i], A[i + 1], 7),
        cols[i],
        weight,
        0.04
      );
    }
  }

  // Tier 1: Molded Base Foot (Y_RINGB1 to Y_BASE)
  buildTier(20, Y_RINGB1, RX_RB1, RY_RB1, Y_BASE, RX_BASE, RY_BASE, [
    PAL.redBounceCool, PAL.redBright, PAL.redPink, PAL.redTomato, PAL.redDeep, PAL.redDark, PAL.redBounceWarm
  ], 1.0);

  // Tier 2: Bottom Grip Ring Groove (Y_RINGB2 to Y_RINGB1)
