// Helper to get glass radius at any y between 280 and 885
function getColaRadius(y) {
  if (y >= 825) {
    return map(y, 825, 885, 78, 73);
  } else if (y >= 665) {
    return map(y, 665, 825, 92, 78);
  } else {
    return map(y, 280, 665, 115, 92);
  }
}

function getColaRy(y) {
  return map(y, 280, 885, 24, 22);
}

function buildColaGlass() {
  const cx = 925;

  // LAYER 40: Drinking Straw (Upper aerial segment & Refracted submerged segment)
  // Aerial straw above meniscus (from x:944, y:342 up to x:1032, y:146)
  const sx1 = 940, sy1 = 344, sx2 = 1026, sy2 = 148;
  const sw = 18;
  const stSteps = 7;
  for (let i = 0; i < stSteps; i++) {
    let t1 = i / stSteps, t2 = (i + 1) / stSteps;
    let xA = lerp(sx1, sx2, t1), yA = lerp(sy1, sy2, t1);
    let xB = lerp(sx1, sx2, t2), yB = lerp(sy1, sy2, t2);
    let col = (i % 2 === 0) ? PAL.napkinWhite : PAL.redTomato;
    addCloison(40, [
      [xA, yA], [xB, yB], [xB + sw, yB + 7], [xA + sw, yA + 7]
    ], col, 0.95, 0.02);
  }
  // Straw top opening ellipse
  addCloison(40, ellipsePoly(sx2 + sw * 0.5, sy2 + 3.5, 9.5, 4.2, 14), PAL.chromeSlate, 0.9, 0.05);

  // LAYER 41: Upper Glass Rim above Liquid Meniscus (y: 280 to 346)
  const Y_RIM = 280, RX_RIM = 115, RY_RIM = 24;
