// ============================================================================
// RENDER ENGINE: WATERCOLOR FILLS + PONT-AVEN CLOISONS + PRECISION PEN DETAILS
// ============================================================================

function renderAllCloisons() {
  // Sort queue by layer to preserve exact painter's order
  cloisonQueue.sort((a, b) => a.layer - b.layer);

  // Group into contiguous layer bands so we can batch by color within each band for speed
  // Band 0: Background & Counter (0..9)
  // Band 1: Napkin Dispenser (10..19)
  // Band 2: Ketchup Bottle (20..29)
  // Band 3: Mustard Bottle (30..39)
  // Band 4: Cola Glass (40..49)
  const bands = [
    [0, 3], [4, 5], [6, 9],
    [10, 12], [13, 14], [15, 19],
    [20, 21], [22, 24], [25, 29],
    [30, 31], [32, 34], [35, 39],
    [40, 42], [43, 43], [44, 45], [46, 49]
  ];

  brush.noField();
  brush.noStroke();
  brush.noHatch();

  // PASS 1: Flat, Saturated Watercolor Fills (Wash + Watercolor Fill batched by color per band)
  for (let b of bands) {
    let items = cloisonQueue.filter(it => it.layer >= b[0] && it.layer <= b[1]);
    if (items.length === 0) continue;

    // Group by color within this depth band
    let byColor = {};
    for (let it of items) {
      if (!byColor[it.color]) byColor[it.color] = [];
      byColor[it.color].push(it);
    }

    for (let col in byColor) {
      let group = byColor[col];
      // First: Opaque saturated wash pass so colors are flat and enamel-rich
      brush.noFill();
      brush.wash(col, 210);
      for (let it of group) {
        drawPolyShape(it.pts, it.curvature);
      }
      brush.noWash();

      // Second: Watercolor texture & edge ring pass on larger cells
      brush.fill(col, 115);
      brush.fillBleed(0.025, "in");
      brush.fillTexture(0.42, 0.32);
      for (let it of group) {
        if (it.useWatercolor) {
          drawPolyShape(it.pts, it.curvature);
        }
      }
      brush.noFill();
    }
  }

  // PASS 2: Pont-Aven Heavy Dark-Blue-Black Cloison Outlines
  brush.noFill();
  brush.noWash();
  brush.wiggle(0.45);

  for (let it of cloisonQueue) {
    if (it.outlineWeight <= 0) continue;
    if (it.outlineWeight >= 1.0) {
      brush.set("cloison_heavy", PAL.cloisonOuter, it.outlineWeight * 0.95);
    } else {
      brush.set("cloison", PAL.cloisonInner, it.outlineWeight * 1.05);
    }
    drawPolyShape(it.pts, it.curvature);
  }

  // Reinforce major exterior object silhouettes with bold Pont-Aven cloison contours
  drawMajorSilhouetteCloisons();
  brush.noField();
}

