function renderCondensationBeads() {
  const cx = 925;
  brush.noField();
  brush.noFill();
  brush.noWash();

  // 1. Vertical Drip Tracks (where a heavy condensation drop slid down the glass)
  const dripTracks = [
    { a: 118, yStart: 395, yEnd: 585, rEnd: 7.5 },
    { a: 78,  yStart: 440, yEnd: 690, rEnd: 8.2 },
    { a: 52,  yStart: 380, yEnd: 545, rEnd: 6.8 },
    { a: 144, yStart: 510, yEnd: 745, rEnd: 7.0 }
  ];

  for (let dt of dripTracks) {
    let steps = 12;
    let leftTrack = [], rightTrack = [];
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = lerp(dt.yStart, dt.yEnd, t);
      let rx = getColaRadius(y) - 2;
      let ry = getColaRy(y);
      let wobble = sin(t * 360 * 1.5 + dt.a) * 1.6;
      let x = cx + rx * cos(dt.a) + wobble;
      let ySurf = y + ry * sin(dt.a);
      leftTrack.push([x - 2.2, ySurf]);
      rightTrack.push([x + 2.2, ySurf]);
    }
    brush.set("finepen", PAL.cloisonOuter, 0.75);
    brush.spline(leftTrack, 0.3);
    brush.set("finepen", PAL.chromeWhite, 0.75);
    brush.spline(rightTrack, 0.3);
  }

  // Generate deterministic list of droplets avoiding drip track interiors
  let drops = [];

  // Add the 4 heavy pendant drops at the bottom of the drip tracks
  for (let dt of dripTracks) {
    let rx = getColaRadius(dt.yEnd) - 2;
    let ry = getColaRy(dt.yEnd);
    let x = cx + rx * cos(dt.a);
    let y = dt.yEnd + ry * sin(dt.a);
    drops.push({ x, y, r: dt.rEnd, a: dt.a, isPendant: true });
  }

  // Add 48 Large Hero Teardrop Beads
  randomSeed(303);
  for (let i = 0; i < 48; i++) {
    let y = random(345, 815);
    let a = random(12, 168);
    let rx = getColaRadius(y) - 3;
    let ry = getColaRy(y);
    let x = cx + rx * cos(a);
    let ySurf = y + ry * sin(a);
    let r = random(4.5, 8.2);
    // Avoid overlapping existing large drops
    let ok = true;
    for (let d of drops) {
      if (hypot(x - d.x, ySurf - d.y) < (r + d.r + 3.5)) {
        ok = false;
        break;
      }
    }
    if (ok) drops.push({ x, y: ySurf, r, a, isPendant: false });
  }

  // Add 135 Medium Condensation Beads
  for (let i = 0; i < 135; i++) {
    let y = random(325, 842);
    let a = random(8, 172);
    let rx = getColaRadius(y) - 2;
    let ry = getColaRy(y);
    let x = cx + rx * cos(a);
    let ySurf = y + ry * sin(a);
    let r = random(2.3, 4.3);
    let ok = true;
    for (let d of drops) {
      if (hypot(x - d.x, ySurf - d.y) < (r + d.r + 1.8)) {
        ok = false;
        break;
      }
    }
    if (ok) drops.push({ x, y: ySurf, r, a, isPendant: false });
  }

  // First: Fast batch wash for internal refraction inside the large hero drops
  brush.noStroke();
  brush.noFill();
  for (let d of drops) {
    if (d.r < 4.4) continue;
    let squash = Math.max(0.42, sin(d.a));
    let rx = d.r * squash;
    let ry = d.r * (d.isPendant ? 1.35 : 1.15);
    // Lower half of large drop refracts bright amber or ice cyan
    let refrCol = (d.a < 85) ? PAL.colaGold : (d.a > 125 ? PAL.iceWhite : PAL.colaAmber);
    brush.wash(refrCol, 225);
    drawPolyShape(ellipsePoly(d.x, d.y + ry * 0.15, rx * 0.82, ry * 0.72, 10), 0.1);
  }
  brush.noWash();

  // Second: Precision dark-blue-black pen contours, upper internal crescent shadow & cast shadow
  brush.set("finepen", PAL.cloisonOuter, 0.95);
  for (let d of drops) {
    let squash = Math.max(0.42, sin(d.a));
    let rx = d.r * squash;
    let ry = d.r * (d.isPendant ? 1.35 : 1.15);

    if (d.r >= 4.2) {
      // Teardrop cloison outline
      let pts = [
        [d.x, d.y - ry * 1.15],
        [d.x + rx * 0.92, d.y - ry * 0.2],
        [d.x + rx, d.y + ry * 0.35],
        [d.x + rx * 0.55, d.y + ry * 0.95],
        [d.x, d.y + ry * 1.05],
        [d.x - rx * 0.55, d.y + ry * 0.95],
        [d.x - rx, d.y + ry * 0.35],
        [d.x - rx * 0.92, d.y - ry * 0.2]
      ];
      drawPolyShape(pts, 0.25);

      // Upper internal dark crescent (refraction of dark cola at top of bead)
      brush.arc(d.x, d.y - ry * 0.1, rx * 0.75, 195, 345);
      // Tiny cast shadow crescent beneath bead
      brush.arc(d.x + 1, d.y + ry * 0.95, rx * 0.85, 20, 160);
    } else {
      // Medium bead dark upper crescent + contour
      brush.circle(d.x, d.y, d.r * 0.92, 0.08);
      brush.arc(d.x, d.y - 0.6, d.r * 0.65, 190, 350);
    }
  }

  // Third: Micro-mist stipple beads (220 tiny droplets across the sweating surface)
  brush.set("finepen", PAL.cloisonOuter, 0.7);
  let mistPts = [];
  for (let i = 0; i < 220; i++) {
    let y = random(315, 850);
    let a = random(6, 174);
    let rx = getColaRadius(y) - 2;
    let ry = getColaRy(y);
    let x = cx + rx * cos(a);
    let ySurf = y + ry * sin(a);
    let r = random(1.0, 2.0);
    mistPts.push({ x, y: ySurf, r });
    brush.arc(x, ySurf, r, 180, 360);
  }

  // Fourth: Razor-sharp bright white pen specular highlights & lower caustic crescents on all beads
  brush.set("finepen", "#ffffff", 1.05);
  for (let d of drops) {
    let squash = Math.max(0.45, sin(d.a));
    let rx = d.r * squash;
    let ry = d.r * (d.isPendant ? 1.35 : 1.15);

    // Upper-left pinpoint neon specular catchlight
    let hx = d.x - rx * 0.35;
    let hy = d.y - ry * 0.32;
    brush.line(hx - 1.2, hy, hx + 1.2, hy);
    brush.line(hx, hy - 1.2, hx, hy + 1.2);

    // Lower-right secondary refractive crescent
    if (d.r >= 3.2) {
      brush.arc(d.x + rx * 0.08, d.y + ry * 0.15, rx * 0.78, 15, 145);
    } else {
      brush.line(d.x - 0.8, d.y + d.r * 0.7, d.x + 1.2, d.y + d.r * 0.5);
    }
  }

  // White pinpoint catchlights on micro-mist beads
  brush.set("finepen", "#ffffff", 0.75);
  for (let m of mistPts) {
    brush.line(m.x - 0.7, m.y + m.r * 0.6, m.x + 0.8, m.y + m.r * 0.5);
  }
}

