function draw() {
  translate(-width / 2, -height / 2);
  background("#d6eaf5");

  cloisonQueue = [];

  // 1. Construct all hyperreal geometric & reflection cloisons
  buildBackgroundAndCounter();
  buildNapkinDispenser();
  buildKetchupBottle();
  buildMustardBottle();
  buildColaGlass();

  // 2. Render flat, saturated watercolor fills and heavy dark-blue-black Pont-Aven cloisons
  renderAllCloisons();

  // 3. Render precise pen details ONLY on condensation beads and logo highlights
  renderCondensationBeads();
  renderLogoHighlights();

  noLoop();
}

