};

async function setup() {
  createCanvas(1200, 1200, WEBGL);
  angleMode(DEGREES);
  randomSeed(4217);
  noiseSeed(4217);

  // Register custom brushes before scaling
  brush.add("pbn_marker", {
    type: "marker",
    weight: 1.45,
    scatter: 0.04,
    opacity: 92,
    spacing: 0.35,
    pressure: [0.85, 1.0, 0.85],
    markerTip: true
  });

  brush.add("pbn_border", {
    type: "default",
    weight: 0.42,
    scatter: 0.02,
    sharpness: 0.82,
    grain: 0.18,
    opacity: 195,
    spacing: 0.25,
    pressure: [0.95, 1.0, 0.95],
    noise: 0.25
  });

  brush.add("pbn_print", {
    type: "default",
