  brush.scaleBrushes(3);
}

function draw() {
  translate(-width / 2, -height / 2);

  // Warm vintage paint-by-numbers cardboard ground
  background("#f6f0e3");

  // 1. Build the 600x600 high-precision optical scene buffer
  const GW = 600;
  const GH = 600;
  const scene = buildHyperrealPieScene(GW, GH);

  // 2. Generate contour-aligned Voronoi Paint-by-Numbers facets
  const cells = buildVoronoiFacets(scene, GW, GH);

  // 3. Subtle raw cardboard fiber texture (visible in unpainted cells & borders)
  brush.noFill();
  brush.noWash();
  brush.noHatch();
  brush.set("2H", "#e8dfd0", 0.22);
  for (let i = 0; i < 95; i++) {
    const y = random(20, 1180);
    const x1 = random(15, 900);
    const x2 = min(1185, x1 + random(80, 260));
    brush.line(x1, y, x2, y + random(-2, 2));
  }

  // 4. Group painted cells by palette index (0..35) for optimal wash batching
  const batches = Array.from({ length: PALETTE.length }, () => []);
  const unpaintedCells = [];
  const partialCells = [];

  for (let i = 0; i < cells.length; i++) {
    const c = cells[i];
    if (c.verts.length < 3) continue;
    if (c.unpainted) {
      unpaintedCells.push(c);
    } else if (c.partial) {
      partialCells.push(c);
    } else {
      batches[c.palIdx].push(c);
    }
  }

  // 5. Render flat colour facet washes + thin pale borders batched by palette colour
  for (let pIdx = 0; pIdx < PALETTE.length; pIdx++) {
    const list = batches[pIdx];
    if (list.length === 0) continue;
    const pal = PALETTE[pIdx];

    brush.noFill();
    brush.noHatch();
    brush.wash(pal.hex, 244);
    brush.set("pbn_border", pal.border, 0.34);

    for (let i = 0; i < list.length; i++) {
      const c = list[i];
      const v = c.verts;
      brush.beginShape(0.14);
      for (let k = 0; k < v.length; k++) {
        brush.vertex(v[k][0], v[k][1]);
      }
      brush.endShape(true);
    }
  }
  brush.noWash();

  // 6. Render saturated marker fill strokes inside each painted facet
  for (let pIdx = 0; pIdx < PALETTE.length; pIdx++) {
    const list = batches[pIdx];
    if (list.length === 0) continue;
    const pal = PALETTE[pIdx];

    brush.set("pbn_marker", pal.marker, 0.58);
    for (let i = 0; i < list.length; i++) {
      const c = list[i];
      drawCellMarkerStrokes(c, 2);
    }
  }

  // 7. Render partially finished cells near the unpainted edges
  for (let i = 0; i < partialCells.length; i++) {
    const c = partialCells[i];
    const pal = PALETTE[c.palIdx];
    brush.set("pbn_marker", pal.hex, 0.65);
    drawCellMarkerStrokes(c, 1);
  }

  // 8. Render faint printed outlines & tiny numbers in unpainted / partial edge cells
  const guideCells = unpaintedCells.concat(partialCells);
  brush.noWash();
  brush.noFill();
  brush.set("pbn_print", "#96adc2", 0.38);

  for (let i = 0; i < guideCells.length; i++) {
    const c = guideCells[i];
    const v = c.verts;
    brush.beginShape(0.12);
    for (let k = 0; k < v.length; k++) {
      brush.vertex(v[k][0], v[k][1]);
    }
    brush.endShape(true);
  }

  // Crisp printed numbers inside unpainted cells
  brush.set("pbn_print", "#869fb6", 0.32);
  for (let i = 0; i < guideCells.length; i++) {
    const c = guideCells[i];
    if (c.radius >= 8.5) {
      const numStr = String(PALETTE[c.palIdx].id);
      const digitScale = constrain(c.radius * 0.48, 5.2, 9.5);
      drawPrintedNumber(numStr, c.cx, c.cy, digitScale);
    }
  }

  noLoop();
}

// ============================================================================
// MARKER FILL & PRINTED NUMBER HELPERS
// ============================================================================

function drawCellMarkerStrokes(cell, numChords) {
  const cx = cell.cx;
  const cy = cell.cy;
  const ang = cell.flowAngle;
  const dx = Math.cos(ang);
  const dy = Math.sin(ang);
  const nx = -dy;
  const ny = dx;

  const offsets = numChords === 1 ? [-cell.radius * 0.18] : [-cell.radius * 0.24, cell.radius * 0.24];

  for (let m = 0; m < offsets.length; m++) {
    const off = offsets[m];
    const ox = cx + nx * off;
    const oy = cy + ny * off;
    const span = clipRayToPolygon(ox, oy, dx, dy, cell.verts);
    if (span) {
      const tMin = span[0] + 1.8;
      const tMax = span[1] - 1.8;
      if (tMax - tMin > 3.2) {
        brush.line(
          ox + dx * tMin,
          oy + dy * tMin,
          ox + dx * tMax,
          oy + dy * tMax
        );
      }
    }
  }
}

function clipRayToPolygon(ox, oy, dx, dy, verts) {
  let tEnter = -1e9;
  let tExit = 1e9;
  const n = verts.length;
  for (let i = 0; i < n; i++) {
    const p1 = verts[i];
    const p2 = verts[(i + 1) % n];
    const ex = p2[0] - p1[0];
    const ey = p2[1] - p1[1];
    // Inward normal for CCW polygon
    const inx = -ey;
    const iny = ex;
    const num = (p1[0] - ox) * inx + (p1[1] - oy) * iny;
    const den = dx * inx + dy * iny;
    if (Math.abs(den) < 1e-6) {
      if (num > 0) return null;
    } else {
      const t = num / den;
      if (den > 0) {
        if (t > tEnter) tEnter = t;
      } else {
        if (t < tExit) tExit = t;
      }
    }
  }
  return tExit > tEnter ? [tEnter, tExit] : null;
}

function drawPrintedNumber(str, cx, cy, h) {
  const w = h * 0.64;
  const gap = h * 0.22;
  const totalW = str.length * w + (str.length - 1) * gap;
  let startX = cx - totalW * 0.5 + w * 0.5;

  for (let c = 0; c < str.length; c++) {
    const ch = str[c];
    const strokes = DIGIT_STROKES[ch];
    if (strokes) {
      for (let s = 0; s < strokes.length; s++) {
        const pts = strokes[s];
        for (let k = 0; k < pts.length - 1; k++) {
          const x1 = startX + pts[k][0] * w;
          const y1 = cy + pts[k][1] * h;
          const x2 = startX + pts[k + 1][0] * w;
          const y2 = cy + pts[k + 1][1] * h;
          brush.line(x1, y1, x2, y2);
        }
      }
    }
    startX += w + gap;
  }
}

// ============================================================================
// HYPERREAL 3D OPTICAL CHERRY PIE SCENE GENERATOR
// ============================================================================

function buildHyperrealPieScene(GW, GH) {
  const N = GW * GH;
  const palGrid = new Uint8Array(N);
  const famGrid = new Uint8Array(N); // 0: PASTEL, 1: CHERRY, 2: CRUST, 3: GLINT
  const flowGrid = new Float32Array(N);

  // Wedge anchors on the porcelain plate
  const T = { x: 295, y: 742 };
  const BL = { x: 562, y: 388 };
  const BR = { x: 912, y: 638 };

  // Helper to evaluate curved back arc of the pie slice for v in [0, 1]
  function evalArc(v) {
    const lx = BL.x + (BR.x - BL.x) * v;
    const ly = BL.y + (BR.y - BL.y) * v;
    const bulge = 4.0 * v * (1.0 - v);
    return {
      x: lx + 56 * bulge,
      y: ly - 38 * bulge
    };
  }

  // Helper to evaluate 3D height of the pie top surface at (u, v)
  function evalPieHeight(u, v) {
    const uClamped = Math.max(0, Math.min(1.1, u));
    const vClamped = Math.max(0, Math.min(1.0, v));
    const dome = 34 * Math.sin(Math.PI * Math.pow(uClamped, 0.85)) * (0.4 + 0.6 * Math.sin(Math.PI * vClamped));
    const baseSlope = 86 + 52 * Math.pow(uClamped, 0.72);
    return baseSlope + dome;
  }

  function evalBasePos(u, v) {
    const arc = evalArc(v);
    return {
      x: (1.0 - u) * T.x + u * arc.x,
      y: (1.0 - u) * T.y + u * arc.y
    };
  }

  function evalTopPos(u, v) {
    const b = evalBasePos(u, v);
    const h = evalPieHeight(u, v);
    return { x: b.x, y: b.y - h, h: h };
  }

  // Build explicit 3D cherries:
  // 1) Packed inside the front cut wall
  // 2) Peeking through the top lattice windows
  // 3) Spilled into the glossy syrup puddle on the plate
  const cherries = [];

  // Cut-wall cherries (two staggered tiers along u = 0.07 .. 0.90)
  const cutCherrySpecs = [
    { u: 0.08, w: 0.36, r: 33, z: 12, dimple: -0.5 },
    { u: 0.16, w: 0.62, r: 35, z: 8, dimple: -0.8 },
    { u: 0.22, w: 0.28, r: 37, z: 16, dimple: -0.3 },
    { u: 0.30, w: 0.58, r: 38, z: 14, dimple: -0.9 },
    { u: 0.36, w: 0.25, r: 36, z: 9, dimple: -0.4 },
    { u: 0.43, w: 0.64, r: 39, z: 18, dimple: -0.7 },
    { u: 0.49, w: 0.32, r: 41, z: 22, dimple: -0.6 },
    { u: 0.56, w: 0.68, r: 38, z: 11, dimple: -1.0 },
    { u: 0.61, w: 0.30, r: 39, z: 17, dimple: -0.2 },
    { u: 0.68, w: 0.58, r: 40, z: 20, dimple: -0.7 },
    { u: 0.74, w: 0.26, r: 37, z: 13, dimple: -0.5 },
    { u: 0.80, w: 0.62, r: 38, z: 15, dimple: -0.9 },
    { u: 0.86, w: 0.34, r: 35, z: 10, dimple: -0.4 },
    // Deeper interior cherries peeking between front cherries
    { u: 0.13, w: 0.45, r: 34, z: 2, dimple: -0.6 },
    { u: 0.27, w: 0.42, r: 36, z: 3, dimple: -0.6 },
    { u: 0.40, w: 0.46, r: 37, z: 4, dimple: -0.5 },
    { u: 0.53, w: 0.48, r: 38, z: 3, dimple: -0.7 },
    { u: 0.65, w: 0.46, r: 37, z: 4, dimple: -0.6 },
    { u: 0.77, w: 0.45, r: 36, z: 3, dimple: -0.5 }
  ];

  for (let i = 0; i < cutCherrySpecs.length; i++) {
    const s = cutCherrySpecs[i];
    const b = evalBasePos(s.u, 1.0);
    const t = evalTopPos(s.u, 1.0);
    const cx = b.x + (t.x - b.x) * s.w;
    const cy = b.y + (t.y - b.y) * s.w;
    cherries.push({
      x: cx,
      y: cy,
      r: s.r,
      rx: s.r * 1.05,
      ry: s.r * 0.94,
      z: s.z,
      dimple: s.dimple,
      layer: "CUT"
    });
  }

  // Spilled foreground cherries sitting in the syrup puddle on the plate
  const spilledSpecs = [
    { x: 356, y: 765, r: 35, z: 30, dimple: -0.7 },
    { x: 462, y: 744, r: 39, z: 32, dimple: -0.4 },
    { x: 522, y: 762, r: 36, z: 34, dimple: -0.9 },
    { x: 658, y: 718, r: 38, z: 31, dimple: -0.5 },
    { x: 748, y: 694, r: 34, z: 29, dimple: -0.8 }
  ];
  for (let i = 0; i < spilledSpecs.length; i++) {
    const s = spilledSpecs[i];
    cherries.push({
      x: s.x,
      y: s.y,
      r: s.r,
      rx: s.r * 1.06,
      ry: s.r * 0.92,
      z: s.z,
      dimple: s.dimple,
      layer: "SPILLED"
    });
  }

  // Top dome cherries visible inside the lattice windows
  const topCherrySpecs = [
    { u: 0.25, v: 0.45, r: 38 },
    { u: 0.38, v: 0.30, r: 40 },
    { u: 0.42, v: 0.68, r: 41 },
    { u: 0.54, v: 0.22, r: 39 },
    { u: 0.56, v: 0.52, r: 42 },
    { u: 0.58, v: 0.80, r: 39 },
    { u: 0.70, v: 0.35, r: 41 },
    { u: 0.72, v: 0.66, r: 41 },
    { u: 0.80, v: 0.48, r: 38 }
  ];
  for (let i = 0; i < topCherrySpecs.length; i++) {
    const s = topCherrySpecs[i];
    const tp = evalTopPos(s.u, s.v);
    cherries.push({
      x: tp.x,
      y: tp.y + 6,
      r: s.r,
      rx: s.r * 1.08,
      ry: s.r * 0.88,
      z: 10,
      dimple: -0.6,
      layer: "TOP_WINDOW"
    });
  }

  // Syrup puddle metaball lobes on the plate
  const syrupLobes = [
    { x: 292, y: 746, rx: 46, ry: 34 },
    { x: 342, y: 762, rx: 64, ry: 44 },
    { x: 405, y: 752, rx: 58, ry: 40 },
    { x: 468, y: 754, rx: 72, ry: 48 },
    { x: 528, y: 766, rx: 64, ry: 45 },
    { x: 588, y: 734, rx: 58, ry: 40 },
    { x: 655, y: 722, rx: 70, ry: 46 },
    { x: 725, y: 698, rx: 65, ry: 43 },
    { x: 792, y: 678, rx: 56, ry: 38 },
    { x: 848, y: 658, rx: 46, ry: 32 },
    // Detached glossy syrup droplets on the plate
    { x: 232, y: 778, rx: 21, ry: 15 },
    { x: 388, y: 822, rx: 24, ry: 17 },
    { x: 598, y: 812, rx: 27, ry: 19 },
    { x: 792, y: 742, rx: 22, ry: 16 }
  ];

  // Pastry crumbs on the plate
  const crumbs = [
    { x: 256, y: 716, r: 9 },
    { x: 312, y: 816, r: 11 },
    { x: 334, y: 828, r: 7.5 },
    { x: 448, y: 826, r: 9.5 },
    { x: 676, y: 778, r: 11.5 },
    { x: 702, y: 786, r: 8 },
    { x: 856, y: 712, r: 10.5 },
    { x: 938, y: 668, r: 9 }
  ];

  // Helper to invert Top(u, v) for any canvas coordinate (x, y)
  function invertTopUV(x, y) {
    let u = 0.5;
    let v = 0.5;
    for (let it = 0; it < 4; it++) {
      const p0 = evalTopPos(u, v);
      const pu = evalTopPos(u + 0.005, v);
      const pv = evalTopPos(u, v + 0.005);
      const dux = (pu.x - p0.x) / 0.005;
      const duy = (pu.y - p0.y) / 0.005;
      const dvx = (pv.x - p0.x) / 0.005;
      const dvy = (pv.y - p0.y) / 0.005;
      const det = dux * dvy - duy * dvx;
      if (Math.abs(det) < 1e-5) break;
      const ex = x - p0.x;
      const ey = y - p0.y;
      u += (ex * dvy - ey * dvx) / det;
      v += (dux * ey - duy * ex) / det;
    }
    return { u, v };
  }

  // Helper to invert Front Cut Wall (u, w) where v = 1
  function invertCutWallUW(x, y) {
    const dx = BR.x - T.x;
    const dy = BR.y - T.y;
    const lenSq = dx * dx + dy * dy;
    let u = ((x - T.x) * dx + (y - T.y) * dy) / lenSq;
    u = Math.max(-0.05, Math.min(1.08, u));
    const b = evalBasePos(u, 1.0);
    const t = evalTopPos(u, 1.0);
    const h = b.y - t.y;
    const w = h > 1 ? (b.y - y) / h : -1;
    return { u, w, baseY: b.y, topY: t.y };
  }

  // Evaluate scene pixel by pixel on the 600x600 grid
  for (let gy = 0; gy < GH; gy++) {
    const y = (gy + 0.5) * 2.0;
    for (let gx = 0; gx < GW; gx++) {
      const x = (gx + 0.5) * 2.0;
      const idx = gy * GW + gx;

      // ----------------------------------------------------------------------
      // 1. PASTEL GINGHAM TABLECLOTH & PLATE
      // ----------------------------------------------------------------------
      let r = 250, g = 244, b = 232;
      let fam = "PASTEL";
      let flow = 0.38;

      // Perspective gingham coordinates
      const py = (y - 600) / 1200;
      const persp = 1.0 / (1.0 - 0.24 * py);
      const rxG = (x - 600) * persp;
      const ryG = (y - 600) * persp * 1.32;
      const cosG = 0.927, sinG = 0.374; // ~22 deg rotation
      const gu = rxG * cosG - ryG * sinG + 1600;
      const gv = rxG * sinG + ryG * cosG + 1600;

      const checkP = 92.0;
      const uMod = (gu % (2 * checkP)) / checkP;
      const vMod = (gv % (2 * checkP)) / checkP;

      // Stripe types: 0 = Cream, 1 = Pastel Blue, 2 = Pastel Pink
      const uType = (uMod > 0.04 && uMod < 0.48) ? 1 : ((uMod > 1.04 && uMod < 1.48) ? 2 : 0);
      const vType = (vMod > 0.04 && vMod < 0.48) ? 1 : ((vMod > 1.04 && vMod < 1.48) ? 2 : 0);

      // Subtle twill weave rib
      const twill = Math.sin((gu + gv) * 0.45) * 4;

      if (uType === 0 && vType === 0) {
        r = 252 + twill; g = 247 + twill; b = 236 + twill;
        flow = 0.38;
      } else if ((uType === 1 && vType === 0) || (uType === 0 && vType === 1)) {
        r = 206 + twill; g = 228 + twill; b = 246 + twill;
        flow = uType === 1 ? 0.38 : -1.19;
      } else if (uType === 1 && vType === 1) {
        r = 148 + twill; g = 184 + twill; b = 222 + twill;
        flow = 1.15;
      } else if ((uType === 2 && vType === 0) || (uType === 0 && vType === 2)) {
        r = 248 + twill; g = 212 + twill; b = 223 + twill;
        flow = uType === 2 ? 0.38 : -1.19;
      } else if (uType === 2 && vType === 2) {
        r = 238 + twill; g = 172 + twill; b = 192 + twill;
        flow = 1.15;
      } else {
        // Blue + Pink intersection = Kitsch Pastel Lilac
        r = 208 + twill; g = 198 + twill; b = 228 + twill;
        flow = 0.38;
      }

      // Plate Cast Shadow on Gingham
      const sdx = x - 664;
      const sdy = (y - 714) / 0.71;
      const sDist = Math.sqrt(sdx * sdx + sdy * sdy);
      if (sDist < 502) {
        const sh = Math.max(0, Math.min(1, (502 - sDist) / 48));
        r = r * (1 - 0.25 * sh) + 165 * (0.25 * sh);
        g = g * (1 - 0.26 * sh) + 152 * (0.26 * sh);
        b = b * (1 - 0.16 * sh) + 202 * (0.16 * sh);
      }

      // Vintage Porcelain Plate Geometry
      const pdx = x - 606;
      const pdy = y - 668;
      const pCos = 0.996, pSin = 0.087; // -5 deg tilt
      const px = pdx * pCos + pdy * pSin;
      const pyPlate = (-pdx * pSin + pdy * pCos) / 0.715;
      const pRad = Math.sqrt(px * px + pyPlate * pyPlate);
      const pTheta = Math.atan2(pyPlate, px);
      const scallop = 488 + 6.5 * Math.cos(18 * pTheta);

      if (pRad <= scallop) {
        const rNorm = pRad / scallop;
        flow = pTheta + Math.PI * 0.5;

        if (rNorm > 0.74) {
          // Sloped Porcelain Rim
          const rimT = (rNorm - 0.74) / 0.26;
          // Rim normal facing inward towards center
          const rimLight = Math.cos(pTheta - 0.68); // +1 on lower-right slope facing upper-left light
          if (rNorm > 0.86 && rNorm < 0.955) {
            // Vintage Pastel Blush Pink Rim Band
            r = 248 + 6 * rimLight;
            g = 212 + 10 * rimLight;
            b = 222 + 10 * rimLight;
          } else if (rNorm >= 0.83 && rNorm <= 0.86) {
            // Pastel Mint Cream Fillet
            r = 212 + 12 * rimLight;
            g = 239 + 8 * rimLight;
            b = 229 + 8 * rimLight;
          } else {
            // Glazed Porcelain Rim Slope
            if (rimLight > 0.58 && rimT < 0.5) {
              // Glossy Cool-White Window Glint on lower-right inner rim slope
              r = 242; g = 250; b = 255;
              fam = "GLINT";
            } else if (rimLight < -0.25) {
              // Cool Pastel Sky-Blue / Lilac shade on upper-left rim slope
              r = 212; g = 230; b = 247;
            } else {
              r = 250; g = 244; b = 232;
            }
          }
        } else {
          // Flat Porcelain Well
          const wellGrad = (px * 0.6 + pyPlate * 0.8) / 360;
          r = 251 - wellGrad * 6;
          g = 245 - wellGrad * 7;
          b = 233 - wellGrad * 9;

          // Cast shadow of the pie slice on the plate well
          const cutCheck = invertCutWallUW(x - 44, y - 34);
          if (cutCheck.u > -0.04 && cutCheck.u < 1.04 && y > cutCheck.baseY - 12 && y < cutCheck.baseY + 86) {
            const dySh = y - cutCheck.baseY;
            const uFade = Math.sin(Math.PI * Math.max(0, Math.min(1, (cutCheck.u + 0.04) / 1.08)));
            const shStrength = Math.max(0, 1.0 - dySh / (76 * uFade + 14));
            if (shStrength > 0.45) {
              // Deep Pastel Mauve-Lilac shadow core
              r = 176; g = 164; b = 205;
            } else if (shStrength > 0.12) {
              // Soft Pastel Lilac penumbra
              r = 212; g = 205; b = 230;
            }
            flow = -0.18;
          }
        }
      }

      // ----------------------------------------------------------------------
      // 2. GLOSSY SYRUP PUDDLE & CAUSTIC GLOW ON PLATE
      // ----------------------------------------------------------------------
      let syrupField = 0;
      let sGradX = 0;
      let sGradY = 0;
      for (let i = 0; i < syrupLobes.length; i++) {
        const lb = syrupLobes[i];
        const ldx = (x - lb.x) / lb.rx;
        const ldy = (y - lb.y) / lb.ry;
        const d2 = ldx * ldx + ldy * ldy;
        if (d2 < 3.2) {
          const w = Math.exp(-d2 * 1.45);
          syrupField += w;
          sGradX += -2.9 * ldx * w / lb.rx;
          sGradY += -2.9 * ldy * w / lb.ry;
        }
      }

      if (syrupField > 0.34 && syrupField <= 0.48) {
        // Ruby Caustic Glow on the porcelain plate right outside the syrup meniscus
        if (sGradX + sGradY < 0) {
          r = 250; g = 195; b = 208;
          fam = "PASTEL";
        }
      } else if (syrupField > 0.48) {
        fam = "CHERRY";
        const depth = syrupField - 0.48;
        const gMag = Math.sqrt(sGradX * sGradX + sGradY * sGradY) + 1e-5;
        const nx = -sGradX / gMag;
        const ny = -sGradY / gMag;
        flow = Math.atan2( nx, -ny );

        // Specular reflection near curved meniscus rim facing upper-left window
        const lightDot = nx * (-0.58) + ny * (-0.81);
        if (depth > 0.06 && depth < 0.34 && lightDot > 0.66) {
          r = 248; g = 252; b = 255;
          fam = "GLINT";
        } else if (depth < 0.16) {
          // Thin translucent Scarlet Lake outer syrup edge
          r = 236; g = 51; b = 63;
        } else if (depth < 0.36) {
          // Bright Scarlet Lake syrup mid-zone
          r = 192; g = 25; b = 39;
        } else if (depth < 0.62) {
          // Deep Scarlet / Warm Oxblood
          r = 132; g = 16; b = 28;
        } else {
          // Thick Oxblood syrup core
          r = 68; g = 7; b = 13;
        }
      }

      // ----------------------------------------------------------------------
      // 3. PASTRY CRUMBS ON THE PLATE
      // ----------------------------------------------------------------------
      for (let i = 0; i < crumbs.length; i++) {
        const cr = crumbs[i];
        const cdx = x - cr.x;
        const cdy = (y - cr.y) / 0.78;
        const cd = Math.sqrt(cdx * cdx + cdy * cdy) + 1.8 * Math.sin(cdx * 0.4 + cdy * 0.5);
        if (cd < cr.r) {
          fam = "CRUST";
          flow = 0.2;
          if (cdx + cdy < -cr.r * 0.2) {
            r = 247; g = 194; b = 104; // Highlighted Butterscotch
          } else if (cdx + cdy < cr.r * 0.3) {
            r = 226; g = 150; b = 54;  // Golden Butterscotch
          } else {
            r = 164; g = 85; b = 37;   // Toasted Burnt Umber edge
          }
        }
      }

      // ----------------------------------------------------------------------
      // 4. PIE CUT WALL (BOTTOM CRUST, SYRUP MATRIX & 3D CHERRIES)
      // ----------------------------------------------------------------------
      const cut = invertCutWallUW(x, y);
      const topUV = invertTopUV(x, y);

      // Check if inside the front cut wall quad
      const inCutWall = (
        cut.u >= 0.0 &&
        cut.u <= 0.99 &&
        cut.w >= -0.02 &&
        cut.w <= 1.02 &&
        topUV.v >= 0.88
      );

      if (inCutWall) {
        const crustWave = 0.13 + 0.025 * Math.sin(cut.u * 26.0);
        if (cut.w <= crustWave && syrupField < 0.72) {
          // Flaky Bottom Pastry Crust along the cut edge
          fam = "CRUST";
          flow = -0.17;
          const layerNoise = Math.sin(cut.u * 45 + cut.w * 30);
          if (cut.w > crustWave * 0.68) {
            // Syrup-soaked Amber / Burnt Umber upper contact
            r = 138; g = 65; b = 29;
          } else if (layerNoise > 0.2) {
            r = 226; g = 150; b = 54;
          } else {
            r = 184; g = 104; b = 23;
          }
        } else {
          // Recessed Jammy Cherry Syrup Matrix inside the cut slice
          fam = "CHERRY";
          flow = -0.17;
          const meniscusGlint = Math.sin(cut.u * 38.0 + cut.w * 19.0);
          if (meniscusGlint > 0.94 && cut.w > 0.25 && cut.w < 0.82) {
            r = 238; g = 247; b = 255;
            fam = "GLINT";
          } else if (cut.w < 0.22 || cut.w > 0.85) {
            r = 38; g = 2; b = 5; // Pitch Oxblood crevice
          } else if (meniscusGlint > 0.55) {
            r = 110; g = 12; b = 23; // Warm Oxblood
          } else {
            r = 61; g = 5; b = 10; // Dark Oxblood
          }
        }
      }

      // Evaluate 3D Cherries in Cut Wall & Spilled Foreground (Z-buffered)
      let bestCherryZ = -1e9;
      let hitCherry = null;
      for (let i = 0; i < cherries.length; i++) {
        const ch = cherries[i];
        if (ch.layer === "TOP_WINDOW") continue;
        const dx = (x - ch.x) / ch.rx;
        const dy = (y - ch.y) / ch.ry;
        const d2 = dx * dx + dy * dy;
        if (d2 <= 1.0) {
          const nz = Math.sqrt(1.0 - d2);
          const zVal = ch.z + nz * ch.r;
          if (zVal > bestCherryZ) {
            bestCherryZ = zVal;
            hitCherry = { ch, dx, dy, d2, nz };
          }
        }
      }

      if (hitCherry) {
        const shaded = shade3DCherry(hitCherry.dx, hitCherry.dy, hitCherry.nz, hitCherry.ch);
        r = shaded.r;
        g = shaded.g;
        b = shaded.b;
        fam = shaded.fam;
        flow = shaded.flow;
      }

      // ----------------------------------------------------------------------
      // 5. TOP DOME: WOVEN LATTICE CRUST, WINDOWS & FLUTED BACK RIM
      // ----------------------------------------------------------------------
      const u = topUV.u;
      const v = topUV.v;

      // Soft scalloped outer bound of the fluted crust rim
      const crimpWave = Math.sin(v * 8.5 * Math.PI);
      const uMaxRim = 1.015 + 0.022 * crimpWave;
      const vMinTop = -0.025 * Math.sin(Math.PI * Math.max(0, Math.min(1, u)));
      const vMaxTop = 1.02;

      if (u >= -0.02 && u <= uMaxRim && v >= vMinTop && v <= vMaxTop) {
        if (u >= 0.855) {
          // ------------------------------------------------------------------
          // TALL FLUTED / CRIMPED BACK PASTRY RIM
          // ------------------------------------------------------------------
          fam = "CRUST";
          const rimU = (u - 0.855) / (uMaxRim - 0.855);
          const flutePhase = v * 8.5 * Math.PI;
          const fluteN = Math.cos(flutePhase); // Azimuthal slope of pinch
          const ridgeCrest = Math.sin(flutePhase);
          flow = -0.62 + 0.35 * fluteN;

          // Specular egg-wash glint on the pinched flute crest
          if (ridgeCrest > 0.72 && rimU > 0.22 && rimU < 0.62 && fluteN > -0.2) {
            r = 250; g = 246; b = 225;
            if (ridgeCrest > 0.88 && rimU > 0.32 && rimU < 0.50) {
              r = 255; g = 255; b = 255;
              fam = "GLINT";
            }
          } else if (rimU > 0.76 && ridgeCrest > 0.35) {
            // Caramelized Burnt Umber outer pinched tips
            r = 58; g = 21; b = 7;
          } else if (fluteN > 0.28) {
            // Sunlit Butterscotch left-facing flute slope
            if (rimU < 0.55) {
              r = 247; g = 194; b = 104;
            } else {
              r = 240; g = 172; b = 76;
            }
          } else if (fluteN > -0.25) {
            // Golden Butterscotch midtone
            r = 207; g = 127; b = 36;
          } else if (fluteN > -0.68) {
            // Warm Burnt Umber shadowed flute hollow
            r = 138; g = 65; b = 29;
          } else {
            // Deep Burnt Umber crevice
            r = 82; g = 32; b = 13;
          }
        } else {
          // ------------------------------------------------------------------
          // WOVEN TOP LATTICE CRUST & CHERRY WINDOWS
          // ------------------------------------------------------------------
          // Two sets of diagonal pastry strips in (u, v) space
          const rotA = 0.58; // ~33 deg
          const sA = (u * Math.cos(rotA) + (v - 0.5) * 0.72 * Math.sin(rotA)) * 4.6 + 2.2;
          const sB = (u * Math.cos(rotA) - (v - 0.5) * 0.72 * Math.sin(rotA)) * 4.6 + 2.2;

          const idxA = Math.floor(sA);
          const idxB = Math.floor(sB);
          const fA = sA - idxA - 0.5; // [-0.5, 0.5]
          const fB = sB - idxB - 0.5;

          const halfW = 0.285; // Strip width = 57% of pitch, window = 43%
          const onA = Math.abs(fA) < halfW;
          const onB = Math.abs(fB) < halfW;

          if (!onA && !onB) {
            // ----------------------------------------------------------------
            // DIAMOND LATTICE WINDOW: Recessed Cherries & Bubbling Syrup
            // ----------------------------------------------------------------
            fam = "CHERRY";
            flow = -0.35;

            // Distance from overhanging lattice strip edges for cast shadow
            const distA = Math.abs(fA) - halfW;
            const distB = Math.abs(fB) - halfW;
            const winEdgeDist = Math.min(distA, distB);

            // Check if a top-window 3D cherry is visible here
            let topHit = null;
            for (let i = 0; i < cherries.length; i++) {
              const ch = cherries[i];
              if (ch.layer !== "TOP_WINDOW") continue;
              const dx = (x - ch.x) / ch.rx;
              const dy = (y - ch.y) / ch.ry;
              const d2 = dx * dx + dy * dy;
              if (d2 <= 1.0) {
                topHit = { ch, dx, dy, nz: Math.sqrt(1.0 - d2) };
                break;
              }
            }

            if (winEdgeDist < 0.045) {
              // Deep Oxblood shadow under the lattice strip overhang
              r = 38; g = 2; b = 5;
            } else if (topHit) {
              const shaded = shade3DCherry(topHit.dx, topHit.dy, topHit.nz, topHit.ch);
              r = shaded.r;
              g = shaded.g;
              b = shaded.b;
              fam = shaded.fam;
              flow = shaded.flow;
            } else {
              // Bubbling Scarlet Lake & Oxblood syrup inside the window
              const bubble = Math.sin(x * 0.22 + y * 0.18) * Math.cos(x * 0.15 - y * 0.24);
              if (bubble > 0.78) {
                r = 255; g = 255; b = 255;
                fam = "GLINT";
              } else if (bubble > 0.25) {
                r = 216; g = 34; b = 48; // Bright Scarlet Lake
              } else if (bubble > -0.25) {
                r = 158; g = 19; b = 32; // Deep Scarlet Lake
              } else {
                r = 84; g = 8; b = 16;   // Rich Oxblood
              }
            }
          } else {
            // ----------------------------------------------------------------
            // WOVEN PASTRY STRIP (Over / Under Weave + Glossy Glaze)
            // ----------------------------------------------------------------
            fam = "CRUST";
            const aOverB = ((idxA + idxB) & 1) === 0;
            let activeA = onA;
            if (onA && onB) {
              activeA = aOverB;
            }

            const fCross = activeA ? (fA / halfW) : (fB / halfW); // [-1, 1] across strip width
            const fAlong = activeA ? fB : fA;                     // [-0.5, 0.5] toward crossing
            const isOverAtCrossing = (activeA && aOverB) || (!activeA && !aOverB);

            flow = activeA ? -0.78 : 0.12;

            // Shadow cast by the perpendicular over-strip onto the under-strip
            const underShadow = (!isOverAtCrossing && Math.abs(fAlong) < halfW + 0.09)
              ? Math.max(0, 1.0 - (Math.abs(fAlong) - halfW) / 0.09)
              : 0.0;

            // Cut pastry cross-section right at the front edge (v > 0.94)
            if (v > 0.945) {
              r = 207; g = 127; b = 36;
              if (Math.abs(fCross) > 0.75) {
                r = 138; g = 65; b = 29;
              }
            } else if (underShadow > 0.55) {
              // Deep Burnt Umber weave crevice shadow
              r = 51; g = 18; b = 6;
            } else if (underShadow > 0.15) {
              // Warm Burnt Umber under-weave shade
              r = 108; g = 46; b = 20;
            } else {
              // 3D arched profile of the lattice ribbon + baked blisters
              const archZ = Math.sqrt(Math.max(0, 1.0 - fCross * fCross));
              const blister = Math.sin(x * 0.14 + y * 0.11) * Math.cos(x * 0.09 - y * 0.16);
              const lightBias = activeA ? -fCross * 0.55 : fCross * 0.45;
              const tone = archZ * 0.78 + lightBias * 0.35 + (isOverAtCrossing ? 0.14 : -0.06) + blister * 0.12;

              if (Math.abs(fCross) > 0.84) {
                // Crisp caramelized Burnt Umber strip border
                r = 108; g = 46; b = 20;
              } else if (blister < -0.62 && Math.abs(fCross) < 0.6) {
                // Toasted Burnt Umber baked blister
                r = 138; g = 65; b = 29;
              } else if (archZ > 0.93 && isOverAtCrossing && Math.abs(fAlong) < 0.18 && blister > 0.1) {
                // Glossy Egg-Wash / Sugar Glint on top of the over-weave arch
                r = 255; g = 255; b = 255;
                fam = "GLINT";
              } else if (tone > 0.92) {
                // Cream Butterscotch highlight
                r = 251; g = 224; b = 148;
              } else if (tone > 0.76) {
                // Pale Golden Butterscotch
                r = 247; g = 194; b = 104;
              } else if (tone > 0.58) {
                // Warm Honey Butterscotch
                r = 240; g = 172; b = 76;
              } else if (tone > 0.40) {
                // Classic Butterscotch
                r = 226; g = 150; b = 54;
              } else if (tone > 0.22) {
                // Rich Butterscotch
                r = 207; g = 127; b = 36;
              } else {
                // Deep Butterscotch / Amber Umber slope
                r = 164; g = 85; b = 37;
              }
            }
          }
        }
      }

      // Back-Right Outer Crust Wall (turning the corner from (912, 495) to BR(912, 638))
      if (cut.u > 0.93 && cut.u <= 1.035 && cut.w >= 0.0 && cut.w <= 1.0) {
        fam = "CRUST";
        flow = 1.45;
        const cornerShade = (cut.u - 0.93) / 0.105;
        if (cornerShade > 0.65) {
          r = 78; g = 31; b = 12; // Deep Burnt Umber shadow side
        } else if (cornerShade > 0.3) {
          r = 138; g = 65; b = 29; // Warm Burnt Umber
        } else {
          r = 184; g = 104; b = 23; // Deep Butterscotch
        }
      }

      // Map (r, g, b, fam) to discrete Paint-by-Numbers Palette Index (0..35)
      const pIdx = matchPaletteColor(r, g, b, fam);
      palGrid[idx] = pIdx;
      famGrid[idx] = fam === "PASTEL" ? 0 : (fam === "CHERRY" ? 1 : (fam === "CRUST" ? 2 : 3));
      flowGrid[idx] = flow;
    }
  }

  // Clean 1-pixel isolated noise on non-glint pixels for crisp paint-by-numbers zones
  const cleanPal = new Uint8Array(palGrid);
  for (let gy = 1; gy < GH - 1; gy++) {
    for (let gx = 1; gx < GW - 1; gx++) {
      const idx = gy * GW + gx;
      if (famGrid[idx] === 3) continue; // Never erode Cool White specular glints
      const c = palGrid[idx];
      const n1 = palGrid[idx - 1];
      const n2 = palGrid[idx + 1];
      const n3 = palGrid[idx - GW];
      const n4 = palGrid[idx + GW];
      if (c !== n1 && c !== n2 && c !== n3 && c !== n4) {
        cleanPal[idx] = n1;
      }
    }
  }

  return { palGrid: cleanPal, famGrid, flowGrid };
}

function shade3DCherry(dx, dy, nz, ch) {
  // Subtle stem dimple on upper cherry contour
  const ca = Math.cos(ch.dimple), sa = Math.sin(ch.dimple);
  const rx = dx * ca - dy * sa;
  const ry = dx * sa + dy * ca;

  let nx = dx;
  let ny = dy - 0.12 * Math.exp(-((rx * 2.5) * (rx * 2.5) + ((ry + 0.55) * 4.0) * ((ry + 0.55) * 4.0)));
  const invL = 1.0 / Math.sqrt(nx * nx + ny * ny + nz * nz);
  nx *= invL;
  ny *= invL;
  const nzz = nz * invL;

  // Tangent flow angle around the spherical cherry contour
  const flow = Math.atan2(nx, -ny);

  // Key window light from upper-left (-0.52, -0.62, 0.58)
  const diff = nx * (-0.52) + ny * (-0.62) + nzz * 0.58;
  // Half-vector for glossy window reflection
  const spec = nx * (-0.34) + ny * (-0.42) + nzz * 0.84;

  // Primary Curved Window Specular Glint
  if (spec > 0.915 && rx > -0.55 && rx < 0.35) {
    if (spec > 0.948) {
      return { r: 255, g: 255, b: 255, fam: "GLINT", flow };
    }
    return { r: 237, g: 247, b: 255, fam: "GLINT", flow };
  }
  // Thin Pastel Ice-Blue Fresnel halo around specular glint on dark cherry
  if (spec > 0.885 && spec <= 0.915 && rx < 0.25) {
    return { r: 208, g: 232, b: 252, fam: "GLINT", flow };
  }

  // Secondary pinpoint glint near lower-right rim
  if (nx * 0.48 + ny * 0.52 + nzz * 0.70 > 0.955) {
    return { r: 237, g: 247, b: 255, fam: "GLINT", flow };
  }

  // Subsurface scattering & bounce light from the porcelain plate on lower rim
  const rimBounce = (1.0 - nzz) * (0.4 * nx + 0.7 * ny);
  if (rimBounce > 0.38 && diff < 0.1) {
    if (rimBounce > 0.52) {
      return { r: 250, g: 124, b: 132, fam: "CHERRY", flow }; // Pastel Scarlet-Coral rim
    }
    return { r: 102, g: 27, b: 36, fam: "CHERRY", flow };    // Muted Rose-Oxblood bounce
  }

  // Main cherry body & internal ruby subsurface glow
  if (diff > 0.62) {
    return { r: 246, g: 79, b: 88, fam: "CHERRY", flow };     // Vermilion Scarlet glow
  } else if (diff > 0.44) {
    return { r: 236, g: 51, b: 63, fam: "CHERRY", flow };     // Glowing Scarlet Lake
  } else if (diff > 0.26) {
    return { r: 216, g: 34, b: 48, fam: "CHERRY", flow };     // Bright Scarlet Lake
  } else if (diff > 0.08) {
    return { r: 189, g: 24, b: 38, fam: "CHERRY", flow };     // Classic Scarlet Lake
  } else if (diff > -0.08) {
    return { r: 158, g: 19, b: 32, fam: "CHERRY", flow };     // Deep Scarlet Lake
  } else if (diff > -0.24) {
    return { r: 132, g: 18, b: 31, fam: "CHERRY", flow };     // Luminous Oxblood
  } else if (diff > -0.40) {
    return { r: 109, g: 12, b: 23, fam: "CHERRY", flow };     // Warm Oxblood
  } else if (diff > -0.58) {
    return { r: 84, g: 8, b: 16, fam: "CHERRY", flow };       // Rich Oxblood
  } else if (diff > -0.74) {
    return { r: 61, g: 5, b: 10, fam: "CHERRY", flow };       // Dark Oxblood
  } else {
    return { r: 38, g: 2, b: 5, fam: "CHERRY", flow };        // Pitch Oxblood core
  }
}

function matchPaletteColor(r, g, b, fam) {
  let bestIdx = 0;
  let bestDist = 1e12;
  for (let i = 0; i < PALETTE.length; i++) {
    const p = PALETTE[i];
    if (p.fam !== fam) continue;
    const dr = r - p.r;
    const dg = g - p.g;
    const db = b - p.b;
    // Perceptual RGB weights
    const d = dr * dr * 2.1 + dg * dg * 3.8 + db * db * 1.6;
    if (d < bestDist) {
      bestDist = d;
      bestIdx = i;
    }
  }
  return bestIdx;
}

// ============================================================================
// CONTOUR-ALIGNED VORONOI PAINT-BY-NUMBERS ENGINE
// ============================================================================

function buildVoronoiFacets(scene, GW, GH) {
  const { palGrid, famGrid, flowGrid } = scene;

  // Spatial grid for fast minimum-distance Poisson seed placement
  const cellSize = 8;
  const sCols = Math.ceil(1200 / cellSize);
  const sRows = Math.ceil(1200 / cellSize);
  const occGrid = Array.from({ length: sCols * sRows }, () => []);
  const seeds = [];

  function canPlaceSeed(x, y, minDist) {
    if (x < 5 || x > 1195 || y < 5 || y > 1195) return false;
    const c0 = Math.floor(x / cellSize);
    const r0 = Math.floor(y / cellSize);
    const rad = Math.ceil(minDist / cellSize);
    const md2 = minDist * minDist;

    for (let rr = Math.max(0, r0 - rad); rr <= Math.min(sRows - 1, r0 + rad); rr++) {
      for (let cc = Math.max(0, c0 - rad); cc <= Math.min(sCols - 1, c0 + rad); cc++) {
        const bucket = occGrid[rr * sCols + cc];
        for (let k = 0; k < bucket.length; k++) {
          const s = seeds[bucket[k]];
          const dx = x - s.x;
          const dy = y - s.y;
          if (dx * dx + dy * dy < md2) return false;
        }
      }
    }
    return true;
  }

  function addSeed(x, y, palIdx, fam, isGlint) {
    const id = seeds.length;
    seeds.push({ x, y, palIdx, fam, isGlint });
    const cc = Math.floor(x / cellSize);
    const rr = Math.floor(y / cellSize);
    occGrid[rr * sCols + cc].push(id);
  }

  // Pass 1: Seed every Cool White Specular Glint so every highlight facet is preserved
  for (let gy = 2; gy < GH - 2; gy++) {
    for (let gx = 2; gx < GW - 2; gx++) {
      const idx = gy * GW + gx;
      if (famGrid[idx] === 3) {
        const x = (gx + 0.5) * 2.0;
        const y = (gy + 0.5) * 2.0;
        if (canPlaceSeed(x, y, 8.2)) {
          addSeed(x, y, palGrid[idx], 3, true);
        }
      }
    }
  }

  // Pass 2: Seed Contour Boundaries (where palette colour changes)
  for (let gy = 2; gy < GH - 2; gy++) {
    for (let gx = 2; gx < GW - 2; gx++) {
      const idx = gy * GW + gx;
      const p = palGrid[idx];
      const f = famGrid[idx];
      if (
        palGrid[idx - 1] !== p ||
        palGrid[idx + 1] !== p ||
        palGrid[idx - GW] !== p ||
        palGrid[idx + GW] !== p
      ) {
        const x = (gx + 0.5) * 2.0 + random(-0.6, 0.6);
        const y = (gy + 0.5) * 2.0 + random(-0.6, 0.6);
        const minDist = (f === 1 || f === 2 || f === 3) ? 9.5 : 15.5;
        if (canPlaceSeed(x, y, minDist)) {
          addSeed(x, y, p, f, f === 3);
        }
      }
    }
  }

  // Pass 3: Seed Interior Regions with adaptive Paint-by-Numbers facet density
  for (let gy = 2; gy < GH - 2; gy += 2) {
    for (let gx = 2; gx < GW - 2; gx += 2) {
      const idx = gy * GW + gx;
      const p = palGrid[idx];
      const f = famGrid[idx];
      const x = (gx + 0.5) * 2.0 + random(-2.2, 2.2);
      const y = (gy + 0.5) * 2.0 + random(-2.2, 2.2);

      // Dense tiny facets inside the pie & syrup; medium facets on plate & gingham
      let minDist = 24.5;
      if (f === 1 || f === 2) {
        minDist = 13.0;
      } else if (x > 200 && x < 1030 && y > 320 && y < 920) {
        minDist = 18.5; // Plate rim and shadow
      }

      if (canPlaceSeed(x, y, minDist)) {
        addSeed(x, y, p, f, false);
      }
    }
  }

  // Build spatial hash of all seeds for fast half-plane Voronoi clipping
  const vBucketSize = 40;
  const vCols = Math.ceil(1200 / vBucketSize);
  const vRows = Math.ceil(1200 / vBucketSize);
  const vGrid = Array.from({ length: vCols * vRows }, () => []);

  for (let i = 0; i < seeds.length; i++) {
    const s = seeds[i];
    const c = Math.min(vCols - 1, Math.max(0, Math.floor(s.x / vBucketSize)));
    const r = Math.min(vRows - 1, Math.max(0, Math.floor(s.y / vBucketSize)));
    vGrid[r * vCols + c].push(i);
  }

  const cells = [];

  for (let i = 0; i < seeds.length; i++) {
    const s = seeds[i];
    // Initial bounding polygon around seed i, clipped to canvas margins [8, 1192]
    const initR = 46;
    let poly = [
      [Math.max(8, s.x - initR), Math.max(8, s.y - initR)],
      [Math.min(1192, s.x + initR), Math.max(8, s.y - initR)],
      [Math.min(1192, s.x + initR), Math.min(1192, s.y + initR)],
      [Math.max(8, s.x - initR), Math.min(1192, s.y + initR)]
    ];

    const c0 = Math.floor(s.x / vBucketSize);
    const r0 = Math.floor(s.y / vBucketSize);
    const neighbors = [];

    for (let rr = Math.max(0, r0 - 2); rr <= Math.min(vRows - 1, r0 + 2); rr++) {
      for (let cc = Math.max(0, c0 - 2); cc <= Math.min(vCols - 1, c0 + 2); cc++) {
        const b = vGrid[rr * vCols + cc];
        for (let k = 0; k < b.length; k++) {
          const j = b[k];
          if (j === i) continue;
          const sj = seeds[j];
          const dx = sj.x - s.x;
          const dy = sj.y - s.y;
          const d2 = dx * dx + dy * dy;
          if (d2 < 6800) {
            neighbors.push({ j, dx, dy, d2 });
          }
        }
      }
    }

    neighbors.sort((a, b) => a.d2 - b.d2);

    for (let nIdx = 0; nIdx < neighbors.length; nIdx++) {
      const nb = neighbors[nIdx];
      // Early exit if neighbor is further than twice max polygon vertex distance
      let maxV2 = 0;
      for (let v = 0; v < poly.length; v++) {
        const vx = poly[v][0] - s.x;
        const vy = poly[v][1] - s.y;
        const vd2 = vx * vx + vy * vy;
        if (vd2 > maxV2) maxV2 = vd2;
      }
      if (nb.d2 > 4.1 * maxV2) break;

      const sj = seeds[nb.j];
      // Slightly favor Cool White specular glint seeds so highlights stay crisp
      let frac = 0.5;
      if (s.isGlint && !sj.isGlint) frac = 0.54;
      else if (!s.isGlint && sj.isGlint) frac = 0.46;

      const mx = s.x + nb.dx * frac;
      const my = s.y + nb.dy * frac;
      poly = clipPolygonHalfPlane(poly, mx, my, nb.dx, nb.dy);
      if (poly.length < 3) break;
    }

    if (poly.length < 3) continue;

    // Compute centroid & average radius
    let cx = 0, cy = 0;
    for (let k = 0; k < poly.length; k++) {
      cx += poly[k][0];
      cy += poly[k][1];
    }
    cx /= poly.length;
    cy /= poly.length;

    let sumR = 0;
    for (let k = 0; k < poly.length; k++) {
      const dx = poly[k][0] - cx;
      const dy = poly[k][1] - cy;
      sumR += Math.sqrt(dx * dx + dy * dy);
    }
    const avgR = sumR / poly.length;

    // Inset vertices by 0.62 px toward centroid to form the uniform pale facet border
    const inset = 0.62;
    const insetVerts = [];
    for (let k = 0; k < poly.length; k++) {
      const vx = poly[k][0] - cx;
      const vy = poly[k][1] - cy;
      const vl = Math.sqrt(vx * vx + vy * vy) + 1e-5;
      const scale = Math.max(0.25, (vl - inset) / vl);
      insetVerts.push([cx + vx * scale, cy + vy * scale]);
    }

    // Look up local flow angle & palette color at centroid (preserving glint seeds)
    const gx = Math.min(GW - 1, Math.max(0, Math.floor(cx * 0.5)));
    const gy = Math.min(GH - 1, Math.max(0, Math.floor(cy * 0.5)));
    const gIdx = gy * GW + gx;

    const palIdx = s.isGlint ? s.palIdx : palGrid[gIdx];
    const flowAngle = flowGrid[gIdx];

    // Determine if this cell is an unpainted / partially painted edge cell
    const edgeFlag = evaluateUnpaintedEdgeState(cx, cy);

    cells.push({
      verts: insetVerts,
      cx,
      cy,
      radius: avgR,
      palIdx,
      flowAngle,
      unpainted: edgeFlag === 2,
      partial: edgeFlag === 1
    });
  }

  return cells;
}

function clipPolygonHalfPlane(poly, mx, my, nx, ny) {
  const out = [];
  const n = poly.length;
  for (let i = 0; i < n; i++) {
    const a = poly[i];
    const b = poly[(i + 1) % n];
    const da = (a[0] - mx) * nx + (a[1] - my) * ny;
    const db = (b[0] - mx) * nx + (b[1] - my) * ny;
    const aIn = da <= 0;
    const bIn = db <= 0;

    if (aIn && bIn) {
      out.push(b);
    } else if (aIn && !bIn) {
      const t = da / (da - db);
      out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
    } else if (!aIn && bIn) {
      const t = da / (da - db);
      out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
      out.push(b);
    }
  }
  return out;
}

function evaluateUnpaintedEdgeState(x, y) {
  // Distance from canvas borders
  const dLeft = x;
  const dRight = 1200 - x;
  const dTop = y;
  const dBottom = 1200 - y;
  const minBorder = Math.min(dLeft, dRight, dTop, dBottom);

  // Corner pockets & organic edge clusters for unpainted paint-by-numbers cells
  const dTL = Math.sqrt(x * x + y * y);
  const dBR = Math.sqrt((1200 - x) * (1200 - x) + (1200 - y) * (1200 - y));
  const dBL = Math.sqrt(x * x + (1200 - y) * (1200 - y));
  const dTR = Math.sqrt((1200 - x) * (1200 - x) + y * y);

  const nVal = noise(x * 0.006, y * 0.006);

  let score = 0;
  if (dTL < 235 + nVal * 75) score = Math.max(score, (235 + nVal * 75 - dTL) / 45);
  if (dBR < 245 + nVal * 80) score = Math.max(score, (245 + nVal * 80 - dBR) / 45);
  if (dBL < 195 + nVal * 65) score = Math.max(score, (195 + nVal * 65 - dBL) / 45);
  if (dTR < 185 + nVal * 65) score = Math.max(score, (185 + nVal * 65 - dTR) / 45);
  if (minBorder < 42 + nVal * 44) score = Math.max(score, (42 + nVal * 44 - minBorder) / 22);

  if (score > 0.42) return 2; // Unpainted cell with faint printed outline & number
  if (score > 0.14) return 1; // Partially marker-filled cell
  return 0;                   // Completed painted cell
}
